--
-- Name: admin_bulk_import_catalog_items(jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_bulk_import_catalog_items(p_records jsonb, p_source_type text, p_default_role text DEFAULT 'User_DiasporaMember'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor    uuid := auth.uid();
  v_rec      jsonb;
  v_name     text;
  v_company  text;
  v_city     text;
  v_country  text;
  v_profession text;
  v_phone    text;
  v_email    text;
  v_web      text;
  v_address  text;
  v_ext_id   text;
  v_src_url  text;
  v_role_key text;
  v_item_type text;
  v_slug     text;
  v_attr_id  uuid;
  v_item_id  uuid;
  v_created  int := 0;
  v_skipped  int := 0;
  v_item_ids uuid[] := '{}';
  v_batch_id text;
begin
  -- Yetki: yalnız moderator/admin.
  if v_actor is null or not public.is_moderator(v_actor) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if p_source_type is null or btrim(p_source_type) = '' then
    raise exception 'source_type zorunlu' using errcode = '22023';
  end if;

  if jsonb_typeof(p_records) <> 'array' then
    raise exception 'p_records bir JSON dizi olmalı' using errcode = '22023';
  end if;

  -- Varsayılan rol geçerli olmalı (FK platform_role_key -> roles.key).
  if not exists (select 1 from public.roles where key = p_default_role and is_active = true) then
    raise exception 'geçersiz default rol: %', p_default_role using errcode = '22023';
  end if;

  -- Batch kimliği: aynı içe aktarma partisini gruplamak için (random yok — actor+source+now hash'i).
  v_batch_id := substr(md5(coalesce(v_actor::text, '') || p_source_type || now()::text), 1, 16);

  for v_rec in select * from jsonb_array_elements(p_records)
  loop
    v_name       := nullif(btrim(coalesce(v_rec ->> 'name', '')), '');
    if v_name is null then
      v_skipped := v_skipped + 1;  -- isimsiz kayıt atlanır
      continue;
    end if;

    v_company    := nullif(btrim(coalesce(v_rec ->> 'company', '')), '');
    v_city       := nullif(btrim(coalesce(v_rec ->> 'city', '')), '');
    v_country    := nullif(btrim(coalesce(v_rec ->> 'country', '')), '');
    v_profession := nullif(btrim(coalesce(v_rec ->> 'profession', '')), '');
    v_phone      := nullif(btrim(coalesce(v_rec ->> 'phone', '')), '');
    v_email      := nullif(btrim(coalesce(v_rec ->> 'email', '')), '');
    v_web        := nullif(btrim(coalesce(v_rec ->> 'web', '')), '');
    v_address    := nullif(btrim(coalesce(v_rec ->> 'address', '')), '');
    v_src_url    := nullif(btrim(coalesce(v_rec ->> 'source_url', '')), '');

    -- Dedup anahtarı: verilmişse external_id, yoksa name|company|city slug'ı.
    v_ext_id := nullif(btrim(coalesce(v_rec ->> 'external_id', '')), '');
    if v_ext_id is null then
      v_ext_id := public.catalog_slugify(
        concat_ws('|', v_name, coalesce(v_company, ''), coalesce(v_city, ''))
      );
    end if;

    -- Idempotency: bu source_type + external_id zaten içe aktarılmışsa atla.
    if exists (
      select 1 from public.source_records sr
      where sr.source_type = p_source_type and sr.external_id = v_ext_id
    ) then
      v_skipped := v_skipped + 1;
      continue;
    end if;

    -- Rol eşlemesi: profession metnine göre kaba eşleme, belirsizse p_default_role.
    -- (Admin onayda detay panelinden değiştirebilir.)
    v_role_key := public._bulk_import_role_for_profession(v_profession, p_default_role);
    v_item_type := case
      when v_role_key like 'Consultant\_%' or v_role_key like 'Healthcare\_%' then 'advisor'
      when v_role_key like 'Business\_%' then 'business'
      when v_role_key like 'Organization\_%' then 'organization'
      else 'member'
    end;

    -- Benzersiz slug (external_id + kısa rastgelelik yerine batch parçası).
    v_slug := left(
      'import-' || public.catalog_slugify(concat_ws('-', v_city, v_name)) || '-' || substr(md5(v_ext_id), 1, 8),
      96
    );

    -- 1. catalog_items (beklemede + gizli + sahipsiz).
    insert into public.catalog_items (
      item_type, slug, title, headline, short_description,
      status, visibility, verification_status,
      linked_user_id, created_by, platform_role_key, country_code, city,
      attributes, published_at
    )
    values (
      v_item_type,
      v_slug,
      v_name,
      coalesce(v_profession, v_company),
      concat_ws(' · ', v_profession, v_company, v_city),
      'pending_review',
      'private',
      'unverified',
      null,
      null,
      v_role_key,
      v_country,
      v_city,
      jsonb_strip_nulls(jsonb_build_object(
        'import_source',  p_source_type,
        'import_batch',   v_batch_id,
        'source_type',    p_source_type,
        'external_id',    v_ext_id,
        'platform_role_key', v_role_key,
        'raw_company',    v_company,
        'raw_profession', v_profession
      )),
      null
    )
    on conflict (slug) do nothing
    returning id into v_item_id;

    -- Slug çakışması (nadir) → atla.
    if v_item_id is null then
      v_skipped := v_skipped + 1;
      continue;
    end if;

    -- 2. source_records (dedup kaydı + ham anlık görüntü).
    insert into public.source_records (item_id, source_type, external_id, source_url, raw_snapshot, imported_at, last_seen_at)
    values (v_item_id, p_source_type, v_ext_id, v_src_url, v_rec, now(), now())
    on conflict (source_type, external_id) do nothing;

    -- 3. catalog_item_roles (birincil rol).
    insert into public.catalog_item_roles (catalog_item_id, role_id, is_primary)
    select v_item_id, r.id, true
    from public.roles r
    where r.key = v_role_key
    on conflict (catalog_item_id, role_id) do nothing;

    -- 4. Attribute değerleri (beklemede onay durumuyla; onayda 'approved' olur).
    insert into public.catalog_item_attribute_values
      (item_id, attribute_id, value_text, visibility, approval_status, updated_at)
    select v_item_id, a.id, v.value_text, 'public', 'pending', now()
    from (values
      ('full_name',      v_name),
      ('business_name',  v_company),
      ('expertise_area', v_profession),
      ('city',           v_city),
      ('country',        v_country)
    ) v(attr_key, value_text)
    join public.afs_attributes a on a.key = v.attr_key and a.is_active = true
    where v.value_text is not null
    on conflict (item_id, attribute_id) do nothing;

    -- 5. İletişim (telefon/e-posta gizli; web herkese açık).
    insert into public.catalog_item_contacts (item_id, contact_type, contact_value, label, is_public, is_primary, sort_order)
    select v_item_id, c.contact_type, c.contact_value, c.label, c.is_public, c.is_primary, c.sort_order
    from (values
      ('phone',   v_phone, 'Telefon',    false, (v_phone is not null),                       0),
      ('email',   v_email, 'E-posta',    false, (v_phone is null and v_email is not null),  10),
      ('website', v_web,   'Web Sitesi', true,  false,                                       20)
    ) c(contact_type, contact_value, label, is_public, is_primary, sort_order)
    where c.contact_value is not null;

    -- 6. Lokasyon (şehir/ülke/adres).
    if v_city is not null or v_country is not null or v_address is not null then
      insert into public.catalog_item_locations (item_id, country_code, city, address_line, is_primary)
      values (v_item_id, v_country, v_city, v_address, true);
    end if;

    v_created := v_created + 1;
    v_item_ids := array_append(v_item_ids, v_item_id);
  end loop;

  -- Audit log (batch özeti).
  insert into public.catalog_audit_logs (item_id, actor_user_id, action, details)
  values (
    null, v_actor, 'bulk_import',
    jsonb_build_object(
      'source_type', p_source_type,
      'batch_id',    v_batch_id,
      'created',     v_created,
      'skipped',     v_skipped,
      'default_role', p_default_role
    )
  );

  return jsonb_build_object(
    'created',  v_created,
    'skipped',  v_skipped,
    'batch_id', v_batch_id,
    'item_ids', to_jsonb(v_item_ids)
  );
end;
$$;


--
-- Name: FUNCTION admin_bulk_import_catalog_items(p_records jsonb, p_source_type text, p_default_role text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_bulk_import_catalog_items(p_records jsonb, p_source_type text, p_default_role text) IS 'Moderator-gated toplu profil içe aktarma. Kayıtlar status=pending_review + visibility=private olarak girer; source_records ile dedup; admin onayı bekler.';


--
-- Name: admin_cancel_service_finder_job(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_cancel_service_finder_job(p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := public.service_finder_require_admin();
  v_status text;
begin
  select status into v_status from public.service_finder_jobs where id = p_job_id for update;
  if not found then
    raise exception 'sf_job_not_found';
  end if;
  if v_status not in ('queued', 'running') then
    raise exception 'sf_job_not_cancellable';
  end if;

  update public.service_finder_jobs
  set status = 'cancelled', cancelled_at = now(), finished_at = now(),
      locked_by = null, lease_expires_at = null, updated_at = now()
  where id = p_job_id;

  insert into public.service_finder_job_events (job_id, event_type, message, event_payload)
  values (p_job_id, 'job_cancelled', 'İş admin tarafından iptal edildi.', jsonb_build_object('cancelled_by', v_uid));

  return jsonb_build_object('job_id', p_job_id, 'status', 'cancelled');
end;
$$;


--
-- Name: admin_change_catalog_item_role(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_change_catalog_item_role(p_item_id uuid, p_role_key text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_current_role_key text;
  v_role public.roles%rowtype;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  if auth.uid() is null or not public.is_admin(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if v_reason is null then
    raise exception 'reason is required' using errcode = '22023';
  end if;

  select ci.platform_role_key
  into v_current_role_key
  from public.catalog_items ci
  where ci.id = p_item_id
  limit 1;

  if v_current_role_key is null then
    raise exception 'catalog item not found' using errcode = 'P0002';
  end if;

  select *
  into v_role
  from public.roles r
  where r.key = p_role_key
    and r.is_active = true
  limit 1;

  if v_role.id is null then
    raise exception 'invalid role key' using errcode = '22023';
  end if;

  if not v_role.is_assignable then
    raise exception 'role is not assignable' using errcode = '22023';
  end if;

  update public.catalog_items
  set
    platform_role_key = p_role_key,
    attributes = coalesce(attributes, '{}'::jsonb) || jsonb_build_object('platform_role_key', p_role_key),
    updated_at = now()
  where id = p_item_id;

  perform public.write_admin_audit_log(
    'catalog_item.role_repaired',
    null,
    'catalog_item',
    p_item_id,
    jsonb_build_object('old_role_key', v_current_role_key),
    jsonb_build_object(
      'old_role_key', v_current_role_key,
      'new_role_key', p_role_key,
      'reason', v_reason
    )
  );

  return jsonb_build_object(
    'item_id', p_item_id,
    'old_role_key', v_current_role_key,
    'new_role_key', p_role_key
  );
end;
$$;


--
-- Name: admin_clear_user_feature_override(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_clear_user_feature_override(target_user_id uuid, feature_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_before public.user_feature_overrides%rowtype;
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'forbidden'
      using errcode = '42501';
  end if;

  if target_user_id is null then
    raise exception 'target user is required'
      using errcode = '22023';
  end if;

  if feature_key is null or btrim(feature_key) = '' then
    raise exception 'feature key is required'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.afs_features fc
    where fc.key = admin_clear_user_feature_override.feature_key
  ) then
    raise exception 'invalid feature key'
      using errcode = '22023';
  end if;

  select * into v_before
  from public.user_feature_overrides ufo
  where ufo.user_id = target_user_id
    and ufo.feature_key = admin_clear_user_feature_override.feature_key;

  delete from public.user_feature_overrides ufo
  where ufo.user_id = target_user_id
    and ufo.feature_key = admin_clear_user_feature_override.feature_key;

  perform public.write_admin_audit_log(
    'feature.override_cleared',
    target_user_id,
    'user_feature_override',
    target_user_id,
    case when v_before.user_id is null then null else to_jsonb(v_before) end,
    jsonb_build_object('feature_key', feature_key)
  );
end;
$$;


--
-- Name: admin_create_service_finder_job(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_create_service_finder_job(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := public.service_finder_require_admin();
  v_template public.service_finder_profession_templates%rowtype;
  v_role_key text;
  v_item_type text;
  v_category_slug text;
  v_title text := nullif(trim(coalesce(p_payload ->> 'title', '')), '');
  v_location_label text := nullif(trim(coalesce(p_payload ->> 'location_label', '')), '');
  v_soft numeric(12,4) := coalesce((p_payload ->> 'soft_cap_usd')::numeric, 3.0000);
  v_hard numeric(12,4) := coalesce((p_payload ->> 'hard_cap_usd')::numeric, 5.0000);
  v_search_provider uuid;
  v_extract_provider uuid;
  v_classifier_provider uuid;
  v_job_id uuid;
begin
  if v_title is null then
    raise exception 'sf_title_required';
  end if;
  if v_location_label is null then
    raise exception 'sf_location_required';
  end if;
  if v_soft <= 0 or v_hard <= 0 or v_hard < v_soft then
    raise exception 'sf_invalid_budget';
  end if;

  if p_payload ->> 'template_id' is not null then
    select * into v_template
    from public.service_finder_profession_templates
    where id = (p_payload ->> 'template_id')::uuid and is_active = true;
    if not found then
      raise exception 'sf_template_not_found';
    end if;
  end if;

  v_role_key := coalesce(nullif(p_payload ->> 'role_key', ''), v_template.role_key);
  v_item_type := coalesce(nullif(p_payload ->> 'item_type', ''), v_template.item_type);
  v_category_slug := coalesce(nullif(p_payload ->> 'category_slug', ''), v_template.category_slug);

  if v_role_key is null or v_item_type is null then
    raise exception 'sf_role_required';
  end if;
  if not exists (select 1 from public.roles where key = v_role_key and is_active = true) then
    raise exception 'sf_invalid_role';
  end if;

  -- Sağlayıcı çözümlemesi: payload > etkin + en düşük priority
  v_search_provider := coalesce(
    (p_payload ->> 'search_provider_id')::uuid,
    (select id from public.service_finder_provider_configs
      where provider_kind = 'search' and is_enabled = true
      order by priority asc limit 1)
  );
  v_extract_provider := coalesce(
    (p_payload ->> 'extract_provider_id')::uuid,
    (select id from public.service_finder_provider_configs
      where provider_key = 'tavily' and is_enabled = true limit 1)
  );
  v_classifier_provider := coalesce(
    (p_payload ->> 'classifier_provider_id')::uuid,
    (select id from public.service_finder_provider_configs
      where provider_kind = 'classify' and is_enabled = true
      order by priority asc limit 1)
  );
  if v_search_provider is null or v_classifier_provider is null then
    raise exception 'sf_no_enabled_provider';
  end if;

  insert into public.service_finder_jobs (
    title, created_by_user_id, template_id,
    search_provider_id, extract_provider_id, classifier_provider_id,
    role_key, item_type, category_slug,
    location_label, country_code, region, city, language_code, freeform_topic,
    must_include_terms, must_exclude_terms, seed_queries,
    max_queries, max_source_urls, max_extract_urls, max_candidates,
    soft_cap_usd, hard_cap_usd, catalog_publish_mode, priority
  )
  values (
    v_title, v_uid, v_template.id,
    v_search_provider, v_extract_provider, v_classifier_provider,
    v_role_key, v_item_type, v_category_slug,
    v_location_label,
    nullif(p_payload ->> 'country_code', ''),
    nullif(p_payload ->> 'region', ''),
    nullif(p_payload ->> 'city', ''),
    coalesce(nullif(p_payload ->> 'language_code', ''), 'tr'),
    nullif(p_payload ->> 'freeform_topic', ''),
    case when p_payload ? 'must_include_terms'
         then public.service_finder_text_array(p_payload -> 'must_include_terms')
         else coalesce(v_template.must_include_terms, '{}'::text[]) end,
    case when p_payload ? 'must_exclude_terms'
         then public.service_finder_text_array(p_payload -> 'must_exclude_terms')
         else coalesce(v_template.must_exclude_terms, '{}'::text[]) end,
    coalesce(p_payload -> 'seed_queries', '[]'::jsonb),
    coalesce((p_payload ->> 'max_queries')::int, v_template.default_max_queries, 12),
    coalesce((p_payload ->> 'max_source_urls')::int, v_template.default_max_source_urls, 40),
    coalesce((p_payload ->> 'max_extract_urls')::int, v_template.default_max_extract_urls, 25),
    coalesce((p_payload ->> 'max_candidates')::int, 100),
    v_soft, v_hard,
    coalesce(nullif(p_payload ->> 'catalog_publish_mode', ''), 'manual_review'),
    coalesce((p_payload ->> 'priority')::int, 100)
  )
  returning id into v_job_id;

  insert into public.service_finder_job_events (job_id, event_type, message, event_payload)
  values (v_job_id, 'job_created', 'İş kuyruğa alındı.', jsonb_build_object('created_by', v_uid));

  return jsonb_build_object(
    'job_id', v_job_id,
    'status', 'queued',
    'soft_cap_usd', v_soft,
    'hard_cap_usd', v_hard
  );
end;
$$;


--
-- Name: admin_delete_catalog_item_attribute_override(uuid, text); Type: FUNCTION; Schema: public; Owner: -
