--
-- Name: admin_get_notification_subscribers(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_notification_subscribers(p_event_type text) RETURNS TABLE(user_id uuid, email text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_event_type not in ('new_member', 'admin_update', 'revision_request') then
    raise exception 'unknown_event_type' using errcode = '22023';
  end if;

  return query
  select s.user_id, au.email::text
  from public.admin_notification_subscriptions s
  join auth.users au on au.id = s.user_id
  where au.email is not null
    and public.is_moderator(s.user_id)
    and case p_event_type
      when 'new_member' then s.new_member_email
      when 'revision_request' then s.revision_request_email
      else s.admin_update_email
    end;
end;
$$;


--
-- Name: admin_get_service_finder_job(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_service_finder_job(p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := public.service_finder_require_admin();
  v_job jsonb;
begin
  select to_jsonb(j) into v_job from public.service_finder_jobs j where j.id = p_job_id;
  if v_job is null then
    raise exception 'sf_job_not_found';
  end if;

  return jsonb_build_object(
    'job', v_job,
    'queries', coalesce((
      select jsonb_agg(to_jsonb(q) order by q.created_at)
      from public.service_finder_job_queries q where q.job_id = p_job_id
    ), '[]'::jsonb),
    'sources', coalesce((
      select jsonb_agg(to_jsonb(s) - 'extracted_text' - 'extracted_markdown' order by s.created_at)
      from (
        select * from public.service_finder_job_sources
        where job_id = p_job_id order by created_at limit 300
      ) s
    ), '[]'::jsonb),
    'candidates', coalesce((
      select jsonb_agg(to_jsonb(c) order by c.confidence_score desc)
      from public.service_finder_candidates c where c.job_id = p_job_id
    ), '[]'::jsonb),
    'costs', coalesce((
      select jsonb_agg(to_jsonb(l) order by l.created_at desc)
      from (
        select * from public.service_finder_cost_ledger
        where job_id = p_job_id order by created_at desc limit 500
      ) l
    ), '[]'::jsonb),
    'events', coalesce((
      select jsonb_agg(to_jsonb(e) order by e.created_at desc)
      from (
        select * from public.service_finder_job_events
        where job_id = p_job_id order by created_at desc limit 300
      ) e
    ), '[]'::jsonb)
  );
end;
$$;


--
-- Name: admin_get_user_email(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_user_email(p_user_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_email text;
begin
  if v_actor_id is null or not public.is_moderator(v_actor_id) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if p_user_id is null then
    return null;
  end if;

  select au.email::text into v_email
  from auth.users au
  where au.id = p_user_id;

  return v_email;
end;
$$;


--
-- Name: admin_grant_catalog_editor(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_grant_catalog_editor(p_item_id uuid, p_target_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor_id uuid := auth.uid();
begin
  if v_actor_id is null or not public.is_moderator(v_actor_id) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if not exists (select 1 from public.catalog_items where id = p_item_id) then
    raise exception 'catalog item not found' using errcode = 'P0002';
  end if;

  if not exists (select 1 from auth.users where id = p_target_user_id) then
    raise exception 'target user not found' using errcode = 'P0002';
  end if;

  insert into public.catalog_item_managers (item_id, user_id, role, status)
  values (p_item_id, p_target_user_id, 'editor', 'active')
  on conflict (item_id, user_id, role) do update
  set status = 'active',
      updated_at = now();
end;
$$;


--
-- Name: admin_grant_catalog_item_access(uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_grant_catalog_item_access(p_item_id uuid, p_user_id uuid, p_access_level text, p_is_primary_owner boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null or not public.is_moderator(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if p_access_level not in ('owner', 'manager', 'editor', 'viewer') then
    raise exception 'invalid access level' using errcode = '22023';
  end if;

  insert into public.catalog_item_managers (item_id, user_id, role, status)
  values (p_item_id, p_user_id, p_access_level, 'active')
  on conflict (item_id, user_id, role) do update
  set
    status = 'active',
    updated_at = now();

  if p_is_primary_owner and p_access_level = 'owner' then
    update public.catalog_items
    set linked_user_id = p_user_id,
        updated_at = now()
    where id = p_item_id;
  end if;

  perform public.write_admin_audit_log(
    'catalog_item.access_granted',
    p_user_id,
    'catalog_item',
    p_item_id,
    null,
    jsonb_build_object('access_level', p_access_level, 'is_primary_owner', p_is_primary_owner)
  );
end;
$$;


--
-- Name: admin_grant_whatsapp_landing_editor(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_grant_whatsapp_landing_editor(p_landing_id uuid, p_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_assignment_id uuid;
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'forbidden'
      using errcode = '42501';
  end if;

  if p_landing_id is null or p_user_id is null then
    raise exception 'landing_id and user_id are required'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.whatsapp_landings wl
    where wl.id = p_landing_id
  ) then
    raise exception 'landing not found'
      using errcode = 'P0002';
  end if;

  if not exists (
    select 1
    from auth.users u
    where u.id = p_user_id
  ) then
    raise exception 'user profile not found'
      using errcode = 'P0002';
  end if;

  insert into public.whatsapp_landing_editors (landing_id, user_id, granted_by, updated_at)
  values (p_landing_id, p_user_id, auth.uid(), now())
  on conflict (landing_id, user_id) do update
  set
    granted_by = excluded.granted_by,
    updated_at = now()
  returning id into v_assignment_id;

  insert into public.user_feature_overrides (user_id, feature_key, is_enabled, updated_by, updated_at, reason)
  values (
    p_user_id,
    'whatsapp_landing.edit_assigned',
    true,
    auth.uid(),
    now(),
    'Assigned landing editor permission'
  )
  on conflict on constraint user_feature_overrides_pkey do update
  set
    is_enabled = true,
    updated_by = excluded.updated_by,
    updated_at = excluded.updated_at,
    reason = excluded.reason;

  perform public.write_admin_audit_log(
    'whatsapp_landing.editor_granted',
    p_user_id,
    'whatsapp_landing',
    p_landing_id,
    null,
    jsonb_build_object('landing_id', p_landing_id, 'user_id', p_user_id)
  );

  return v_assignment_id;
end;
$$;


--
-- Name: admin_import_cadde_geo_v1(text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_import_cadde_geo_v1(p_country_code text, p_city_names text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_geo_country public.geo_countries%rowtype;
  v_country_id uuid;
  v_cities_added int := 0;
  v_cities_missing text[] := '{}';
  v_city text;
  v_geo_city_id uuid;
begin
  if v_uid is null or not public.is_admin_user(v_uid) then
    raise exception 'cadde_admin_required';
  end if;

  select * into v_geo_country
  from public.geo_countries
  where code = upper(trim(coalesce(p_country_code, ''))) and is_active = true;

  if v_geo_country.id is null then
    raise exception 'cadde_geo_country_not_found';
  end if;

  select id into v_country_id
  from public.cadde_countries
  where geo_country_id = v_geo_country.id or code = v_geo_country.code
  limit 1;

  if v_country_id is null then
    insert into public.cadde_countries (code, name, sort_order, is_active, geo_country_id)
    values (
      v_geo_country.code,
      v_geo_country.name,
      coalesce((select max(sort_order) + 10 from public.cadde_countries), 10),
      true,
      v_geo_country.id
    )
    returning id into v_country_id;
  else
    update public.cadde_countries
    set geo_country_id = coalesce(geo_country_id, v_geo_country.id), is_active = true
    where id = v_country_id;
  end if;

  foreach v_city in array coalesce(p_city_names, '{}') loop
    v_city := trim(v_city);
    if v_city = '' then continue; end if;

    select id into v_geo_city_id
    from public.geo_cities
    where country_id = v_geo_country.id and lower(name) = lower(v_city) and is_active = true
    limit 1;

    if v_geo_city_id is null then
      v_cities_missing := array_append(v_cities_missing, v_city);
      continue;
    end if;

    if not exists (
      select 1 from public.cadde_cities
      where country_id = v_country_id and (geo_city_id = v_geo_city_id or lower(name) = lower(v_city))
    ) then
      insert into public.cadde_cities (country_id, name, timezone, sort_order, is_active, geo_city_id)
      values (
        v_country_id,
        v_city,
        'UTC',
        coalesce((select max(sort_order) + 10 from public.cadde_cities where country_id = v_country_id), 10),
        true,
        v_geo_city_id
      );
      v_cities_added := v_cities_added + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'countryId', v_country_id,
    'countryCode', v_geo_country.code,
    'citiesAdded', v_cities_added,
    'citiesNotFound', to_jsonb(v_cities_missing)
  );
end;
$$;


--
-- Name: admin_list_catalog_claims(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_catalog_claims(p_item_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text) RETURNS TABLE(id uuid, item_id uuid, item_title text, requested_by_user_id uuid, requester_full_name text, requester_email text, claim_type text, note text, status text, created_at timestamp with time zone, reviewed_at timestamp with time zone, reviewed_by_user_id uuid, reviewer_full_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor_id uuid := auth.uid();
begin
  if v_actor_id is null or not public.is_moderator(v_actor_id) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  return query
  select
    ccr.id,
    ccr.item_id,
    ci.title as item_title,
    ccr.requested_by_user_id,
    coalesce(
      (select upa.value_text from public.user_profile_attributes upa
       join public.afs_attributes ac on ac.id = upa.attribute_id
       where upa.user_id = ccr.requested_by_user_id and ac.key = 'full_name' limit 1),
      split_part(coalesce(req_email.email, 'corteqs-uye'), '@', 1)
    ) as requester_full_name,
    req_email.email::text as requester_email,
    ccr.claim_type,
    ccr.note,
    ccr.status,
    ccr.created_at,
    ccr.reviewed_at,
    ccr.reviewed_by_user_id,
    coalesce(
      (select upa.value_text from public.user_profile_attributes upa
       join public.afs_attributes ac on ac.id = upa.attribute_id
       where upa.user_id = ccr.reviewed_by_user_id and ac.key = 'full_name' limit 1),
      'İsimsiz kullanıcı'
    ) as reviewer_full_name
  from public.catalog_item_claims ccr
  join public.catalog_items ci on ci.id = ccr.item_id
  left join auth.users req_email on req_email.id = ccr.requested_by_user_id
  where (p_item_id is null or ccr.item_id = p_item_id)
    and (p_status is null or btrim(p_status) = '' or ccr.status = p_status)
  order by
    case when ccr.status = 'pending' then 0 else 1 end,
    ccr.created_at desc;
end;
$$;


--
-- Name: admin_list_catalog_item_access(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_catalog_item_access(p_item_id uuid) RETURNS TABLE(user_id uuid, full_name text, email text, access_level text, status text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    cim.user_id,
    coalesce(
      (select upa.value_text from public.user_profile_attributes upa
       join public.afs_attributes ac on ac.id = upa.attribute_id
       where upa.user_id = cim.user_id and ac.key = 'full_name' limit 1),
      split_part(coalesce(au.email, 'corteqs-user'), '@', 1)
    ) as full_name,
    au.email::text as email,
    cim.role as access_level,
    cim.status,
    cim.created_at
  from public.catalog_item_managers cim
  left join auth.users au on au.id = cim.user_id
  where public.is_moderator(auth.uid())
    and cim.item_id = p_item_id
  order by
    case when cim.role = 'owner' then 0 when cim.role = 'manager' then 1 when cim.role = 'editor' then 2 else 3 end,
    cim.created_at asc;
$$;


--
-- Name: admin_list_catalog_profiles(text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_catalog_profiles(p_query text DEFAULT NULL::text, p_item_type text DEFAULT NULL::text, p_role_key text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_country_code text DEFAULT NULL::text, p_access_role text DEFAULT NULL::text) RETURNS TABLE(item_id uuid, slug text, title text, item_type text, platform_role_key text, role_label text, status text, visibility text, verification_status text, primary_city text, primary_country_code text, owner_count bigint, editor_count bigint, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_query text := nullif(btrim(coalesce(p_query, '')), '');
  v_item_type text := nullif(btrim(coalesce(p_item_type, '')), '');
  v_role_key text := nullif(btrim(coalesce(p_role_key, '')), '');
  v_city text := nullif(btrim(coalesce(p_city, '')), '');
  v_country_code text := upper(nullif(btrim(coalesce(p_country_code, '')), ''));
  v_access_role text := nullif(btrim(coalesce(p_access_role, '')), '');
begin
  if v_actor_id is null or not public.is_moderator(v_actor_id) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  return query
  with primary_locations as (
    select distinct on (cil.item_id)
      cil.item_id,
      cil.city,
      cil.country_code
    from public.catalog_item_locations cil
    order by cil.item_id, cil.is_primary desc, cil.created_at asc
  ),
  access_summary as (
    select
      cim.item_id,
      count(*) filter (where cim.status = 'active' and cim.role = 'owner') as owner_count,
      count(*) filter (where cim.status = 'active' and cim.role in ('manager', 'editor')) as editor_count
    from public.catalog_item_managers cim
    group by cim.item_id
  )
  select
    ci.id as item_id,
    ci.slug,
    ci.title,
    ci.item_type,
    ci.platform_role_key,
    coalesce(r.label, ci.platform_role_key, ci.item_type) as role_label,
    ci.status,
    ci.visibility,
    ci.verification_status,
    pl.city as primary_city,
    pl.country_code as primary_country_code,
    coalesce(acc.owner_count, 0) as owner_count,
    coalesce(acc.editor_count, 0) as editor_count,
    ci.created_at
  from public.catalog_items ci
  left join public.roles r on r.key = ci.platform_role_key
  left join primary_locations pl on pl.item_id = ci.id
  left join access_summary acc on acc.item_id = ci.id
  where (v_item_type is null or ci.item_type = v_item_type)
    and (v_role_key is null or ci.platform_role_key = v_role_key)
    and (v_city is null or lower(coalesce(pl.city, '')) = lower(v_city))
    and (v_country_code is null or upper(coalesce(pl.country_code, '')) = v_country_code)
    and (
      v_access_role is null
      or exists (
        select 1
        from public.catalog_item_managers cim
        where cim.item_id = ci.id
          and cim.status = 'active'
          and cim.role = v_access_role
      )
    )
    and (
      v_query is null
      or ci.title ilike '%' || v_query || '%'
      or ci.slug ilike '%' || v_query || '%'
      or coalesce(ci.platform_role_key, '') ilike '%' || v_query || '%'
    )
  order by ci.updated_at desc, ci.title asc;
end;
$$;


--
-- Name: admin_list_member_catalog_profiles(text, text, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_member_catalog_profiles(p_query text DEFAULT NULL::text, p_provider text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_sort text DEFAULT 'created_desc'::text) RETURNS TABLE(item_id uuid, user_id uuid, email text, full_name text, profile_type text, auth_provider text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_query text := nullif(btrim(coalesce(p_query, '')), '');
  v_provider text := nullif(btrim(coalesce(p_provider, '')), '');
  v_sort text := coalesce(nullif(btrim(coalesce(p_sort, '')), ''), 'created_desc');
begin
  if v_actor_id is null or not public.is_moderator(v_actor_id) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  return query
  select
    ci.id as item_id,
    ci.linked_user_id as user_id,
    au.email::text,
    ci.title as full_name,
    coalesce(ci.platform_role_key, 'bireysel') as profile_type,
    (au.raw_app_meta_data ->> 'provider') as auth_provider,
    ci.created_at
  from public.catalog_items ci
  left join auth.users au on au.id = ci.linked_user_id
  where ci.item_type = 'member'
    and ci.linked_user_id is not null
    and (
      v_provider is null
      or v_provider = 'all'
      or (v_provider = 'unknown' and coalesce(au.raw_app_meta_data ->> 'provider', 'unknown') = 'unknown')
      or au.raw_app_meta_data ->> 'provider' = v_provider
    )
    and (p_from is null or ci.created_at >= p_from)
    and (p_to is null or ci.created_at < p_to)
    and (
      v_query is null
      or ci.title ilike '%' || v_query || '%'
      or coalesce(au.email::text, '') ilike '%' || v_query || '%'
    )
  order by
    case when v_sort = 'name_asc' then lower(ci.title) end asc nulls last,
    case when v_sort = 'created_asc' then ci.created_at end asc nulls last,
    case when v_sort = 'created_desc' then ci.created_at end desc nulls last,
    ci.created_at desc,
    ci.title asc;
end;
$$;


--
-- Name: admin_list_service_finder_jobs(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_service_finder_jobs(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := public.service_finder_require_admin();
  v_total bigint;
  v_rows jsonb;
begin
  select count(*) into v_total
  from public.service_finder_jobs
  where p_status is null or status = p_status;

  select coalesce(jsonb_agg(to_jsonb(j) order by j.created_at desc), '[]'::jsonb)
  into v_rows
  from (
    select id, title, status, role_key, item_type, location_label, city, country_code,
           language_code, soft_cap_usd, hard_cap_usd, cost_total_usd,
           search_requests, extract_requests, classify_requests,
           progress, last_error_code, created_at, started_at, finished_at
    from public.service_finder_jobs
    where p_status is null or status = p_status
    order by created_at desc
    limit greatest(1, least(coalesce(p_limit, 25), 100))
    offset greatest(0, coalesce(p_offset, 0))
  ) j;

  return jsonb_build_object('total', v_total, 'jobs', v_rows);
end;
$$;


--
-- Name: admin_list_unified_records(integer, integer, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_unified_records(p_page integer DEFAULT 1, p_page_size integer DEFAULT 50, p_kind text DEFAULT NULL::text, p_query text DEFAULT NULL::text, p_item_type text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_verification_status text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_country_code text DEFAULT NULL::text, p_platform_role_key text DEFAULT NULL::text) RETURNS TABLE(id uuid, kind text, slug text, item_type text, title text, summary text, status text, visibility text, verification_status text, platform_role_key text, primary_city text, primary_country_code text, category_labels text[], source_types text[], created_at timestamp with time zone, updated_at timestamp with time zone, profile_type text, email text, total_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
declare
  v_actor_id uuid := auth.uid();
  v_page_size integer := greatest(least(coalesce(p_page_size, 50), 100), 1);
  v_offset integer := (greatest(coalesce(p_page, 1), 1) - 1) * greatest(least(coalesce(p_page_size, 50), 100), 1);
  v_query text := nullif(btrim(coalesce(p_query, '')), '');
  v_kind text := nullif(btrim(coalesce(p_kind, '')), '');
  v_item_type text := nullif(btrim(coalesce(p_item_type, '')), '');
  v_status text := nullif(btrim(coalesce(p_status, '')), '');
  v_verification_status text := nullif(btrim(coalesce(p_verification_status, '')), '');
  v_city text := nullif(btrim(coalesce(p_city, '')), '');
  v_country_code text := nullif(btrim(coalesce(p_country_code, '')), '');
  v_platform_role_key text := nullif(btrim(coalesce(p_platform_role_key, '')), '');
begin
  if v_actor_id is null or not public.is_moderator(v_actor_id) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  return query
  with catalog_rows as (
    select
      ci.id,
      case when ci.linked_user_id is not null then 'member_profile' else 'catalog_item' end::text as kind,
      ci.slug,
      ci.item_type,
      ci.title,
      coalesce(ci.short_description, ci.headline, left(ci.long_description, 240)) as summary,
      ci.status,
      ci.visibility,
      ci.verification_status,
      ci.platform_role_key,
      primary_location.city as primary_city,
      primary_location.country_code as primary_country_code,
      coalesce(category_names.category_labels, '{}'::text[]) as category_labels,
      coalesce(source_names.source_types, '{}'::text[]) as source_types,
      ci.created_at,
      ci.updated_at,
      ci.platform_role_key as profile_type,
      member_email.email::text as email,
      concat_ws(
        ' ',
        ci.title,
        ci.slug,
        ci.headline,
        ci.short_description,
        ci.platform_role_key,
        primary_location.city,
        primary_location.country_code,
        array_to_string(coalesce(category_names.category_labels, '{}'::text[]), ' '),
        array_to_string(coalesce(source_names.source_types, '{}'::text[]), ' '),
        member_email.email
      ) as search_text
    from public.catalog_items ci
    left join lateral (
      select cil.city, cil.country_code
      from public.catalog_item_locations cil
      where cil.item_id = ci.id
      order by cil.is_primary desc, cil.created_at asc
      limit 1
    ) primary_location on true
    left join lateral (
      select array_agg(cc.name order by cic.is_primary desc, cc.name asc) as category_labels
      from public.catalog_item_categories cic
      join public.catalog_categories cc on cc.id = cic.category_id
      where cic.item_id = ci.id
    ) category_names on true
    left join lateral (
      select array_agg(distinct sr.source_type order by sr.source_type) as source_types
      from public.source_records sr
      where sr.item_id = ci.id
    ) source_names on true
    left join lateral (
      select au.email
      from auth.users au
      where au.id = ci.linked_user_id
      limit 1
    ) member_email on true
  ),
  filtered as (
    select catalog_rows.*
    from catalog_rows
    where (v_kind is null or catalog_rows.kind = v_kind)
      and (v_item_type is null or catalog_rows.item_type = v_item_type)
      and (v_status is null or catalog_rows.status = v_status)
      and (v_verification_status is null or catalog_rows.verification_status = v_verification_status)
      and (v_city is null or lower(coalesce(catalog_rows.primary_city, '')) = lower(v_city))
      and (v_country_code is null or lower(coalesce(catalog_rows.primary_country_code, '')) = lower(v_country_code))
      and (v_platform_role_key is null or catalog_rows.platform_role_key = v_platform_role_key)
      and (
        v_query is null
        or catalog_rows.search_text ilike '%' || v_query || '%'
      )
  ),
  paged as (
    select
      filtered.*,
      count(*) over() as total_count
    from filtered
    order by filtered.created_at desc, filtered.title asc
    offset v_offset
    limit v_page_size
  )
  select
    paged.id,
    paged.kind,
    paged.slug,
    paged.item_type,
    paged.title,
    paged.summary,
    paged.status,
    paged.visibility,
    paged.verification_status,
    paged.platform_role_key,
    paged.primary_city,
    paged.primary_country_code,
    paged.category_labels,
    paged.source_types,
    paged.created_at,
    paged.updated_at,
    paged.profile_type,
    paged.email,
    paged.total_count
  from paged;
end;
$$;


--
-- Name: admin_moderate_cadde_entity_v1(text, uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_moderate_cadde_entity_v1(p_entity_type text, p_entity_id uuid, p_action text, p_note text DEFAULT NULL::text, p_ban_days integer DEFAULT 7) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_note text := nullif(trim(coalesce(p_note, '')), '');
  v_owner uuid;
begin
  if not public.is_cadde_moderator(v_uid) then
    raise exception 'cadde_moderation_permission_denied';
  end if;

  if p_entity_type not in ('post', 'comment', 'cafe', 'carsi_item') then
    raise exception 'cadde_invalid_report_entity';
  end if;

  if p_action not in ('dismiss', 'hide', 'publish', 'ban_owner', 'unban_owner') then
    raise exception 'cadde_invalid_moderation_action';
  end if;

  v_owner := case p_entity_type
    when 'post' then (select author_user_id from public.cadde_posts where id = p_entity_id)
    when 'comment' then (select user_id from public.cadde_post_comments where id = p_entity_id)
    when 'cafe' then (select host_user_id from public.cadde_cafes where id = p_entity_id)
    when 'carsi_item' then (select owner_user_id from public.carsi_items where id = p_entity_id)
  end;
  if v_owner is null and p_action <> 'dismiss' then
    raise exception 'cadde_entity_not_found';
  end if;

  if p_action = 'hide' then
    case p_entity_type
      when 'post' then update public.cadde_posts set status = 'hidden' where id = p_entity_id;
      when 'comment' then delete from public.cadde_post_comments where id = p_entity_id;
      when 'cafe' then update public.cadde_cafes set status = 'hidden', is_active = false, archived_at = coalesce(archived_at, now()) where id = p_entity_id;
      when 'carsi_item' then update public.carsi_items set moderation_status = 'rejected', status = 'paused', updated_at = now() where id = p_entity_id;
    end case;
  elsif p_action = 'publish' then
    case p_entity_type
      when 'post' then update public.cadde_posts set status = 'published' where id = p_entity_id;
      when 'comment' then null; -- silinen yorum geri getirilemez
      when 'cafe' then update public.cadde_cafes set status = 'published' where id = p_entity_id;
      when 'carsi_item' then update public.carsi_items set moderation_status = 'approved', status = 'published', updated_at = now() where id = p_entity_id;
    end case;
  elsif p_action = 'ban_owner' then
    insert into public.cadde_user_bans (user_id, scope, reason, ends_at, created_by)
    values (v_owner, 'cadde', coalesce(v_note, 'moderasyon aksiyonu'),
            case when coalesce(p_ban_days, 0) > 0 then now() + make_interval(days => p_ban_days) end,
            v_uid);
  elsif p_action = 'unban_owner' then
    update public.cadde_user_bans
    set ends_at = now()
    where user_id = v_owner and scope = 'cadde'
      and starts_at <= now() and (ends_at is null or ends_at > now());
  end if;

  -- Açık kuyruk kayıtlarını kapat (audit notu ile).
  update public.cadde_moderation_queue
  set status = 'resolved', resolved_at = now(), resolved_by = v_uid,
      resolution_note = coalesce(v_note, p_action)
  where entity_type = p_entity_type and entity_id = p_entity_id and status = 'open';

  if p_action in ('hide', 'ban_owner') then
    perform public.cadde_notify(
      v_owner, v_uid, 'cadde.moderation.action',
      case when p_action = 'hide' then 'İçeriğin moderasyon tarafından gizlendi' else 'Hesabına Cadde kısıtlaması uygulandı' end,
      coalesce(v_note, 'Topluluk kurallarını ihlal eden içerik.'),
      p_entity_type, p_entity_id,
      jsonb_build_object('action', p_action)
    );
  end if;
end;
$$;


--
-- Name: admin_promote_relocation_model(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_promote_relocation_model(p_model_version text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'rl_admin_required';
  end if;
  if not exists (select 1 from public.relocation_rank_models where model_version = p_model_version) then
    raise exception 'rl_model_not_found';
  end if;
  update public.relocation_rank_models set is_active = false where is_active;
  update public.relocation_rank_models
  set is_active = true, activated_at = now()
  where model_version = p_model_version;
end;
$$;


--
-- Name: admin_publish_relocation_candidate(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_publish_relocation_candidate(p_candidate_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_cand public.relocation_candidates%rowtype;
  v_p jsonb;
  v_entity_id uuid;
begin
  if not public.is_admin(v_uid) then
    raise exception 'rl_admin_required';
  end if;
  select * into v_cand from public.relocation_candidates where id = p_candidate_id;
  if not found then
    raise exception 'rl_candidate_not_found';
  end if;
  if v_cand.review_status not in ('approved', 'needs_edit') then
    raise exception 'rl_candidate_not_approved';
  end if;
  v_p := v_cand.normalized_payload;

  if v_cand.target_kind = 'service' then
    insert into public.relocation_services
      (category, provider_name, country_code, city_code, plan_name, price_min, price_max,
       currency, languages, website_url, appointment_url, source_id, trust_score, freshness_at)
    values (
      v_p ->> 'category', v_p ->> 'provider_name', v_p ->> 'country_code', v_p ->> 'city_code',
      v_p ->> 'plan_name', nullif(v_p ->> 'price_min','')::numeric, nullif(v_p ->> 'price_max','')::numeric,
      v_p ->> 'currency',
      coalesce(array(select jsonb_array_elements_text(v_p -> 'languages')), '{}'::text[]),
      v_p ->> 'website_url', v_p ->> 'appointment_url',
      (select id from public.relocation_source_registry where id = (v_p ->> 'source_id')::uuid),
      coalesce((v_p ->> 'trust_score')::numeric, 0.3), now()
    )
    returning id into v_entity_id;
  elsif v_cand.target_kind = 'bureaucratic_step' then
    insert into public.relocation_bureaucratic_steps
      (country_code, city_code, name, description, trigger, deadline_rule, required_documents,
       official_url_label, official_url, source_id)
    values (
      v_p ->> 'country_code', v_p ->> 'city_code', v_p ->> 'name', v_p ->> 'description',
      coalesce(v_p ->> 'trigger', 'after_arrival'), v_p ->> 'deadline_rule',
      coalesce(array(select jsonb_array_elements_text(v_p -> 'required_documents')), '{}'::text[]),
      v_p ->> 'official_url_label', v_p ->> 'official_url',
      (v_p ->> 'source_id')::uuid
    )
    returning id into v_entity_id;
  elsif v_cand.target_kind = 'emergency_contact' then
    insert into public.relocation_emergency_contacts
      (country_code, city_code, type, label, phone, url, source_id)
    values (
      v_p ->> 'country_code', v_p ->> 'city_code', v_p ->> 'type', v_p ->> 'label',
      v_p ->> 'phone', v_p ->> 'url', (v_p ->> 'source_id')::uuid
    )
    returning id into v_entity_id;
  else
    raise exception 'rl_unknown_target_kind';
  end if;

  update public.relocation_candidates
  set review_status = 'published', published_entity_id = v_entity_id, published_at = now(), updated_at = now()
  where id = p_candidate_id;

  return v_entity_id;
end;
$$;


--
-- Name: admin_publish_service_finder_candidate(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_publish_service_finder_candidate(p_candidate_id uuid, p_patch jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := public.service_finder_require_admin();
  v_c public.service_finder_candidates%rowtype;
  v_job public.service_finder_jobs%rowtype;
  v_category_slug text;
  v_category_id uuid;
  v_slug text;
  v_item_id uuid;
  v_headline text;
  v_description text;
  v_contact jsonb;
  v_idx int := 0;
  v_lang text;
  v_service text;
  v_tag text;
  v_tags text[];
  v_appointment text;
  v_source_url text;
BEGIN
  -- Onaylı adayı kilitle
  SELECT * INTO v_c FROM public.service_finder_candidates WHERE id = p_candidate_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'sf_candidate_not_found';
  END IF;
  IF v_c.review_status = 'published' THEN
    RAISE EXCEPTION 'sf_candidate_already_published';
  END IF;

  -- Yayın öncesi son düzenlemeler (review ile aynı alanlar)
  IF p_patch <> '{}'::jsonb THEN
    PERFORM public.admin_review_service_finder_candidate(p_candidate_id, 'approved', p_patch);
    SELECT * INTO v_c FROM public.service_finder_candidates WHERE id = p_candidate_id;
  END IF;

  IF v_c.review_status <> 'approved' THEN
    RAISE EXCEPTION 'sf_candidate_not_approved';
  END IF;

  SELECT * INTO v_job FROM public.service_finder_jobs WHERE id = v_c.job_id;

  -- Kategori çözümle (importer: ensureCatalogCategory)
  v_category_slug := coalesce(v_c.category_slug, v_job.category_slug);
  IF v_category_slug IS NULL THEN
    RAISE EXCEPTION 'sf_category_required';
  END IF;

  SELECT id INTO v_category_id FROM public.catalog_categories WHERE slug = v_category_slug;
  IF v_category_id IS NULL THEN
    INSERT INTO public.catalog_categories (module, slug, name, description, is_active, sort_order)
    VALUES (
      v_c.item_type,
      v_category_slug,
      coalesce(v_c.profession_label, v_category_slug),
      coalesce(v_c.profession_label, v_category_slug) || ' category for ' || v_c.item_type,
      true,
      1000
    )
    RETURNING id INTO v_category_id;
  END IF;

  -- Slug: importer deseni [city, roleLabel, title]
  v_slug := public.service_finder_slugify(
    concat_ws(' ', v_c.city, coalesce(v_c.profession_label, v_c.role_key), v_c.canonical_name)
  );
  IF v_slug IS NULL OR v_slug = '' THEN
    RAISE EXCEPTION 'sf_slug_generation_failed';
  END IF;

  v_headline := coalesce(
    nullif(array_to_string(v_c.services, ', '), ''),
    v_c.profession_label,
    v_c.role_key
  );
  v_description := concat_ws(' ',
    v_c.canonical_name,
    CASE WHEN v_c.city IS NOT NULL THEN v_c.city || ' lokasyonunda' END,
    v_c.profession_label,
    CASE WHEN array_length(v_c.services, 1) > 0 THEN '(' || array_to_string(v_c.services, ', ') || ')' END
  );
  v_source_url := coalesce(
    v_c.website_url,
    (SELECT s.source_url FROM public.service_finder_job_sources s WHERE s.id = v_c.primary_source_id)
  );

  -- Kanonik upsert
  v_item_id := public.catalog_upsert_source_item(
    p_source_type => 'service_finder',
    p_external_id => v_c.id::text,
    p_item_type => v_c.item_type,
    p_slug => v_slug,
    p_title => v_c.canonical_name,
    p_headline => v_headline,
    p_short_description => v_description,
    p_long_description => v_description || ' Service Finder taraması ile bulunmuş, admin onayı sonrası yayınlanmıştır.',
    p_status => 'published',
    p_visibility => 'public',
    p_verification_status => 'unverified',
    p_created_by_user_id => v_uid,
    p_published_at => now(),
    p_attributes => jsonb_build_object(
      'import_source', 'service_finder',
      'source_label', 'Service Finder',
      'platform_role_label', coalesce(v_c.profession_label, v_c.role_key),
      'service_finder_job_id', v_c.job_id,
      'service_finder_candidate_id', v_c.id,
      'confidence_score', v_c.confidence_score
    ),
    p_source_url => v_source_url,
    p_raw_snapshot => v_c.normalized_payload,
    p_platform_role_key => v_c.role_key
  );

  PERFORM public.catalog_reset_item_projection(v_item_id);

  -- Uydu tablolar (importer sırası ve alan değerleriyle birebir)
  INSERT INTO public.catalog_item_categories (item_id, category_id, is_primary)
  VALUES (v_item_id, v_category_id, true)
  ON CONFLICT (item_id, category_id) DO UPDATE SET is_primary = excluded.is_primary;

  FOR v_contact IN SELECT value FROM jsonb_array_elements(coalesce(v_c.contacts, '[]'::jsonb))
  LOOP
    IF nullif(v_contact ->> 'value', '') IS NOT NULL THEN
      INSERT INTO public.catalog_item_contacts
        (item_id, contact_type, contact_value, label, is_primary, is_public, sort_order)
      VALUES
        (v_item_id,
         coalesce(nullif(v_contact ->> 'type', ''), 'website'),
         v_contact ->> 'value',
         nullif(v_contact ->> 'label', ''),
         coalesce((v_contact ->> 'is_primary')::boolean, v_idx = 0),
         true,
         v_idx * 10);
      v_idx := v_idx + 1;
    END IF;
  END LOOP;

  INSERT INTO public.catalog_item_locations
    (item_id, country_code, region, city, address_line, postal_code, latitude, longitude, is_primary)
  VALUES
    (v_item_id, v_c.country_code, v_c.region, v_c.city, v_c.address_line, null, null, null, true);

  v_idx := 0;
  FOREACH v_lang IN ARRAY coalesce(v_c.languages, '{}'::text[])
  LOOP
    INSERT INTO public.catalog_item_languages (item_id, language_code, proficiency, is_primary)
    VALUES (v_item_id, v_lang, CASE WHEN v_idx = 0 THEN 'native_or_fluent' ELSE 'professional' END, v_idx = 0)
    ON CONFLICT (item_id, language_code) DO NOTHING;
    v_idx := v_idx + 1;
  END LOOP;

  v_idx := 0;
  FOREACH v_service IN ARRAY coalesce(v_c.services, '{}'::text[])
  LOOP
    INSERT INTO public.catalog_item_services
      (item_id, service_slug, service_name, description, is_public, sort_order)
    VALUES
      (v_item_id, public.service_finder_slugify(v_service), v_service, null, true, v_idx * 10)
    ON CONFLICT (item_id, service_slug) DO NOTHING;
    v_idx := v_idx + 1;
  END LOOP;

  SELECT coalesce(array_agg(t), '{}'::text[]) INTO v_tags
  FROM unnest(array[
    coalesce(v_c.profession_label, v_c.role_key), v_c.city, v_c.country_code
  ]) AS t WHERE t IS NOT NULL AND t <> '';

  FOREACH v_tag IN ARRAY v_tags
  LOOP
    INSERT INTO public.catalog_item_tags (item_id, tag_slug, tag_label)
    VALUES (v_item_id, public.service_finder_slugify(v_tag), v_tag)
    ON CONFLICT (item_id, tag_slug) DO NOTHING;
  END LOOP;

  -- item_type'a göre uzantı tablosu (importer: upsertExtensionRecord)
  v_appointment := coalesce(
    v_c.appointment_url,
    (SELECT c ->> 'value' FROM jsonb_array_elements(coalesce(v_c.contacts, '[]'::jsonb)) c
      WHERE c ->> 'type' = 'appointment_url' LIMIT 1)
  );

  IF v_c.item_type = 'advisor' THEN
    INSERT INTO public.advisor_details
      (item_id, consultation_modes, languages, supports_online_consultation, appointment_url)
    VALUES
      (v_item_id, array['in_person'], v_c.languages, false, v_appointment)
    ON CONFLICT (item_id) DO UPDATE
      SET languages = excluded.languages, appointment_url = excluded.appointment_url;
  ELSIF v_c.item_type = 'business' THEN
    INSERT INTO public.business_details (item_id, supports_online_booking, appointment_url)
    VALUES (v_item_id, false, v_appointment)
    ON CONFLICT (item_id) DO UPDATE SET appointment_url = excluded.appointment_url;
  ELSIF v_c.item_type = 'organization' THEN
    INSERT INTO public.organization_details (item_id, organization_kind, metadata)
    VALUES (v_item_id, coalesce(v_c.profession_label, v_c.role_key), v_c.normalized_payload)
    ON CONFLICT (item_id) DO UPDATE
      SET organization_kind = excluded.organization_kind, metadata = excluded.metadata;
  END IF;

  -- Aday durumunu yayınlandı yap
  UPDATE public.service_finder_candidates
  SET review_status = 'published',
      catalog_item_id = v_item_id,
      published_at = now(),
      reviewed_by_user_id = v_uid,
      reviewed_at = now(),
      updated_at = now()
  WHERE id = p_candidate_id;

  INSERT INTO public.service_finder_job_events (job_id, candidate_id, event_type, message, event_payload)
  VALUES (v_c.job_id, p_candidate_id, 'candidate_published',
          'Aday kataloğa yayınlandı.',
          jsonb_build_object('catalog_item_id', v_item_id, 'published_by', v_uid));

  RETURN jsonb_build_object(
    'candidate_id', p_candidate_id,
    'catalog_item_id', v_item_id,
    'review_status', 'published'
  );
END;
$$;


