-- Name: admin_remove_catalog_item_editor(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_remove_catalog_item_editor(p_item_id uuid, p_user_id uuid, p_role text DEFAULT 'editor'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  update public.catalog_item_managers
  set
    status = 'revoked',
    updated_at = now()
  where item_id = p_item_id
    and user_id = p_user_id
    and role = p_role;

  perform public.write_admin_audit_log(
    'catalog.editor_removed',
    p_user_id,
    'catalog_item',
    p_item_id,
    null,
    jsonb_build_object('role', p_role)
  );
end;
$$;


