--
-- Name: admin_replace_resource_entries_from_csv(jsonb, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_replace_resource_entries_from_csv(payload jsonb, expected_count integer, batch_id text) RETURNS TABLE(inserted_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_inserted integer := 0;
begin
  if not public.is_admin(auth.uid()) and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'forbidden'
      using errcode = '42501';
  end if;

  if payload is null or jsonb_typeof(payload) <> 'array' then
    raise exception 'payload must be a json array'
      using errcode = '22023';
  end if;

  if expected_count is null or expected_count < 0 then
    raise exception 'expected_count must be a non-negative integer'
      using errcode = '22023';
  end if;

  if expected_count <> jsonb_array_length(payload) then
    raise exception 'expected_count mismatch'
      using errcode = '22023';
  end if;

  if batch_id is null or btrim(batch_id) = '' then
    raise exception 'batch_id is required'
      using errcode = '22023';
  end if;

  delete from public.resource_entries
  where id is not null;

  insert into public.resource_entries (
    order_no,
    slug,
    section,
    subsection,
    department,
    record_kind,
    added_by,
    title,
    description,
    url,
    file_id,
    file_type,
    mime_type,
    privacy_level,
    is_public_import,
    import_suggestion,
    tags,
    source_path,
    status,
    source_folder,
    source_subfolder,
    source_snapshot_date,
    import_batch,
    storage_bucket,
    storage_path,
    file_name,
    person_first_name,
    person_last_name,
    person_role,
    linkedin_url,
    instagram_url,
    website_url
  )
  select
    t.order_no,
    t.slug,
    t.section,
    t.subsection,
    t.department,
    t.record_kind,
    t.added_by,
    t.title,
    t.description,
    t.url,
    t.file_id,
    t.file_type,
    t.mime_type,
    t.privacy_level,
    t.is_public_import,
    t.import_suggestion,
    t.tags,
    t.source_path,
    t.status,
    t.source_folder,
    t.source_subfolder,
    t.source_snapshot_date,
    batch_id,
    null,
    null,
    null,
    null,
    null,
    null,
    null,
    null,
    null
  from jsonb_to_recordset(payload) as t(
    order_no integer,
    slug text,
    section text,
    subsection text,
    department text,
    record_kind text,
    added_by text,
    title text,
    description text,
    url text,
    file_id text,
    file_type text,
    mime_type text,
    privacy_level text,
    is_public_import boolean,
    import_suggestion text,
    tags text,
    source_path text,
    status text,
    source_folder text,
    source_subfolder text,
    source_snapshot_date date
  )
  where coalesce(btrim(t.title), '') <> '';

  get diagnostics v_inserted = row_count;

  if v_inserted <> expected_count then
    raise exception 'inserted_count mismatch: expected %, got %', expected_count, v_inserted
      using errcode = 'P0001';
  end if;

  return query select v_inserted;
end;
$$;


--
-- Name: admin_retry_service_finder_job(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_retry_service_finder_job(p_job_id uuid, p_patch jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := public.service_finder_require_admin();
  v_status text;
begin
  select status into v_status from public.service_finder_jobs where id = p_job_id for update;
  if not found then
    raise exception 'sf_job_not_found';
  end if;
  if v_status not in ('failed', 'cancelled', 'budget_stopped') then
    raise exception 'sf_job_not_retryable';
  end if;

  update public.service_finder_jobs
  set status = 'queued',
      run_after = now(),
      locked_by = null,
      lease_expires_at = null,
      finished_at = null,
      cancelled_at = null,
      last_error_code = null,
      last_error_message = null,
      soft_cap_usd = coalesce((p_patch ->> 'soft_cap_usd')::numeric, soft_cap_usd),
      hard_cap_usd = coalesce((p_patch ->> 'hard_cap_usd')::numeric, hard_cap_usd),
      updated_at = now()
  where id = p_job_id;

  insert into public.service_finder_job_events (job_id, event_type, message, event_payload)
  values (p_job_id, 'job_retried', 'İş yeniden kuyruğa alındı.', jsonb_build_object('retried_by', v_uid, 'patch', p_patch));

  return jsonb_build_object('job_id', p_job_id, 'status', 'queued');
end;
$$;


--
-- Name: admin_review_approval_request(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_review_approval_request(request_id uuid, decision text, note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request public.approval_requests%rowtype;
  v_attribute public.afs_attributes%rowtype;
  v_attribute_value jsonb;
  v_visibility text;
  v_value_text text;
  v_new_item_id uuid;
  v_new_role_id uuid;
  v_new_slug text;
  v_new_title text;
  v_new_role_key text;
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if decision not in ('approved', 'rejected') then
    raise exception 'invalid decision' using errcode = '22023';
  end if;

  select * into v_request
  from public.approval_requests
  where id = request_id
  limit 1;

  if v_request.id is null then
    raise exception 'approval request not found' using errcode = 'P0002';
  end if;

  if v_request.status <> 'pending' then
    raise exception 'approval request is not pending' using errcode = '22023';
  end if;

  if decision = 'approved' then
    if v_request.request_type = 'role_change' then
      perform public.admin_set_user_role(v_request.user_id, v_request.target_role_key);
    elsif v_request.request_type = 'new_profile' then
      v_new_role_key := v_request.payload ->> 'role_key';
      v_new_title := nullif(btrim(coalesce(v_request.payload ->> 'title', '')), '');

      if v_new_title is null then
        v_new_title := 'CorteQS Üyesi';
      end if;

      select id into v_new_role_id
      from public.roles
      where key = v_new_role_key and is_active = true
      limit 1;

      if v_new_role_id is null then
        raise exception 'target role no longer valid' using errcode = '22023';
      end if;

      v_new_slug := 'profile-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 16);

      insert into public.catalog_items (
        item_type,
        slug,
        title,
        status,
        visibility,
        verification_status,
        linked_user_id,
        created_by,
        platform_role_key,
        attributes,
        published_at
      ) values (
        'member',
        v_new_slug,
        v_new_title,
        'published',
        'public',
        'claimed',
        v_request.user_id,
        v_request.user_id,
        v_new_role_key,
        jsonb_build_object('bridge_source', 'new_profile_request', 'platform_role_key', v_new_role_key),
        now()
      )
      returning id into v_new_item_id;

      insert into public.catalog_item_roles (catalog_item_id, role_id, is_primary)
      values (v_new_item_id, v_new_role_id, true)
      on conflict (catalog_item_id, role_id) do nothing;

      insert into public.catalog_item_managers (item_id, user_id, role, status)
      values (v_new_item_id, v_request.user_id, 'owner', 'active')
      on conflict (item_id, user_id, role) do update
      set status = 'active', updated_at = now();

      perform public.write_admin_audit_log(
        'catalog_item.new_profile_approved',
        v_request.user_id,
        'catalog_item',
        v_new_item_id,
        null,
        v_request.payload
      );
    elsif v_request.request_type = 'attribute_change' then
      select * into v_attribute
      from public.afs_attributes
      where key = v_request.payload ->> 'attribute_key'
      limit 1;

      v_attribute_value := v_request.payload -> 'attribute_value';
      v_visibility := coalesce(v_request.payload ->> 'visibility', 'private');
      v_value_text := nullif(btrim(coalesce(v_attribute_value #>> '{}', '')), '');

      if v_attribute.key = 'full_name' then
        insert into public.user_profile_attributes (
          user_id,
          attribute_id,
          value_text,
          value_json,
          visibility,
          approval_status,
          approved_by,
          approved_at,
          updated_at
        ) values (
          v_request.user_id,
          v_attribute.id,
          v_value_text,
          null,
          'public',
          'approved',
          auth.uid(),
          now(),
          now()
        )
        on conflict (user_id, attribute_id) do update
        set
          value_text = excluded.value_text,
          value_json = null,
          visibility = excluded.visibility,
          approval_status = 'approved',
          approved_by = excluded.approved_by,
          approved_at = excluded.approved_at,
          updated_at = now();
      else
        insert into public.user_profile_attributes (
          user_id,
          attribute_id,
          value_text,
          value_json,
          visibility,
          approval_status,
          approved_by,
          approved_at,
          updated_at
        ) values (
          v_request.user_id,
          v_attribute.id,
          case when v_attribute.data_type in ('text','textarea','select','url','phone') then v_value_text else null end,
          case when v_attribute.data_type in ('multi_select','boolean','json') then v_attribute_value else null end,
          v_visibility,
          'approved',
          auth.uid(),
          now(),
          now()
        )
        on conflict (user_id, attribute_id) do update
        set
          value_text = excluded.value_text,
          value_json = excluded.value_json,
          visibility = excluded.visibility,
          approval_status = 'approved',
          approved_by = excluded.approved_by,
          approved_at = excluded.approved_at,
          updated_at = now();
      end if;

      perform public.write_admin_audit_log(
        'attribute.value_approved',
        v_request.user_id,
        'attribute',
        null,
        null,
        v_request.payload
      );
    elsif v_request.request_type in ('directory_visibility','contact_visibility','featured_listing','event_create','offer_create','referral_create','city_manage') then
      if v_request.target_feature_key is not null then
        perform public.admin_set_user_feature_override_detailed(
          v_request.user_id,
          v_request.target_feature_key,
          true,
          coalesce(note, 'approval_request:' || v_request.id::text)
        );
      end if;
    end if;
  elsif v_request.request_type = 'attribute_change' then
    perform public.write_admin_audit_log(
      'attribute.value_rejected',
      v_request.user_id,
      'attribute',
      null,
      null,
      v_request.payload
    );
  end if;

  update public.approval_requests
  set
    status = decision,
    admin_note = note,
    reviewed_by = auth.uid(),
    reviewed_at = now(),
    updated_at = now()
  where id = request_id;

  perform public.write_admin_audit_log(
    case when decision = 'approved' then 'approval.approved' else 'approval.rejected' end,
    v_request.user_id,
    'approval_request',
    v_request.id,
    to_jsonb(v_request),
    jsonb_build_object('status', decision, 'admin_note', note)
  );
end;
$$;


--
-- Name: FUNCTION admin_review_approval_request(request_id uuid, decision text, note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_review_approval_request(request_id uuid, decision text, note text) IS 'Secondary profile request 2026-07-23: added new_profile branch (creates catalog_items + catalog_item_roles + catalog_item_managers on approval).';


--
-- Name: admin_review_cadde_promotion_v1(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_review_cadde_promotion_v1(p_campaign_id uuid, p_approve boolean, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_campaign public.cadde_promotion_campaigns%rowtype;
begin
  if v_uid is null or not (public.is_admin(v_uid) or public.is_moderator(v_uid)) then
    raise exception 'cadde_admin_required';
  end if;

  select * into v_campaign from public.cadde_promotion_campaigns where id = p_campaign_id;
  if v_campaign.id is null then
    raise exception 'cadde_promotion_not_found';
  end if;
  if v_campaign.status <> 'pending' then
    raise exception 'cadde_promotion_not_pending';
  end if;

  update public.cadde_promotion_campaigns
  set status = case when p_approve then 'approved' else 'rejected' end,
      approved_at = case when p_approve then now() end,
      approved_by = v_uid,
      review_note = nullif(trim(coalesce(p_note, '')), ''),
      updated_at = now()
  where id = p_campaign_id;

  perform public.cadde_notify(
    v_campaign.owner_user_id, v_uid, 'cadde.promotion.approved',
    case when p_approve then 'Tanıtım kampanyan onaylandı' else 'Tanıtım kampanyan reddedildi' end,
    v_campaign.title,
    'promotion', p_campaign_id,
    jsonb_build_object('approved', p_approve, 'note', nullif(trim(coalesce(p_note, '')), ''))
  );
end;
$$;


--
-- Name: admin_review_catalog_import(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_review_catalog_import(p_item_id uuid, p_decision text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor   uuid := auth.uid();
  v_item    public.catalog_items%rowtype;
  v_before  jsonb;
begin
  if v_actor is null or not public.is_moderator(v_actor) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if p_decision not in ('approved', 'rejected') then
    raise exception 'geçersiz karar: % (approved|rejected)', p_decision using errcode = '22023';
  end if;

  select * into v_item from public.catalog_items where id = p_item_id limit 1;
  if v_item.id is null then
    raise exception 'item bulunamadı: %', p_item_id using errcode = 'P0002';
  end if;

  -- Güvenlik: yalnız import kaynaklı (provenance tag taşıyan) item'lar review edilir.
  if coalesce(v_item.attributes ->> 'import_source', '') = '' then
    raise exception 'bu item bir içe aktarma kaydı değil' using errcode = '22023';
  end if;

  v_before := jsonb_build_object('status', v_item.status, 'visibility', v_item.visibility);

  if p_decision = 'approved' then
    update public.catalog_items
    set status = 'published', visibility = 'public', published_at = coalesce(published_at, now()), updated_at = now()
    where id = p_item_id;

    update public.catalog_item_attribute_values
    set approval_status = 'approved', approved_at = now(), updated_at = now()
    where item_id = p_item_id and approval_status = 'pending';
  else
    update public.catalog_items
    set status = 'rejected', visibility = 'private', updated_at = now()
    where id = p_item_id;
  end if;

  insert into public.catalog_audit_logs (item_id, actor_user_id, action, details, before_data, after_data)
  values (
    p_item_id, v_actor, 'import_review',
    jsonb_build_object('decision', p_decision, 'note', p_note),
    v_before,
    jsonb_build_object(
      'status',     case when p_decision = 'approved' then 'published' else 'rejected' end,
      'visibility', case when p_decision = 'approved' then 'public' else 'private' end
    )
  );

  return jsonb_build_object('item_id', p_item_id, 'decision', p_decision);
end;
$$;


--
-- Name: FUNCTION admin_review_catalog_import(p_item_id uuid, p_decision text, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_review_catalog_import(p_item_id uuid, p_decision text, p_note text) IS 'Moderator-gated içe aktarma onayı: approved -> published+public (+attribute approved); rejected -> rejected+private. Sadece import_source provenance taşıyan item''larda çalışır.';


--
-- Name: admin_review_relocation_candidate(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_review_relocation_candidate(p_candidate_id uuid, p_action text, p_notes text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'rl_admin_required';
  end if;
  if p_action not in ('approved', 'rejected', 'needs_edit') then
    raise exception 'rl_invalid_review_action';
  end if;
  update public.relocation_candidates
  set review_status = p_action, review_notes = p_notes, updated_at = now()
  where id = p_candidate_id;
end;
$$;


--
-- Name: admin_review_service_finder_candidate(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_review_service_finder_candidate(p_candidate_id uuid, p_action text, p_patch jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := public.service_finder_require_admin();
  v_status text;
begin
  if p_action not in ('approved', 'rejected', 'needs_edit', 'pending') then
    raise exception 'sf_invalid_review_action';
  end if;

  select review_status into v_status
  from public.service_finder_candidates where id = p_candidate_id for update;
  if not found then
    raise exception 'sf_candidate_not_found';
  end if;
  if v_status = 'published' then
    raise exception 'sf_candidate_already_published';
  end if;

  update public.service_finder_candidates
  set review_status = p_action,
      review_notes = case when p_patch ? 'review_notes' then nullif(p_patch ->> 'review_notes', '') else review_notes end,
      canonical_name = coalesce(nullif(p_patch ->> 'canonical_name', ''), canonical_name),
      profession_label = case when p_patch ? 'profession_label' then nullif(p_patch ->> 'profession_label', '') else profession_label end,
      organization_name = case when p_patch ? 'organization_name' then nullif(p_patch ->> 'organization_name', '') else organization_name end,
      category_slug = case when p_patch ? 'category_slug' then nullif(p_patch ->> 'category_slug', '') else category_slug end,
      country_code = case when p_patch ? 'country_code' then nullif(p_patch ->> 'country_code', '') else country_code end,
      region = case when p_patch ? 'region' then nullif(p_patch ->> 'region', '') else region end,
      city = case when p_patch ? 'city' then nullif(p_patch ->> 'city', '') else city end,
      address_line = case when p_patch ? 'address_line' then nullif(p_patch ->> 'address_line', '') else address_line end,
      languages = case when p_patch ? 'languages' then public.service_finder_text_array(p_patch -> 'languages') else languages end,
      services = case when p_patch ? 'services' then public.service_finder_text_array(p_patch -> 'services') else services end,
      contacts = coalesce(p_patch -> 'contacts', contacts),
      website_url = case when p_patch ? 'website_url' then nullif(p_patch ->> 'website_url', '') else website_url end,
      appointment_url = case when p_patch ? 'appointment_url' then nullif(p_patch ->> 'appointment_url', '') else appointment_url end,
      reviewed_by_user_id = v_uid,
      reviewed_at = now(),
      updated_at = now()
  where id = p_candidate_id;

  return jsonb_build_object('candidate_id', p_candidate_id, 'review_status', p_action);
end;
$$;


--
-- Name: admin_revoke_catalog_editor(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_revoke_catalog_editor(p_item_id uuid, p_target_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor_id uuid := auth.uid();
begin
  if v_actor_id is null or not public.is_moderator(v_actor_id) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  update public.catalog_item_managers
  set status = 'revoked',
      updated_at = now()
  where item_id = p_item_id
    and user_id = p_target_user_id
    and role = 'editor';
end;
$$;


