-- Name: admin_revoke_catalog_item_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_revoke_catalog_item_access(p_item_id uuid, p_user_id uuid) RETURNS void
