--
-- Name: admin_revoke_whatsapp_landing_editor(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_revoke_whatsapp_landing_editor(p_assignment_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_assignment public.whatsapp_landing_editors%rowtype;
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'forbidden'
      using errcode = '42501';
  end if;

  if p_assignment_id is null then
    raise exception 'assignment id is required'
      using errcode = '22023';
  end if;

  select *
  into v_assignment
  from public.whatsapp_landing_editors
  where id = p_assignment_id;

  if v_assignment.id is null then
    raise exception 'assignment not found'
      using errcode = 'P0002';
  end if;

  delete from public.whatsapp_landing_editors
  where id = p_assignment_id;

  if not exists (
    select 1
    from public.whatsapp_landing_editors
    where user_id = v_assignment.user_id
  ) then
    delete from public.user_feature_overrides
    where user_id = v_assignment.user_id
      and feature_key = 'whatsapp_landing.edit_assigned';
  end if;

  perform public.write_admin_audit_log(
    'whatsapp_landing.editor_revoked',
    v_assignment.user_id,
    'whatsapp_landing',
    v_assignment.landing_id,
    to_jsonb(v_assignment),
    null
  );
end;
$$;


--
-- Name: admin_role_record_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_role_record_counts() RETURNS TABLE(role_key text, role_label text, record_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor_id uuid := auth.uid();
begin
  if v_actor_id is null or not public.is_moderator(v_actor_id) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  return query
  select
    coalesce(r.key, '__none__')::text as role_key,
    coalesce(r.label, 'Rol Atanmamış')::text as role_label,
    count(ci.id) as record_count
  from public.catalog_items ci
  left join public.roles r on r.key = ci.platform_role_key
  group by r.key, r.label, coalesce(r.sort_order, 999999)
  order by coalesce(r.sort_order, 999999) asc, role_label asc;
end;
$$;


--
-- Name: FUNCTION admin_role_record_counts(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_role_record_counts() IS 'Moderator-gated: catalog_items içindeki tüm kayıtların platform_role_key bazında gruplu toplam sayısı (label ile). /admin/data rol dağılımı kartı için.';


--
-- Name: admin_search_profiles(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_search_profiles(p_query text, p_limit integer DEFAULT 10) RETURNS TABLE(id uuid, full_name text, email text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_limit integer := greatest(least(coalesce(p_limit, 10), 25), 1);
  v_query text := nullif(btrim(coalesce(p_query, '')), '');
begin
  if v_actor_id is null or not public.is_moderator(v_actor_id) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  return query
  select
    au.id,
    coalesce(
      (select upa.value_text from public.user_profile_attributes upa
       join public.afs_attributes ac on ac.id = upa.attribute_id
       where upa.user_id = au.id and ac.key = 'full_name' limit 1),
      split_part(coalesce(au.email, 'corteqs-uye'), '@', 1)
    ) as full_name,
    au.email::text as email
  from auth.users au
  where v_query is not null
    and (
      coalesce(au.email, '') ilike '%' || v_query || '%'
      or exists (
        select 1 from public.user_profile_attributes upa
        join public.afs_attributes ac on ac.id = upa.attribute_id
        where upa.user_id = au.id
          and ac.key = 'full_name'
          and upa.value_text ilike '%' || v_query || '%'
      )
    )
  order by
    case
      when coalesce(au.email, '') ilike v_query || '%' then 0
      else 1
    end,
    au.updated_at desc
  limit v_limit;
end;
$$;


--
-- Name: admin_set_attribute_rule(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_attribute_rule(role_key text, attribute_key text, rule_payload jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role public.roles%rowtype;
  v_attribute public.afs_attributes%rowtype;
  v_existing public.role_attributes%rowtype;
  v_rule_id uuid;
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select * into v_role from public.roles where key = role_key and is_active = true limit 1;
  if v_role.id is null then
    raise exception 'invalid role key' using errcode = '22023';
  end if;

  select * into v_attribute from public.afs_attributes where key = attribute_key limit 1;
  if v_attribute.id is null then
    raise exception 'invalid attribute key' using errcode = '22023';
  end if;

  select * into v_existing
  from public.role_attributes
  where role_id = v_role.id
    and attribute_id = v_attribute.id
  limit 1;

  insert into public.role_attributes (
    role_id,
    attribute_id,
    is_enabled,
    is_required,
    is_public_default,
    user_can_edit,
    user_can_hide,
    requires_admin_approval_on_change,
    sort_order
  ) values (
    v_role.id,
    v_attribute.id,
    coalesce((rule_payload ->> 'is_enabled')::boolean, coalesce(v_existing.is_enabled, true)),
    coalesce((rule_payload ->> 'is_required')::boolean, coalesce(v_existing.is_required, false)),
    coalesce((rule_payload ->> 'is_public_default')::boolean, coalesce(v_existing.is_public_default, false)),
    coalesce((rule_payload ->> 'user_can_edit')::boolean, coalesce(v_existing.user_can_edit, true)),
    coalesce((rule_payload ->> 'user_can_hide')::boolean, coalesce(v_existing.user_can_hide, true)),
    coalesce((rule_payload ->> 'requires_admin_approval_on_change')::boolean, coalesce(v_existing.requires_admin_approval_on_change, false)),
    coalesce((rule_payload ->> 'sort_order')::integer, coalesce(v_existing.sort_order, v_attribute.sort_order))
  ) on conflict (role_id, attribute_id) do update
  set
    is_enabled = excluded.is_enabled,
    is_required = excluded.is_required,
    is_public_default = excluded.is_public_default,
    user_can_edit = excluded.user_can_edit,
    user_can_hide = excluded.user_can_hide,
    requires_admin_approval_on_change = excluded.requires_admin_approval_on_change,
    sort_order = excluded.sort_order,
    updated_at = now()
  returning id into v_rule_id;

  perform public.write_admin_audit_log(
    'attribute.rule_updated',
    null,
    'role_attribute_rule',
    v_rule_id,
    case when v_existing.id is null then null else to_jsonb(v_existing) end,
    rule_payload
  );
end;
$$;


--
-- Name: admin_set_catalog_item_attribute(uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_catalog_item_attribute(p_item_id uuid, p_attribute_key text, p_value jsonb, p_visibility text DEFAULT 'public'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_attribute public.afs_attributes%rowtype;
  v_value_text text;
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select *
  into v_attribute
  from public.afs_attributes
  where key = p_attribute_key
    and is_active = true
  limit 1;

  if v_attribute.id is null then
    raise exception 'invalid attribute key' using errcode = '22023';
  end if;

  if v_attribute.data_type in ('text', 'textarea', 'select', 'url', 'phone') then
    v_value_text := nullif(btrim(coalesce(p_value #>> '{}', '')), '');
  end if;

  if p_attribute_key = 'full_name' then
    update public.catalog_items
    set
      title = coalesce(v_value_text, title),
      updated_at = now()
    where id = p_item_id;
  end if;

  insert into public.catalog_item_attribute_values (
    item_id,
    attribute_id,
    value_text,
    value_json,
    visibility,
    approval_status,
    approved_by,
    approved_at,
    updated_at
  )
  values (
    p_item_id,
    v_attribute.id,
    case when v_attribute.data_type in ('text', 'textarea', 'select', 'url', 'phone') then v_value_text else null end,
    case when v_attribute.data_type in ('multi_select', 'boolean', 'json') then p_value else null end,
    coalesce(nullif(btrim(coalesce(p_visibility, '')), ''), 'public'),
    'approved',
    auth.uid(),
    now(),
    now()
  )
  on conflict (item_id, attribute_id) do update
  set
    value_text = excluded.value_text,
    value_json = excluded.value_json,
    visibility = excluded.visibility,
    approval_status = 'approved',
    approved_by = excluded.approved_by,
    approved_at = excluded.approved_at,
    updated_at = now();

  perform public.write_admin_audit_log(
    'catalog.attribute_set',
    null,
    'catalog_item',
    p_item_id,
    null,
    jsonb_build_object('attribute_key', p_attribute_key, 'value', p_value)
  );
end;
$$;


--
-- Name: admin_set_catalog_item_editor(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_catalog_item_editor(p_item_id uuid, p_user_id uuid, p_role text DEFAULT 'editor'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if p_role not in ('owner', 'manager', 'editor', 'contributor', 'viewer') then
    raise exception 'invalid role' using errcode = '22023';
  end if;

  insert into public.catalog_item_managers (item_id, user_id, role, status)
  values (p_item_id, p_user_id, p_role, 'active')
  on conflict (item_id, user_id, role) do update
  set
    status = 'active',
    updated_at = now();

  perform public.write_admin_audit_log(
    'catalog.editor_set',
    p_user_id,
    'catalog_item',
    p_item_id,
    null,
    jsonb_build_object('role', p_role)
  );
end;
$$;


--
-- Name: admin_set_catalog_item_feature_override(uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_catalog_item_feature_override(p_item_id uuid, p_feature_key text, p_is_enabled boolean, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.feature_definitions fd
    where fd.key = p_feature_key
  ) then
    raise exception 'invalid feature key' using errcode = '22023';
  end if;

  insert into public.catalog_item_feature_overrides (
    item_id,
    feature_key,
    is_enabled,
    updated_by,
    reason,
    updated_at
  )
  values (
    p_item_id,
    p_feature_key,
    p_is_enabled,
    auth.uid(),
    nullif(btrim(coalesce(p_reason, '')), ''),
    now()
  )
  on conflict (item_id, feature_key) do update
  set
    is_enabled = excluded.is_enabled,
    updated_by = excluded.updated_by,
    reason = excluded.reason,
    updated_at = now();

  perform public.write_admin_audit_log(
    'catalog.feature_override_set',
    null,
    'catalog_item',
    p_item_id,
    null,
    jsonb_build_object(
      'feature_key', p_feature_key,
      'is_enabled', p_is_enabled,
      'reason', p_reason
    )
  );
end;
$$;


