--
-- Name: admin_set_feature_global_state(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_feature_global_state(feature_key text, is_active_globally boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_before public.afs_features%rowtype;
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select * into v_before from public.afs_features where key = feature_key limit 1;
  if v_before.key is null then
    raise exception 'invalid feature key' using errcode = '22023';
  end if;

  update public.afs_features
  set is_active_globally = admin_set_feature_global_state.is_active_globally,
      updated_at = now()
  where key = feature_key;

  perform public.write_admin_audit_log(
    case when is_active_globally then 'feature.enabled' else 'feature.disabled' end,
    null,
    'afs_features',
    null,
    to_jsonb(v_before),
    jsonb_build_object('feature_key', feature_key, 'is_active_globally', is_active_globally)
  );
end;
$$;


--
-- Name: admin_set_member_catalog_role(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_member_catalog_role(p_item_id uuid, p_role_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid;
  v_role_id uuid;
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select ci.linked_user_id
  into v_user_id
  from public.catalog_items ci
  where ci.id = p_item_id
    and ci.item_type = 'member'
  limit 1;

  if v_user_id is null then
    raise exception 'member catalog item not found' using errcode = 'P0002';
  end if;

  select r.id
  into v_role_id
  from public.roles r
  where r.key = p_role_key
    and r.is_active = true
  limit 1;

  if v_role_id is null then
    raise exception 'invalid role key' using errcode = '22023';
  end if;

  update public.catalog_items ci
  set
    platform_role_key = p_role_key,
    attributes = coalesce(ci.attributes, '{}'::jsonb) || jsonb_build_object('platform_role_key', p_role_key),
    updated_at = now()
  where ci.id = p_item_id;

  insert into public.user_role_assignments (user_id, role_id, updated_by)
  values (v_user_id, v_role_id, auth.uid())
  on conflict (user_id) do update
  set
    role_id = excluded.role_id,
    updated_by = excluded.updated_by,
    updated_at = now();

  perform public.write_admin_audit_log(
    'catalog.member_role_set',
    v_user_id,
    'catalog_item',
    p_item_id,
    null,
    jsonb_build_object('role_key', p_role_key)
  );
end;
$$;


--
-- Name: admin_set_role_feature_flag(text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_role_feature_flag(role_key text, feature_key text, is_enabled boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role_id uuid;
  v_before boolean;
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'forbidden'
      using errcode = '42501';
  end if;

  if role_key is null or btrim(role_key) = '' then
    raise exception 'role key is required'
      using errcode = '22023';
  end if;

  if feature_key is null or btrim(feature_key) = '' then
    raise exception 'feature key is required'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.afs_features fc
    where fc.key = admin_set_role_feature_flag.feature_key
  ) then
    raise exception 'invalid feature key'
      using errcode = '22023';
  end if;

  select r.id
  into v_role_id
  from public.roles r
  where r.key = admin_set_role_feature_flag.role_key
    and r.is_active = true
  limit 1;

  if v_role_id is null then
    raise exception 'invalid role key'
      using errcode = '22023';
  end if;

  select rff.is_enabled into v_before
  from public.role_features rff
  where rff.role_id = v_role_id
    and rff.feature_key = admin_set_role_feature_flag.feature_key;

  insert into public.role_features (role_id, feature_key, is_enabled, updated_by)
  values (
    v_role_id,
    admin_set_role_feature_flag.feature_key,
    admin_set_role_feature_flag.is_enabled,
    auth.uid()
  )
  on conflict on constraint role_feature_flags_pkey do update
  set
    is_enabled = excluded.is_enabled,
    updated_by = excluded.updated_by,
    updated_at = now();

  perform public.write_admin_audit_log(
    case when is_enabled then 'feature.enabled' else 'feature.disabled' end,
    null,
    'role_feature_flag',
    null,
    jsonb_build_object('role_key', role_key, 'feature_key', feature_key, 'is_enabled', v_before),
    jsonb_build_object('role_key', role_key, 'feature_key', feature_key, 'is_enabled', is_enabled)
  );
end;
$$;


--
-- Name: admin_set_taxonomy_option_active(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_taxonomy_option_active(option_key text, is_active boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_before public.taxonomy_options%rowtype;
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select * into v_before from public.taxonomy_options where key = option_key limit 1;
  if v_before.id is null then
    raise exception 'invalid option key' using errcode = '22023';
  end if;

  update public.taxonomy_options
  set is_active = admin_set_taxonomy_option_active.is_active,
      updated_at = now()
  where key = option_key;

  perform public.write_admin_audit_log(
    case when is_active then 'taxonomy.option_activated' else 'taxonomy.option_deactivated' end,
    null,
    'taxonomy_option',
    v_before.id,
    to_jsonb(v_before),
    jsonb_build_object('key', option_key, 'is_active', is_active)
  );
end;
$$;


--
-- Name: admin_set_user_feature_override(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_user_feature_override(target_user_id uuid, feature_key text, is_enabled boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.admin_set_user_feature_override_detailed(target_user_id, feature_key, is_enabled, null);
end;
$$;


--
-- Name: admin_set_user_feature_override_detailed(uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_user_feature_override_detailed(target_user_id uuid, feature_key text, is_enabled boolean, reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_scope_role text;
  v_before public.user_feature_overrides%rowtype;
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if target_user_id is null then
    raise exception 'target user is required' using errcode = '22023';
  end if;

  if feature_key is null or btrim(feature_key) = '' then
    raise exception 'feature key is required' using errcode = '22023';
  end if;

  select fc.scope_role into v_scope_role
  from public.afs_features fc
  where fc.key = feature_key;

  if v_scope_role is null then
    raise exception 'invalid feature key' using errcode = '22023';
  end if;

  -- scope_role = '*' ise herkese uygulanabilir, değilse rol kontrolü
  if v_scope_role <> '*' then
    if not exists (
      select 1 from public.user_role_assignments ura
      join public.roles r on r.id = ura.role_id
      where ura.user_id = target_user_id and r.key = v_scope_role
    ) then
      raise exception 'user profile not found for feature scope' using errcode = 'P0002';
    end if;
  end if;

  select * into v_before
  from public.user_feature_overrides
  where user_id = target_user_id and feature_key = admin_set_user_feature_override_detailed.feature_key;

  insert into public.user_feature_overrides (user_id, feature_key, is_enabled, updated_by, updated_at, reason)
  values (target_user_id, feature_key, is_enabled, auth.uid(), now(), reason)
  on conflict (user_id, feature_key) do update
  set is_enabled = excluded.is_enabled,
      updated_by = excluded.updated_by,
      updated_at = now(),
      reason = excluded.reason;

  perform public.write_admin_audit_log(
    'feature.override_set', target_user_id, 'user_feature_override', target_user_id,
    case when v_before.user_id is null then null else to_jsonb(v_before) end,
    jsonb_build_object('feature_key', feature_key, 'is_enabled', is_enabled, 'reason', reason)
  );
end;
$$;


--
-- Name: admin_set_user_profile_type(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_user_profile_type(target_user_id uuid, next_profile_type text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role_id uuid;
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.roles r
    where r.key = next_profile_type and r.is_active = true
  ) then
    raise exception 'invalid profile type' using errcode = '22023';
  end if;

  select r.id into v_role_id
  from public.roles r
  where r.key = next_profile_type and r.is_active = true
  limit 1;

  insert into public.user_role_assignments (user_id, role_id, updated_by)
  values (target_user_id, v_role_id, auth.uid())
  on conflict (user_id) do update
  set role_id = excluded.role_id,
      updated_by = excluded.updated_by,
      updated_at = now();
end;
$$;


--
-- Name: admin_set_user_role(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_user_role(target_user_id uuid, role_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role_id uuid;
  v_before_role text;
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if target_user_id is null then
    raise exception 'target user is required' using errcode = '22023';
  end if;

  if role_key is null or btrim(role_key) = '' then
    raise exception 'role key is required' using errcode = '22023';
  end if;

  select r.key into v_before_role
  from public.user_role_assignments ura
  join public.roles r on r.id = ura.role_id
  where ura.user_id = target_user_id;

  if not exists (select 1 from auth.users where id = target_user_id) then
    raise exception 'user not found' using errcode = 'P0002';
  end if;

  select r.id into v_role_id
  from public.roles r
  where r.key = admin_set_user_role.role_key and r.is_active = true
  limit 1;

  if v_role_id is null then
    raise exception 'invalid role key' using errcode = '22023';
  end if;

  insert into public.user_role_assignments (user_id, role_id, updated_by)
  values (target_user_id, v_role_id, auth.uid())
  on conflict (user_id) do update
  set role_id = excluded.role_id,
      updated_by = excluded.updated_by,
      updated_at = now();

  perform public.write_admin_audit_log(
    case when v_before_role is null then 'role.assigned' else 'role.changed' end,
    target_user_id, 'user_role_assignment', target_user_id,
    jsonb_build_object('role_key', v_before_role),
    jsonb_build_object('role_key', role_key)
  );
end;
$$;


--
-- Name: admin_update_catalog_item_access(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_update_catalog_item_access(p_item_id uuid, p_user_id uuid, p_access_level text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_existing_role text;
begin
  if auth.uid() is null or not public.is_moderator(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if p_access_level not in ('owner', 'manager', 'editor', 'viewer') then
    raise exception 'invalid access level' using errcode = '22023';
  end if;

  select cim.role
  into v_existing_role
  from public.catalog_item_managers cim
  where cim.item_id = p_item_id
    and cim.user_id = p_user_id
    and cim.status = 'active'
  order by cim.created_at asc
  limit 1;

  if v_existing_role is null then
    raise exception 'access row not found' using errcode = 'P0002';
  end if;

  if v_existing_role = p_access_level then
    return;
  end if;

  update public.catalog_item_managers
  set status = 'revoked',
      updated_at = now()
  where item_id = p_item_id
    and user_id = p_user_id
    and status = 'active';

  insert into public.catalog_item_managers (item_id, user_id, role, status)
  values (p_item_id, p_user_id, p_access_level, 'active')
  on conflict (item_id, user_id, role) do update
  set
    status = 'active',
    updated_at = now();

  perform public.write_admin_audit_log(
    'catalog_item.access_updated',
    p_user_id,
    'catalog_item',
    p_item_id,
    null,
    jsonb_build_object('old_access_level', v_existing_role, 'new_access_level', p_access_level)
  );
end;
$$;


--
-- Name: admin_update_user_profile_attribute(uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_update_user_profile_attribute(target_user_id uuid, attribute_key text, attribute_value jsonb, visibility text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_attribute public.afs_attributes%rowtype;
  v_visibility text;
  v_value_text text;
  v_before public.user_profile_attributes%rowtype;
  v_full_name_attribute_id uuid;
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if target_user_id is null then
    raise exception 'target user is required' using errcode = '22023';
  end if;

  if attribute_key is null or btrim(attribute_key) = '' then
    raise exception 'attribute key is required' using errcode = '22023';
  end if;

  if attribute_key = 'full_name' then
    select id
    into v_full_name_attribute_id
    from public.afs_attributes
    where key = 'full_name'
    limit 1;

    if v_full_name_attribute_id is null then
      raise exception 'full_name attribute missing' using errcode = 'P0002';
    end if;

    v_value_text := nullif(btrim(coalesce(attribute_value #>> '{}', '')), '');

    insert into public.user_profile_attributes (
      user_id,
      attribute_id,
      value_text,
      value_json,
      visibility,
      approval_status,
      approved_by,
      approved_at,
      updated_at
    ) values (
      target_user_id,
      v_full_name_attribute_id,
      v_value_text,
      null,
      'public',
      'approved',
      auth.uid(),
      now(),
      now()
    )
    on conflict (user_id, attribute_id) do update
    set
      value_text = excluded.value_text,
      value_json = null,
      visibility = excluded.visibility,
      approval_status = 'approved',
      approved_by = excluded.approved_by,
      approved_at = excluded.approved_at,
      updated_at = now();

    perform public.write_admin_audit_log(
      'admin.user_profile_attribute_updated',
      target_user_id,
      'user_profile',
      target_user_id,
      null,
      jsonb_build_object(
        'attribute_key', attribute_key,
        'value', attribute_value,
        'visibility', 'public'
      )
    );

    return jsonb_build_object(
      'attribute_key', attribute_key,
      'status', 'approved'
    );
  end if;

  select * into v_attribute
  from public.afs_attributes
  where key = attribute_key
    and is_active = true
  limit 1;

  if v_attribute.id is null then
    raise exception 'invalid attribute key' using errcode = '22023';
  end if;

  if v_attribute.key in ('referral_code', 'referral_source') then
    v_visibility := 'private';
  else
    v_visibility := coalesce(visibility, 'private');
  end if;

  if v_visibility not in ('public', 'private') then
    raise exception 'invalid visibility' using errcode = '22023';
  end if;

  if v_attribute.data_type in ('text','textarea','select','url','phone') then
    v_value_text := nullif(btrim(coalesce(attribute_value #>> '{}', '')), '');
  end if;

  if v_attribute.key = 'referral_code' and v_value_text is not null then
    v_value_text := upper(v_value_text);
    attribute_value := to_jsonb(v_value_text);
  end if;

  if v_attribute.key = 'referral_source' then
    v_value_text := public.validate_profile_onboarding_referral_source(v_value_text);
    attribute_value := to_jsonb(v_value_text);
  end if;

  select * into v_before
  from public.user_profile_attributes
  where user_id = target_user_id
    and attribute_id = v_attribute.id
  limit 1;

  insert into public.user_profile_attributes (
    user_id,
    attribute_id,
    value_text,
    value_json,
    visibility,
    approval_status,
    approved_by,
    approved_at,
    updated_at
  ) values (
    target_user_id,
    v_attribute.id,
    case when v_attribute.data_type in ('text','textarea','select','url','phone') then v_value_text else null end,
    case when v_attribute.data_type in ('multi_select','boolean','json') then attribute_value else null end,
    v_visibility,
    'approved',
    auth.uid(),
    now(),
    now()
  )
  on conflict (user_id, attribute_id) do update
  set
    value_text = excluded.value_text,
    value_json = excluded.value_json,
    visibility = excluded.visibility,
    approval_status = 'approved',
    approved_by = excluded.approved_by,
    approved_at = excluded.approved_at,
    updated_at = now();

  perform public.write_admin_audit_log(
    'admin.user_profile_attribute_updated',
    target_user_id,
    'user_profile_attribute',
    target_user_id,
    case when v_before.id is null then null else to_jsonb(v_before) end,
    jsonb_build_object(
      'attribute_key', attribute_key,
      'value', attribute_value,
      'visibility', v_visibility
    )
  );

  return jsonb_build_object(
    'attribute_key', attribute_key,
    'status', 'approved'
  );
end;
$$;


--
-- Name: admin_update_user_taxonomy_selection(uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_update_user_taxonomy_selection(target_user_id uuid, group_key text, option_keys text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role_key text;
  v_group public.taxonomy_groups%rowtype;
  v_rule public.role_taxonomy_rules%rowtype;
  v_role public.roles%rowtype;
  v_selected_count integer;
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select r.key
  into v_role_key
  from public.user_role_assignments ura
  join public.roles r on r.id = ura.role_id
  where ura.user_id = target_user_id
  limit 1;

  select * into v_group from public.taxonomy_groups where key = group_key and is_active = true limit 1;
  select * into v_role from public.roles where key = v_role_key limit 1;

  if v_role_key is null or v_group.id is null or v_role.id is null then
    raise exception 'invalid taxonomy update context' using errcode = '22023';
  end if;

  select * into v_rule
  from public.role_taxonomy_rules
  where role_id = v_role.id and group_id = v_group.id and is_enabled = true
  limit 1;

  if v_rule.id is null then
    raise exception 'taxonomy group is not enabled for current role' using errcode = '42501';
  end if;

  select count(*)
  into v_selected_count
  from public.taxonomy_options
  where group_id = v_group.id
    and is_active = true
    and key = any(coalesce(option_keys, array[]::text[]));

  if v_selected_count <> coalesce(array_length(option_keys, 1), 0) then
    raise exception 'one or more taxonomy options are invalid' using errcode = '22023';
  end if;

  if v_rule.selection_mode = 'single' and coalesce(array_length(option_keys, 1), 0) > 1 then
    raise exception 'single selection group cannot accept multiple options' using errcode = '22023';
  end if;

  if v_rule.is_required and coalesce(array_length(option_keys, 1), 0) = 0 then
    raise exception 'at least one taxonomy option is required' using errcode = '22023';
  end if;

  delete from public.user_taxonomy_selections
  where user_id = target_user_id
    and group_id = v_group.id;

  insert into public.user_taxonomy_selections (user_id, group_id, option_id)
  select target_user_id, v_group.id, t.id
  from public.taxonomy_options t
  where t.group_id = v_group.id
    and t.key = any(coalesce(option_keys, array[]::text[]));

  perform public.write_admin_audit_log(
    'admin.user_taxonomy_selection_updated',
    target_user_id,
    'user_taxonomy_selection',
    target_user_id,
    null,
    jsonb_build_object(
      'group_key', group_key,
      'option_keys', coalesce(option_keys, array[]::text[])
    )
  );

  return jsonb_build_object(
    'group_key', group_key,
    'selection_count', coalesce(array_length(option_keys, 1), 0),
    'status', 'approved'
  );
end;
$$;


--
-- Name: admin_upsert_catalog_item_attribute_override(uuid, text, boolean, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_upsert_catalog_item_attribute_override(p_item_id uuid, p_attribute_key text, p_is_enabled boolean DEFAULT true, p_display_order integer DEFAULT NULL::integer, p_override_label text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor_id uuid := auth.uid();
begin
  if v_actor_id is null or not public.is_moderator(v_actor_id) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if not exists (select 1 from public.catalog_items where id = p_item_id) then
    raise exception 'catalog item not found' using errcode = 'P0002';
  end if;

  if not exists (select 1 from public.afs_attributes where key = p_attribute_key and is_active = true) then
    raise exception 'attribute not found' using errcode = 'P0002';
  end if;

  insert into public.catalog_item_attribute_overrides (
    item_id,
    attribute_key,
    is_enabled,
    display_order,
    override_label
  )
  values (
    p_item_id,
    p_attribute_key,
    coalesce(p_is_enabled, true),
    p_display_order,
    nullif(btrim(coalesce(p_override_label, '')), '')
  )
  on conflict (item_id, attribute_key) do update
  set
    is_enabled = excluded.is_enabled,
    display_order = excluded.display_order,
    override_label = excluded.override_label,
    updated_at = now();
end;
$$;


