--
-- Name: cadde_auto_moderation_scan(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cadde_auto_moderation_scan() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_content text;
  v_entity_type text;
  v_signal text;
begin
  case tg_table_name
    when 'cadde_posts' then
      v_content := coalesce(new.title, '') || ' ' || coalesce(new.body, '');
      v_entity_type := 'post';
    when 'cadde_post_comments' then
      v_content := coalesce(new.body, '');
      v_entity_type := 'comment';
    when 'cadde_cafes' then
      v_content := coalesce(new.title, '') || ' ' || coalesce(new.summary, '');
      v_entity_type := 'cafe';
    when 'carsi_items' then
      v_content := coalesce(new.title, '') || ' ' || coalesce(new.description, '');
      v_entity_type := 'carsi_item';
  end case;

  v_signal := public.cadde_risky_signal(v_content);
  if v_signal is not null then
    -- Açık kayıt varsa çoğaltma; yoksa kuyruğa düşür (yayın engellenmez — insan kararı).
    if not exists (
      select 1 from public.cadde_moderation_queue
      where entity_type = v_entity_type and entity_id = new.id and status = 'open'
    ) then
      insert into public.cadde_moderation_queue (entity_type, entity_id, reason, status, risk_score)
      values (v_entity_type, new.id, 'auto: ' || v_signal, 'open', 0.5);
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: cadde_check_brand_conflict(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cadde_check_brand_conflict(p_name text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select b.brand_name
  from public.cadde_protected_brands b
  where b.is_active = true
    and lower(unaccent(coalesce(p_name, ''))) ~ ('\m' || b.match_pattern || '\M')
  order by length(b.match_pattern) desc
  limit 1;
$$;


--
-- Name: cadde_ensure_geo_city(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cadde_ensure_geo_city(p_country_name text, p_city_name text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_country text := trim(coalesce(p_country_name, ''));
  v_city text := trim(coalesce(p_city_name, ''));
  v_geo_country public.geo_countries%rowtype;
  v_geo_city_id uuid;
  v_country_id uuid;
  v_city_id uuid;
  v_timezone text;
begin
  if v_city = '' or lower(v_city) in ('belirtilmedi', '-') then
    return null;
  end if;

  -- Zaten Cadde kataloğunda mı? (aksan-toleranslı)
  select ci.id into v_city_id
  from public.cadde_cities ci
  where ci.is_active and public.cadde_fold_text(ci.name) = public.cadde_fold_text(v_city)
  limit 1;
  if v_city_id is not null then
    return v_city_id;
  end if;

  -- Ülkeyi geo kataloğunda bul (ad veya kod ile, aksan-toleranslı).
  if v_country <> '' then
    select * into v_geo_country
    from public.geo_countries
    where is_active
      and (public.cadde_fold_text(name) = public.cadde_fold_text(v_country)
           or lower(code) = lower(v_country))
    limit 1;
  end if;

  -- Şehri geo kataloğunda bul; ülke çözülemediyse ada göre global ara.
  -- NOT: skaler ve %rowtype tek SELECT INTO'da birlikte doldurulamaz — iki adım.
  if v_geo_country.id is not null then
    select g.id into v_geo_city_id
    from public.geo_cities g
    where g.is_active and g.country_id = v_geo_country.id
      and public.cadde_fold_text(g.name) = public.cadde_fold_text(v_city)
    limit 1;
  else
    declare
      v_fallback_country_id uuid;
    begin
      select g.id, g.country_id into v_geo_city_id, v_fallback_country_id
      from public.geo_cities g
      where g.is_active and public.cadde_fold_text(g.name) = public.cadde_fold_text(v_city)
      limit 1;

      if v_fallback_country_id is not null then
        select * into v_geo_country from public.geo_countries where id = v_fallback_country_id;
      end if;
    end;
  end if;

  if v_geo_city_id is null or v_geo_country.id is null then
    return null;
  end if;

  -- Cadde ülkesi yoksa aç.
  select id into v_country_id
  from public.cadde_countries
  where geo_country_id = v_geo_country.id or code = v_geo_country.code
  limit 1;

  if v_country_id is null then
    insert into public.cadde_countries (code, name, sort_order, is_active, geo_country_id)
    values (
      v_geo_country.code,
      v_geo_country.name,
      coalesce((select max(sort_order) + 10 from public.cadde_countries), 10),
      true,
      v_geo_country.id
    )
    returning id into v_country_id;
  end if;

  -- Zaman dilimi: geo_cities'te timezone YOK. Aynı ülkedeki mevcut bir şehirden
  -- devral (Türkiye'nin tüm şehirleri Europe/Istanbul); yoksa UTC.
  select ci.timezone into v_timezone
  from public.cadde_cities ci
  where ci.country_id = v_country_id and ci.timezone is not null and ci.timezone <> 'UTC'
  limit 1;

  insert into public.cadde_cities (country_id, name, timezone, sort_order, is_active, geo_city_id)
  values (
    v_country_id,
    v_city,
    coalesce(v_timezone, 'UTC'),
    coalesce((select max(sort_order) + 10 from public.cadde_cities where country_id = v_country_id), 10),
    true,
    v_geo_city_id
  )
  on conflict (geo_city_id) where geo_city_id is not null do nothing
  returning id into v_city_id;

  return v_city_id;
end;
$$;


--
-- Name: cadde_fold_text(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cadde_fold_text(p_text text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select lower(unaccent(trim(coalesce(p_text, ''))));
$$;


--
-- Name: cadde_normalize_tag(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cadde_normalize_tag(p_tag text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select regexp_replace(lower(unaccent(ltrim(coalesce(p_tag, ''), '#'))), '[^a-z0-9]', '', 'g');
$$;


--
-- Name: cadde_notify(uuid, uuid, text, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cadde_notify(p_recipient uuid, p_actor uuid, p_type text, p_title text, p_message text, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_recipient is null or p_recipient = p_actor then
    return;
  end if;
  insert into public.notifications (user_id, actor_user_id, type, title, message, related_id, entity_type, payload)
  values (p_recipient, p_actor, p_type, p_title, p_message, p_entity_id, p_entity_type, coalesce(p_payload, '{}'::jsonb));
end;
$$;


--
-- Name: cadde_notify_expiring_cafes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cadde_notify_expiring_cafes() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cafe record;
  v_member record;
  v_count integer := 0;
begin
  for v_cafe in
    select c.*
    from public.cadde_cafes c
    where c.content_mode = 'real'
      and c.status = 'published'
      and c.is_active = true
      and c.archived_at is null
      and c.ends_at between now() and now() + interval '30 minutes'
      and not exists (
        select 1 from public.notifications n
        where n.type = 'cadde.cafe.expiring' and n.related_id = c.id
      )
  loop
    perform public.cadde_notify(
      v_cafe.host_user_id, null, 'cadde.cafe.expiring',
      'Cafe''n yakında kapanıyor',
      v_cafe.title || ' 30 dakika içinde sona eriyor.',
      'cafe', v_cafe.id, '{}'::jsonb
    );
    for v_member in
      select user_id from public.cadde_cafe_members
      where cafe_id = v_cafe.id and status = 'approved' and user_id is distinct from v_cafe.host_user_id
    loop
      perform public.cadde_notify(
        v_member.user_id, null, 'cadde.cafe.expiring',
        'Katıldığın cafe yakında kapanıyor',
        v_cafe.title || ' 30 dakika içinde sona eriyor.',
        'cafe', v_cafe.id, '{}'::jsonb
      );
    end loop;
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;


