--
-- Name: cadde_profile_city_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cadde_profile_city_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_key text;
  v_country text;
begin
  select key into v_key from public.afs_attributes where id = new.attribute_id;
  if v_key is distinct from 'city' then
    return new;
  end if;

  select upa.value_text into v_country
  from public.user_profile_attributes upa
  join public.afs_attributes a on a.id = upa.attribute_id
  where a.key = 'country' and upa.user_id = new.user_id
  limit 1;

  begin
    perform public.cadde_ensure_geo_city(v_country, new.value_text);
  exception when others then
    -- Katalog büyümesi profil kaydından daha az önemli; sessizce geç.
    raise notice 'cadde_profile_city_sync atlandi: %', sqlerrm;
  end;

  return new;
end;
$$;


--
-- Name: cadde_risky_signal(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cadde_risky_signal(p_text text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
  v_text text := lower(coalesce(p_text, ''));
begin
  if v_text ~ '\m(amk|aq|orospu|piç|sik|yarrak|göt|amcık)\M' then
    return 'kufur';
  end if;
  if v_text ~ '\m(akp|chp|mhp|hdp|dem parti|iyi parti)\M' then
    return 'siyasi-propaganda';
  end if;
  if v_text ~ '\m(porn|porno|escort|bahis|casino|kumar)\M' then
    return 'yetiskin-kumar-spam';
  end if;
  if v_text ~ '(.)\1{9,}' then
    return 'asiri-tekrar';
  end if;
  if (length(v_text) - length(replace(replace(v_text, 'https://', ''), 'http://', ''))) / 7 >= 3 then
    return 'coklu-url';
  end if;
  return null;
end;
$$;


