-- Name: cadde_user_owns_brand(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cadde_user_owns_brand(p_user_id uuid, p_brand_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
