-- Name: can_post_cadde(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_post_cadde(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select uid is not null
     and public.is_cadde_profile_complete(uid)
     and public.has_cadde_feature(uid, 'cadde.post.create');
$$;


--
-- Name: can_post_kopru(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_post_kopru(uid uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role_key text;
  v_individual boolean;
begin
  if uid is null then return false; end if;
  if public.is_admin(uid) or public.is_moderator(uid) then return true; end if;
  if not public.is_cadde_profile_complete(uid) then return false; end if;
  if not public.has_cadde_feature(uid, 'cadde.bridge.post') then return false; end if;

  if public.is_diaspora_resident(uid) then return true; end if;
  if not public.is_tr_resident(uid) then return false; end if;

  select r.key into v_role_key
  from public.user_role_assignments ura
  join public.roles r on r.id = ura.role_id
  where ura.user_id = uid
  limit 1;

  v_individual := v_role_key in ('User_Standard', 'User_DiasporaMember', 'User_Contributor');

  if v_individual then
    return lower(coalesce(public.cadde_attr_text(uid, 'indiv_relocating'), '')) = 'true';
  end if;

  return lower(coalesce(public.cadde_attr_text(uid, 'digital_community_enabled'), '')) = 'true';
end;
$$;


--
-- Name: can_view_catalog_item(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_view_catalog_item(p_item_id uuid, p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.catalog_items ci
    where ci.id = p_item_id
      and (
        public.catalog_item_is_publicly_visible(ci.id)
        or (
          p_user_id is not null
          and ci.status = 'published'
          and ci.visibility in ('public', 'unlisted')
        )
        or public.catalog_user_can_edit_item(p_user_id, ci.id)
        or public.is_moderator(p_user_id)
      )
  );
$$;


--
-- Name: catalog_create_duplicate_candidates_for_item(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_create_duplicate_candidates_for_item(p_item_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item record;
  v_other record;
  v_left uuid;
  v_right uuid;
begin
  select
    ci.id,
    ci.item_type,
    public.catalog_search_normalize(ci.title) as normalized_title,
    public.catalog_search_normalize(coalesce(loc.city, '')) as normalized_city,
    public.catalog_search_normalize(coalesce(loc.country_code, '')) as normalized_country_code
  into v_item
  from public.catalog_items ci
  left join public.catalog_item_locations loc
    on loc.item_id = ci.id
   and loc.is_primary = true
  where ci.id = p_item_id;

  if v_item.id is null or v_item.normalized_title = '' then
    return;
  end if;

  for v_other in
    select
      other_ci.id,
      public.catalog_search_normalize(other_ci.title) as normalized_title,
      public.catalog_search_normalize(coalesce(other_loc.city, '')) as normalized_city,
      public.catalog_search_normalize(coalesce(other_loc.country_code, '')) as normalized_country_code
    from public.catalog_items other_ci
    left join public.catalog_item_locations other_loc
      on other_loc.item_id = other_ci.id
     and other_loc.is_primary = true
    where other_ci.id <> v_item.id
      and other_ci.item_type = v_item.item_type
      and public.catalog_search_normalize(other_ci.title) = v_item.normalized_title
      and public.catalog_search_normalize(coalesce(other_loc.city, '')) = v_item.normalized_city
      and public.catalog_search_normalize(coalesce(other_loc.country_code, '')) = v_item.normalized_country_code
  loop
    v_left := least(v_item.id, v_other.id);
    v_right := greatest(v_item.id, v_other.id);

    insert into public.duplicate_candidates (
      left_item_id,
      right_item_id,
      confidence,
      reason,
      status,
      payload
    )
    values (
      v_left,
      v_right,
      0.88,
      'auto-detected-equal-title-and-primary-location',
      'pending',
      jsonb_build_object('detected_from_item_id', p_item_id)
    )
    on conflict (left_item_id, right_item_id) do update
    set
      confidence = greatest(public.duplicate_candidates.confidence, excluded.confidence),
      reason = excluded.reason,
      payload = excluded.payload,
      updated_at = now();
  end loop;
end;
$$;


--
-- Name: catalog_delete_item_for_source(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_delete_item_for_source(p_source_type text, p_external_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item_id uuid;
begin
  select sr.item_id
  into v_item_id
  from public.source_records sr
  where sr.source_type = p_source_type
    and sr.external_id = p_external_id
  limit 1;

  if v_item_id is null then
    return;
  end if;

  delete from public.source_records
  where source_type = p_source_type
    and external_id = p_external_id;

  if not exists (
    select 1
    from public.source_records sr
    where sr.item_id = v_item_id
  ) then
    delete from public.catalog_items
    where id = v_item_id;
  end if;
end;
$$;


--
-- Name: catalog_item_is_publicly_visible(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_item_is_publicly_visible(p_item_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.catalog_items ci
    left join public.person_profile_details ppd on ppd.item_id = ci.id
    where ci.id = p_item_id
      and ci.status = 'published'
      and ci.visibility = 'public'
      and (
        ci.item_type <> 'person_profile'
        or coalesce(ppd.directory_opt_in, false) = true
      )
  );
$$;


--
-- Name: catalog_rebuild_search_document(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_rebuild_search_document(p_item_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_payload record;
begin
  if p_item_id is null then
    return;
  end if;

  with base_item as (
    select
      ci.id,
      ci.item_type,
      ci.title,
      ci.headline,
      ci.short_description,
      ci.long_description,
      ci.status,
      ci.visibility,
      ci.verification_status,
      ci.published_at
    from public.catalog_items ci
    where ci.id = p_item_id
  ),
  locations as (
    select
      cil.item_id,
      max(cil.country_code) filter (where cil.is_primary) as country_code,
      max(cil.city) filter (where cil.is_primary) as city
    from public.catalog_item_locations cil
    where cil.item_id = p_item_id
    group by cil.item_id
  ),
  categories as (
    select
      cic.item_id,
      coalesce(array_agg(distinct cc.slug order by cc.slug), '{}'::text[]) as category_slugs,
      string_agg(distinct cc.name, ' ') as category_text
    from public.catalog_item_categories cic
    join public.catalog_categories cc on cc.id = cic.category_id
    where cic.item_id = p_item_id
    group by cic.item_id
  ),
  languages as (
    select
      cil.item_id,
      coalesce(array_agg(distinct cil.language_code order by cil.language_code), '{}'::text[]) as language_codes
    from public.catalog_item_languages cil
    where cil.item_id = p_item_id
    group by cil.item_id
  ),
  contacts as (
    select
      cic.item_id,
      string_agg(distinct cic.contact_value, ' ') filter (where cic.is_public) as public_contacts
    from public.catalog_item_contacts cic
    where cic.item_id = p_item_id
    group by cic.item_id
  ),
  tags as (
    select
      cit.item_id,
      string_agg(distinct cit.tag_label, ' ') as tag_text
    from public.catalog_item_tags cit
    where cit.item_id = p_item_id
    group by cit.item_id
  ),
  services as (
    select
      cis.item_id,
      string_agg(distinct cis.service_name, ' ') filter (where cis.is_public) as service_text
    from public.catalog_item_services cis
    where cis.item_id = p_item_id
    group by cis.item_id
  ),
  media as (
    select
      cim.item_id,
      max(coalesce(cim.thumbnail_url, cim.url)) filter (where cim.is_public and cim.is_primary) as thumbnail_url
    from public.catalog_item_media cim
    where cim.item_id = p_item_id
    group by cim.item_id
  ),
  person_visibility as (
    select
      ppd.item_id,
      ppd.directory_opt_in
    from public.person_profile_details ppd
    where ppd.item_id = p_item_id
  ),
  expiry_state as (
    select
      ed.item_id,
      ed.ends_at as expires_at
    from public.event_details ed
    where ed.item_id = p_item_id
    union all
    select
      jpd.item_id,
      jpd.expires_at
    from public.job_posting_details jpd
    where jpd.item_id = p_item_id
    union all
    select
      mld.item_id,
      mld.expires_at
    from public.marketplace_listing_details mld
    where mld.item_id = p_item_id
  )
  select
    bi.id as item_id,
    bi.item_type,
    bi.title,
    concat_ws(
      ' ',
      bi.title,
      bi.headline,
      bi.short_description,
      bi.long_description,
      cat.category_text,
      c.public_contacts,
      t.tag_text,
      s.service_text,
      loc.city,
      loc.country_code
    ) as search_text,
    loc.country_code,
    loc.city,
    coalesce(cat.category_slugs, '{}'::text[]) as category_slugs,
    coalesce(lang.language_codes, '{}'::text[]) as language_codes,
    jsonb_build_object(
      'status', bi.status,
      'visibility', bi.visibility,
      'verification_status', bi.verification_status,
      'published_at', bi.published_at,
      'thumbnail_url', media.thumbnail_url,
      'directory_opt_in', coalesce(pv.directory_opt_in, false),
      'expires_at', (
        select max(expires_at)
        from expiry_state es
        where es.item_id = bi.id
      )
    ) as filter_data
  into v_payload
  from base_item bi
  left join locations loc on loc.item_id = bi.id
  left join categories cat on cat.item_id = bi.id
  left join languages lang on lang.item_id = bi.id
  left join contacts c on c.item_id = bi.id
  left join tags t on t.item_id = bi.id
  left join services s on s.item_id = bi.id
  left join media on media.item_id = bi.id
  left join person_visibility pv on pv.item_id = bi.id;

  if v_payload.item_id is null then
    delete from public.catalog_search_documents
    where item_id = p_item_id;
    return;
  end if;

  insert into public.catalog_search_documents (
    item_id,
    item_type,
    title,
    search_text,
    search_vector,
    country_code,
    city,
    category_slugs,
    language_codes,
    filter_data,
    updated_at
  )
  values (
    v_payload.item_id,
    v_payload.item_type,
    v_payload.title,
    coalesce(v_payload.search_text, v_payload.title),
    to_tsvector('simple', public.catalog_search_normalize(coalesce(v_payload.search_text, v_payload.title))),
    v_payload.country_code,
    v_payload.city,
    v_payload.category_slugs,
    v_payload.language_codes,
    v_payload.filter_data,
    now()
  )
  on conflict (item_id) do update
  set
    item_type = excluded.item_type,
    title = excluded.title,
    search_text = excluded.search_text,
    search_vector = excluded.search_vector,
    country_code = excluded.country_code,
    city = excluded.city,
    category_slugs = excluded.category_slugs,
    language_codes = excluded.language_codes,
    filter_data = excluded.filter_data,
    updated_at = now();
end;
$$;


--
-- Name: catalog_rebuild_search_documents_for_category(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_rebuild_search_documents_for_category(p_category_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item_id uuid;
begin
  for v_item_id in
    select cic.item_id
    from public.catalog_item_categories cic
    where cic.category_id = p_category_id
  loop
    perform public.catalog_rebuild_search_document(v_item_id);
  end loop;
end;
$$;


--
-- Name: catalog_refresh_all_search_documents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_refresh_all_search_documents() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item_id uuid;
begin
  for v_item_id in
    select ci.id
    from public.catalog_items ci
  loop
    perform public.catalog_rebuild_search_document(v_item_id);
  end loop;
end;
$$;


--
-- Name: catalog_reset_item_projection(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_reset_item_projection(p_item_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  delete from public.catalog_item_categories where item_id = p_item_id;
  delete from public.catalog_item_contacts where item_id = p_item_id;
  delete from public.catalog_item_locations where item_id = p_item_id;
  delete from public.catalog_item_links where item_id = p_item_id;
  delete from public.catalog_item_media where item_id = p_item_id;
  delete from public.catalog_item_languages where item_id = p_item_id;
  delete from public.catalog_item_tags where item_id = p_item_id;
  delete from public.catalog_item_services where item_id = p_item_id;
end;
$$;


--
-- Name: catalog_search_document_category_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_search_document_category_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.catalog_rebuild_search_documents_for_category(coalesce(new.id, old.id));
  return coalesce(new, old);
end;
$$;


--
-- Name: catalog_search_document_item_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_search_document_item_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'DELETE' then
    delete from public.catalog_search_documents
    where item_id = old.id;
    return old;
  end if;

  perform public.catalog_rebuild_search_document(new.id);
  return new;
end;
$$;


--
-- Name: catalog_search_document_related_item_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_search_document_related_item_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item_id uuid := coalesce(new.item_id, old.item_id);
begin
  perform public.catalog_rebuild_search_document(v_item_id);
  return coalesce(new, old);
end;
$$;


--
-- Name: catalog_search_normalize(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_search_normalize(input_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select trim(both ' ' from lower(unaccent(coalesce(input_text, ''))));
$$;


--
-- Name: catalog_slugify(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_slugify(input_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select trim(
    both '-'
    from regexp_replace(
      lower(
        translate(
          coalesce(input_text, ''),
          'ÇĞİIÖŞÜçğıiöşü',
          'CGIIOSUcgiiosu'
        )
      ),
      '[^a-z0-9]+',
      '-',
      'g'
    )
  );
$$;


--
-- Name: catalog_sync_event(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_sync_event(p_event_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_event public.events%rowtype;
  v_item_id uuid;
  v_category_slug text;
  v_starts_at timestamptz;
  v_ends_at timestamptz;
begin
  select *
  into v_event
  from public.events
  where id = p_event_id;

  if v_event.id is null then
    perform public.catalog_delete_item_for_source('legacy.events', p_event_id::text);
    return null;
  end if;

  v_starts_at := case
    when v_event.event_date is null then null
    when v_event.start_time is null then (v_event.event_date::timestamp at time zone 'UTC')
    else ((v_event.event_date::text || ' ' || v_event.start_time::text)::timestamp at time zone 'UTC')
  end;

  v_ends_at := case
    when v_event.event_date is null then null
    when v_event.end_time is null then null
    else ((v_event.event_date::text || ' ' || v_event.end_time::text)::timestamp at time zone 'UTC')
  end;

  v_item_id := public.catalog_upsert_source_item(
    'legacy.events',
    v_event.id::text,
    'event',
    'event-' || v_event.id::text,
    v_event.title,
    coalesce(v_event.organizer_name, v_event.category),
    left(coalesce(v_event.description, v_event.title), 240),
    v_event.description,
    case when v_event.status = 'published' then 'published' else 'draft' end,
    'public',
    'unverified',
    v_event.user_id,
    case when v_event.status = 'published' then coalesce(v_starts_at, v_event.created_at) else null end,
    jsonb_build_object(
      'legacy_table', 'events',
      'legacy_id', v_event.id,
      'legacy_category', v_event.category,
      'legacy_type', v_event.type,
      'featured', v_event.featured
    ),
    null,
    to_jsonb(v_event)
  );

  perform public.catalog_reset_item_projection(v_item_id);

  v_category_slug := public.catalog_slugify(v_event.category);
  insert into public.catalog_item_categories (item_id, category_id, is_primary)
  select v_item_id, cc.id, true
  from public.catalog_categories cc
  where cc.module = 'event'
    and cc.slug = v_category_slug
  on conflict do nothing;

  insert into public.catalog_item_locations (
    item_id,
    country_code,
    city,
    address_line,
    is_primary
  )
  values (
    v_item_id,
    null,
    nullif(v_event.city, ''),
    nullif(v_event.location, ''),
    true
  );

  if nullif(v_event.online_url, '') is not null then
    insert into public.catalog_item_links (item_id, link_type, url, label, is_public, sort_order)
    values (v_item_id, 'registration', v_event.online_url, 'Online URL', true, 10);
  end if;

  if nullif(v_event.cover_image, '') is not null then
    insert into public.catalog_item_media (
      item_id,
      media_type,
      url,
      thumbnail_url,
      alt_text,
      is_public,
      is_primary,
      sort_order
    )
    values (
      v_item_id,
      'cover',
      v_event.cover_image,
      v_event.cover_image,
      v_event.title,
      true,
      true,
      10
    );
  end if;

  insert into public.catalog_item_tags (item_id, tag_slug, tag_label)
  select
    v_item_id,
    public.catalog_slugify(tag_row.tag_value),
    tag_row.tag_value
  from unnest(coalesce(v_event.tags, '{}'::text[])) as tag_row(tag_value)
  where nullif(btrim(tag_row.tag_value), '') is not null
  on conflict do nothing;

  insert into public.event_details (
    item_id,
    starts_at,
    ends_at,
    venue_name,
    registration_url,
    capacity,
    timezone,
    is_online
  )
  values (
    v_item_id,
    v_starts_at,
    v_ends_at,
    nullif(v_event.location, ''),
    nullif(v_event.online_url, ''),
    v_event.max_attendees,
    'UTC',
    nullif(v_event.online_url, '') is not null
  )
  on conflict (item_id) do update
  set
    starts_at = excluded.starts_at,
    ends_at = excluded.ends_at,
    venue_name = excluded.venue_name,
    registration_url = excluded.registration_url,
    capacity = excluded.capacity,
    timezone = excluded.timezone,
    is_online = excluded.is_online,
    updated_at = now();

  perform public.catalog_upsert_owner_membership(v_item_id, v_event.user_id);
  perform public.catalog_create_duplicate_candidates_for_item(v_item_id);

  return v_item_id;
end;
$$;


--
-- Name: catalog_sync_event_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_sync_event_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'DELETE' then
    perform public.catalog_delete_item_for_source('legacy.events', old.id::text);
    return old;
  end if;

  perform public.catalog_sync_event(new.id);
  return new;
end;
$$;


--
-- Name: catalog_sync_independent_profile(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_sync_independent_profile(p_profile_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_profile public.independent_profiles%rowtype;
  v_item_id uuid;
  v_category_slug text;
begin
  select *
  into v_profile
  from public.independent_profiles
  where id = p_profile_id;

  if v_profile.id is null then
    perform public.catalog_delete_item_for_source('legacy.independent_profiles', p_profile_id::text);
    return null;
  end if;

  v_category_slug := case
    when v_profile.profile_kind = 'embassy' then 'embassy'
    when v_profile.profile_kind = 'consulate' then 'consulate'
    else 'digital-community'
  end;

  v_item_id := public.catalog_upsert_source_item(
    'legacy.independent_profiles',
    v_profile.id::text,
    'organization',
    v_profile.slug,
    v_profile.title,
    v_profile.subtitle,
    left(coalesce(v_profile.description, v_profile.title), 240),
    v_profile.description,
    case when v_profile.is_published then 'published' else 'draft' end,
    'public',
    'verified',
    null,
    case when v_profile.is_published then v_profile.created_at else null end,
    jsonb_build_object(
      'legacy_table', 'independent_profiles',
      'legacy_id', v_profile.id,
      'profile_kind', v_profile.profile_kind,
      'type_label', v_profile.type_label
    ),
    v_profile.website_url,
    to_jsonb(v_profile)
  );

  perform public.catalog_reset_item_projection(v_item_id);

  insert into public.catalog_item_categories (item_id, category_id, is_primary)
  select v_item_id, cc.id, true
  from public.catalog_categories cc
  where cc.module = 'organization'
    and cc.slug = v_category_slug
  on conflict do nothing;

  insert into public.catalog_item_locations (item_id, city, address_line, is_primary)
  values (
    v_item_id,
    nullif(v_profile.city, ''),
    nullif(v_profile.address_text, ''),
    true
  );

  if nullif(v_profile.contact_email, '') is not null then
    insert into public.catalog_item_contacts (item_id, contact_type, contact_value, label, is_public, is_primary, sort_order)
    values (v_item_id, 'email', v_profile.contact_email, 'Public Email', true, true, 10);
  end if;

  if nullif(v_profile.contact_phone, '') is not null then
    insert into public.catalog_item_contacts (item_id, contact_type, contact_value, label, is_public, is_primary, sort_order)
    values (v_item_id, 'phone', v_profile.contact_phone, 'Public Phone', true, false, 20);
  end if;

  if nullif(v_profile.website_url, '') is not null then
    insert into public.catalog_item_links (item_id, link_type, url, label, is_public, sort_order)
    values (v_item_id, 'website', v_profile.website_url, 'Website', true, 10);
  end if;

  if nullif(v_profile.hero_image_url, '') is not null then
    insert into public.catalog_item_media (item_id, media_type, url, thumbnail_url, alt_text, is_public, is_primary, sort_order)
    values (v_item_id, 'cover', v_profile.hero_image_url, v_profile.hero_image_url, v_profile.title, true, true, 10);
  end if;

  if nullif(v_profile.logo_url, '') is not null then
    insert into public.catalog_item_media (item_id, media_type, url, thumbnail_url, alt_text, is_public, is_primary, sort_order)
    values (v_item_id, 'logo', v_profile.logo_url, v_profile.logo_url, v_profile.title, true, false, 20);
  end if;

  insert into public.organization_details (
    item_id,
    organization_kind,
    legal_name,
    metadata
  )
  values (
    v_item_id,
    v_profile.profile_kind,
    v_profile.title,
    jsonb_build_object(
      'working_hours', v_profile.working_hours,
      'services_json', v_profile.services_json,
      'announcements_json', v_profile.announcements_json,
      'cta_json', v_profile.cta_json
    )
  )
  on conflict (item_id) do update
  set
    organization_kind = excluded.organization_kind,
    legal_name = excluded.legal_name,
    metadata = excluded.metadata,
    updated_at = now();

  perform public.catalog_create_duplicate_candidates_for_item(v_item_id);

  return v_item_id;
end;
$$;


--
-- Name: catalog_sync_independent_profile_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_sync_independent_profile_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
