--
-- Name: catalog_upsert_owner_membership(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_upsert_owner_membership(p_item_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_item_id is null or p_user_id is null then
    return;
  end if;

  -- the legacy profiles table was dropped (legacy); existence check moved to auth.users.
  if not exists (select 1 from auth.users u where u.id = p_user_id) then
    return;
  end if;

  insert into public.catalog_item_managers (item_id, user_id, role, status)
  values (p_item_id, p_user_id, 'owner', 'active')
  on conflict (item_id, user_id, role) do update
  set
    status = 'active',
    updated_at = now();
end;
$$;


--
-- Name: catalog_upsert_source_item(text, text, text, text, text, text, text, text, text, text, text, uuid, timestamp with time zone, jsonb, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_upsert_source_item(p_source_type text, p_external_id text, p_item_type text, p_slug text, p_title text, p_headline text, p_short_description text, p_long_description text, p_status text, p_visibility text, p_verification_status text, p_created_by_user_id uuid, p_published_at timestamp with time zone, p_attributes jsonb DEFAULT '{}'::jsonb, p_source_url text DEFAULT NULL::text, p_raw_snapshot jsonb DEFAULT '{}'::jsonb, p_platform_role_key text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item_id uuid;
  v_platform_role_key text := nullif(coalesce(p_platform_role_key, p_attributes ->> 'platform_role_key'), '');
begin
  if v_platform_role_key is not null and not exists (
    select 1 from public.roles where key = v_platform_role_key and is_active = true
  ) then
    raise exception 'invalid catalog item role' using errcode = '22023';
  end if;

  select sr.item_id
  into v_item_id
  from public.source_records sr
  where sr.source_type = p_source_type
    and sr.external_id = p_external_id
  limit 1;

  if v_item_id is null then
    insert into public.catalog_items (
      item_type,
      slug,
      title,
      headline,
      short_description,
      long_description,
      status,
      visibility,
      verification_status,
      created_by_user_id,
      published_at,
      attributes,
      platform_role_key
    )
    values (
      p_item_type,
      p_slug,
      p_title,
      p_headline,
      p_short_description,
      p_long_description,
      p_status,
      p_visibility,
      p_verification_status,
      p_created_by_user_id,
      p_published_at,
      coalesce(p_attributes, '{}'::jsonb),
      v_platform_role_key
    )
    on conflict (slug) do update
    set
      item_type = excluded.item_type,
      title = excluded.title,
      headline = excluded.headline,
      short_description = excluded.short_description,
      long_description = excluded.long_description,
      status = excluded.status,
      visibility = excluded.visibility,
      verification_status = excluded.verification_status,
      created_by_user_id = coalesce(excluded.created_by_user_id, public.catalog_items.created_by_user_id),
      published_at = excluded.published_at,
      attributes = coalesce(public.catalog_items.attributes, '{}'::jsonb) || excluded.attributes,
      platform_role_key = coalesce(excluded.platform_role_key, public.catalog_items.platform_role_key),
      updated_at = now()
    returning id into v_item_id;
  else
    update public.catalog_items
    set
      item_type = p_item_type,
      slug = p_slug,
      title = p_title,
      headline = p_headline,
      short_description = p_short_description,
      long_description = p_long_description,
      status = p_status,
      visibility = p_visibility,
      verification_status = p_verification_status,
      created_by_user_id = coalesce(p_created_by_user_id, created_by_user_id),
      published_at = p_published_at,
      attributes = coalesce(attributes, '{}'::jsonb) || coalesce(p_attributes, '{}'::jsonb),
      platform_role_key = coalesce(v_platform_role_key, platform_role_key),
      updated_at = now()
    where id = v_item_id;
  end if;

  insert into public.source_records (
    item_id,
    source_type,
    external_id,
    source_url,
    raw_snapshot,
    imported_at,
    last_seen_at
  )
  values (
    v_item_id,
    p_source_type,
    p_external_id,
    p_source_url,
    coalesce(p_raw_snapshot, '{}'::jsonb),
    now(),
    now()
  )
  on conflict (source_type, external_id) do update
  set
    item_id = excluded.item_id,
    source_url = excluded.source_url,
    raw_snapshot = excluded.raw_snapshot,
    last_seen_at = now(),
    updated_at = now();

  return v_item_id;
end;
$$;


--
-- Name: catalog_user_can_edit_item(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_user_can_edit_item(p_user_id uuid, p_item_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.catalog_user_can_manage_item(p_user_id, p_item_id, array['owner', 'manager', 'editor']);
$$;


--
-- Name: catalog_user_can_manage_item(uuid, uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_user_can_manage_item(p_user_id uuid, p_item_id uuid, p_allowed_roles text[] DEFAULT ARRAY['owner'::text, 'manager'::text]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    public.is_moderator(p_user_id)
    or exists (
      select 1
      from public.catalog_item_managers cim
      where cim.item_id = p_item_id
        and cim.user_id = p_user_id
        and cim.status = 'active'
        and cim.role = any (p_allowed_roles)
    );
$$;


--
-- Name: notification_email_outbox; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notification_email_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_type text NOT NULL,
    dedupe_key text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    last_error text,
    recipient_count integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    claimed_at timestamp with time zone,
    sent_at timestamp with time zone,
    deliver_after timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT notification_email_outbox_event_type_check CHECK ((event_type = ANY (ARRAY['new_member'::text, 'admin_update'::text, 'member_welcome'::text, 'revision_request'::text]))),
    CONSTRAINT notification_email_outbox_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'sent'::text, 'failed'::text, 'skipped'::text])))
);


--
-- Name: TABLE notification_email_outbox; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.notification_email_outbox IS 'Bildirim e-postası kuyruğu. dedupe_key: new_member:<user_id> | admin_update:<entry_id> | member_welcome:<user_id> | revision_request:<request_id>. UNIQUE kısıtı çift gönderimi imkânsız kılar.';


--
-- Name: COLUMN notification_email_outbox.deliver_after; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.notification_email_outbox.deliver_after IS 'Bu andan önce claim edilemez (p_force hariç). admin_update satırlarını trigger bir sonraki 18:00 Europe/Berlin''e kurar; diğer tipler now() varsayılanıyla anlık kalır.';


--
-- Name: claim_notification_emails(integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_notification_emails(p_limit integer DEFAULT 50, p_force boolean DEFAULT false) RETURNS SETOF public.notification_email_outbox
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return query
  with claimed as (
    update public.notification_email_outbox o
    set claimed_at = now(),
        attempts = o.attempts + 1
    where o.id in (
      select c.id
      from public.notification_email_outbox c
      where c.status = 'pending'
        and c.attempts < 5
        and (c.claimed_at is null or c.claimed_at < now() - interval '5 minutes')
        and (p_force or c.deliver_after <= now())
      order by c.created_at
      limit greatest(coalesce(p_limit, 50), 1)
      for update skip locked
    )
    returning o.*
  )
  select * from claimed;
end;
$$;


--
-- Name: complete_current_profile_onboarding_activation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_current_profile_onboarding_activation() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_email_normalized text;
  v_row public.profile_onboarding_imports%rowtype;
begin
  if v_user_id is null then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select public.normalize_profile_onboarding_email(email)
  into v_email_normalized
  from auth.users
  where id = v_user_id;

  select *
  into v_row
  from public.profile_onboarding_imports poi
  where (poi.auth_user_id = v_user_id or poi.email_normalized = v_email_normalized)
    and poi.status in ('queued', 'existing_auth_user', 'profile_created', 'invited', 'pending_user_review')
  order by poi.created_at desc
  limit 1
  for update;

  if v_row.id is null then
    raise exception 'onboarding import not found' using errcode = 'P0002';
  end if;

  update public.profile_onboarding_imports
  set
    auth_user_id = v_user_id,
    profile_user_id = v_user_id,
    status = 'active',
    activated_at = now(),
    updated_at = now()
  where id = v_row.id;

  insert into public.admin_audit_logs (
    actor_user_id,
    action,
    target_user_id,
    target_entity_type,
    target_entity_id,
    before_value,
    after_value
  ) values (
    v_user_id,
    'profile.onboarding_activated',
    v_user_id,
    'profile_onboarding_import',
    v_row.id,
    jsonb_build_object(
      'status', v_row.status,
      'activated_at', v_row.activated_at
    ),
    jsonb_build_object(
      'status', 'active',
      'activated_at', now(),
      'source_submission_id', v_row.source_submission_id
    )
  );

  return jsonb_build_object(
    'id', v_row.id,
    'status', 'active',
    'activated_at', now()
  );
end;
$$;


--
-- Name: create_cadde_cafe_v1(text, text, text, text, text, boolean, text, text, text, timestamp with time zone, timestamp with time zone, integer, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_cadde_cafe_v1(p_title text, p_summary text, p_theme_key text, p_country text, p_city text, p_is_bridge boolean, p_entry_mode text, p_referral_code text DEFAULT NULL::text, p_entry_question text DEFAULT NULL::text, p_starts_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_capacity integer DEFAULT NULL::integer, p_external_links jsonb DEFAULT '[]'::jsonb, p_diaspora_key text DEFAULT 'tr'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_title text := trim(coalesce(p_title, ''));
  v_summary text := trim(coalesce(p_summary, ''));
  v_theme text := nullif(trim(coalesce(p_theme_key, '')), '');
  v_brand text;
  v_referral text := nullif(trim(coalesce(p_referral_code, '')), '');
  v_question text := nullif(trim(coalesce(p_entry_question, '')), '');
  v_starts timestamptz := coalesce(p_starts_at, now());
  v_ends timestamptz;
  v_max_hours integer := public.cadde_setting_int('cadde.cafe.max_duration_hours', 6);
  v_diaspora text := coalesce(nullif(trim(coalesce(p_diaspora_key, '')), ''), 'tr');
  v_country_id uuid;
  v_city_id uuid;
  v_cafe_id uuid;
  v_slug text;
  v_today_count integer;
begin
  if v_uid is null then
    raise exception 'cadde_auth_required';
  end if;

  if v_diaspora not in ('tr', 'in', 'cn', 'ph') then
    raise exception 'cadde_invalid_diaspora';
  end if;

  if not public.is_cadde_profile_complete(v_uid) then
    if public.cadde_phone_required() and not public.is_phone_verified(v_uid) then
      raise exception 'phone_verification_required';
    end if;
    raise exception 'cadde_profile_incomplete';
  end if;

  if not public.has_cadde_feature(v_uid, 'cadde.cafe.create') then
    if public.is_cadde_banned(v_uid) then
      raise exception 'cadde_banned';
    end if;
    raise exception 'cadde_cafe_permission_denied';
  end if;

  if length(v_title) < 3 or length(v_title) > 80 then
    raise exception 'cadde_invalid_cafe_title';
  end if;

  -- Tema kataloğa bağlı (FK yok — legacy satırlar düşmesin diye burada doğrulanır).
  if v_theme is null or not exists (
    select 1 from public.cadde_cafe_themes t where t.key = v_theme and t.is_active = true
  ) then
    raise exception 'cadde_invalid_cafe_theme';
  end if;

  -- Marka koruması: markanın meşru sahibi değilse bu adla cafe açılamaz.
  -- Admin/moderatör muaf (moderasyon amaçlı açabilmeliler).
  v_brand := public.cadde_check_brand_conflict(v_title);
  if v_brand is not null
     and not public.cadde_user_owns_brand(v_uid, v_brand)
     and not (public.is_admin(v_uid) or public.is_moderator(v_uid)) then
    raise exception 'cadde_cafe_brand_protected';
  end if;

  if length(v_summary) < 1 or length(v_summary) > 500 then
    raise exception 'cadde_invalid_cafe_summary';
  end if;

  if p_entry_mode not in ('open', 'approval', 'referral') then
    raise exception 'cadde_invalid_entry_mode';
  end if;

  if p_entry_mode = 'referral' and (v_referral is null or length(v_referral) < 4) then
    raise exception 'cadde_cafe_referral_code_required';
  end if;

  if p_entry_mode = 'approval' and v_question is null then
    raise exception 'cadde_cafe_question_required';
  end if;

  v_ends := coalesce(p_ends_at, v_starts + interval '2 hours');
  if v_ends <= v_starts then
    raise exception 'cadde_invalid_cafe_time';
  end if;
  if v_ends > v_starts + make_interval(hours => v_max_hours) then
    raise exception 'cadde_cafe_duration_exceeded';
  end if;

  if p_capacity is not null and p_capacity < 1 then
    raise exception 'cadde_invalid_cafe_capacity';
  end if;

  if not (public.is_admin(v_uid) or public.is_moderator(v_uid)) then
    select count(*) into v_today_count
    from public.cadde_cafes
    where host_user_id = v_uid and created_at > now() - interval '24 hours';
    if v_today_count >= public.cadde_setting_int('cadde.cafe.daily_create_limit', 3) then
      raise exception 'cadde_rate_limit';
    end if;
  end if;

  select c.id into v_country_id
  from public.cadde_countries c
  where c.name = nullif(trim(coalesce(p_country, '')), '') and c.is_active = true
  limit 1;

  select ci.id into v_city_id
  from public.cadde_cities ci
  where ci.name = nullif(trim(coalesce(p_city, '')), '')
    and (v_country_id is null or ci.country_id = v_country_id)
    and ci.is_active = true
  limit 1;

  v_slug := trim(both '-' from regexp_replace(lower(v_title), '[^a-z0-9]+', '-', 'g'));
  v_slug := nullif(v_slug, '') || '-' || substr(md5(gen_random_uuid()::text), 1, 6);

  insert into public.cadde_cafes (
    host_user_id, title, summary, country_id, city_id,
    content_mode, status, is_bridge, is_free,
    starts_at, ends_at, is_active,
    slug, theme_key, entry_mode, referral_code_hash, entry_question,
    capacity, external_links, diaspora_key
  )
  values (
    v_uid, v_title, v_summary, v_country_id, v_city_id,
    'real', 'published', coalesce(p_is_bridge, false), true,
    v_starts, v_ends, true,
    v_slug, v_theme, p_entry_mode,
    case when v_referral is not null then encode(digest(upper(v_referral), 'sha256'), 'hex') end,
    v_question, p_capacity, coalesce(p_external_links, '[]'::jsonb), v_diaspora
  )
  returning id into v_cafe_id;

  insert into public.cadde_cafe_members (cafe_id, user_id, status, approved_at, approved_by)
  values (v_cafe_id, v_uid, 'approved', now(), v_uid)
  on conflict (cafe_id, user_id) do nothing;

  return v_cafe_id;
end;
$$;


--
-- Name: create_cadde_comment_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_cadde_comment_v1(p_post_id uuid, p_body text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_body text := trim(coalesce(p_body, ''));
  v_post public.cadde_posts%rowtype;
  v_recent int;
  v_comment_id uuid;
begin
  if v_uid is null then
    raise exception 'cadde_auth_required';
  end if;

  if public.is_cadde_banned(v_uid) then
    raise exception 'cadde_banned';
  end if;

  if not public.is_cadde_profile_complete(v_uid) then
    if public.cadde_phone_required() and not public.is_phone_verified(v_uid) then
      raise exception 'phone_verification_required';
    end if;
    raise exception 'cadde_profile_incomplete';
  end if;

  if length(v_body) < 1 or length(v_body) > 2000 then
    raise exception 'cadde_invalid_comment';
  end if;

  select * into v_post from public.cadde_posts where id = p_post_id;
  if v_post.id is null or v_post.status <> 'published' then
    raise exception 'cadde_post_not_found';
  end if;

  if not (public.is_admin(v_uid) or public.is_moderator(v_uid)) then
    select count(*) into v_recent
    from public.cadde_post_comments
    where user_id = v_uid and created_at > now() - interval '1 minute';
    if v_recent >= public.cadde_setting_int('cadde.comment.minute_limit', 5) then
      raise exception 'cadde_rate_limit';
    end if;
  end if;

  insert into public.cadde_post_comments (post_id, user_id, body)
  values (p_post_id, v_uid, v_body)
  returning id into v_comment_id;

  perform public.cadde_notify(
    v_post.author_user_id, v_uid, 'cadde.comment.created',
    'Paylaşımına yorum geldi',
    left(v_body, 140),
    'post', p_post_id,
    jsonb_build_object('commentId', v_comment_id)
  );

  return v_comment_id;
end;
$$;


--
-- Name: create_cadde_post_v1(text, text, text, text, text, boolean, text, text[], uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_cadde_post_v1(p_post_type text, p_title text, p_body text, p_country text, p_city text, p_is_bridge boolean, p_need_category text DEFAULT NULL::text, p_interests text[] DEFAULT NULL::text[], p_cafe_id uuid DEFAULT NULL::uuid, p_diaspora_key text DEFAULT 'tr'::text, p_media jsonb DEFAULT '[]'::jsonb, p_mentions jsonb DEFAULT '[]'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_body text := trim(coalesce(p_body, ''));
  v_title text := nullif(trim(coalesce(p_title, '')), '');
  v_need text := nullif(trim(coalesce(p_need_category, '')), '');
  v_interests text[] := coalesce(p_interests, '{}');
  v_diaspora text := coalesce(nullif(trim(coalesce(p_diaspora_key, '')), ''), 'tr');
  v_media jsonb := coalesce(p_media, '[]'::jsonb);
  v_country_id uuid;
  v_city_id uuid;
  v_is_privileged boolean;
  v_post_id uuid;
  v_valid_count int;
  v_cafe public.cadde_cafes%rowtype;
  v_is_cafe_member boolean;
begin
  if v_uid is null then
    raise exception 'cadde_auth_required';
  end if;

  if public.is_cadde_banned(v_uid) then
    raise exception 'cadde_banned';
  end if;

  if v_diaspora not in ('tr', 'in', 'cn', 'ph') then
    raise exception 'cadde_invalid_diaspora';
  end if;

  if not public.is_cadde_profile_complete(v_uid) then
    if public.cadde_phone_required() and not public.is_phone_verified(v_uid) then
      raise exception 'phone_verification_required';
    end if;
    raise exception 'cadde_profile_incomplete';
  end if;

  if not public.has_cadde_feature(v_uid, 'cadde.post.create') then
    raise exception 'cadde_post_permission_denied';
  end if;

  if p_post_type not in ('text', 'question', 'offer', 'event') then
    raise exception 'cadde_invalid_post_type';
  end if;

  -- Medya varsa gövde zorunluluğu gevşer: salt görsel/video paylaşımı meşrudur.
  if jsonb_array_length(v_media) = 0 and length(v_body) < 1 then
    raise exception 'cadde_invalid_body';
  end if;
  if length(v_body) > 4000 then
    raise exception 'cadde_invalid_body';
  end if;

  if v_title is not null and length(v_title) > 160 then
    raise exception 'cadde_invalid_title';
  end if;

  v_media := public.cadde_validate_media(v_media);

  v_interests := (select coalesce(array_agg(distinct k), '{}') from unnest(v_interests) k where trim(k) <> '');
  if cardinality(v_interests) > 3 then
    raise exception 'cadde_invalid_interests';
  end if;
  if cardinality(v_interests) > 0 then
    select count(*) into v_valid_count
    from public.cadde_interest_catalog c
    where c.key = any(v_interests) and c.is_active = true;
    if v_valid_count <> cardinality(v_interests) then
      raise exception 'cadde_invalid_interests';
    end if;
  end if;

  if v_need is not null and not exists (
    select 1 from public.cadde_interest_catalog c where c.key = v_need and c.is_active = true
  ) then
    raise exception 'cadde_invalid_need_category';
  end if;

  v_is_privileged := public.is_admin(v_uid) or public.is_moderator(v_uid);

  if p_cafe_id is not null then
    select * into v_cafe from public.cadde_cafes where id = p_cafe_id;
    if v_cafe.id is null or v_cafe.status <> 'published' or v_cafe.content_mode <> 'real' then
      raise exception 'cadde_cafe_not_found';
    end if;
    if v_cafe.archived_at is not null or not v_cafe.is_active then
      raise exception 'cadde_cafe_archived';
    end if;
    if now() >= v_cafe.ends_at then
      raise exception 'cadde_cafe_ended';
    end if;

    v_is_cafe_member := exists (
      select 1 from public.cadde_cafe_members
      where cafe_id = p_cafe_id and user_id = v_uid and status = 'approved'
    );
    if not (v_is_cafe_member or v_cafe.host_user_id = v_uid or v_is_privileged) then
      raise exception 'cadde_cafe_membership_required';
    end if;

    insert into public.cadde_posts (
      author_user_id, content_mode, status, post_type,
      title, body, country_id, city_id, is_bridge,
      need_category, published_at, cafe_id, visibility, diaspora_key, media
    )
    values (
      v_uid, 'real', 'published', p_post_type,
      v_title, v_body, v_cafe.country_id, v_cafe.city_id, v_cafe.is_bridge,
      v_need, now(), p_cafe_id, 'cafe', v_cafe.diaspora_key, v_media
    )
    returning id into v_post_id;

    insert into public.cadde_post_interests (post_id, interest_key)
    select v_post_id, k from unnest(v_interests) k;

    perform public.cadde_sync_post_hashtags(v_post_id, v_body);
    perform public.cadde_sync_post_mentions(v_post_id, p_mentions, v_uid, coalesce(v_title, left(v_body, 120)));

    return v_post_id;
  end if;

  select c.id into v_country_id
  from public.cadde_countries c
  where c.name = nullif(trim(coalesce(p_country, '')), '') and c.is_active = true
  limit 1;

  select ci.id into v_city_id
  from public.cadde_cities ci
  where ci.name = nullif(trim(coalesce(p_city, '')), '')
    and (v_country_id is null or ci.country_id = v_country_id)
    and ci.is_active = true
  limit 1;

  if p_is_bridge and not public.can_post_kopru(v_uid) then
    raise exception 'cadde_bridge_permission_denied';
  end if;

  if not p_is_bridge
     and public.is_tr_resident(v_uid)
     and not v_is_privileged
     and (v_country_id is null
          or v_country_id not in (select id from public.cadde_countries where code = 'TR')) then
    raise exception 'cadde_tr_scope_restricted';
  end if;

  insert into public.cadde_posts (
    author_user_id, content_mode, status, post_type,
    title, body, country_id, city_id, is_bridge,
    need_category, published_at, diaspora_key, media
  )
  values (
    v_uid, 'real', 'published', p_post_type,
    v_title, v_body, v_country_id, v_city_id, coalesce(p_is_bridge, false),
    v_need, now(), v_diaspora, v_media
  )
  returning id into v_post_id;

  insert into public.cadde_post_interests (post_id, interest_key)
  select v_post_id, k from unnest(v_interests) k;

  perform public.cadde_sync_post_hashtags(v_post_id, v_body);
  perform public.cadde_sync_post_mentions(v_post_id, p_mentions, v_uid, coalesce(v_title, left(v_body, 120)));

  return v_post_id;
end;
$$;


--
-- Name: create_cadde_post_v2(text, text, text, text, text, boolean, text, text[], uuid, text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_cadde_post_v2(p_post_type text, p_title text, p_body text, p_country text, p_city text, p_is_bridge boolean, p_need_category text DEFAULT NULL::text, p_interests text[] DEFAULT NULL::text[], p_cafe_id uuid DEFAULT NULL::uuid, p_diaspora_key text DEFAULT 'tr'::text, p_media jsonb DEFAULT '[]'::jsonb, p_mentions jsonb DEFAULT '[]'::jsonb, p_targets jsonb DEFAULT '[]'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_body text := trim(coalesce(p_body, ''));
  v_title text := nullif(trim(coalesce(p_title, '')), '');
  v_need text := nullif(trim(coalesce(p_need_category, '')), '');
  v_interests text[] := coalesce(p_interests, '{}');
  v_diaspora text := coalesce(nullif(trim(coalesce(p_diaspora_key, '')), ''), 'tr');
  v_media jsonb := coalesce(p_media, '[]'::jsonb);
  v_targets jsonb := coalesce(p_targets, '[]'::jsonb);
  v_resolved_targets jsonb := '[]'::jsonb;
  v_first_target jsonb;
  v_country_id uuid;
  v_city_id uuid;
  v_is_privileged boolean;
  v_post_id uuid;
  v_valid_count int;
  v_target_count int := 0;
  v_raw_target_count int := 0;
  v_invalid_target_count int := 0;
  v_has_non_tr_target boolean := false;
  v_cafe public.cadde_cafes%rowtype;
  v_is_cafe_member boolean;
begin
  if v_uid is null then
    raise exception 'cadde_auth_required';
  end if;

  if public.is_cadde_banned(v_uid) then
    raise exception 'cadde_banned';
  end if;

  if v_diaspora not in ('tr', 'in', 'cn', 'ph') then
    raise exception 'cadde_invalid_diaspora';
  end if;

  if not public.is_cadde_profile_complete(v_uid) then
    if public.cadde_phone_required() and not public.is_phone_verified(v_uid) then
      raise exception 'phone_verification_required';
    end if;
    raise exception 'cadde_profile_incomplete';
  end if;

  if not public.has_cadde_feature(v_uid, 'cadde.post.create') then
    raise exception 'cadde_post_permission_denied';
  end if;

  if p_post_type not in ('text', 'question', 'offer', 'event') then
    raise exception 'cadde_invalid_post_type';
  end if;

  if jsonb_array_length(v_media) = 0 and length(v_body) < 1 then
    raise exception 'cadde_invalid_body';
  end if;
  if length(v_body) > 4000 then
    raise exception 'cadde_invalid_body';
  end if;

  if v_title is not null and length(v_title) > 160 then
    raise exception 'cadde_invalid_title';
  end if;

  v_media := public.cadde_validate_media(v_media);

  v_interests := (select coalesce(array_agg(distinct k), '{}') from unnest(v_interests) k where trim(k) <> '');
  if cardinality(v_interests) > 3 then
    raise exception 'cadde_invalid_interests';
  end if;
  if cardinality(v_interests) > 0 then
    select count(*) into v_valid_count
    from public.cadde_interest_catalog c
    where c.key = any(v_interests) and c.is_active = true;
    if v_valid_count <> cardinality(v_interests) then
      raise exception 'cadde_invalid_interests';
    end if;
  end if;

  if v_need is not null and not exists (
    select 1 from public.cadde_interest_catalog c where c.key = v_need and c.is_active = true
  ) then
    raise exception 'cadde_invalid_need_category';
  end if;

  v_is_privileged := public.is_admin(v_uid) or public.is_moderator(v_uid);

  if p_cafe_id is not null then
    select * into v_cafe from public.cadde_cafes where id = p_cafe_id;
    if v_cafe.id is null or v_cafe.status <> 'published' or v_cafe.content_mode <> 'real' then
      raise exception 'cadde_cafe_not_found';
    end if;
    if v_cafe.archived_at is not null or not v_cafe.is_active then
      raise exception 'cadde_cafe_archived';
    end if;
    if now() >= v_cafe.ends_at then
      raise exception 'cadde_cafe_ended';
    end if;

    v_is_cafe_member := exists (
      select 1 from public.cadde_cafe_members
      where cafe_id = p_cafe_id and user_id = v_uid and status = 'approved'
    );
    if not (v_is_cafe_member or v_cafe.host_user_id = v_uid or v_is_privileged) then
      raise exception 'cadde_cafe_membership_required';
    end if;

    insert into public.cadde_posts (
      author_user_id, content_mode, status, post_type,
      title, body, country_id, city_id, is_bridge,
      need_category, published_at, cafe_id, visibility, diaspora_key, media
    )
    values (
      v_uid, 'real', 'published', p_post_type,
      v_title, v_body, v_cafe.country_id, v_cafe.city_id, v_cafe.is_bridge,
      v_need, now(), p_cafe_id, 'cafe', v_cafe.diaspora_key, v_media
    )
    returning id into v_post_id;

    if v_cafe.country_id is not null then
      insert into public.cadde_post_targets (post_id, country_id, city_id)
      values (v_post_id, v_cafe.country_id, v_cafe.city_id)
      on conflict do nothing;
    end if;

    insert into public.cadde_post_interests (post_id, interest_key)
    select v_post_id, k from unnest(v_interests) k;

    perform public.cadde_sync_post_hashtags(v_post_id, v_body);
    perform public.cadde_sync_post_mentions(v_post_id, p_mentions, v_uid, coalesce(v_title, left(v_body, 120)));

    return v_post_id;
  end if;

  if jsonb_typeof(v_targets) <> 'array' then
    raise exception 'cadde_invalid_targets';
  end if;

  if jsonb_array_length(v_targets) = 0 then
    v_targets := jsonb_build_array(jsonb_build_object('country', p_country, 'city', p_city));
  end if;

  with raw as (
    select
      e.ordinality,
      nullif(trim(coalesce(e.value ->> 'country', '')), '') as country_name,
      nullif(trim(coalesce(e.value ->> 'city', '')), '') as city_name
    from jsonb_array_elements(v_targets) with ordinality as e(value, ordinality)
  ),
  resolved_raw as (
    select
      r.ordinality,
      r.country_name,
      r.city_name,
      c.id as country_id,
      ci.id as city_id,
      c.code as country_code
    from raw r
    left join public.cadde_countries c on c.name = r.country_name and c.is_active = true
    left join public.cadde_cities ci on ci.name = r.city_name and ci.is_active = true and ci.country_id = c.id
  ),
  invalid as (
    select count(*)::int as invalid_count
    from resolved_raw
    where country_name is null
       or country_id is null
       or (city_name is not null and city_id is null)
  ),
  dedup as (
    select country_id, city_id, country_code, min(ordinality) as ordinality
    from resolved_raw
    where country_id is not null and (city_name is null or city_id is not null)
    group by country_id, city_id, country_code
  )
  select
    (select count(*)::int from raw),
    (select invalid_count from invalid),
    coalesce(jsonb_agg(
      jsonb_build_object('country_id', d.country_id, 'city_id', d.city_id, 'country_code', d.country_code)
      order by d.ordinality
    ), '[]'::jsonb),
    count(*)::int,
    coalesce(bool_or(d.country_code <> 'TR'), false)
  into v_raw_target_count, v_invalid_target_count, v_resolved_targets, v_target_count, v_has_non_tr_target
  from dedup d;

  if v_raw_target_count < 1 or v_invalid_target_count > 0 or v_target_count < 1 or v_target_count > 2 then
    raise exception 'cadde_invalid_targets';
  end if;

  if v_target_count > 1
     and public.cadde_setting_bool('cadde.post.multi_target_requires_premium', true)
     and not v_is_privileged
     and not public.has_cadde_feature(v_uid, 'cadde.post.multi_target') then
    raise exception 'cadde_multi_target_premium_required';
  end if;

  v_first_target := v_resolved_targets -> 0;
  v_country_id := (v_first_target ->> 'country_id')::uuid;
  v_city_id := nullif(v_first_target ->> 'city_id', '')::uuid;

  if p_is_bridge and not public.can_post_kopru(v_uid) then
    raise exception 'cadde_bridge_permission_denied';
  end if;

  if not p_is_bridge
     and public.is_tr_resident(v_uid)
     and not v_is_privileged
     and v_has_non_tr_target then
    raise exception 'cadde_tr_scope_restricted';
  end if;

  insert into public.cadde_posts (
    author_user_id, content_mode, status, post_type,
    title, body, country_id, city_id, is_bridge,
    need_category, published_at, diaspora_key, media
  )
  values (
    v_uid, 'real', 'published', p_post_type,
    v_title, v_body, v_country_id, v_city_id, coalesce(p_is_bridge, false),
    v_need, now(), v_diaspora, v_media
  )
  returning id into v_post_id;

  insert into public.cadde_post_targets (post_id, country_id, city_id)
  select
    v_post_id,
    (target.value ->> 'country_id')::uuid,
    nullif(target.value ->> 'city_id', '')::uuid
  from jsonb_array_elements(v_resolved_targets) as target(value)
  on conflict do nothing;

  insert into public.cadde_post_interests (post_id, interest_key)
  select v_post_id, k from unnest(v_interests) k;

  perform public.cadde_sync_post_hashtags(v_post_id, v_body);
  perform public.cadde_sync_post_mentions(v_post_id, p_mentions, v_uid, coalesce(v_title, left(v_body, 120)));

  return v_post_id;
end;
$$;


--
-- Name: create_cadde_promotion_campaign_v1(text, text, text, text, text, timestamp with time zone, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_cadde_promotion_campaign_v1(p_campaign_type text, p_title text, p_description text, p_target_url text, p_image_url text DEFAULT NULL::text, p_starts_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_placements jsonb DEFAULT '[]'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_title text := trim(coalesce(p_title, ''));
  v_description text := trim(coalesce(p_description, ''));
  v_target_url text := trim(coalesce(p_target_url, ''));
  v_image_url text := nullif(trim(coalesce(p_image_url, '')), '');
  v_is_highlight boolean := p_campaign_type = 'city_highlight';
  v_campaign_id uuid;
  v_placement jsonb;
  v_placement_key text;
  v_placement_diaspora text;
  v_country_id uuid;
  v_city_id uuid;
  v_placement_count int := 0;
  v_sort int := 0;
begin
  if v_uid is null then
    raise exception 'cadde_auth_required';
  end if;

  if not public.is_cadde_profile_complete(v_uid) then
    if public.cadde_phone_required() and not public.is_phone_verified(v_uid) then
      raise exception 'phone_verification_required';
    end if;
    raise exception 'cadde_profile_incomplete';
  end if;

  if v_is_highlight then
    if not (public.has_cadde_feature(v_uid, 'cadde.city.highlight_free')
            or public.has_cadde_feature(v_uid, 'cadde.promotion.create')) then
      raise exception 'cadde_promotion_permission_denied';
    end if;
  else
    if not public.has_cadde_feature(v_uid, 'cadde.promotion.create') then
      raise exception 'cadde_promotion_permission_denied';
    end if;
  end if;

  if p_campaign_type not in ('business', 'consultant', 'event', 'community', 'city_highlight') then
    raise exception 'cadde_invalid_promotion_type';
  end if;

  if length(v_title) < 3 or length(v_title) > 100 then
    raise exception 'cadde_invalid_promotion_title';
  end if;

  if length(v_description) < 1 or length(v_description) > 500 then
    raise exception 'cadde_invalid_promotion_description';
  end if;

  if v_target_url !~ '^(https?://|/)' then
    raise exception 'cadde_invalid_promotion_url';
  end if;

  if v_image_url is not null and v_image_url !~ '^https?://' then
    raise exception 'cadde_invalid_promotion_url';
  end if;

  if p_starts_at is not null and p_ends_at is not null and p_ends_at <= p_starts_at then
    raise exception 'cadde_invalid_promotion_dates';
  end if;

  insert into public.cadde_promotion_campaigns (
    owner_user_id, campaign_type, title, description, target_url, image_url,
    status, starts_at, ends_at
  )
  values (
    v_uid, p_campaign_type, v_title, v_description, v_target_url, v_image_url,
    'pending', p_starts_at, p_ends_at
  )
  returning id into v_campaign_id;

  for v_placement in select * from jsonb_array_elements(coalesce(p_placements, '[]'::jsonb)) loop
    v_placement_key := trim(coalesce(v_placement ->> 'key', ''));
    v_placement_diaspora := coalesce(nullif(trim(coalesce(v_placement ->> 'diaspora', '')), ''), 'tr');

    if v_placement_diaspora not in ('tr', 'in', 'cn', 'ph') then
      raise exception 'cadde_invalid_diaspora';
    end if;

    if not exists (
      select 1 from public.cadde_promotion_placement_catalog
      where key = v_placement_key and is_active = true
    ) then
      raise exception 'cadde_invalid_placement';
    end if;

    if v_is_highlight and v_placement_key <> 'city-ambassador-highlight' then
      raise exception 'cadde_invalid_placement';
    end if;

    if v_placement_key = 'homepage-ai-bar'
       and p_starts_at is not null and p_ends_at is not null
       and p_ends_at > p_starts_at + interval '3 months' then
      raise exception 'cadde_invalid_promotion_dates';
    end if;

    select c.id into v_country_id
    from public.cadde_countries c
    where c.name = nullif(trim(coalesce(v_placement ->> 'country', '')), '') and c.is_active = true
    limit 1;

    select ci.id into v_city_id
    from public.cadde_cities ci
    where ci.name = nullif(trim(coalesce(v_placement ->> 'city', '')), '')
      and (v_country_id is null or ci.country_id = v_country_id)
      and ci.is_active = true
    limit 1;

    insert into public.cadde_promotion_placements (campaign_id, placement_key, country_id, city_id, diaspora_key, theme_keys, sort_order)
    select
      v_campaign_id,
      v_placement_key,
      v_country_id,
      v_city_id,
      v_placement_diaspora,
      coalesce((select array_agg(t) from jsonb_array_elements_text(coalesce(v_placement -> 'themeKeys', '[]'::jsonb)) t), '{}'),
      v_sort;

    v_sort := v_sort + 1;
    v_placement_count := v_placement_count + 1;
  end loop;

  if v_placement_count = 0 or v_placement_count > 6 then
    raise exception 'cadde_invalid_placement';
  end if;

  return v_campaign_id;
end;
$$;


--
-- Name: create_carsi_item_v1(text, text, text, numeric, text, text, text, text[], text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_carsi_item_v1(p_category_key text, p_title text, p_description text, p_price_amount numeric DEFAULT NULL::numeric, p_price_currency text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_image_urls text[] DEFAULT '{}'::text[], p_contact_mode text DEFAULT 'platform'::text, p_diaspora_key text DEFAULT 'tr'::text, p_video_url text DEFAULT NULL::text, p_contact_value text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_uid uuid := auth.uid();
  v_title text := trim(coalesce(p_title, ''));
  v_description text := trim(coalesce(p_description, ''));
  v_currency text := upper(nullif(trim(coalesce(p_price_currency, '')), ''));
  v_images text[] := coalesce(p_image_urls, '{}');
  v_video text := nullif(trim(coalesce(p_video_url, '')), '');
  v_contact text := nullif(trim(coalesce(p_contact_value, '')), '');
  v_diaspora text := coalesce(nullif(trim(coalesce(p_diaspora_key, '')), ''), 'tr');
  v_country_id uuid;
  v_city_id uuid;
  v_active_count integer;
  v_item_id uuid;
  v_url text;
  v_paid_mode boolean := public.cadde_setting_bool('cadde.carsi.paid_mode', false);
  v_status text;
  v_payment text;
begin
  if v_uid is null then
    raise exception 'cadde_auth_required';
  end if;

  if public.is_cadde_banned(v_uid) then
    raise exception 'cadde_banned';
  end if;

  if v_diaspora not in ('tr', 'in', 'cn', 'ph') then
    raise exception 'cadde_invalid_diaspora';
  end if;

  if not public.is_cadde_profile_complete(v_uid) then
    if public.cadde_phone_required() and not public.is_phone_verified(v_uid) then
      raise exception 'phone_verification_required';
    end if;
    raise exception 'cadde_profile_incomplete';
  end if;

  if not public.has_cadde_feature(v_uid, 'cadde.carsi.create') then
    raise exception 'cadde_carsi_permission_denied';
  end if;

  if not exists (select 1 from public.carsi_categories where key = p_category_key and is_active = true) then
    raise exception 'cadde_invalid_carsi_category';
  end if;

  if length(v_title) < 3 or length(v_title) > 100 then
    raise exception 'cadde_invalid_carsi_title';
  end if;

  if length(v_description) < 1 or length(v_description) > 2000 then
    raise exception 'cadde_invalid_carsi_description';
  end if;

  if p_price_amount is not null and p_price_amount < 0 then
    raise exception 'cadde_invalid_carsi_price';
  end if;

  if v_currency is not null and v_currency !~ '^[A-Z]{3}$' then
    raise exception 'cadde_invalid_carsi_currency';
  end if;

  if p_contact_mode not in ('platform', 'phone', 'email') then
    raise exception 'cadde_invalid_carsi_contact_mode';
  end if;

  -- phone/email seçildiyse iletişim değeri ZORUNLU; aksi halde ilan sahibine ulaşılamaz.
  if p_contact_mode = 'phone' then
    if v_contact is null or v_contact !~ '^\+?[0-9 ()-]{7,20}$' then
      raise exception 'cadde_invalid_carsi_contact';
    end if;
  elsif p_contact_mode = 'email' then
    if v_contact is null or v_contact !~ '^[^@[:space:]]+@[^@[:space:]]+\.[a-zA-Z]{2,}$' then
      raise exception 'cadde_invalid_carsi_contact';
    end if;
  else
    v_contact := null;
  end if;

  if cardinality(v_images) > 6 then
    raise exception 'cadde_invalid_carsi_image';
  end if;
  foreach v_url in array v_images loop
    if v_url !~ '^https?://' then
      raise exception 'cadde_invalid_carsi_image';
    end if;
  end loop;

  if v_video is not null then
    if not public.cadde_setting_bool('cadde.media.video_enabled', true) then
      raise exception 'cadde_video_disabled';
    end if;
    if v_video !~ '^https://' then
      raise exception 'cadde_invalid_carsi_video';
    end if;
  end if;

  -- D-07: aktif ilan limiti (admin/mod muaf; premium kademesi ayrı karar).
  if not (public.is_admin(v_uid) or public.is_moderator(v_uid)) then
    select count(*) into v_active_count
    from public.carsi_items
    where owner_user_id = v_uid
      and deleted_at is null
      and status in ('draft', 'published', 'paused')
      and (expires_at is null or expires_at > now());
    if v_active_count >= public.cadde_setting_int('cadde.carsi.active_item_limit', 5) then
      raise exception 'cadde_carsi_item_limit';
    end if;
  end if;

  select c.id into v_country_id
  from public.cadde_countries c
  where c.name = nullif(trim(coalesce(p_country, '')), '') and c.is_active = true
  limit 1;

  select ci.id into v_city_id
  from public.cadde_cities ci
  where ci.name = nullif(trim(coalesce(p_city, '')), '')
    and (v_country_id is null or ci.country_id = v_country_id)
    and ci.is_active = true
  limit 1;

  -- Ücretli mod açıkken ilan taslak kalır ve ödeme bekler; kapalıyken doğrudan yayında.
  if v_paid_mode and not (public.is_admin(v_uid) or public.is_moderator(v_uid)) then
    v_status := 'draft';
    v_payment := 'pending';
  else
    v_status := 'published';
    v_payment := 'free';
  end if;

  insert into public.carsi_items (
    owner_user_id, diaspora_key, category_key, title, description,
    price_amount, price_currency, country_id, city_id,
    image_urls, video_url, contact_mode, contact_value,
    status, moderation_status, payment_status, expires_at
  )
  values (
    v_uid, v_diaspora, p_category_key, v_title, v_description,
    p_price_amount, v_currency, v_country_id, v_city_id,
    v_images, v_video, p_contact_mode, v_contact,
    v_status, 'approved', v_payment,
    now() + make_interval(days => public.cadde_setting_int('cadde.carsi.default_expiry_days', 30))
  )
  returning id into v_item_id;

  return v_item_id;
end;
$_$;


--
-- Name: current_user_can_edit_whatsapp_landing(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_can_edit_whatsapp_landing(p_landing_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    auth.uid() is not null
    and (
      public.is_admin(auth.uid())
      or (
        exists (
          select 1
          from public.whatsapp_landing_editors wle
          where wle.landing_id = p_landing_id
            and wle.user_id = auth.uid()
        )
        and exists (
          select 1
          from public.get_current_user_features() guf
          where guf.feature_key = 'whatsapp_landing.edit_assigned'
            and guf.is_enabled = true
        )
      )
    );
$$;


--
-- Name: defer_admin_update_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.defer_admin_update_notification() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.event_type = 'admin_update' and new.status = 'pending' then
    new.deliver_after := public.next_admin_digest_time();
  end if;
  return new;
end;
$$;


--
-- Name: delete_carsi_item_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_carsi_item_v1(p_item_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_item public.carsi_items%rowtype;
begin
  if v_uid is null then
    raise exception 'cadde_auth_required';
  end if;

  select * into v_item from public.carsi_items where id = p_item_id and deleted_at is null;
  if v_item.id is null then
    raise exception 'cadde_carsi_item_not_found';
  end if;

  if v_item.owner_user_id is distinct from v_uid
     and not (public.is_admin(v_uid) or public.is_moderator(v_uid)) then
    raise exception 'cadde_carsi_owner_required';
  end if;

  update public.carsi_items
  set deleted_at = now(), status = 'paused', updated_at = now()
  where id = p_item_id;
end;
$$;


--
-- Name: diaspora_accept_intro_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.diaspora_accept_intro_v1(p_match_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := public.rl_tool_require_user();
begin
  update public.diaspora_matches
    set status = 'accepted', updated_at = now()
    where id = p_match_id and candidate_id = v_uid and status = 'requested';
  if not found then raise exception 'rl_match_not_actionable'; end if;
end;
$$;


--
-- Name: diaspora_decline_intro_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.diaspora_decline_intro_v1(p_match_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := public.rl_tool_require_user();
begin
  update public.diaspora_matches
    set status = 'declined', updated_at = now()
    where id = p_match_id and candidate_id = v_uid and status in ('requested','suggested');
  if not found then raise exception 'rl_match_not_actionable'; end if;
end;
$$;


--
-- Name: diaspora_request_intro_v1(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.diaspora_request_intro_v1(p_candidate_id uuid, p_context jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := public.rl_tool_require_user();
  v_cand public.diaspora_match_preferences%rowtype;
  v_match_id uuid;
begin
  if p_candidate_id = v_uid then raise exception 'rl_self_match'; end if;
  select * into v_cand from public.diaspora_match_preferences where user_id = p_candidate_id;
  if not found or v_cand.visibility_status = 'off' then raise exception 'rl_candidate_unavailable'; end if;

  insert into public.diaspora_matches (requester_id, candidate_id, score, status, intro_context)
  values (v_uid, p_candidate_id, 0, 'requested', coalesce(p_context, '{}'::jsonb))
  on conflict (requester_id, candidate_id) do update set
    status = case when public.diaspora_matches.status in ('declined','blocked')
                  then public.diaspora_matches.status else 'requested' end,
    updated_at = now()
  returning id into v_match_id;

  return jsonb_build_object('match_id', v_match_id, 'status', 'requested');
end;
$$;


--
-- Name: enforce_cafe_capacity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_cafe_capacity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_cap integer; v_count integer;
BEGIN
  SELECT capacity, member_count INTO v_cap, v_count FROM public.cafes WHERE id = NEW.cafe_id;
  IF v_cap IS NOT NULL AND v_count >= v_cap THEN
    RAISE EXCEPTION 'cafe_full' USING HINT = 'Cafe doldu.';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_daily_cafe_join(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_daily_cafe_join() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_kind text;
BEGIN
  SELECT kind INTO v_kind FROM public.cafes WHERE id = NEW.cafe_id;
  IF v_kind IN ('relocation','expo') THEN RETURN NEW; END IF;
  IF EXISTS (
    SELECT 1 FROM public.cafe_memberships cm JOIN public.cafes c ON c.id = cm.cafe_id
    WHERE cm.user_id = NEW.user_id AND cm.cafe_id <> NEW.cafe_id
      AND cm.joined_at > now() - interval '24 hours' AND c.kind = 'community'
  ) THEN RAISE EXCEPTION 'daily_cafe_limit' USING HINT = 'Bir gün içinde sadece bir community cafe''ye katılabilirsiniz.';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enqueue_new_member_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_new_member_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_should_notify boolean := false;
  v_full_name text;
begin
  if tg_op = 'INSERT' then
    v_should_notify := new.email_confirmed_at is not null;
  elsif tg_op = 'UPDATE' then
    v_should_notify := old.email_confirmed_at is null and new.email_confirmed_at is not null;
  end if;

  if not v_should_notify or new.email is null then
    return new;
  end if;

  -- Google/OAuth kayıtlarında dolu gelir; e-posta+şifre kayıtlarında genelde NULL'dır.
  -- Şablon isim yoksa nötr hitaba düşer, e-postadan isim türetmez.
  v_full_name := nullif(trim(coalesce(
    new.raw_user_meta_data ->> 'full_name',
    new.raw_user_meta_data ->> 'name'
  )), '');

  -- (a) Adminlere "yeni üye kaydoldu" bildirimi — mevcut davranış.
  insert into public.notification_email_outbox (event_type, dedupe_key, payload)
  values (
    'new_member',
    'new_member:' || new.id::text,
    jsonb_build_object(
      'user_id', new.id::text,
      'email', new.email::text,
      'provider', coalesce(new.raw_app_meta_data ->> 'provider', 'email'),
      'created_at', coalesce(new.created_at, now())
    )
  )
  on conflict (dedupe_key) do nothing;

  -- (b) Üyenin kendisine hoş geldin maili — yeni.
  insert into public.notification_email_outbox (event_type, dedupe_key, payload)
  values (
    'member_welcome',
    'member_welcome:' || new.id::text,
    jsonb_build_object(
      'user_id', new.id::text,
      'email', new.email::text,
      'full_name', v_full_name,
      'created_at', coalesce(new.created_at, now())
    )
  )
  on conflict (dedupe_key) do nothing;

  perform public.poke_notification_dispatcher();

  return new;
exception when others then
  return new;
end;
$$;


--
-- Name: enqueue_revision_request_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_revision_request_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_author text;
begin
  if coalesce(current_setting('corteqs.skip_revision_notify', true), '') = 'on' then
    return new;
  end if;

  -- Soft-delete edilmiş olarak eklenen satır (seed/geri yükleme) bildirim üretmez.
  if new.deleted_at is not null then
    return new;
  end if;

  select au.email::text into v_author
  from auth.users au
  where au.id = new.created_by;

  insert into public.notification_email_outbox (event_type, dedupe_key, payload)
  values (
    'revision_request',
    'revision_request:' || new.id::text,
    jsonb_build_object(
      'request_id', new.id::text,
      'title', new.title,
      'detail', new.detail,
      'status', new.status,
      'priority', new.priority,
      'area_label', new.area_label,
      'author_email', v_author,
      'created_at', coalesce(new.created_at, now())
    )
  )
  on conflict (dedupe_key) do nothing;

  perform public.poke_notification_dispatcher();

  return new;
exception when others then
  -- Bildirim ASLA talebin kaydedilmesini bloklamaz.
  return new;
end;
$$;


--
-- Name: generate_ambassador_referral_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_ambassador_referral_code() RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_code text;
BEGIN
  v_code := 'AMB-' || upper(substring(md5(random()::text || clock_timestamp()::text) for 6));
  RETURN v_code;
END;
$$;


--
-- Name: get_admin_notification_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_admin_notification_state() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_sub public.admin_notification_subscriptions%rowtype;
  v_recent jsonb;
begin
  if v_uid is null or not public.is_moderator(v_uid) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select * into v_sub
  from public.admin_notification_subscriptions
  where user_id = v_uid;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc), '[]'::jsonb)
  into v_recent
  from (
    select id, event_type, status, recipient_count, last_error, created_at, sent_at, payload
    from public.notification_email_outbox
    order by created_at desc
    limit 20
  ) x;

  return jsonb_build_object(
    'isAdmin', public.is_admin(v_uid),
    'newMemberEnabled', public.notification_setting_enabled('email.new_member.enabled'),
    'adminUpdateEnabled', public.notification_setting_enabled('email.admin_update.enabled'),
    'memberWelcomeEnabled', public.notification_setting_enabled('email.member_welcome.enabled'),
    'revisionRequestEnabled', public.notification_setting_enabled('email.revision_request.enabled'),
    'myNewMemberEmail', coalesce(v_sub.new_member_email, false),
    'myAdminUpdateEmail', coalesce(v_sub.admin_update_email, false),
    'myRevisionRequestEmail', coalesce(v_sub.revision_request_email, false),
    'pendingCount', (select count(*) from public.notification_email_outbox where status = 'pending'),
    'recent', v_recent
  );
end;
$$;


--
-- Name: get_cadde_actor_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cadde_actor_context() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_role_key text;
  v_country text;
  v_city text;
  v_phone_required boolean;
  v_phone_verified boolean;
  v_missing text[] := '{}';
  v_features jsonb;
  v_verification record;
begin
  if v_uid is null then
    return jsonb_build_object('userId', null, 'canEnterCadde', false, 'missingGateFields', jsonb_build_array('auth'));
  end if;

  select r.key into v_role_key
  from public.user_role_assignments ura
  join public.roles r on r.id = ura.role_id
  where ura.user_id = v_uid
  limit 1;

  v_country := nullif(trim(coalesce(public.cadde_attr_text(v_uid, 'country'), '')), '');
  v_city := nullif(trim(coalesce(public.cadde_attr_text(v_uid, 'city'), '')), '');
  v_phone_required := public.cadde_phone_required();
  v_phone_verified := public.is_phone_verified(v_uid);

  select uv.phone_e164, uv.phone_verified_at into v_verification
  from public.user_verifications uv where uv.user_id = v_uid;

  if v_country is null then v_missing := array_append(v_missing, 'country'); end if;
  if v_city is null then v_missing := array_append(v_missing, 'city'); end if;
  if v_phone_required and not v_phone_verified then
    v_missing := array_append(v_missing, 'phone_verification');
  end if;

  select coalesce(jsonb_agg(f.feature_key order by f.feature_key), '[]'::jsonb)
  into v_features
  from public.get_current_user_features() f
  where f.is_enabled and f.feature_key like 'cadde.%';

  return jsonb_build_object(
    'userId', v_uid,
    'roleKey', v_role_key,
    'featureKeys', v_features,
    'country', v_country,
    'city', v_city,
    'phoneE164', v_verification.phone_e164,
    'phoneVerifiedAt', v_verification.phone_verified_at,
    'isPhoneVerified', v_phone_verified,
    'phoneRequired', v_phone_required,
    'isTRResident', public.is_tr_resident(v_uid),
    'isDiasporaResident', public.is_diaspora_resident(v_uid),
    'indivRelocating', lower(coalesce(public.cadde_attr_text(v_uid, 'indiv_relocating'), '')) = 'true',
    'digitalCommunityEnabled', lower(coalesce(public.cadde_attr_text(v_uid, 'digital_community_enabled'), '')) = 'true',
    'profilePublic', true,
    'missingGateFields', to_jsonb(v_missing),
    'canEnterCadde', cardinality(v_missing) = 0,
    'canPostCadde', public.can_post_cadde(v_uid),
    'canPostKopru', public.can_post_kopru(v_uid)
  );
end;
$$;


--
-- Name: get_catalog_item_profile(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_catalog_item_profile(p_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item       public.catalog_items%rowtype;
  v_role_id    uuid;
  v_attributes jsonb := '[]'::jsonb;
  v_features   jsonb := '[]'::jsonb;
begin
  select *
  into v_item
  from public.catalog_items
  where id = p_item_id
  limit 1;

  if v_item.id is null then
    return '{}'::jsonb;
  end if;

  if not (
    public.catalog_item_is_publicly_visible(v_item.id)
    or v_item.linked_user_id = auth.uid()
    or public.catalog_user_can_edit_item(auth.uid(), v_item.id)
    or public.is_admin(auth.uid())
  ) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  -- Primary flat role; fallback to platform_role_key.
  select cir.role_id
  into v_role_id
  from public.catalog_item_roles cir
  join public.roles r on r.id = cir.role_id and r.is_active = true and r.deleted_at is null
  where cir.catalog_item_id = v_item.id
    and cir.is_primary
  limit 1;

  if v_role_id is null and v_item.platform_role_key is not null then
    select r.id
    into v_role_id
    from public.roles r
    where r.key = v_item.platform_role_key
      and r.is_active = true
      and r.deleted_at is null
    limit 1;
  end if;

  if v_role_id is not null then
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'attribute_key',                        ac.key,
          'label',                                ac.label,
          'data_type',                            ac.data_type,
          'is_system',                            ac.is_system,
          'sort_order',                           coalesce(rar.sort_order, ac.sort_order),
          'is_required',                          coalesce(rar.is_required, false),
          'is_public_default',                    coalesce(rar.is_public_default, false),
          'editor_can_edit',                      coalesce(rar.user_can_edit, true),
          'editor_can_hide',                      coalesce(rar.user_can_hide, true),
          'requires_admin_approval_on_change',    coalesce(rar.requires_admin_approval_on_change, false),
          'visibility',   coalesce(
                            cia.visibility,
                            case when coalesce(rar.is_public_default, false) then 'public' else 'private' end
                          ),
          'approval_status',   coalesce(cia.approval_status, 'approved'),
          'value_text',   case when ac.key = 'full_name' then coalesce(cia.value_text, v_item.title) else cia.value_text end,
          'value_json',   cia.value_json
        )
        order by coalesce(rar.sort_order, ac.sort_order), ac.label
      ),
      '[]'::jsonb
    )
    into v_attributes
    from public.role_attributes rar
    join public.afs_attributes ac
      on ac.id = rar.attribute_id
     and ac.is_active = true
    left join public.catalog_item_attribute_values cia
      on cia.item_id = v_item.id
     and cia.attribute_id = ac.id
    where rar.role_id = v_role_id
      and rar.is_enabled = true;

    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'feature_key',  rff.feature_key,
          'is_enabled',   coalesce(cifo.is_enabled, rff.is_enabled),
          'source',       case when cifo.id is not null then 'override' else 'role_default' end,
          'reason',       cifo.reason
        )
        order by rff.feature_key
      ),
      '[]'::jsonb
    )
    into v_features
    from public.role_features rff
    left join public.catalog_item_feature_overrides cifo
      on cifo.item_id = v_item.id
     and cifo.feature_key = rff.feature_key
    where rff.role_id = v_role_id
      and rff.is_enabled = true;
  end if;

  return jsonb_build_object(
    'id',           v_item.id,
    'item_type',    v_item.item_type,
    'slug',         v_item.slug,
    'title',        v_item.title,
    'status',       v_item.status,
    'visibility',   v_item.visibility,
    'linked_user_id', v_item.linked_user_id,
    'attributes',   v_attributes,
    'features',     v_features
  );
end;
$$;


--
-- Name: FUNCTION get_catalog_item_profile(p_item_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_catalog_item_profile(p_item_id uuid) IS 'Owner/editor/admin profile payload for a catalog item. Attribute and feature rules resolve via the flat-role AFS tables (role_attributes / role_features).';


--
-- Name: get_catalog_item_public_page_v2(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_catalog_item_public_page_v2(p_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item public.catalog_items%rowtype;
  v_role_id uuid;
  v_role_key text;
  v_role_label text;
  v_avatar_url text;
  v_cover_url text;
  v_country_code text;
  v_country_label text;
  v_city text;
  v_address_line text;
  v_categories jsonb := '[]'::jsonb;
  v_sections jsonb := '[]'::jsonb;
  v_attributes jsonb := '[]'::jsonb;
  v_contacts jsonb := '[]'::jsonb;
  v_links jsonb := '[]'::jsonb;
  v_services jsonb := '[]'::jsonb;
  v_languages jsonb := '[]'::jsonb;
  v_media jsonb := '[]'::jsonb;
begin
  if p_slug is null or btrim(p_slug) = '' then
    return null;
  end if;

  select * into v_item
  from public.catalog_items ci
  where ci.slug = p_slug
    and ci.status = 'published'
    and ci.visibility = 'public'
    and ci.deleted_at is null
  limit 1;

  if v_item.id is null then
    return null;
  end if;

  -- Primary flat role; fallback to platform_role_key for legacy rows.
  select r.id, r.key, r.label
    into v_role_id, v_role_key, v_role_label
  from public.catalog_item_roles cir
  join public.roles r on r.id = cir.role_id
  where cir.catalog_item_id = v_item.id
    and cir.is_primary
    and r.is_active = true
    and r.deleted_at is null
  limit 1;

  if v_role_id is null and v_item.platform_role_key is not null then
    select r.id, r.key, r.label
      into v_role_id, v_role_key, v_role_label
    from public.roles r
    where r.key = v_item.platform_role_key
      and r.is_active = true
      and r.deleted_at is null
    limit 1;
  end if;

  -- Primary location + country label from geo_countries (no hardcoded dictionary).
  select cil.country_code, cil.city, cil.address_line
    into v_country_code, v_city, v_address_line
  from public.catalog_item_locations cil
  where cil.item_id = v_item.id
  order by cil.is_primary desc, cil.created_at asc
  limit 1;

  v_country_code := coalesce(v_country_code, v_item.country_code);
  v_city := coalesce(v_city, v_item.city);

  if v_country_code is not null then
    select gc.name into v_country_label
    from public.geo_countries gc
    where upper(gc.code) = upper(v_country_code)
      and gc.is_active = true
    limit 1;
  end if;

  -- Avatar: primary public logo/image media -> profile_photo_url/avatar_url attribute.
  select cim.url into v_avatar_url
  from public.catalog_item_media cim
  where cim.item_id = v_item.id
    and cim.is_public = true
    and cim.media_type in ('logo', 'image')
    and cim.url is not null
  order by (cim.media_type = 'logo') desc, cim.is_primary desc, cim.sort_order asc, cim.created_at asc
  limit 1;

  if v_avatar_url is null then
    select v.value_text into v_avatar_url
    from public.catalog_item_attribute_values v
    join public.afs_attributes a on a.id = v.attribute_id
    where v.item_id = v_item.id
      and a.key in ('profile_photo_url', 'avatar_url')
      and a.storage_strategy <> 'private_storage'
      and coalesce(nullif(v.visibility_override, ''), v.visibility) = 'public'
      and coalesce(v.approval_status, 'approved') = 'approved'
      and v.value_text is not null
      and btrim(v.value_text) <> ''
    order by (a.key = 'profile_photo_url') desc
    limit 1;
  end if;

  select cim.url into v_cover_url
  from public.catalog_item_media cim
  where cim.item_id = v_item.id
    and cim.is_public = true
    and cim.media_type = 'cover'
    and cim.url is not null
  order by cim.is_primary desc, cim.sort_order asc
  limit 1;

  -- Categories.
  select coalesce(jsonb_agg(
    jsonb_build_object('slug', cc.slug, 'name', cc.name, 'isPrimary', cicat.is_primary)
    order by cicat.is_primary desc, cc.name asc
  ), '[]'::jsonb)
  into v_categories
  from public.catalog_item_categories cicat
  join public.catalog_categories cc on cc.id = cicat.category_id and cc.is_active = true
  where cicat.item_id = v_item.id;

  -- Public, approved, non-private attribute values gated by the role rule.
  if v_role_id is not null then
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'key', a.key,
        'label', a.label,
        'dataType', a.data_type,
        'sortOrder', ra.sort_order,
        'valueText', v.value_text,
        'valueJson', v.value_json
      ) order by ra.sort_order, a.label
    ), '[]'::jsonb)
    into v_attributes
    from public.catalog_item_attribute_values v
    join public.afs_attributes a on a.id = v.attribute_id
    join public.role_attributes ra on ra.role_id = v_role_id and ra.attribute_id = a.id
    where v.item_id = v_item.id
      and a.is_active = true
      and a.storage_strategy <> 'private_storage'
      and ra.is_public = true
      and coalesce(nullif(v.visibility_override, ''), v.visibility) = 'public'
      and coalesce(v.approval_status, 'approved') = 'approved'
      and (
        (v.value_text is not null and btrim(v.value_text) <> '')
        or v.value_json is not null
      );
  end if;

  -- Sections: primary role -> role_sections -> afs_sections (enabled + public),
  -- with a whitelisted content payload per component_key. Unknown component keys
  -- still flow through (frontend renders them with the generic fallback).
  if v_role_id is not null then
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'sectionKey', s.key,
        'label', s.label,
        'description', s.description,
        'sectionArea', s.section_area,
        'componentKey', s.component_key,
        'sortOrder', rs.sort_order,
        'content',
          case s.component_key
            when 'rich_text' then jsonb_build_object(
              'text', coalesce(v_item.long_description, v_item.short_description)
            )
            when 'badges' then jsonb_build_object(
              'badges', coalesce((
                select jsonb_agg(cc.name order by cicat.is_primary desc, cc.name)
                from public.catalog_item_categories cicat
                join public.catalog_categories cc on cc.id = cicat.category_id and cc.is_active = true
                where cicat.item_id = v_item.id
              ), '[]'::jsonb)
            )
            when 'links' then jsonb_build_object(
              'links', coalesce((
                select jsonb_agg(
                  jsonb_build_object('type', l.link_type, 'label', l.label, 'url', l.url)
                  order by l.sort_order, l.created_at
                )
                from public.catalog_item_links l
                where l.item_id = v_item.id and l.is_public = true
              ), '[]'::jsonb)
            )
            when 'title' then jsonb_build_object('text', v_item.title)
            when 'location' then jsonb_build_object(
              'city', v_city, 'countryCode', v_country_code, 'countryLabel', v_country_label
            )
            when 'image' then jsonb_build_object('url', v_avatar_url)
            else '{}'::jsonb
          end
      ) order by rs.sort_order, s.key
    ), '[]'::jsonb)
    into v_sections
    from public.role_sections rs
    join public.afs_sections s on s.id = rs.section_id
    where rs.role_id = v_role_id
      and rs.is_enabled = true
      and coalesce(rs.visibility, 'public') = 'public'
      and coalesce(s.default_visibility, 'public') = 'public'
      and s.is_active = true;
  end if;

  -- Contacts (public rows only).
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'type', cic.contact_type,
      'value', cic.contact_value,
      'label', cic.label,
      'isPrimary', cic.is_primary
    ) order by cic.is_primary desc, cic.sort_order asc, cic.created_at asc
  ), '[]'::jsonb)
  into v_contacts
  from public.catalog_item_contacts cic
  where cic.item_id = v_item.id
    and cic.is_public = true;

  -- Links (public rows only).
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'type', l.link_type,
      'label', l.label,
      'url', l.url,
      'isPrimary', false
    ) order by l.sort_order asc, l.created_at asc
  ), '[]'::jsonb)
  into v_links
  from public.catalog_item_links l
  where l.item_id = v_item.id
    and l.is_public = true;

  -- Services (public rows only).
  select coalesce(jsonb_agg(
    jsonb_build_object('name', cis.service_name, 'description', cis.description)
    order by cis.sort_order asc, cis.created_at asc
  ), '[]'::jsonb)
  into v_services
  from public.catalog_item_services cis
  where cis.item_id = v_item.id
    and cis.is_public = true;

  -- Languages.
  select coalesce(jsonb_agg(
    jsonb_build_object('code', cl.language_code, 'proficiency', cl.proficiency)
    order by cl.is_primary desc, cl.created_at asc
  ), '[]'::jsonb)
  into v_languages
  from public.catalog_item_languages cl
  where cl.item_id = v_item.id;

  -- Media (public, never documents).
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'type', cim.media_type,
      'url', cim.url,
      'altText', cim.alt_text,
      'isPrimary', cim.is_primary
    ) order by cim.is_primary desc, cim.sort_order asc, cim.created_at asc
  ), '[]'::jsonb)
  into v_media
  from public.catalog_item_media cim
  where cim.item_id = v_item.id
    and cim.is_public = true
    and cim.media_type <> 'document'
    and cim.url is not null;

  return jsonb_build_object(
    'item', jsonb_build_object(
      'id', v_item.id,
      'slug', v_item.slug,
      'title', v_item.title,
      'itemType', v_item.item_type,
      'roleKey', v_role_key,
      'roleLabel', coalesce(v_role_label, v_item.item_type),
      'headline', v_item.headline,
      'shortDescription', v_item.short_description,
      'longDescription', v_item.long_description,
      'avatarUrl', v_avatar_url,
      'coverImageUrl', v_cover_url,
      'verificationStatus', v_item.verification_status,
      'isVerified', coalesce(v_item.is_verified, false),
      'isClaimable', coalesce(v_item.verification_status, '') <> 'claimed',
      'city', v_city,
      'countryCode', v_country_code,
      'countryLabel', v_country_label,
      'addressLine', v_address_line,
      'categories', v_categories
    ),
    'sections', v_sections,
    'attributes', v_attributes,
    'contacts', v_contacts,
    'links', v_links,
    'services', v_services,
    'languages', v_languages,
    'media', v_media,
    'claim', jsonb_build_object(
      'canClaim', coalesce(v_item.verification_status, '') <> 'claimed',
      'verificationStatus', v_item.verification_status
    )
  );
end;
$$;


--
-- Name: FUNCTION get_catalog_item_public_page_v2(p_slug text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_catalog_item_public_page_v2(p_slug text) IS 'Public profile page payload (camelCase, whitelist-only). NULL for private/unpublished/missing items. 2026-06-10.';


--
-- Name: get_catalog_item_public_profile(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_catalog_item_public_profile(p_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item public.catalog_items%rowtype;
  v_locations jsonb := '[]'::jsonb;
  v_contacts jsonb := '[]'::jsonb;
  v_services jsonb := '[]'::jsonb;
  v_languages jsonb := '[]'::jsonb;
  v_categories jsonb := '[]'::jsonb;
begin
  select *
  into v_item
  from public.catalog_items ci
  where ci.slug = p_slug
    and ci.status = 'published'
  limit 1;

  if v_item.id is null then
    return '{}'::jsonb;
  end if;

  if not public.can_view_catalog_item(v_item.id) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'contact_type', cic.contact_type,
        'contact_value', cic.contact_value,
        'label', cic.label,
        'is_primary', cic.is_primary
      )
      order by cic.is_primary desc, cic.sort_order asc, cic.created_at asc
    ),
    '[]'::jsonb
  )
  into v_contacts
  from public.catalog_item_contacts cic
  where cic.item_id = v_item.id
    and cic.is_public = true;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'country_code', cil.country_code,
        'city', cil.city,
        'region', cil.region,
        'address_line', cil.address_line,
        'is_primary', cil.is_primary
      )
      order by cil.is_primary desc, cil.created_at asc
    ),
    '[]'::jsonb
  )
  into v_locations
  from public.catalog_item_locations cil
  where cil.item_id = v_item.id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'service_name', cis.service_name,
        'description', cis.description
      )
      order by cis.sort_order asc, cis.created_at asc
    ),
    '[]'::jsonb
  )
  into v_services
  from public.catalog_item_services cis
  where cis.item_id = v_item.id
    and cis.is_public = true;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'language_code', cil.language_code,
        'proficiency', cil.proficiency
      )
      order by cil.is_primary desc, cil.created_at asc
    ),
    '[]'::jsonb
  )
  into v_languages
  from public.catalog_item_languages cil
  where cil.item_id = v_item.id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'is_primary', cic.is_primary,
        'catalog_categories', jsonb_build_object(
          'slug', cc.slug,
          'name', cc.name
        )
      )
      order by cic.is_primary desc, cc.name asc
    ),
    '[]'::jsonb
  )
  into v_categories
  from public.catalog_item_categories cic
  join public.catalog_categories cc on cc.id = cic.category_id
  where cic.item_id = v_item.id;

  return jsonb_build_object(
    'id', v_item.id,
    'item_type', v_item.item_type,
    'platform_role_key', v_item.platform_role_key,
    'slug', v_item.slug,
    'title', v_item.title,
    'headline', v_item.headline,
    'short_description', v_item.short_description,
    'long_description', v_item.long_description,
    'verification_status', v_item.verification_status,
    'attributes', v_item.attributes,
    'catalog_item_contacts', v_contacts,
    'catalog_item_locations', v_locations,
    'catalog_item_services', v_services,
    'catalog_item_languages', v_languages,
    'catalog_item_categories', v_categories
  );
end;
$$;


--
-- Name: get_catalog_item_rules(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_catalog_item_rules(p_item_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with item_role as (
    select
      ci.id as item_id,
      ci.platform_role_key,
      r.id as role_id
    from public.catalog_items ci
    left join public.roles r on r.key = ci.platform_role_key and r.is_active = true
    where ci.id = p_item_id
      and (
        public.catalog_item_is_publicly_visible(ci.id)
        or public.catalog_user_can_edit_item(auth.uid(), ci.id)
        or public.is_admin(auth.uid())
      )
  ),
  attribute_base as (
    select
      ac.key,
      ac.label,
      ac.data_type,
      case when rar.is_public_default then 'public' else 'private' end as visibility,
      rar.is_required,
      rar.sort_order as display_order
    from item_role ir
    join public.role_attributes rar
      on rar.role_id = ir.role_id
     and rar.is_enabled = true
    join public.afs_attributes ac
      on ac.id = rar.attribute_id
     and ac.is_active = true
  ),
  feature_base as (
    select
      fc.key,
      fc.label,
      rff.is_enabled,
      coalesce(fc.sort_order, 0) as sort_order
    from item_role ir
    join public.role_features rff
      on rff.role_id = ir.role_id
     and rff.is_enabled = true
    join public.afs_features fc
      on fc.key = rff.feature_key
     and fc.is_active_globally = true
  ),
  section_base as (
    select
      psc.key,
      psc.label,
      rpsr.is_enabled as is_visible,
      rpsr.sort_order as display_order
    from item_role ir
    join public.role_sections rpsr
      on rpsr.role_id = ir.role_id
     and rpsr.is_enabled = true
    join public.afs_sections psc
      on psc.id = rpsr.section_id
     and psc.is_active = true
  )
  select jsonb_build_object(
    'platformRoleKey', (select platform_role_key from item_role),
    'attributes', coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'key', key,
            'label', label,
            'dataType', data_type,
            'visibility', visibility,
            'isRequired', is_required,
            'displayOrder', display_order,
            'isOverride', false,
            'isEnabled', true
          )
          order by display_order, label
        )
        from attribute_base
      ),
      '[]'::jsonb
    ),
    'features', coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'key', key,
            'label', label,
            'isEnabled', is_enabled,
            'isOverride', false
          )
          order by sort_order, label
        )
        from feature_base
      ),
      '[]'::jsonb
    ),
    'sections', coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'key', key,
            'label', label,
            'isVisible', is_visible,
            'displayOrder', display_order,
            'isOverride', false
          )
          order by display_order, label
        )
        from section_base
      ),
      '[]'::jsonb
    ),
    'overrides', jsonb_build_object(
      'attributes', '[]'::jsonb,
      'features', '[]'::jsonb,
      'sections', '[]'::jsonb
    )
  )
  where exists (select 1 from item_role);
$$;


--
-- Name: get_current_member_catalog_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_current_member_catalog_profile() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    (
      select jsonb_build_object(
        'item_id', ci.id,
        'user_id', ci.linked_user_id,
        'full_name', ci.title,
        'profile_type', coalesce(ci.platform_role_key, 'bireysel'),
        'created_at', ci.created_at,
        'status', ci.status,
        'visibility', ci.visibility
      )
      from public.catalog_items ci
      where ci.linked_user_id = auth.uid()
        and ci.item_type = 'member'
      order by ci.created_at asc
      limit 1
    ),
    '{}'::jsonb
  );
$$;


--
-- Name: get_current_profile_onboarding_activation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_current_profile_onboarding_activation() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_email_normalized text;
  v_payload jsonb;
begin
  if v_user_id is null then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select public.normalize_profile_onboarding_email(email)
  into v_email_normalized
  from auth.users
  where id = v_user_id;

  update public.profile_onboarding_imports poi
  set
    auth_user_id = v_user_id,
    updated_at = now()
  where poi.id = (
    select candidate.id
    from public.profile_onboarding_imports candidate
    where candidate.auth_user_id is null
      and candidate.email_normalized = v_email_normalized
      and candidate.status in ('queued', 'existing_auth_user', 'profile_created', 'invited', 'pending_user_review')
    order by candidate.created_at desc
    limit 1
  );

  select jsonb_build_object(
    'id', poi.id,
    'batch_id', poi.batch_id,
    'status', poi.status,
    'source_submission_id', poi.source_submission_id,
    'email_normalized', poi.email_normalized,
    'invite_sent_at', poi.invite_sent_at,
    'activated_at', poi.activated_at,
    'snapshot', poi.snapshot,
    'submission', jsonb_build_object(
      'fullname', coalesce(poi.snapshot ->> 'fullname', s.fullname),
      'email', coalesce(poi.snapshot ->> 'email', s.email),
      'country', coalesce(poi.snapshot ->> 'country', s.country),
      'city', coalesce(poi.snapshot ->> 'city', s.city),
      'business', coalesce(poi.snapshot ->> 'business', s.business),
      'field', coalesce(poi.snapshot ->> 'field', s.field),
      'referral_code', coalesce(poi.snapshot ->> 'referral_code', s.referral_code),
      'referral_source', coalesce(poi.snapshot ->> 'referral_source', s.referral_source)
    )
  )
  into v_payload
  from public.profile_onboarding_imports poi
  join public.submissions s on s.id = poi.source_submission_id
  where (poi.auth_user_id = v_user_id or poi.email_normalized = v_email_normalized)
    and poi.status in ('queued', 'existing_auth_user', 'profile_created', 'invited', 'pending_user_review')
  order by poi.created_at desc
  limit 1;

  return v_payload;
end;
$$;


--
-- Name: get_current_user_dashboard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_current_user_dashboard() RETURNS TABLE(feature_key text, label text, description text, scope text, feature_type text, is_enabled boolean, source text, sort_order integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    fc.key as feature_key,
    fc.label,
    fc.description,
    fc.scope,
    fc.feature_type,
    guf.is_enabled,
    guf.source,
    fc.sort_order
  from public.get_current_user_features() guf
  join public.afs_features fc on fc.key = guf.feature_key
  where fc.key like 'dashboard.%'
  order by fc.sort_order, fc.key;
$$;


--
-- Name: whatsapp_landings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.whatsapp_landings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid,
    slug text NOT NULL,
    group_name text NOT NULL,
    category text NOT NULL,
    country text NOT NULL,
    city text NOT NULL,
    mode text DEFAULT 'visual'::text NOT NULL,
    hero_image text,
    tagline text,
    call_to_action_text text,
    conditions text,
    whatsapp_link text NOT NULL,
    admin_name text,
    admin_contact text,
    description text,
    status text DEFAULT 'pending'::text NOT NULL,
    rejection_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    member_approved boolean DEFAULT false NOT NULL,
    admin_approved boolean DEFAULT false NOT NULL,
    member_count integer,
    member_count_updated_at timestamp with time zone,
    group_score integer,
    language text,
    origin text,
    CONSTRAINT chk_single_badge CHECK ((NOT (member_approved AND admin_approved))),
    CONSTRAINT whatsapp_landings_category_check CHECK ((category = ANY (ARRAY['alumni'::text, 'hobi'::text, 'is'::text, 'doktor'::text, 'yatirim'::text, 'akademik'::text, 'dayanisma'::text, 'hr'::text, 'kisisel-gelisim'::text, 'diger'::text]))),
    CONSTRAINT whatsapp_landings_language_check CHECK ((language = ANY (ARRAY['tr'::text, 'en'::text, 'de'::text, 'ar'::text]))),
    CONSTRAINT whatsapp_landings_mode_check CHECK ((mode = ANY (ARRAY['visual'::text, 'text'::text]))),
    CONSTRAINT whatsapp_landings_origin_check CHECK ((origin = ANY (ARRAY['global'::text, 'mena'::text, 'berlin'::text, 'turkiye'::text, 'avrupa'::text]))),
    CONSTRAINT whatsapp_landings_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text])))
);


--
-- Name: get_current_user_editable_whatsapp_landing(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_current_user_editable_whatsapp_landing(p_slug text) RETURNS SETOF public.whatsapp_landings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_landing public.whatsapp_landings%rowtype;
begin
  if auth.uid() is null then
    return;
  end if;

  select *
  into v_landing
  from public.whatsapp_landings
  where slug = p_slug
  limit 1;

  if v_landing.id is null then
    return;
  end if;

  if not public.current_user_can_edit_whatsapp_landing(v_landing.id) then
    return;
  end if;

  return next v_landing;
end;
$$;


--
-- Name: get_current_user_features(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_current_user_features() RETURNS TABLE(feature_key text, is_enabled boolean, source text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with effective_role as (
    select r.id as role_id, r.key as role_key
    from public.user_role_assignments ura
    join public.roles r on r.id = ura.role_id
    where ura.user_id = auth.uid()
    limit 1
  )
  select
    fc.key as feature_key,
    (
      fc.is_active_globally
      and coalesce(ufo.is_enabled, rff.is_enabled, false)
    ) as is_enabled,
    case
      when ufo.user_id is not null then 'override'
      when rff.role_id is not null then 'role_default'
      else 'fallback'
    end as source
  from public.afs_features fc
  join effective_role er
    on fc.scope_role = '*'
    or fc.scope_role = er.role_key
  left join public.role_features rff
    on rff.role_id = er.role_id
   and rff.feature_key = fc.key
  left join public.user_feature_overrides ufo
    on ufo.user_id = auth.uid()
   and ufo.feature_key = fc.key
  order by fc.key;
$$;


--
-- Name: get_current_user_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_current_user_profile() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_role_key text;
  v_role_id uuid;
  v_role_label text;
  v_role_description text;
  v_role_slug text;
  v_full_name text;
  v_email text;
  v_features jsonb;
  v_attributes jsonb;
  v_pending jsonb;
  v_completion_total integer;
  v_completion_completed integer;
begin
  if v_user_id is null then
    return '{}'::jsonb;
  end if;

  -- auth.users'tan email al
  select au.email
  into v_email
  from auth.users au
  where au.id = v_user_id;

  -- full_name attribute'tan al
  select upa.value_text
  into v_full_name
  from public.user_profile_attributes upa
  join public.afs_attributes ac on ac.id = upa.attribute_id
  where upa.user_id = v_user_id
    and ac.key = 'full_name'
  limit 1;

  -- Rolü user_role_assignments'tan al
  select r.id, r.key, r.label, r.description
  into v_role_id, v_role_key, v_role_label, v_role_description
  from public.user_role_assignments ura
  join public.roles r on r.id = ura.role_id
  where ura.user_id = v_user_id
  limit 1;

  if v_role_key is null then
    return jsonb_build_object(
      'user_id', v_user_id,
      'email', v_email,
      'full_name', v_full_name,
      'profile_type', null,
      'role_key', null,
      'features', '[]'::jsonb,
      'attributes', '[]'::jsonb,
      'pending_requests', '[]'::jsonb,
      'profile_completion', jsonb_build_object('required_total', 0, 'required_completed', 0, 'percentage', 100)
    );
  end if;

  v_role_slug := case v_role_key
    when 'bireysel' then 'individual'
    when 'danisman' then 'consultant'
    when 'isletme' then 'business'
    when 'kurulus-dernek' then 'organization'
    when 'blogger-vlogger-youtuber' then 'influencer'
    when 'sehir-elcisi' then 'ambassador'
    else v_role_key
  end;

  select coalesce(jsonb_agg(jsonb_build_object(
    'key', feature_key,
    'is_enabled', is_enabled,
    'source', source
  ) order by feature_key), '[]'::jsonb)
  into v_features
  from public.get_current_user_features();

  select coalesce(jsonb_agg(jsonb_build_object(
    'attribute_key', ac.key,
    'label', ac.label,
    'description', ac.description,
    'data_type', ac.data_type,
    'is_system', ac.is_system,
    'sort_order', rar.sort_order,
    'is_required', rar.is_required,
    'is_public_default', rar.is_public_default,
    'user_can_edit', rar.user_can_edit,
    'user_can_hide', rar.user_can_hide,
    'requires_admin_approval_on_change', rar.requires_admin_approval_on_change,
    'visibility', coalesce(
      upa.visibility,
      case when rar.is_public_default then 'public' else 'private' end
    ),
    'approval_status', coalesce(upa.approval_status, 'approved'),
    'value_text', coalesce(upa.value_text, case when ac.key = 'full_name' then v_full_name else null end),
    'value_json', upa.value_json,
    'display_value', case
      when ac.key = 'full_name' then to_jsonb(coalesce(v_full_name, ''))
      when upa.value_json is not null then upa.value_json
      else to_jsonb(coalesce(upa.value_text, ''))
    end
  ) order by rar.sort_order, ac.label), '[]'::jsonb)
  into v_attributes
  from public.role_attributes rar
  join public.afs_attributes ac on ac.id = rar.attribute_id and ac.is_active = true
  join public.roles r on r.id = rar.role_id
  left join public.user_profile_attributes upa
    on upa.user_id = v_user_id
   and upa.attribute_id = ac.id
  where r.key = v_role_key
    and rar.is_enabled = true;

  select count(*) filter (where rar.is_required),
         count(*) filter (where rar.is_required and (
           (ac.key = 'full_name' and coalesce(v_full_name, '') <> '')
           or upa.value_text is not null
           or upa.value_json is not null
         ))
  into v_completion_total, v_completion_completed
  from public.role_attributes rar
  join public.afs_attributes ac on ac.id = rar.attribute_id and ac.is_active = true
  join public.roles r on r.id = rar.role_id
  left join public.user_profile_attributes upa
    on upa.user_id = v_user_id
   and upa.attribute_id = ac.id
   and upa.approval_status = 'approved'
  where r.key = v_role_key
    and rar.is_enabled = true;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', ar.id,
    'request_type', ar.request_type,
    'status', ar.status,
    'target_role_key', ar.target_role_key,
    'target_feature_key', ar.target_feature_key,
    'target_entity_type', ar.target_entity_type,
    'created_at', ar.created_at,
    'admin_note', ar.admin_note,
    'payload', ar.payload
  ) order by ar.created_at desc), '[]'::jsonb)
  into v_pending
  from public.approval_requests ar
  where ar.user_id = v_user_id
    and ar.status = 'pending';

  return jsonb_build_object(
    'user_id', v_user_id,
    'email', v_email,
    'full_name', coalesce(v_full_name, ''),
    'profile_type', v_role_key,
    'role_key', v_role_key,
    'role_label', coalesce(v_role_label, v_role_key),
    'role_description', v_role_description,
    'role_slug', v_role_slug,
    'features', coalesce(v_features, '[]'::jsonb),
    'attributes', coalesce(v_attributes, '[]'::jsonb),
    'pending_requests', coalesce(v_pending, '[]'::jsonb),
    'profile_completion', jsonb_build_object(
      'required_total', coalesce(v_completion_total, 0),
      'required_completed', coalesce(v_completion_completed, 0),
      'percentage', case
        when coalesce(v_completion_total, 0) = 0 then 100
        else floor((coalesce(v_completion_completed, 0)::numeric / v_completion_total::numeric) * 100)
      end
    )
  );
end;
$$;


--
-- Name: get_flat_roles(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_flat_roles() RETURNS TABLE(key text, label text, description text, sort_order integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select r.key, r.label, r.description, r.sort_order
  from public.roles r
  where r.is_active = true
    and r.deleted_at is null
  order by r.sort_order nulls last, r.label;
$$;


