--
-- Name: get_my_editable_catalog_items(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_editable_catalog_items() RETURNS TABLE(item_id uuid, slug text, title text, item_type text, platform_role_key text, access_level text, is_primary_owner boolean, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    ci.id as item_id,
    ci.slug,
    ci.title,
    ci.item_type,
    ci.platform_role_key,
    cim.role as access_level,
    (cim.role = 'owner') as is_primary_owner,
    ci.created_at
  from public.catalog_item_managers cim
  join public.catalog_items ci on ci.id = cim.item_id
  where cim.user_id = auth.uid()
    and cim.status = 'active'
    and cim.role in ('owner', 'manager', 'editor')
  order by
    case when cim.role = 'owner' then 0 when cim.role = 'manager' then 1 else 2 end,
    ci.created_at asc;
$$;


--
-- Name: get_public_catalog_item_profile(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_catalog_item_profile(p_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item public.catalog_items%rowtype;
  v_result jsonb;
begin
  select * into v_item from public.catalog_items
   where slug = p_slug and status = 'published' and visibility = 'public' and deleted_at is null;
  if v_item.id is null then
    return null;
  end if;

  select jsonb_build_object(
    'slug', v_item.slug,
    'display_name', v_item.title,
    'short_description', v_item.short_description,
    'country_code', v_item.country_code,
    'city', v_item.city,
    'is_verified', v_item.is_verified,
    'is_placeholder', v_item.is_placeholder,
    'primary_role', (
      select jsonb_build_object('key', r.key, 'label', r.label)
      from public.catalog_item_roles cir
      join public.roles r on r.id = cir.role_id
      where cir.catalog_item_id = v_item.id and cir.is_primary
      limit 1
    ),
    'public_attributes', coalesce((
      select jsonb_object_agg(a.key, v.value_text)
      from public.catalog_item_attribute_values v
      join public.afs_attributes a on a.id = v.attribute_id
      join public.catalog_item_roles cir on cir.catalog_item_id = v_item.id and cir.is_primary
      join public.role_attributes ra on ra.role_id = cir.role_id and ra.attribute_id = a.id
      where v.item_id = v_item.id and ra.is_public = true
    ), '{}'::jsonb)
  ) into v_result;

  return v_result;
end;
$$;


