--
-- Name: get_public_independent_profile(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_independent_profile(p_slug text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_profile public.independent_profiles%rowtype;
begin
  select *
  into v_profile
  from public.independent_profiles
  where slug = p_slug
    and is_published = true
  limit 1;

  if v_profile.id is null then
    return null;
  end if;

  return jsonb_build_object(
    'id', v_profile.id,
    'slug', v_profile.slug,
    'profile_kind', v_profile.profile_kind,
    'type_label', v_profile.type_label,
    'title', v_profile.title,
    'subtitle', v_profile.subtitle,
    'country', v_profile.country,
    'city', v_profile.city,
    'description', v_profile.description,
    'website_url', v_profile.website_url,
    'hero_image_url', v_profile.hero_image_url,
    'logo_url', v_profile.logo_url,
    'contact_email', v_profile.contact_email,
    'contact_phone', v_profile.contact_phone,
    'address_text', v_profile.address_text,
    'map_query', v_profile.map_query,
    'working_hours', v_profile.working_hours,
    'services_json', coalesce(v_profile.services_json, '[]'::jsonb),
    'announcements_json', coalesce(v_profile.announcements_json, '[]'::jsonb),
    'cta_json', coalesce(v_profile.cta_json, '[]'::jsonb),
    'is_published', v_profile.is_published,
    'sort_order', v_profile.sort_order,
    'created_at', v_profile.created_at,
    'updated_at', v_profile.updated_at
  );
end;
$$;


--
-- Name: get_public_profile_sections(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_profile_sections(target_user_id uuid) RETURNS TABLE(section_key text, section_area text, label text, component_name text, sort_order integer, content jsonb)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with base_user as (
    select
      ura.user_id,
      r.key as profile_type,
      coalesce(nullif(fn.value_text, ''), 'CorteQS Üyesi') as display_name
    from public.user_role_assignments ura
    join public.roles r on r.id = ura.role_id
    left join lateral (
      select upa.value_text
      from public.user_profile_attributes upa
      join public.afs_attributes ac on ac.id = upa.attribute_id
      where upa.user_id = ura.user_id
        and ac.key = 'full_name'
      limit 1
    ) fn on true
    where ura.user_id = target_user_id
  ),
  feature_state as (
    select
      fc.key,
      coalesce(ufo.is_enabled, rff.is_enabled, false)
        and coalesce(fc.is_active_globally, false) as is_enabled
    from base_user bu
    join public.roles r on r.key = bu.profile_type
    join public.afs_features fc
      on fc.key in (
        'directory.visible',
        'profile.linkedin_card',
        'profile.website_card',
        'individual.job_seeking_badge',
        'individual.moving_soon_badge',
        'individual.volunteer_mentorship'
      )
    left join public.role_features rff
      on rff.role_id = r.id
     and rff.feature_key = fc.key
    left join public.user_feature_overrides ufo
      on ufo.user_id = bu.user_id
     and ufo.feature_key = fc.key
  ),
  visibility_gate as (
    select
      bu.user_id,
      coalesce(
        (select fs.is_enabled from feature_state fs where fs.key = 'directory.visible'),
        false
      ) as directory_visible
    from base_user bu
  ),
  role_meta as (
    select
      r.key,
      r.label
    from base_user bu
    join public.roles r on r.key = bu.profile_type
  ),
  public_attributes as (
    select
      ac.key,
      upa.value_text,
      upa.value_json
    from public.user_profile_attributes upa
    join public.afs_attributes ac on ac.id = upa.attribute_id
    where upa.user_id = target_user_id
      and upa.visibility = 'public'
      and upa.approval_status = 'approved'
  ),
  extra_badges as (
    select coalesce(jsonb_agg(label order by sort_order), '[]'::jsonb) as labels
    from (
      select 10 as sort_order, 'İş Arıyorum' as label
      where exists (
        select 1
        from public_attributes pa
        where pa.key = 'job_seeking_opt_in'
          and pa.value_json = 'true'::jsonb
      )
        and coalesce((select fs.is_enabled from feature_state fs where fs.key = 'individual.job_seeking_badge'), false)

      union all

      select 20 as sort_order, 'Yakında Taşınacağım' as label
      where exists (
        select 1
        from public_attributes pa
        where pa.key = 'moving_soon_opt_in'
          and pa.value_json = 'true'::jsonb
      )
        and coalesce((select fs.is_enabled from feature_state fs where fs.key = 'individual.moving_soon_badge'), false)

      union all

      select 30 as sort_order, 'Gönüllü Mentör' as label
      where exists (
        select 1
        from public_attributes pa
        where pa.key = 'volunteer_mentorship_opt_in'
          and pa.value_json = 'true'::jsonb
      )
        and coalesce((select fs.is_enabled from feature_state fs where fs.key = 'individual.volunteer_mentorship'), false)
    ) badges
  ),
  public_links as (
    select 10 as sort_order, jsonb_build_object('label', 'Website', 'url', pa.value_text) as link
    from public_attributes pa
    where pa.key = 'website_url'
      and coalesce((select fs.is_enabled from feature_state fs where fs.key = 'profile.website_card'), false)

    union all

    select 20 as sort_order, jsonb_build_object('label', 'LinkedIn', 'url', pa.value_text) as link
    from public_attributes pa
    where pa.key = 'linkedin_url'
      and coalesce((select fs.is_enabled from feature_state fs where fs.key = 'profile.linkedin_card'), false)

    union all

    select 30 as sort_order, jsonb_build_object('label', 'Instagram', 'url', pa.value_text) as link
    from public_attributes pa
    where pa.key = 'instagram_url'

    union all

    select 40 as sort_order, jsonb_build_object('label', 'Facebook', 'url', pa.value_text) as link
    from public_attributes pa
    where pa.key = 'facebook_url'

    union all

    select 50 as sort_order, jsonb_build_object('label', 'YouTube', 'url', pa.value_text) as link
    from public_attributes pa
    where pa.key = 'youtube_url'

    union all

    select 60 as sort_order, jsonb_build_object('label', 'TikTok', 'url', pa.value_text) as link
    from public_attributes pa
    where pa.key = 'tiktok_url'

    union all

    select 70 as sort_order, jsonb_build_object('label', 'X (Twitter)', 'url', pa.value_text) as link
    from public_attributes pa
    where pa.key = 'x_url'

    union all

    select 80 as sort_order, jsonb_build_object('label', 'Reddit', 'url', pa.value_text) as link
    from public_attributes pa
    where pa.key = 'reddit_url'
  ),
  allowed_sections as (
    select
      psc.key,
      psc.section_area,
      psc.label,
      psc.component_key as component_name,
      coalesce(rpsr.sort_order, psc.sort_order) as sort_order
    from base_user bu
    join public.roles r on r.key = bu.profile_type
    join public.role_sections rpsr on rpsr.role_id = r.id and rpsr.is_enabled = true
    join public.afs_sections psc on psc.id = rpsr.section_id and psc.is_active = true
    where psc.key <> 'detail.taxonomy_etiketleri'
  )
  select
    s.key as section_key,
    s.section_area,
    s.label,
    s.component_name,
    s.sort_order,
    case s.key
      when 'preview.isim_kurulus_adi' then jsonb_build_object('text', (select display_name from base_user))
      when 'preview.konum' then jsonb_build_object(
        'city', (select value_text from public_attributes where key = 'city'),
        'country', (select value_text from public_attributes where key = 'country')
      )
      when 'preview.profil_logo_gorseli' then jsonb_build_object('url', (select value_text from public_attributes where key = 'profile_photo_url'))
      when 'preview.kategori_sektor_etiketi' then jsonb_build_object(
        'primary_label',
        coalesce(
          (select value_text from public_attributes where key in ('interests', 'expertise_area', 'business_category', 'organization_type', 'main_platform', 'ambassador_city') limit 1),
          (select label from role_meta limit 1)
        ),
        'extra_badges',
        coalesce((select labels from extra_badges), '[]'::jsonb)
      )
      when 'detail.hakkinda_bio' then jsonb_build_object('text', (select value_text from public_attributes where key = 'bio_short'))
      when 'detail.iletisim_linkleri' then jsonb_build_object(
        'links',
        coalesce((select jsonb_agg(pl.link order by pl.sort_order) from public_links pl), '[]'::jsonb)
      )
      else '{}'::jsonb
    end as content
  from allowed_sections s
  join visibility_gate vg on vg.directory_visible = true
  where (
      s.key = 'preview.isim_kurulus_adi'
      or (s.key = 'preview.konum' and exists (select 1 from public_attributes where key in ('city', 'country')))
      or (s.key = 'preview.profil_logo_gorseli' and exists (select 1 from public_attributes where key = 'profile_photo_url'))
      or (s.key = 'preview.kategori_sektor_etiketi' and (
        exists (select 1 from public_attributes where key in ('interests', 'expertise_area', 'business_category', 'organization_type', 'main_platform', 'ambassador_city'))
        or exists (select 1 from role_meta)
        or exists (select 1 from extra_badges eb, jsonb_array_elements_text(eb.labels) badge)
      ))
      or (s.key = 'detail.hakkinda_bio' and exists (select 1 from public_attributes where key = 'bio_short'))
      or (s.key = 'detail.iletisim_linkleri' and exists (select 1 from public_links))
    )
  order by s.sort_order, s.key;
$$;


--
-- Name: get_rebuild_status_report(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_rebuild_status_report() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb;
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'generated_at', now(),
    'roles_total', (select count(*) from public.roles),
    'roles_active', (select count(*) from public.roles where is_active = true and deleted_at is null),
    'legacy_roles', (select count(*) from public.roles
                      where key in ('bireysel','danisman','isletme','kurulus-dernek',
                                    'blogger-vlogger-youtuber','sehir-elcisi')),
    'afs_attributes', (select count(*) from public.afs_attributes),
    'afs_features', (select count(*) from public.afs_features),
    'afs_sections', (select count(*) from public.afs_sections),
    'role_attributes', (select count(*) from public.role_attributes),
    'role_features', (select count(*) from public.role_features),
    'role_sections', (select count(*) from public.role_sections),
    'catalog_items_total', (select count(*) from public.catalog_items),
    'placeholders', (select count(*) from public.catalog_items where is_placeholder = true),
    'item_role_links', (select count(*) from public.catalog_item_roles),
    'items_without_primary_role', (
      select count(*) from public.catalog_items ci
      where ci.is_placeholder = false
        and not exists (select 1 from public.catalog_item_roles cir
                        where cir.catalog_item_id = ci.id and cir.is_primary)
    ),
    'legacy_tables_remaining', (
      select count(*) from information_schema.tables
      where table_schema = 'public'
        and table_name in ('catalog_item_types','item_type_attribute_rules',
                           'item_type_feature_defaults','item_type_features','role_taxonomy_rules')
    ),
    'family_columns_remaining', (
      select count(*) from information_schema.columns
      where table_schema = 'public' and table_name = 'roles'
        and column_name in ('family_key','parent_role_id','default_item_type')
    ),
    'old_table_names_remaining', (
      select count(*) from information_schema.tables
      where table_schema = 'public'
        and table_name in ('attribute_catalog','feature_catalog','profile_section_catalog',
                           'role_attribute_rules','role_feature_flags','role_profile_section_rules',
                           'catalog_item_attributes','catalog_claim_requests','catalog_item_memberships')
    )
  ) into v;

  return v;
end;
$$;


--
-- Name: FUNCTION get_rebuild_status_report(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_rebuild_status_report() IS 'Rebuild 2026-06-09: live status metrics for the admin Durum Raporu page (admin-gated).';


--
-- Name: get_role_form_schema(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_role_form_schema(p_role_key text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role_id uuid;
  v_result jsonb;
begin
  select id into v_role_id from public.roles
   where key = p_role_key and is_active = true and deleted_at is null;
  if v_role_id is null then
    return jsonb_build_object('error', 'role_not_found');
  end if;

  select jsonb_build_object(
    'role_key', p_role_key,
    'attributes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'key', a.key, 'label', a.label, 'data_type', a.data_type,
        'is_required', ra.is_required, 'is_public', ra.is_public,
        'owner_can_edit', ra.owner_can_edit, 'sort_order', ra.sort_order
      ) order by ra.sort_order)
      from public.role_attributes ra
      join public.afs_attributes a on a.id = ra.attribute_id
      where ra.role_id = v_role_id
    ), '[]'::jsonb),
    'features', coalesce((
      select jsonb_agg(jsonb_build_object('key', rf.feature_key, 'is_enabled', rf.is_enabled))
      from public.role_features rf
      where rf.role_id = v_role_id and rf.is_enabled = true
    ), '[]'::jsonb),
    'sections', coalesce((
      select jsonb_agg(jsonb_build_object(
        'key', s.key, 'label', s.label, 'section_area', s.section_area,
        'component_key', s.component_key, 'sort_order', rs.sort_order
      ) order by rs.sort_order)
      from public.role_sections rs
      join public.afs_sections s on s.id = rs.section_id
      where rs.role_id = v_role_id and rs.is_enabled = true
    ), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$$;


--
-- Name: FUNCTION get_role_form_schema(p_role_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_role_form_schema(p_role_key text) IS 'Rebuild 2026-06-09: explicit AFS schema for a role (no inheritance).';


--
-- Name: get_role_management_bundle(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_role_management_bundle(p_role_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role_id   uuid;
  v_role_label text;
  v_result    jsonb;
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'forbidden'
      using errcode = '42501';
  end if;

  select id, label
  into v_role_id, v_role_label
  from public.roles
  where key = p_role_key and is_active = true
  limit 1;

  if v_role_id is null then
    raise exception 'role not found: %', p_role_key
      using errcode = 'P0002';
  end if;

  -- Attributes
  with attr_rows as (
    select
      ac.key,
      ac.label,
      coalesce(em.description, ac.description) as description,
      em.admin_note,
      jsonb_build_object(
        'is_enabled',                           coalesce(rar.is_enabled, false),
        'is_required',                          coalesce(rar.is_required, false),
        'is_public_default',                    coalesce(rar.is_public_default, false),
        'user_can_edit',                        coalesce(rar.user_can_edit, true),
        'user_can_hide',                        coalesce(rar.user_can_hide, true),
        'requires_admin_approval_on_change',    coalesce(rar.requires_admin_approval_on_change, false),
        'sort_order',                           coalesce(rar.sort_order, ac.sort_order)
      ) as rule
    from public.afs_attributes ac
    left join public.role_attributes rar
      on rar.attribute_id = ac.id and rar.role_id = v_role_id
    left join public.entity_metadata em
      on em.entity_type = 'attribute' and em.entity_key = ac.key
    where ac.is_active = true
    order by coalesce(rar.sort_order, ac.sort_order), ac.key
  ),
  -- Features
  feat_rows as (
    select
      fc.key,
      fc.label,
      coalesce(em.description, fc.description) as description,
      em.admin_note,
      fc.is_active_globally,
      coalesce(rff.is_enabled, false) as is_enabled
    from public.afs_features fc
    left join public.role_features rff
      on rff.role_id = v_role_id and rff.feature_key = fc.key
    left join public.entity_metadata em
      on em.entity_type = 'feature' and em.entity_key = fc.key
    order by fc.key
  ),
  -- Profile sections
  sect_rows as (
    select
      psc.key,
      psc.label,
      coalesce(em.description, psc.description) as description,
      em.admin_note,
      psc.section_area,
      jsonb_build_object(
        'is_enabled',          coalesce(rpsr.is_enabled, false),
        'requires_approval',   coalesce(rpsr.requires_approval, false),
        'sort_order',          coalesce(rpsr.sort_order, psc.sort_order)
      ) as rule
    from public.afs_sections psc
    left join public.role_sections rpsr
      on rpsr.role_id = v_role_id and rpsr.section_id = psc.id
    left join public.entity_metadata em
      on em.entity_type = 'profile_section' and em.entity_key = psc.key
    where psc.is_active = true
    order by coalesce(rpsr.sort_order, psc.sort_order), psc.key
  )
  select jsonb_build_object(
    'role',       jsonb_build_object('id', v_role_id, 'key', p_role_key, 'label', v_role_label),
    'attributes', coalesce((select jsonb_agg(to_jsonb(r)) from attr_rows r), '[]'::jsonb),
    'features',   coalesce((select jsonb_agg(to_jsonb(r)) from feat_rows r), '[]'::jsonb),
    'sections',   coalesce((select jsonb_agg(to_jsonb(r)) from sect_rows r), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;


--
-- Name: get_submission_documents_bucket_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_submission_documents_bucket_stats() RETURNS TABLE(bucket_id text, file_count bigint, total_bytes bigint, file_size_limit bigint, usage_ratio numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'storage'
    AS $$
begin
  if not public.is_admin(auth.uid()) then
    raise exception 'Admin access required';
  end if;

  return query
  select
    bucket_row.id::text as bucket_id,
    count(storage_object.id)::bigint as file_count,
    coalesce(sum(coalesce((storage_object.metadata ->> 'size')::bigint, 0)), 0)::bigint as total_bytes,
    coalesce(bucket_row.file_size_limit, 0)::bigint as file_size_limit,
    case
      when coalesce(bucket_row.file_size_limit, 0) > 0 then
        round(
          coalesce(sum(coalesce((storage_object.metadata ->> 'size')::bigint, 0)), 0)::numeric
          / bucket_row.file_size_limit::numeric,
          6
        )
      else 0::numeric
    end as usage_ratio
  from storage.buckets bucket_row
  left join storage.objects storage_object
    on storage_object.bucket_id = bucket_row.id
  where bucket_row.id = 'submission-documents'
  group by bucket_row.id, bucket_row.file_size_limit;
end;
$$;


--
-- Name: handle_new_auth_user_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_auth_user_role() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_default_role_id uuid;
begin
  select id into v_default_role_id
  from public.roles
  where key = 'User_DiasporaMember' and is_active = true
  limit 1;

  if v_default_role_id is not null then
    insert into public.user_role_assignments (user_id, role_id)
    values (new.id, v_default_role_id)
    on conflict (user_id) do nothing;
  end if;

  perform public.sync_member_catalog_role_for_user(new.id);

  return new;
end;
$$;


--
-- Name: has_cadde_feature(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_cadde_feature(uid uuid, fkey text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with effective_role as (
    select r.id as role_id, r.key as role_key
    from public.user_role_assignments ura
    join public.roles r on r.id = ura.role_id
    where ura.user_id = uid
    limit 1
  )
  select not public.is_cadde_banned(uid)
     and coalesce((
    select fc.is_active_globally and coalesce(ufo.is_enabled, rff.is_enabled, false)
    from public.afs_features fc
    join effective_role er
      on fc.scope_role = '*' or fc.scope_role = er.role_key
    left join public.role_features rff
      on rff.role_id = er.role_id and rff.feature_key = fc.key
    left join public.user_feature_overrides ufo
      on ufo.user_id = uid and ufo.feature_key = fc.key
    where fc.key = fkey
  ), false);
$$;


--
-- Name: is_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_admin(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.user_role_assignments ura
    join public.roles r on r.id = ura.role_id
    where ura.user_id = uid
      and r.key ilike 'Admin_%'
  );
$$;


--
-- Name: FUNCTION is_admin(uid uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_admin(uid uuid) IS 'Checks the canonical profiles.platform_role first and falls back to legacy admin_users during migration.';


--
-- Name: is_admin_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_admin_user(check_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.is_admin(check_user_id);
$$;


--
-- Name: is_cadde_banned(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_cadde_banned(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.cadde_user_bans
    where user_id = uid
      and scope = 'cadde'
      and starts_at <= now()
      and (ends_at is null or ends_at > now())
  );
$$;


--
-- Name: is_cadde_moderator(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_cadde_moderator(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select uid is not null
     and (public.is_admin(uid) or public.is_moderator(uid));
$$;


--
-- Name: is_cadde_profile_complete(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_cadde_profile_complete(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(nullif(trim(public.cadde_attr_text(uid, 'country')), ''), '') <> ''
     and coalesce(nullif(trim(public.cadde_attr_text(uid, 'city')), ''), '') <> ''
     and (not public.cadde_phone_required() or public.is_phone_verified(uid));
$$;


--
-- Name: is_diaspora_resident(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_diaspora_resident(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(nullif(trim(public.cadde_attr_text(uid, 'country')), ''), '') <> ''
         and not public.is_tr_resident(uid);
$$;


--
-- Name: is_moderator(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_moderator(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.user_role_assignments ura
    join public.roles r on r.id = ura.role_id
    where ura.user_id = uid
      and (r.key ilike 'Admin_%' or r.key = 'moderator')
  );
$$;


--
-- Name: FUNCTION is_moderator(uid uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_moderator(uid uuid) IS 'Returns true for moderators and admins. Uses user_role_assignments (profiles table removed in 20260609003000).';


--
-- Name: is_phone_verified(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_phone_verified(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.user_verifications
    where user_id = uid and phone_verified_at is not null
  );
$$;


--
-- Name: is_tr_resident(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_tr_resident(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select lower(coalesce(public.cadde_attr_text(uid, 'country'), ''))
         in ('türkiye', 'turkiye', 'tr');
$$;


--
-- Name: join_cadde_cafe_v1(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.join_cadde_cafe_v1(p_cafe_id uuid, p_referral_code text DEFAULT NULL::text, p_answer text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_cafe public.cadde_cafes%rowtype;
  v_policy_error text;
  v_existing public.cadde_cafe_members%rowtype;
  v_answer text := nullif(trim(coalesce(p_answer, '')), '');
  v_referral text := nullif(trim(coalesce(p_referral_code, '')), '');
  v_today_joins integer;
  v_member_id uuid;
  v_status text;
begin
  if v_uid is null then
    raise exception 'cadde_auth_required';
  end if;

  if not public.is_cadde_profile_complete(v_uid) then
    if public.cadde_phone_required() and not public.is_phone_verified(v_uid) then
      raise exception 'phone_verification_required';
    end if;
    raise exception 'cadde_profile_incomplete';
  end if;

  if not public.has_cadde_feature(v_uid, 'cadde.cafe.join') then
    if public.is_cadde_banned(v_uid) then
      raise exception 'cadde_banned';
    end if;
    raise exception 'cadde_cafe_join_permission_denied';
  end if;

  select * into v_existing
  from public.cadde_cafe_members
  where cafe_id = p_cafe_id and user_id = v_uid;

  if v_existing.id is not null then
    if v_existing.status = 'rejected' then
      raise exception 'cadde_cafe_join_denied';
    end if;
    return jsonb_build_object('memberId', v_existing.id, 'status', v_existing.status);
  end if;

  v_policy_error := public.can_join_cadde_cafe(v_uid, p_cafe_id);
  if v_policy_error is not null then
    raise exception '%', v_policy_error;
  end if;

  if not (public.is_admin(v_uid) or public.is_moderator(v_uid)) then
    select count(*) into v_today_joins
    from public.cadde_cafe_members
    where user_id = v_uid and joined_at > now() - interval '24 hours';
    if v_today_joins >= public.cadde_setting_int('cadde.cafe.daily_join_limit', 10) then
      raise exception 'cadde_rate_limit';
    end if;
  end if;

  select * into v_cafe from public.cadde_cafes where id = p_cafe_id;

  if v_cafe.entry_mode = 'referral' then
    if v_referral is null
       or v_cafe.referral_code_hash is distinct from encode(digest(upper(v_referral), 'sha256'), 'hex') then
      raise exception 'cadde_cafe_invalid_referral';
    end if;
    v_status := 'approved';
  elsif v_cafe.entry_mode = 'approval' then
    if v_answer is null then
      raise exception 'cadde_cafe_answer_required';
    end if;
    v_status := 'pending';
  else
    v_status := 'approved';
  end if;

  insert into public.cadde_cafe_members (cafe_id, user_id, status, answer, approved_at, approved_by)
  values (
    p_cafe_id, v_uid, v_status, v_answer,
    case when v_status = 'approved' then now() end,
    case when v_status = 'approved' then v_uid end
  )
  returning id into v_member_id;

  if v_status = 'pending' then
    perform public.cadde_notify(
      v_cafe.host_user_id, v_uid, 'cadde.cafe.joined',
      'Cafe katılım talebi',
      coalesce(v_answer, 'Yeni katılım talebi bekliyor.'),
      'cafe', p_cafe_id,
      jsonb_build_object('memberId', v_member_id)
    );
  end if;

  return jsonb_build_object('memberId', v_member_id, 'status', v_status);
end;
$$;


--
-- Name: list_cadde_feed_v1(jsonb, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_cadde_feed_v1(p_filters jsonb DEFAULT '{}'::jsonb, p_cursor jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_limit int := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_diaspora text := coalesce(nullif(trim(coalesce(p_filters ->> 'diaspora', '')), ''), 'tr');
  v_filter_countries text[];
  v_filter_cities text[];
  v_filter_interests text[];
  v_bridge boolean := coalesce((p_filters ->> 'bridge')::boolean, false);
  v_hashtag text := public.cadde_normalize_tag(coalesce(p_filters ->> 'hashtag', ''));
  v_feed_scope text := lower(coalesce(nullif(trim(coalesce(p_filters ->> 'scope', '')), ''), 'all'));
  v_global_enabled boolean := public.cadde_setting_bool('cadde.global.enabled', true);
  v_global_min_reactions int := public.cadde_setting_int('cadde.global.min_reactions', 10);
  v_global_min_comments int := public.cadde_setting_int('cadde.global.min_comments', 5);
  v_global_min_shares int := public.cadde_setting_int('cadde.global.min_shares', 10);
  v_country_ids uuid[];
  v_city_ids uuid[];
  v_viewer_country_id uuid;
  v_viewer_city_id uuid;
  v_scope text;
  v_viewer_interests text[];
  v_avg numeric;
  v_cur_band int := (p_cursor ->> 'band')::int;
  v_cur_score numeric := (p_cursor ->> 'score')::numeric;
  v_cur_rand int := (p_cursor ->> 'rand')::int;
  v_cur_id uuid := (p_cursor ->> 'id')::uuid;
  v_all jsonb;
  v_total int;
  v_items jsonb;
  v_next jsonb := null;
  v_last jsonb;
begin
  if v_uid is null then
    return jsonb_build_object('items', '[]'::jsonb, 'nextCursor', null);
  end if;

  select coalesce(array_agg(x), '{}') into v_filter_countries
  from jsonb_array_elements_text(coalesce(p_filters -> 'countries', '[]'::jsonb)) x
  where trim(x) <> '';

  select coalesce(array_agg(x), '{}') into v_filter_cities
  from jsonb_array_elements_text(coalesce(p_filters -> 'cities', '[]'::jsonb)) x
  where trim(x) <> '';

  select coalesce(array_agg(x), '{}') into v_filter_interests
  from jsonb_array_elements_text(coalesce(p_filters -> 'interests', '[]'::jsonb)) x
  where trim(x) <> '';

  select coalesce(array_agg(c.id), '{}') into v_country_ids
  from public.cadde_countries c
  where c.is_active = true and c.name = any(v_filter_countries);

  select coalesce(array_agg(ci.id), '{}') into v_city_ids
  from public.cadde_cities ci
  where ci.is_active = true
    and ci.name = any(v_filter_cities)
    and (cardinality(v_country_ids) = 0 or ci.country_id = any(v_country_ids));

  select c.id into v_viewer_country_id
  from public.cadde_countries c
  where c.is_active = true
    and public.cadde_fold_text(c.name) = public.cadde_fold_text(coalesce(nullif(trim(public.cadde_attr_text(v_uid, 'country')), ''), '~'))
  limit 1;

  select ci.id into v_viewer_city_id
  from public.cadde_cities ci
  where ci.is_active = true
    and public.cadde_fold_text(ci.name) = public.cadde_fold_text(coalesce(nullif(trim(public.cadde_attr_text(v_uid, 'city')), ''), '~'))
    and (v_viewer_country_id is null or ci.country_id = v_viewer_country_id)
  limit 1;

  v_scope := coalesce(
    nullif(trim(public.cadde_attr_text(v_uid, 'city')), ''),
    nullif(trim(public.cadde_attr_text(v_uid, 'country')), ''),
    'global'
  );

  select coalesce(array_agg(interest_key), '{}') into v_viewer_interests
  from public.user_cadde_interests
  where user_id = v_uid;

  select coalesce(avg(engagement_score), 0) into v_avg
  from public.cadde_posts
  where content_mode = 'real' and status = 'published' and visibility = 'public'
    and diaspora_key = v_diaspora
    and coalesce(published_at, created_at) > now() - interval '7 days';

  with base as (
    select p.*
    from public.cadde_posts p
    where p.content_mode = 'real'
      and p.status = 'published'
      and (
        case
          when v_feed_scope = 'cafes' then
            p.visibility = 'cafe' and exists (
              select 1 from public.cadde_cafe_members m
              where m.cafe_id = p.cafe_id and m.user_id = v_uid and m.status = 'approved'
            )
          else p.visibility = 'public'
        end
      )
      and (v_hashtag = '' or exists (
        select 1 from public.cadde_post_hashtags ph
        where ph.post_id = p.id and ph.tag = v_hashtag
      ))
      and (
        case v_feed_scope
          when 'city' then v_viewer_city_id is not null and (
            p.city_id = v_viewer_city_id
            or exists (select 1 from public.cadde_post_targets t where t.post_id = p.id and t.city_id = v_viewer_city_id)
          )
          when 'country' then v_viewer_country_id is not null and (
            p.country_id = v_viewer_country_id
            or exists (select 1 from public.cadde_post_targets t where t.post_id = p.id and t.country_id = v_viewer_country_id)
          )
          when 'events' then p.post_type = 'event'
          else true
        end
      )
      and p.diaspora_key = v_diaspora
      and (not v_bridge or p.is_bridge)
      and (
        cardinality(v_country_ids) = 0
        or p.country_id = any(v_country_ids)
        or exists (select 1 from public.cadde_post_targets t where t.post_id = p.id and t.country_id = any(v_country_ids))
      )
      and (
        cardinality(v_city_ids) = 0
        or p.city_id = any(v_city_ids)
        or exists (select 1 from public.cadde_post_targets t where t.post_id = p.id and t.city_id = any(v_city_ids))
      )
      and (
        v_feed_scope in ('city', 'country', 'events', 'cafes')
        or cardinality(v_country_ids) > 0
        or cardinality(v_city_ids) > 0
        or (v_viewer_city_id is not null and (
          p.city_id = v_viewer_city_id
          or exists (select 1 from public.cadde_post_targets t where t.post_id = p.id and t.city_id = v_viewer_city_id)
        ))
        or (v_viewer_country_id is not null and (
          p.country_id = v_viewer_country_id
          or exists (select 1 from public.cadde_post_targets t where t.post_id = p.id and t.country_id = v_viewer_country_id)
        ))
        or (
          v_global_enabled
          and (
            p.reaction_count >= v_global_min_reactions
            or p.comment_count >= v_global_min_comments
            or coalesce(p.share_count, 0) >= v_global_min_shares
          )
        )
      )
      and (cardinality(v_filter_interests) = 0 or exists (
        select 1 from public.cadde_post_interests pi
        where pi.post_id = p.id and pi.interest_key = any(v_filter_interests)
      ))
  ),
  scored as (
    select
      b.*,
      cn.name as country_name,
      ct.name as city_name,
      same_city,
      same_country,
      need_match,
      interest_overlap,
      case
        when same_city and need_match then 1
        when same_city then 2
        when same_country then 3
        when v_avg > 0 and b.engagement_score >= 2 * v_avg then 4
        when v_avg > 0 and b.engagement_score >= 1.5 * v_avg then 5
        else 6
      end as band,
      (case when same_city then 100 when same_country then 60 else 0 end)
      + (case when v_bridge and b.is_bridge then 50 else 0 end)
      + (case when need_match then 40 else 0 end)
      + least(interest_overlap * 8, 32)
      + (case
           when not same_city and not same_country and v_avg > 0 and b.engagement_score >= 2 * v_avg then 35
           when not same_city and not same_country and v_avg > 0 and b.engagement_score >= 1.5 * v_avg then 20
           else 0
         end)
      + (case when b.pinned then 120 else 0 end)
      + (case
           when now() - coalesce(b.published_at, b.created_at) <= interval '6 hours' then 25
           when now() - coalesce(b.published_at, b.created_at) <= interval '24 hours' then 15
           when now() - coalesce(b.published_at, b.created_at) <= interval '7 days' then 5
           else 0
         end) as score,
      hashtext(b.id::text || to_char(current_date, 'YYYY-MM-DD') || v_scope) as rand
    from base b
    left join public.cadde_countries cn on cn.id = b.country_id
    left join public.cadde_cities ct on ct.id = b.city_id
    cross join lateral (
      select
        (v_viewer_city_id is not null and (
          b.city_id = v_viewer_city_id
          or exists (select 1 from public.cadde_post_targets t where t.post_id = b.id and t.city_id = v_viewer_city_id)
        )) as same_city,
        (v_viewer_country_id is not null and (
          b.country_id = v_viewer_country_id
          or exists (select 1 from public.cadde_post_targets t where t.post_id = b.id and t.country_id = v_viewer_country_id)
        )) as same_country,
        (b.need_category is not null and b.need_category = any(v_viewer_interests)) as need_match,
        (select count(*)::int from public.cadde_post_interests pi
         where pi.post_id = b.id and pi.interest_key = any(v_viewer_interests)) as interest_overlap
    ) flags
  ),
  page as (
    select *
    from scored s
    where p_cursor is null
       or (s.band > v_cur_band)
       or (s.band = v_cur_band and s.score < v_cur_score)
       or (s.band = v_cur_band and s.score = v_cur_score and s.rand > v_cur_rand)
       or (s.band = v_cur_band and s.score = v_cur_score and s.rand = v_cur_rand and s.id > v_cur_id)
    order by s.band asc, s.score desc, s.rand asc, s.id asc
    limit v_limit + 1
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', pg.id,
      'author_user_id', pg.author_user_id,
      'author_name_override', pg.author_name_override,
      'author_role', pg.author_role,
      'author_avatar_url', pg.author_avatar_url,
      'content_mode', pg.content_mode,
      'status', pg.status,
      'post_type', pg.post_type,
      'title', pg.title,
      'body', pg.body,
      'country_id', pg.country_id,
      'city_id', pg.city_id,
      'country_name', pg.country_name,
      'city_name', pg.city_name,
      'targets', coalesce((
        select jsonb_agg(jsonb_build_object(
          'country_id', t.country_id,
          'city_id', t.city_id,
          'country_name', target_country.name,
          'city_name', target_city.name
        ) order by target_country.name, target_city.name nulls first)
        from public.cadde_post_targets t
        join public.cadde_countries target_country on target_country.id = t.country_id
        left join public.cadde_cities target_city on target_city.id = t.city_id
        where t.post_id = pg.id
      ), '[]'::jsonb),
      'is_bridge', pg.is_bridge,
      'pinned', pg.pinned,
      'created_at', pg.created_at,
      'published_at', pg.published_at,
      'need_category', pg.need_category,
      'engagement_score', pg.engagement_score,
      'reaction_count', pg.reaction_count,
      'comment_count', pg.comment_count,
      'share_count', pg.share_count,
      'media', pg.media,
      'hashtags', coalesce((
        select jsonb_agg(jsonb_build_object('tag', ph.tag, 'displayTag', h.display_tag) order by ph.tag)
        from public.cadde_post_hashtags ph
        join public.cadde_hashtags h on h.tag = ph.tag
        where ph.post_id = pg.id
      ), '[]'::jsonb),
      'mentions', coalesce((
        select jsonb_agg(jsonb_build_object('type', pm.target_type, 'id', pm.target_id, 'label', pm.display_label) order by pm.target_type, pm.target_id)
        from public.cadde_post_mentions pm where pm.post_id = pg.id
      ), '[]'::jsonb),
      'interests', coalesce((
        select jsonb_agg(pi.interest_key order by pi.interest_key)
        from public.cadde_post_interests pi where pi.post_id = pg.id
      ), '[]'::jsonb),
      'band', pg.band,
      'score', pg.score,
      'rand', pg.rand
    ) order by pg.band asc, pg.score desc, pg.rand asc, pg.id asc), '[]'::jsonb),
    count(*)
  into v_all, v_total
  from page pg;

  if v_total > v_limit then
    select coalesce(jsonb_agg(e.value order by e.ordinality), '[]'::jsonb)
    into v_items
    from jsonb_array_elements(v_all) with ordinality e
    where e.ordinality <= v_limit;

    v_last := v_all -> (v_limit - 1);
    v_next := jsonb_build_object(
      'band', v_last -> 'band',
      'score', v_last -> 'score',
      'rand', v_last -> 'rand',
      'id', v_last -> 'id'
    );
  else
    v_items := v_all;
  end if;

  return jsonb_build_object('items', v_items, 'nextCursor', v_next);
end;
$$;


--
-- Name: list_cadde_promotions_v1(text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_cadde_promotions_v1(p_placement_key text, p_filters jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_limit int := least(greatest(coalesce(p_limit, 5), 1), 20);
  v_diaspora text := coalesce(nullif(trim(coalesce(p_filters ->> 'diaspora', '')), ''), 'tr');
  v_filter_countries text[];
  v_filter_cities text[];
  v_country_ids uuid[];
  v_city_ids uuid[];
  v_items jsonb;
begin
  if v_uid is null then
    return '[]'::jsonb;
  end if;

  select coalesce(array_agg(x), '{}') into v_filter_countries
  from jsonb_array_elements_text(coalesce(p_filters -> 'countries', '[]'::jsonb)) x
  where trim(x) <> '';

  select coalesce(array_agg(x), '{}') into v_filter_cities
  from jsonb_array_elements_text(coalesce(p_filters -> 'cities', '[]'::jsonb)) x
  where trim(x) <> '';

  select coalesce(array_agg(c.id), '{}') into v_country_ids
  from public.cadde_countries c
  where c.is_active = true and c.name = any(v_filter_countries);

  select coalesce(array_agg(ci.id), '{}') into v_city_ids
  from public.cadde_cities ci
  where ci.is_active = true
    and ci.name = any(v_filter_cities)
    and (cardinality(v_country_ids) = 0 or ci.country_id = any(v_country_ids));

  select coalesce(jsonb_agg(card), '[]'::jsonb) into v_items
  from (
    select jsonb_build_object(
      'campaignId', c.id,
      'placementKey', pl.placement_key,
      'campaignType', c.campaign_type,
      'title', c.title,
      'description', c.description,
      'targetUrl', c.target_url,
      'imageUrl', c.image_url
    ) as card
    from public.cadde_promotion_campaigns c
    join public.cadde_promotion_placements pl on pl.campaign_id = c.id
    where c.status = 'approved'
      and (c.starts_at is null or c.starts_at <= now())
      and (c.ends_at is null or c.ends_at > now())
      and pl.placement_key = p_placement_key
      and pl.diaspora_key = v_diaspora
      and (cardinality(v_country_ids) = 0 or pl.country_id is null or pl.country_id = any(v_country_ids))
      and (cardinality(v_city_ids) = 0 or pl.city_id is null or pl.city_id = any(v_city_ids))
    order by pl.sort_order asc, c.approved_at desc
    limit v_limit
  ) cards;

  return v_items;
end;
$$;


--
-- Name: list_member_catalog_names(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_member_catalog_names(p_user_ids uuid[]) RETURNS TABLE(user_id uuid, full_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
