--
-- Name: normalize_survey_slug(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_survey_slug() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
begin
  new.slug = lower(trim(new.slug));
  new.slug = regexp_replace(new.slug, '[^a-z0-9]+', '-', 'g');
  new.slug = regexp_replace(new.slug, '(^-|-$)', '', 'g');
  return new;
end;
$_$;


