--
-- Name: pick_fallback_image(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pick_fallback_image(p_category text) RETURNS TABLE(public_url text, pool_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.fallback_image_pool%rowtype;
  v_base_url constant text := 'https://injprdrsklkxgnaiixzh.supabase.co';
BEGIN
  IF p_category <> 'news_diaspora' THEN
    RAISE EXCEPTION 'fallback_image_invalid_category';
  END IF;

  SELECT * INTO v_row
  FROM public.fallback_image_pool
  WHERE category = p_category AND is_active = true
  ORDER BY used_count ASC, random()
  LIMIT 1
  FOR UPDATE SKIP LOCKED;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  UPDATE public.fallback_image_pool
  SET used_count = used_count + 1
  WHERE id = v_row.id;

  RETURN QUERY SELECT
    v_base_url || '/storage/v1/object/public/' || v_row.storage_bucket || '/' || v_row.storage_path,
    v_row.id;
END;
$$;


--
-- Name: FUNCTION pick_fallback_image(p_category text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pick_fallback_image(p_category text) IS 'category=''news_diaspora'' için en az kullanılan aktif görseli seçer, used_count''ı artırır, public URL döner. Yalnızca Radar News akışı kullanır — service-finder/mekan bu havuzu kullanmaz. Havuz boşsa satır dönmez.';


--
-- Name: poke_notification_dispatcher(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.poke_notification_dispatcher() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_url text;
  v_secret text;
begin
  if not exists (select 1 from pg_extension where extname = 'pg_net') then
    return;
  end if;

  select value #>> '{}' into v_url from public.notification_settings where key = 'dispatch.url';
  select value #>> '{}' into v_secret from public.notification_settings where key = 'dispatch.secret';

  if coalesce(v_url, '') = '' or coalesce(v_secret, '') = '' then
    return;
  end if;

  perform net.http_post(
    url := v_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-dispatch-secret', v_secret
    ),
    body := jsonb_build_object('source', 'db')
  );
exception when others then
  -- Dürtme asla çağıranı (özellikle auth.users trigger'ını) bozmamalı.
  raise notice 'poke_notification_dispatcher atlandi: %', sqlerrm;
end;
$$;


--
-- Name: record_cadde_promotion_event_v1(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_cadde_promotion_event_v1(p_campaign_id uuid, p_placement_key text, p_event_type text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_recent int;
begin
  if v_uid is null then
    return false;
  end if;

  if p_event_type not in ('impression', 'click') then
    raise exception 'cadde_invalid_promotion_event';
  end if;

  if not exists (
    select 1 from public.cadde_promotion_campaigns
    where id = p_campaign_id and status = 'approved'
  ) then
    return false;
  end if;

  select count(*) into v_recent
  from public.cadde_promotion_events
  where viewer_user_id = v_uid
    and campaign_id = p_campaign_id
    and occurred_at > now() - interval '1 hour';

  if v_recent >= 30 then
    return false;
  end if;

  insert into public.cadde_promotion_events (campaign_id, placement_key, event_type, viewer_user_id)
  values (p_campaign_id, p_placement_key, p_event_type, v_uid);

  return true;
end;
$$;


--
-- Name: record_cadde_share_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_cadde_share_v1(p_post_id uuid, p_channel text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_post public.cadde_posts%rowtype;
  v_recent int;
begin
  if v_uid is null then
    raise exception 'cadde_auth_required';
  end if;

  if public.is_cadde_banned(v_uid) then
    raise exception 'cadde_banned';
  end if;

  if p_channel not in ('web_share', 'copy_link') then
    raise exception 'cadde_invalid_share_channel';
  end if;

  select * into v_post
  from public.cadde_posts
  where id = p_post_id;

  if v_post.id is null or v_post.status <> 'published' then
    raise exception 'cadde_share_post_not_found';
  end if;

  if not (public.is_admin(v_uid) or public.is_moderator(v_uid)) then
    select count(*) into v_recent
    from public.cadde_post_shares
    where user_id = v_uid and created_at > now() - interval '1 minute';

    if v_recent >= public.cadde_setting_int('cadde.share.minute_limit', 20) then
      raise exception 'cadde_share_rate_limited';
    end if;
  end if;

  insert into public.cadde_post_shares (post_id, user_id, channel)
  values (p_post_id, v_uid, p_channel);

  update public.cadde_posts
  set share_count = share_count + 1
  where id = p_post_id;
end;
$$;


--
-- Name: record_carsi_contact_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_carsi_contact_v1(p_item_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_item public.carsi_items%rowtype;
begin
  if v_uid is null then
    return false;
  end if;

  select * into v_item from public.carsi_items where id = p_item_id and deleted_at is null;
  if v_item.id is null or v_item.owner_user_id = v_uid then
    return false;
  end if;

  -- Görüntüleyen + ilan başına 24 saatte en fazla 1 bildirim.
  if exists (
    select 1 from public.notifications
    where user_id = v_item.owner_user_id
      and actor_user_id = v_uid
      and type = 'cadde.carsi.item_contacted'
      and related_id = p_item_id
      and created_at > now() - interval '24 hours'
  ) then
    return false;
  end if;

  perform public.cadde_notify(
    v_item.owner_user_id, v_uid, 'cadde.carsi.item_contacted',
    'İlanınla ilgilenen var',
    v_item.title,
    'carsi_item', p_item_id,
    '{}'::jsonb
  );

  return true;
end;
$$;


--
-- Name: record_tool_run(text, text, integer, text, jsonb, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_tool_run(p_tool_key text, p_status text, p_http_status integer DEFAULT NULL::integer, p_idempotency_key text DEFAULT NULL::text, p_payload_redacted jsonb DEFAULT '{}'::jsonb, p_latency_ms integer DEFAULT NULL::integer, p_actor_type text DEFAULT 'agent'::text, p_actor_pseudo_id text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public'
    AS $$
declare
  new_id uuid;
begin
  -- Girdi doğrulama (boundary): status ve tool_key zorunlu.
  if p_tool_key is null or length(p_tool_key) = 0 then
    raise exception 'tool_key zorunlu';
  end if;
  if p_status not in ('ok', 'retry', 'failed', 'blocked') then
    raise exception 'geçersiz status: %', p_status;
  end if;

  insert into ops.tool_runs (
    tool_key, actor_type, actor_pseudo_id, idempotency_key,
    finished_at, status, http_status, latency_ms,
    privacy_level, payload_redacted
  )
  values (
    p_tool_key, p_actor_type, p_actor_pseudo_id, p_idempotency_key,
    now(), p_status, p_http_status, p_latency_ms,
    'anon', coalesce(p_payload_redacted, '{}'::jsonb)
  )
  -- idempotency çakışmasında sessizce mevcut kaydı bırak (çift yazma koruması).
  on conflict (tool_key, idempotency_key) where idempotency_key is not null
  do nothing
  returning run_id into new_id;

  return new_id;
end;
$$;


--
-- Name: FUNCTION record_tool_run(p_tool_key text, p_status text, p_http_status integer, p_idempotency_key text, p_payload_redacted jsonb, p_latency_ms integer, p_actor_type text, p_actor_pseudo_id text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.record_tool_run(p_tool_key text, p_status text, p_http_status integer, p_idempotency_key text, p_payload_redacted jsonb, p_latency_ms integer, p_actor_type text, p_actor_pseudo_id text) IS 'Agent telemetri yazımı (ops.tool_runs). Redacted payload bekler — ham PII gönderilmemeli.';


