--
-- Name: relocation_save_wizard(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.relocation_save_wizard(p_move_id uuid, p_payload jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_move public.relocation_moves%rowtype := public.relocation_owned_move(p_move_id);
  v_step text := p_payload ->> 'step';
begin
  if v_step is null or v_step = '' then
    raise exception 'rl_wizard_step_required';
  end if;
  update public.relocation_moves set
    wizard_answers = wizard_answers || jsonb_build_object(v_step, p_payload -> 'answers'),
    updated_at = now()
  where id = p_move_id;
end;
$$;


--
-- Name: relocation_score_banka_secim_almanya_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.relocation_score_banka_secim_almanya_v1(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session public.relocation_tool_sessions%rowtype := public.rl_tool_owned_session(p_session_id);
  v_ans jsonb := public.rl_tool_answers_json(p_session_id);
  -- Banka kataloğu (id, name, type, weights) — ref101 data.ts BANKS aynası.
  v_banks jsonb := jsonb_build_array(
    jsonb_build_object('id','n26','name','N26','type','Mobil banka','w', jsonb_build_object('DIGITAL',5,'DIRECT',2,'EXPAT',4,'INVEST',5,'CRYPTO',4,'LOW_COST',3,'BRANCH',-4,'LOCAL',-3)),
    jsonb_build_object('id','revolut','name','Revolut','type','Fintech (banka)','w', jsonb_build_object('DIGITAL',5,'EXPAT',4,'CRYPTO',4,'INVEST',2,'LOW_COST',2,'DIRECT',3,'BRANCH',-5,'LOCAL',-4)),
    jsonb_build_object('id','ing','name','ING','type','Direkt banka','w', jsonb_build_object('DIRECT',5,'INVEST',4,'LOW_COST',2,'DIGITAL',2,'EXPAT',1,'BRANCH',-3,'LOCAL',-2,'CRYPTO',0)),
    jsonb_build_object('id','dkb','name','DKB','type','Direkt banka','w', jsonb_build_object('DIRECT',4,'INVEST',4,'LOW_COST',3,'DIGITAL',2,'EXPAT',0,'BRANCH',-3,'LOCAL',-2,'CRYPTO',0)),
    jsonb_build_object('id','sparkasse','name','Sparkasse','type','Yerel banka (şubeli)','w', jsonb_build_object('LOCAL',5,'BRANCH',5,'INVEST',2,'DIGITAL',1,'DIRECT',1,'LOW_COST',-2,'EXPAT',0,'CRYPTO',1)),
    jsonb_build_object('id','volksbank','name','Volksbank / Raiffeisenbank','type','Yerel banka (şubeli)','w', jsonb_build_object('LOCAL',5,'BRANCH',5,'INVEST',2,'DIGITAL',1,'DIRECT',1,'LOW_COST',-2,'EXPAT',0,'CRYPTO',0)),
    jsonb_build_object('id','commerzbank','name','Commerzbank','type','Geleneksel banka','w', jsonb_build_object('LOCAL',3,'BRANCH',3,'DIRECT',2,'INVEST',3,'DIGITAL',1,'LOW_COST',-2,'EXPAT',1,'CRYPTO',0)),
    jsonb_build_object('id','deutschebank','name','Deutsche Bank','type','Geleneksel banka','w', jsonb_build_object('LOCAL',3,'BRANCH',2,'DIRECT',1,'INVEST',3,'DIGITAL',1,'LOW_COST',-2,'EXPAT',0,'CRYPTO',0)),
    jsonb_build_object('id','traderepublic','name','Trade Republic','type','Yatırım + banka (ECB lisanslı)','w', jsonb_build_object('INVEST',6,'LOW_COST',3,'DIGITAL',3,'CRYPTO',3,'DIRECT',3,'EXPAT',1,'BRANCH',-6,'LOCAL',-4)),
    jsonb_build_object('id','c24','name','C24 Bank','type','Direkt banka (app ağırlıklı)','w', jsonb_build_object('DIGITAL',4,'DIRECT',4,'LOW_COST',4,'EXPAT',0,'INVEST',0,'CRYPTO',0,'BRANCH',-4,'LOCAL',-3)),
    jsonb_build_object('id','comdirect','name','comdirect','type','Direkt banka (Commerzbank grubu)','w', jsonb_build_object('DIRECT',4,'INVEST',5,'LOW_COST',2,'DIGITAL',2,'EXPAT',0,'CRYPTO',0,'BRANCH',-2,'LOCAL',-1)),
    jsonb_build_object('id','consorsbank','name','Consorsbank','type','Direkt banka / broker (BNP Paribas)','w', jsonb_build_object('DIRECT',3,'INVEST',6,'LOW_COST',3,'DIGITAL',2,'EXPAT',0,'CRYPTO',0,'BRANCH',-3,'LOCAL',-2)),
    jsonb_build_object('id','targobank','name','Targobank','type','Geleneksel banka (şubeli)','w', jsonb_build_object('LOCAL',3,'BRANCH',4,'DIRECT',1,'INVEST',1,'DIGITAL',1,'LOW_COST',-1,'EXPAT',0,'CRYPTO',0)),
    jsonb_build_object('id','postbank','name','Postbank','type','Geleneksel banka (şubeli)','w', jsonb_build_object('LOCAL',3,'BRANCH',4,'DIRECT',1,'INVEST',2,'DIGITAL',1,'LOW_COST',-2,'EXPAT',0,'CRYPTO',0)),
    jsonb_build_object('id','hvb','name','HypoVereinsbank (UniCredit)','type','Geleneksel banka','w', jsonb_build_object('LOCAL',3,'BRANCH',3,'DIRECT',1,'INVEST',3,'DIGITAL',1,'LOW_COST',-2,'EXPAT',0,'CRYPTO',0)),
    jsonb_build_object('id','santander','name','Santander','type','Banka (şubeli/karma)','w', jsonb_build_object('LOCAL',2,'BRANCH',2,'DIRECT',2,'INVEST',1,'DIGITAL',1,'LOW_COST',2,'EXPAT',0,'CRYPTO',0)),
    jsonb_build_object('id','bunq','name','bunq','type','Mobil banka (AB fintech)','w', jsonb_build_object('DIGITAL',5,'EXPAT',4,'DIRECT',2,'LOW_COST',-2,'INVEST',0,'CRYPTO',0,'BRANCH',-5,'LOCAL',-4)),
    jsonb_build_object('id','tomorrow','name','Tomorrow','type','Mobil banka (sürdürülebilir odak)','w', jsonb_build_object('DIGITAL',4,'DIRECT',2,'LOW_COST',1,'EXPAT',2,'INVEST',0,'CRYPTO',0,'BRANCH',-5,'LOCAL',-4)),
    jsonb_build_object('id','wise','name','Wise','type','Fintech (çoklu para / transfer)','w', jsonb_build_object('DIGITAL',4,'EXPAT',5,'LOW_COST',4,'DIRECT',1,'INVEST',0,'CRYPTO',0,'BRANCH',-6,'LOCAL',-5))
  );
  v_profile_labels jsonb := jsonb_build_object(
    'DIGITAL','Dijital (app-first)','DIRECT','Direkt/Online','LOCAL','Yerel/Klasik','EXPAT','Expat/Dil-dostu',
    'INVEST','Borsa/ETF odaklı','CRYPTO','Kripto odaklı','LOW_COST','Masraf hassasiyeti','BRANCH','Şube ihtiyacı'
  );
  v_scores jsonb := '{}'::jsonb;
  v_q record;
  v_ranked jsonb;
  v_top jsonb;
  v_top_score numeric;
  v_min numeric;
  v_max numeric;
  v_top_signals jsonb;
  v_bands jsonb := jsonb_build_array(
    jsonb_build_object('key','excellent','min',80),
    jsonb_build_object('key','strong','min',60),
    jsonb_build_object('key','good','min',40),
    jsonb_build_object('key','moderate','min',0)
  );
begin
  -- 1) Cevaplardan profil sinyallerini topla (option-add'leri scoring jsonb'den oku).
  for v_q in
    select q.question_key, (q.scoring -> 'add' -> (v_ans ->> q.question_key)) as add_obj
    from public.relocation_tool_questions q
    where q.tool_key = 'banka_secim_almanya' and q.is_active
      and v_ans ? q.question_key
  loop
    if v_q.add_obj is not null then
      select coalesce(
        v_scores || (
          select jsonb_object_agg(k, coalesce((v_scores ->> k)::numeric, 0) + (val)::numeric)
          from jsonb_each_text(v_q.add_obj) as e(k, val)
        ), v_scores
      ) into v_scores;
    end if;
  end loop;

  -- 2) Her banka için ham skor = Σ(profileScore * bankWeight).
  with bank_scores as (
    select
      b ->> 'id' as id,
      b ->> 'name' as name,
      b ->> 'type' as type,
      (
        select coalesce(sum(coalesce((v_scores ->> wk)::numeric, 0) * (wv)::numeric), 0)
        from jsonb_each_text(b -> 'w') as w(wk, wv)
      ) as raw_score
    from jsonb_array_elements(v_banks) as b
  )
  select
    min(raw_score), max(raw_score)
  into v_min, v_max
  from bank_scores;

  -- 3) Top-3 banka → 0..100 normalize edilmiş skor + tip etiketi.
  with bank_scores as (
    select
      b ->> 'id' as id,
      b ->> 'name' as name,
      b ->> 'type' as type,
      (
        select coalesce(sum(coalesce((v_scores ->> wk)::numeric, 0) * (wv)::numeric), 0)
        from jsonb_each_text(b -> 'w') as w(wk, wv)
      ) as raw_score
    from jsonb_array_elements(v_banks) as b
  ),
  ranked as (
    select id, name, type, raw_score,
      case when v_max = v_min then 100
        else round(((raw_score - v_min) / (v_max - v_min)) * 100, 0) end as score100,
      row_number() over (order by raw_score desc, name) as rn
    from bank_scores
  )
  select
    coalesce(jsonb_agg(
      jsonb_build_object(
        'key', id,
        'title', name,
        'score', score100,
        'detail', type
      ) order by rn
    ) filter (where rn <= 3), '[]'::jsonb),
    (select score100 from ranked where rn = 1)
  into v_ranked, v_top_score
  from ranked;

  v_top := coalesce((v_ranked -> 0), '{}'::jsonb);

  -- 4) En güçlü 3 profil sinyali → açıklayıcı etiketler.
  select coalesce(jsonb_agg(label order by sc desc, k), '[]'::jsonb)
  into v_top_signals
  from (
    select k, sc, v_profile_labels ->> k as label
    from (
      select key as k, value::numeric as sc
      from jsonb_each_text(v_scores)
      where value::numeric > 0
    ) s
    order by sc desc, k
    limit 3
  ) t;

  return public.rl_tool_write_result(
    p_session_id,
    'ranked_list',
    v_top_score,
    public.rl_tool_resolve_bucket(coalesce(v_top_score, 0), v_bands),
    jsonb_build_object('ranked_banks', v_ranked, 'top_signals', v_top_signals),
    '{}'::jsonb,
    v_ranked,
    jsonb_build_array(
      'Cevaplarına göre en uygun 3 banka sıralandı.',
      'Skorlar yönlendirme amaçlıdır; ücretler/koşullar değişebilir — son karardan önce bankanın güncel şartlarını kontrol et.'
    ),
    jsonb_build_array(
      jsonb_build_object('key','start_related_tool','label','Para Transferi Aracına Geç','href','/tools/para-transferi-almanya'),
      jsonb_build_object('key','start_related_tool','label','Sigorta Seçimine Geç','href','/tools/sigorta-secim-almanya')
    ),
    '{}'::jsonb,
    'rule-v1'
  );
end;
$$;


--
-- Name: relocation_score_career_path_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.relocation_score_career_path_v1(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session public.relocation_tool_sessions%rowtype := public.rl_tool_owned_session(p_session_id);
  v_ans jsonb := public.rl_tool_answers_json(p_session_id);
  v_study numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'study_willingness')::numeric, 3) - 1) / 4));
  v_risk numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'risk_appetite')::numeric, 3) - 1) / 4));
  v_salary_pref numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'salary_vs_stability')::numeric, 3) - 1) / 4));
  v_lang numeric := public.rl_tool_clamp_neutral((coalesce((v_ans ->> 'language_level')::numeric, 2.5) / 5));
  v_entre numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'entrepreneurship')::numeric, 3) - 1) / 4));
  v_research numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'research_interest')::numeric, 3) - 1) / 4));
  v_hands numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'hands_on_interest')::numeric, 3) - 1) / 4));
  v_people numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'people_helping')::numeric, 3) - 1) / 4));
  v_skills text[] := coalesce(array(select jsonb_array_elements_text(coalesce(v_ans -> 'core_skills', '[]'::jsonb))), '{}'::text[]);
  v_fav text[] := coalesce(array(select jsonb_array_elements_text(coalesce(v_ans -> 'favorite_work', '[]'::jsonb))), '{}'::text[]);
  v_tech numeric := case when 'technical' = any(v_skills) then 1 else 0 end;
  v_leadership numeric := case when 'leadership' = any(v_skills) then 1 else 0 end;
  v_healthcare numeric := case when 'healthcare' = any(v_skills) then 1 else 0 end;
  v_fav_research numeric := case when 'research' = any(v_fav) then 1 else 0 end;
  v_fav_people numeric := case when 'people' = any(v_fav) then 1 else 0 end;
  v_fav_building numeric := case when 'building' = any(v_fav) then 1 else 0 end;
  v_env text := v_ans ->> 'work_environment';
  v_portfolio text := v_ans ->> 'portfolio_signal';
  v_portfolio_score numeric := case v_portfolio when 'strong' then 1.0 when 'partial' then 0.5 else 0.0 end;
  -- YENİ sinyaller
  v_management numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'management_interest')::numeric, 3) - 1) / 4));
  v_cert_openness numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'hands_on_certification_openness')::numeric, 3) - 1) / 4));
  v_client_facing numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'client_facing_comfort')::numeric, 3) - 1) / 4));
  v_flexible numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'structured_vs_flexible')::numeric, 3) - 1) / 4));
  v_mission numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'mission_driven_motivation')::numeric, 3) - 1) / 4));
  v_intl numeric;
  v_acad numeric;
  v_voc numeric;
  v_startup numeric;
  v_remote numeric;
  v_public numeric;
  v_scores jsonb;
  v_top_key text;
  v_top_val numeric;
  v_second_key text;
  v_second_val numeric;
  v_is_hybrid boolean;
  v_labels jsonb;
  v_roadmaps jsonb;
begin
  v_intl := v_tech * 0.20 + v_lang * 0.20 + v_leadership * 0.15 + v_management * 0.10
            + (case when v_env = 'corporate' then 0.2 else 0 end) + (1 - v_risk) * 0.10 + v_client_facing * 0.05;
  v_acad := v_research * 0.35 + v_study * 0.25 + v_fav_research * 0.15
            + (case when v_env = 'academic' then 0.15 else 0 end) + v_cert_openness * 0.10;
  v_voc := v_hands * 0.35 + v_fav_building * 0.15 + v_study * 0.15
           + (case when v_env = 'field_work' then 0.15 else 0 end) + v_cert_openness * 0.20;
  v_startup := v_risk * 0.25 + v_entre * 0.30 + v_salary_pref * 0.10 + v_client_facing * 0.10
               + (case when v_env = 'startup' then 0.15 else 0 end) + v_flexible * 0.10;
  v_remote := v_tech * 0.25 + v_portfolio_score * 0.25 + v_entre * 0.15 + v_flexible * 0.20
              + (case when v_env = 'freelance' then 0.15 else 0 end);
  v_public := v_people * 0.25 + v_fav_people * 0.15 + v_healthcare * 0.10 + v_lang * 0.10 + v_mission * 0.25
              + (case when v_env = 'public' then 0.10 else 0 end) + v_client_facing * 0.05;

  v_scores := jsonb_build_object(
    'international_professional', round(v_intl, 4),
    'academic_research', round(v_acad, 4),
    'vocational_practical', round(v_voc, 4),
    'startup_entrepreneur', round(v_startup, 4),
    'remote_global', round(v_remote, 4),
    'public_ngo_community', round(v_public, 4)
  );

  select key, value::numeric into v_top_key, v_top_val
  from jsonb_each_text(v_scores) order by value::numeric desc, key limit 1;
  select key, value::numeric into v_second_key, v_second_val
  from jsonb_each_text(v_scores) order by value::numeric desc, key offset 1 limit 1;

  v_is_hybrid := (v_top_val - v_second_val) < 0.08;

  v_labels := jsonb_build_object(
    'international_professional', 'Uluslararası Profesyonel',
    'academic_research', 'Akademi & Araştırma',
    'vocational_practical', 'Mesleki & Pratik',
    'startup_entrepreneur', 'Girişimci',
    'remote_global', 'Uzaktan Global',
    'public_ngo_community', 'Kamu & STK & Topluluk'
  );

  v_roadmaps := jsonb_build_object(
    'international_professional', 'Dil seviyeni B2+''ya taşı, CV/portföyünü hedef ülke formatına çevir, maaş ve iş bulma araçlarını çalıştır.',
    'academic_research', 'Hedef program/danışman araştır, yayın/proje portföyünü düzenle, başvuru ve burs takvimini çıkar.',
    'vocational_practical', 'Mesleki denklik/sertifika adımlarını öğren, pratik portföyünü belgeleyin, atölye/staj fırsatlarına bak.',
    'startup_entrepreneur', 'Fikir/ürün doğrulaması yap, hedef ülke girişim vizesi ve ekosistemini araştır, network kur.',
    'remote_global', 'Portföyünü İngilizceye çevir, uzaktan iş platformlarında profil aç, zaman dilimi ve sözleşme modelini netleştir.',
    'public_ngo_community', 'İlgili kurum/STK''ları listele, dil ve saha deneyimini öne çıkar, gönüllülük/staj ile başla.'
  );

  return public.rl_tool_write_result(
    p_session_id,
    'persona',
    null,
    v_top_key,
    jsonb_build_object(
      'persona_key', v_top_key,
      'persona_label', v_labels ->> v_top_key,
      'is_hybrid', v_is_hybrid,
      'secondary_key', case when v_is_hybrid then v_second_key else null end,
      'secondary_label', case when v_is_hybrid then v_labels ->> v_second_key else null end,
      'roadmap', v_roadmaps ->> v_top_key
    ),
    v_scores,
    '[]'::jsonb,
    jsonb_build_array(
      'Birincil kariyer yolun: ' || (v_labels ->> v_top_key) ||
        case when v_is_hybrid then ' (hibrit — ' || (v_labels ->> v_second_key) || ' ile yakın)' else '' end || '.',
      '6 aylık odak: ' || (v_roadmaps ->> v_top_key)
    ),
    jsonb_build_array(
      jsonb_build_object('key','start_related_tool','label','Maaş Karşılaştırma','href','/tools/meslek-maas-karsilastirma'),
      jsonb_build_object('key','start_related_tool','label','İş Bulma Olasılığı','href','/tools/is-bulma-olasiligi'),
      jsonb_build_object('key','find_mentor','label','Bu Patikada Mentor Bul')
    ),
    '{}'::jsonb,
    'rule-v1'
  );
end;
$$;


--
-- Name: relocation_score_city_match_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.relocation_score_city_match_v1(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session public.relocation_tool_sessions%rowtype := public.rl_tool_owned_session(p_session_id);
  v_ans jsonb := public.rl_tool_answers_json(p_session_id);
  v_weights jsonb;
  -- Ülke girişi serbest metin (MVP): yaygın yazımlar ISO alpha-2'ye çevrilir.
  -- upper() Türkçe 'i'yi 'I' yapar (İ değil) — bu yüzden aksansız yazımlar da listede.
  v_targets text[] := coalesce(
    (select array_agg(distinct
       case upper(trim(t))
         when 'UK' then 'GB' when 'ENGLAND' then 'GB' when 'BİRLEŞİK KRALLIK' then 'GB'
         when 'İNGİLTERE' then 'GB' when 'INGILTERE' then 'GB'
         when 'USA' then 'US' when 'ABD' then 'US' when 'AMERİKA' then 'US' when 'AMERIKA' then 'US'
         when 'UAE' then 'AE' when 'BAE' then 'AE' when 'DUBAI' then 'AE' when 'DUBAİ' then 'AE'
         when 'ALMANYA' then 'DE' when 'GERMANY' then 'DE' when 'DEUTSCHLAND' then 'DE'
         when 'HOLLANDA' then 'NL' when 'NETHERLANDS' then 'NL'
         when 'FRANSA' then 'FR' when 'FRANCE' then 'FR'
         when 'İSVİÇRE' then 'CH' when 'ISVICRE' then 'CH' when 'SWITZERLAND' then 'CH'
         when 'AVUSTURYA' then 'AT' when 'AUSTRIA' then 'AT'
         when 'BELÇİKA' then 'BE' when 'BELCIKA' then 'BE' when 'BELGIUM' then 'BE'
         when 'KANADA' then 'CA' when 'CANADA' then 'CA'
         when 'KATAR' then 'QA' when 'QATAR' then 'QA'
         when 'İSVEÇ' then 'SE' when 'ISVEC' then 'SE' when 'SWEDEN' then 'SE'
         when 'DANİMARKA' then 'DK' when 'DANIMARKA' then 'DK' when 'DENMARK' then 'DK'
         when 'NORVEÇ' then 'NO' when 'NORVEC' then 'NO' when 'NORWAY' then 'NO'
         when 'İSPANYA' then 'ES' when 'ISPANYA' then 'ES' when 'SPAIN' then 'ES'
         when 'İTALYA' then 'IT' when 'ITALYA' then 'IT' when 'ITALY' then 'IT'
         when 'POLONYA' then 'PL' when 'POLAND' then 'PL'
         when 'AVUSTRALYA' then 'AU' when 'AUSTRALIA' then 'AU'
         else upper(trim(t))
       end)
     from regexp_split_to_table(coalesce(v_ans ->> 'target_countries', ''), ',') t
     where trim(t) <> ''),
    '{}'::text[]
  );
  v_community_pref numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'community_need')::numeric, 3) - 1) / 4));
  v_safety_pref numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'safety_family')::numeric, 3) - 1) / 4));
  v_airport_pref numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'airport_access')::numeric, 3) - 1) / 4));
  v_industry_pref numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'industry_hub')::numeric, 3) - 1) / 4));
  v_health_pref numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'healthcare_priority')::numeric, 3) - 1) / 4));
  v_transport_pref numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'public_transport_importance')::numeric, 3) - 1) / 4));
  v_green_pref numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'green_space_preference')::numeric, 3) - 1) / 4));
  v_expat_pref text := v_ans ->> 'expat_community_size';
  v_health_urgency numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'healthcare_access_urgency')::numeric, 3) - 1) / 4));
  v_ranked jsonb;
  v_top jsonb;
  v_top_score numeric;
  -- B23/SQL: hedef ülkede hiç aktif şehir yoksa tüm şehirlere düş, durumu işaretle.
  v_fallback boolean := false;
begin
  select weights into v_weights from public.relocation_tools where key = 'city_match';

  if array_length(v_targets, 1) is not null and not exists (
    select 1 from public.relocation_locations l
    where l.is_active and l.country_code = any (v_targets)
  ) then
    v_fallback := true;
    v_targets := '{}'::text[];
  end if;

  with scored as (
    select
      l.id, l.country_code, l.city_code, l.city_name, l.freshness_at,
      jsonb_build_object(
        'budget_housing_fit', round(
          (public.rl_tool_clamp_neutral(1 - coalesce(l.cost_index, 0.5)) * 0.6
           + public.rl_tool_clamp_neutral(l.housing_availability) * 0.4), 4),
        'job_hub_fit', round(
          (public.rl_tool_clamp_neutral(1 - coalesce(l.bureaucracy_complexity, 0.5)) * (0.5 + 0.5 * v_industry_pref)), 4),
        'lifestyle_fit', round(
          public.rl_tool_clamp_neutral(l.gsm_coverage) * (1 - 0.2 * v_green_pref) + 0.2 * v_green_pref, 4),
        'community_fit', round(
          (public.rl_tool_clamp_neutral(l.community_density) * (0.4 + 0.6 * v_community_pref))
          * (case when v_expat_pref = 'large' then 1.05 when v_expat_pref = 'no_preference' then 0.95 else 1.0 end), 4),
        'safety_healthcare_fit', round(
          (public.rl_tool_clamp_neutral(l.safety_index) * (0.4 + 0.6 * v_safety_pref) * 0.5
           + public.rl_tool_clamp_neutral(l.healthcare_access) * (0.4 + 0.6 * greatest(v_health_pref, v_health_urgency)) * 0.5), 4),
        'mobility_flight_fit', round(
          (public.rl_tool_clamp_neutral(l.flight_access) * (0.4 + 0.6 * v_airport_pref)) * 0.8
          + public.rl_tool_clamp_neutral(l.gsm_coverage) * v_transport_pref * 0.2, 4)
      ) as breakdown,
      (select count(*) filter (where r.authority_level in ('official','official_city','regulator'))::numeric
              / nullif(count(*), 0)
       from public.relocation_source_registry r where r.id = l.source_id) as official_ratio,
      case when l.freshness_at is null then null
           else extract(epoch from (now() - l.freshness_at)) / 3600.0 end as freshness_hours
    from public.relocation_locations l
    where l.is_active
      and (array_length(v_targets, 1) is null or l.country_code = any (v_targets))
  ),
  ranked as (
    select
      id, country_code, city_code, city_name, breakdown, official_ratio, freshness_hours,
      round(public.rl_tool_weighted_score(breakdown, v_weights) * 100, 2) as score
    from scored
  ),
  numbered as (
    select *, row_number() over (order by score desc, city_name) as rn from ranked
  )
  select
    coalesce(jsonb_agg(
      jsonb_build_object(
        'key', city_code,
        'country_code', country_code,
        'title', city_name,
        'score', score,
        'sub_scores', breakdown,
        'detail', city_name || ' · ' || country_code || ' — ' || score::text || '/100',
        'source_quality', jsonb_build_object(
          'official_sources_ratio', coalesce(official_ratio, 0),
          'freshness_hours', freshness_hours
        )
      ) order by score desc, city_name
    ) filter (where rn <= 5), '[]'::jsonb),
    (jsonb_agg(breakdown order by score desc, city_name) filter (where rn = 1)) -> 0,
    max(score) filter (where rn = 1)
  into v_ranked, v_top, v_top_score
  from numbered;

  return public.rl_tool_write_result(
    p_session_id,
    'ranked_list',
    v_top_score,
    null,
    jsonb_build_object('ranked_cities', v_ranked, 'fallback_no_target_match', v_fallback),
    coalesce(v_top, '{}'::jsonb),
    v_ranked,
    case
      when v_ranked = '[]'::jsonb
        then jsonb_build_array('Seçtiğin ülkelerde aktif şehir verisi bulunamadı. Hedef ülkeyi genişletmeyi dene.')
      when v_fallback
        then jsonb_build_array(
          'Hedef ülkende henüz aktif şehir verimiz yok — tercihlerin diğer ülkelerdeki şehirlerle eşleştirildi.',
          'Skorlar mevcut şehir verisine dayanır; veri tazeliği sonuçta gösterilir.')
      else jsonb_build_array('Tercihlerine en uygun şehirler sıralandı.', 'Skorlar mevcut şehir verisine dayanır; veri tazeliği sonuçta gösterilir.')
    end,
    jsonb_build_array(
      jsonb_build_object('key','view_directory','label','Bu Şehirdeki Üyeleri Gör'),
      jsonb_build_object('key','open_cadde','label','Cadde Şehir Akışını Aç'),
      jsonb_build_object('key','start_related_tool','label','İlk 90 Gün Planlayıcı','href','/tools/ilk-90-gun-planlayici')
    ),
    '{}'::jsonb,
    'rule-v1'
  );
end;
$$;


--
-- Name: relocation_score_country_match_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.relocation_score_country_match_v1(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session public.relocation_tool_sessions%rowtype := public.rl_tool_owned_session(p_session_id);
  v_ans jsonb := public.rl_tool_answers_json(p_session_id);
  v_weights jsonb;
  v_bands jsonb := jsonb_build_array(
    jsonb_build_object('key','excellent','min',80),
    jsonb_build_object('key','strong','min',65),
    jsonb_build_object('key','moderate','min',50),
    jsonb_build_object('key','risky','min',0));
  v_community_pref numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'community_importance')::numeric, 3) - 1) / 4));
  v_health_pref numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'healthcare_priority')::numeric, 3) - 1) / 4));
  v_safety_pref numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'safety_priority')::numeric, 3) - 1) / 4));
  v_inclusion_pref numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'inclusion_priority')::numeric, 3) - 1) / 4));
  v_has_budget boolean := (v_ans ->> 'monthly_budget') is not null and (v_ans ->> 'monthly_budget') <> '';
  v_english_only boolean := (v_ans ->> 'language_profile') = 'english_only';
  v_climate text := v_ans ->> 'climate_preference';
  v_visa_assets text[] := coalesce(array(select jsonb_array_elements_text(coalesce(v_ans -> 'visa_assets', '[]'::jsonb))), '{}'::text[]);
  v_has_visa_asset boolean := exists (select 1 from unnest(v_visa_assets) a where a <> 'none');
  v_dealbreakers text[] := coalesce(array(select jsonb_array_elements_text(coalesce(v_ans -> 'deal_breakers', '[]'::jsonb))), '{}'::text[]);
  -- YENİ sinyaller: uzaktan çalışma esnekliği (career_market_fit'i hafifçe güçlendirir) +
  -- vergi yükü toleransı (budget_fit'i hafifçe güçlendirir). Eksik cevap nötr 0.5.
  v_remote_pref numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'remote_work_flexibility')::numeric, 3) - 1) / 4));
  v_tax_tolerance numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'tax_burden_tolerance')::numeric, 3) - 1) / 4));
  v_ranked jsonb;
  v_top jsonb;
  v_top_score numeric;
begin
  select weights into v_weights from public.relocation_tools where key = 'country_match';

  with scored as (
    select
      m.country_code, m.country_name_tr,
      jsonb_build_object(
        'budget_fit', case when not v_has_budget then 0.5
          else public.rl_tool_clamp_neutral(
            (1 - coalesce(m.cost_index, 0.5)) * 0.85 + v_tax_tolerance * 0.15) end,
        'career_market_fit', public.rl_tool_clamp_neutral(
          m.employment_index * 0.9 + v_remote_pref * 0.1),
        'visa_path_fit', public.rl_tool_clamp_neutral(
          (1 - coalesce(m.visa_complexity, 0.5)) * (case when v_has_visa_asset then 1.0 else 0.85 end)),
        'language_fit', case when v_english_only
          then public.rl_tool_clamp_neutral(m.english_workability)
          else public.rl_tool_clamp_neutral(0.5 + 0.5 * coalesce(m.english_workability, 0.5)) end,
        'quality_of_life_fit', public.rl_tool_clamp_neutral(
          coalesce(m.healthcare_index, 0.5) * (0.3 + 0.4 * v_health_pref)
          + coalesce(m.safety_index, 0.5) * (0.3 + 0.4 * v_safety_pref) * 0.5
          + coalesce(m.inclusion_index, 0.5) * (0.2 + 0.4 * v_inclusion_pref) * 0.5),
        'community_fit', public.rl_tool_clamp_neutral(
          coalesce(m.community_density, 0.5) * (0.4 + 0.6 * v_community_pref)),
        'climate_fit', case
          when v_climate is null or v_climate = 'no_preference' then 0.6
          when m.climate_tags @> array[v_climate] then 1.0
          else 0.3 end
      ) as raw_breakdown
    from public.relocation_country_metrics m
    where m.is_active
  ),
  capped as (
    select
      country_code, country_name_tr,
      jsonb_build_object(
        'budget_fit', case when 'high_cost' = any(v_dealbreakers)
          then least((raw_breakdown ->> 'budget_fit')::numeric, 0.40) else (raw_breakdown ->> 'budget_fit')::numeric end,
        'career_market_fit', (raw_breakdown ->> 'career_market_fit')::numeric,
        'visa_path_fit', case when 'hard_visa' = any(v_dealbreakers)
          then least((raw_breakdown ->> 'visa_path_fit')::numeric, 0.40) else (raw_breakdown ->> 'visa_path_fit')::numeric end,
        'language_fit', case when 'no_english' = any(v_dealbreakers)
          then least((raw_breakdown ->> 'language_fit')::numeric, 0.40) else (raw_breakdown ->> 'language_fit')::numeric end,
        'quality_of_life_fit', case when ('weak_healthcare' = any(v_dealbreakers) or 'low_safety' = any(v_dealbreakers))
          then least((raw_breakdown ->> 'quality_of_life_fit')::numeric, 0.40) else (raw_breakdown ->> 'quality_of_life_fit')::numeric end,
        'community_fit', case when 'no_community' = any(v_dealbreakers)
          then least((raw_breakdown ->> 'community_fit')::numeric, 0.40) else (raw_breakdown ->> 'community_fit')::numeric end,
        'climate_fit', (raw_breakdown ->> 'climate_fit')::numeric
      ) as breakdown
    from scored
  ),
  ranked as (
    select country_code, country_name_tr, breakdown,
      round(public.rl_tool_weighted_score(breakdown, v_weights) * 100, 2) as score
    from capped
  ),
  numbered as (
    select *, row_number() over (order by score desc, country_name_tr) as rn from ranked
  )
  select
    coalesce(jsonb_agg(
      jsonb_build_object(
        'key', country_code, 'title', country_name_tr, 'score', score,
        'bucket', public.rl_tool_resolve_bucket(score, v_bands),
        'sub_scores', breakdown,
        'detail', country_name_tr || ' — ' || score::text || '/100'
      ) order by score desc, country_name_tr
    ) filter (where rn <= 5), '[]'::jsonb),
    (jsonb_agg(breakdown order by score desc, country_name_tr) filter (where rn = 1)) -> 0,
    max(score) filter (where rn = 1)
  into v_ranked, v_top, v_top_score
  from numbered;

  return public.rl_tool_write_result(
    p_session_id,
    'ranked_list',
    v_top_score,
    public.rl_tool_resolve_bucket(coalesce(v_top_score, 0), v_bands),
    jsonb_build_object('ranked_countries', v_ranked),
    coalesce(v_top, '{}'::jsonb),
    v_ranked,
    jsonb_build_array(
      'Tercihlerine en uygun ülkeler sıralandı.',
      case when array_length(v_dealbreakers, 1) is not null
        then 'Kırmızı çizgi seçtiğin alanlar ilgili ülkelerde puanı sınırladı.'
        else 'Skorlar mevcut ülke verisine dayanır; garanti içermez.' end
    ),
    jsonb_build_array(
      jsonb_build_object('key','start_related_tool','label','Şehir Eşleştirmeyi Başlat','href','/tools/sehir-eslestirme'),
      jsonb_build_object('key','view_directory','label','Bu Ülkedeki Üyeleri Gör'),
      jsonb_build_object('key','start_related_tool','label','İlk 90 Gün Planlayıcı','href','/tools/ilk-90-gun-planlayici')
    ),
    '{}'::jsonb,
    'rule-v1'
  );
end;
$$;


--
-- Name: relocation_score_diaspora_matchmaker_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.relocation_score_diaspora_matchmaker_v1(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session public.relocation_tool_sessions%rowtype := public.rl_tool_owned_session(p_session_id);
  v_uid uuid := v_session.user_id;
  v_ans jsonb := public.rl_tool_answers_json(p_session_id);
  v_weights jsonb;
  v_consent boolean := (v_ans ->> 'consent_match_visibility')::boolean is true;
  v_needs text[] := coalesce(array(select jsonb_array_elements_text(coalesce(v_ans -> 'needs','[]'::jsonb))), '{}'::text[]);
  v_offers text[] := coalesce(array(select jsonb_array_elements_text(coalesce(v_ans -> 'offers','[]'::jsonb))), '{}'::text[]);
  v_langs text[] := coalesce(array(select jsonb_array_elements_text(coalesce(v_ans -> 'languages','[]'::jsonb))), '{}'::text[]);
  v_target text := upper(coalesce(v_ans ->> 'target_location',''));
  v_profession text := lower(coalesce(v_ans ->> 'profession_field',''));
  -- YENİ: konu ilgi alanları (field_overlap ek sinyali) + tecrübe yılı (trust proxy) +
  -- tercih edilen görüşme grup boyutu ve yanıt hızı bekletisi (reciprocity ek sinyali).
  v_topics text[] := coalesce(array(select jsonb_array_elements_text(coalesce(v_ans -> 'topic_interests','[]'::jsonb))), '{}'::text[]);
  v_exp_years integer := coalesce((v_ans ->> 'experience_years_in_target')::integer, 0);
  v_group_pref text := v_ans ->> 'preferred_group_size';
  v_response_pref text := v_ans ->> 'response_time_expectation';
  v_matches jsonb;
  v_count integer;
begin
  select weights into v_weights from public.relocation_tools where key = 'diaspora_matchmaker';

  if not v_consent then
    return public.rl_tool_write_result(
      p_session_id, 'match_list', null, null,
      jsonb_build_object('matches', '[]'::jsonb, 'match_count', 0, 'consent', false),
      '{}'::jsonb, '[]'::jsonb,
      jsonb_build_array('Eşleşme üretmek için görünürlük onayı gerekir. Onay vermeden hiçbir veri kaydedilmez.'),
      jsonb_build_array(jsonb_build_object('key','complete_profile','label','Profilini Tamamla')),
      '{}'::jsonb, 'rule-v1');
  end if;

  insert into public.diaspora_match_preferences as p
    (user_id, visibility_status, profile_status, current_country, target_country_codes,
     needs, offers, profession_tags, languages, availability, contact_style,
     hidden_fields, trust_signals, blocking_topics, intro_text, max_monthly_intros,
     experience_years_in_target, preferred_group_size, topic_interests, response_time_expectation)
  values (
    v_uid,
    case when v_ans ->> 'contact_style' = 'anonymous_intro' then 'anonymous' else 'profile_summary' end,
    nullif(v_ans ->> 'profile_status',''),
    nullif(upper(v_ans ->> 'current_location'),''),
    case when v_target <> '' then array[v_target] else '{}'::text[] end,
    v_needs, v_offers,
    case when v_profession <> '' then array[v_profession] else '{}'::text[] end,
    v_langs,
    nullif(v_ans ->> 'availability',''),
    nullif(v_ans ->> 'contact_style',''),
    coalesce(array(select jsonb_array_elements_text(coalesce(v_ans -> 'sensitive_hide','[]'::jsonb))), '{}'::text[]),
    coalesce(array(select jsonb_array_elements_text(coalesce(v_ans -> 'trust_signals','[]'::jsonb))), '{}'::text[]),
    coalesce(array(select jsonb_array_elements_text(coalesce(v_ans -> 'blocking_topics','[]'::jsonb))), '{}'::text[]),
    left(coalesce(v_ans ->> 'intro_text',''), 280),
    coalesce((v_ans ->> 'mentor_capacity')::integer, 3),
    v_exp_years, nullif(v_group_pref,''), v_topics, nullif(v_response_pref,'')
  )
  on conflict (user_id) do update set
    visibility_status = excluded.visibility_status, profile_status = excluded.profile_status,
    current_country = excluded.current_country, target_country_codes = excluded.target_country_codes,
    needs = excluded.needs, offers = excluded.offers, profession_tags = excluded.profession_tags,
    languages = excluded.languages, availability = excluded.availability,
    contact_style = excluded.contact_style, hidden_fields = excluded.hidden_fields,
    trust_signals = excluded.trust_signals, blocking_topics = excluded.blocking_topics,
    intro_text = excluded.intro_text, max_monthly_intros = excluded.max_monthly_intros,
    experience_years_in_target = excluded.experience_years_in_target,
    preferred_group_size = excluded.preferred_group_size,
    topic_interests = excluded.topic_interests,
    response_time_expectation = excluded.response_time_expectation,
    updated_at = now();

  with cand as (
    select c.*,
      jsonb_build_object(
        'need_offer_complementarity', public.rl_tool_clamp_neutral(
          (cardinality(array(select unnest(v_needs) intersect select unnest(c.offers)))::numeric
           / nullif(greatest(cardinality(v_needs), 1), 0)) * 0.6
          + (cardinality(array(select unnest(v_offers) intersect select unnest(c.needs)))::numeric
             / nullif(greatest(cardinality(v_offers), 1), 0)) * 0.4),
        'geo_proximity', case
          when v_target <> '' and (v_target = any(c.target_country_codes) or v_target = c.current_country) then 1.0
          when array_length(c.target_country_codes,1) is null then 0.5 else 0.3 end,
        -- field_overlap: meslek etiketi + konu ilgi alanları kesişimi.
        'field_overlap', public.rl_tool_clamp_neutral(
          (case
            when v_profession <> '' and v_profession = any(c.profession_tags) then 1.0
            when array_length(c.profession_tags,1) is null then 0.5 else 0.4 end) * 0.7
          + (case when cardinality(v_topics) = 0 or cardinality(c.topic_interests) = 0 then 0.5
             else least(cardinality(array(select unnest(v_topics) intersect select unnest(c.topic_interests)))::numeric
                        / greatest(least(cardinality(v_topics), cardinality(c.topic_interests)), 1), 1.0) end) * 0.3),
        'language_timezone_fit', case
          when cardinality(array(select unnest(v_langs) intersect select unnest(c.languages))) > 0 then 1.0
          else 0.3 end
          * (case when v_response_pref is not null and c.response_time_expectation = v_response_pref then 1.0 else 0.9 end),
        'trust_profile_completeness', public.rl_tool_clamp_neutral(
          least(cardinality(c.trust_signals)::numeric / 3.0, 1.0) * 0.7
          + least(coalesce(c.experience_years_in_target, 0)::numeric / 5.0, 1.0) * 0.3),
        'reciprocity_recent_activity', public.rl_tool_clamp_neutral(
          0.4 + least(c.max_monthly_intros::numeric / 5.0, 0.6))
          * (case when v_group_pref is not null and v_group_pref <> 'either'
                       and c.preferred_group_size is not null and c.preferred_group_size <> 'either'
                       and c.preferred_group_size <> v_group_pref then 0.85 else 1.0 end)
      ) as breakdown
    from public.diaspora_match_preferences c
    where c.visibility_status <> 'off' and c.user_id <> v_uid
  ),
  scored as (
    select user_id, visibility_status, profile_status, current_country, profession_tags,
           languages, intro_text, hidden_fields, breakdown,
           round(public.rl_tool_weighted_score(breakdown, v_weights) * 100, 2) as score
    from cand
  )
  select
    coalesce(jsonb_agg(
      jsonb_build_object(
        'key', user_id,
        'title', 'Diaspora üyesi · ' || coalesce(profile_status, 'üye'),
        'score', score,
        'role', profile_status,
        'location', case when 'city' = any(hidden_fields) then null else current_country end,
        'profession', case when 'profession' = any(hidden_fields) then null
                           else (profession_tags)[1] end,
        'languages', languages,
        'intro', intro_text,
        'sub_scores', breakdown,
        'detail', 'Uyum: ' || score::text || '/100 — iletişim için karşılıklı onay gerekir.'
      ) order by score desc
    ) filter (where rn <= 8), '[]'::jsonb),
    count(*)
  into v_matches, v_count
  from (select *, row_number() over (order by score desc) as rn from scored) s;

  return public.rl_tool_write_result(
    p_session_id,
    'match_list',
    (v_matches -> 0 ->> 'score')::numeric,
    null,
    jsonb_build_object('matches', v_matches, 'match_count', coalesce(v_count, 0), 'consent', true),
    coalesce(v_matches -> 0 -> 'sub_scores', '{}'::jsonb),
    v_matches,
    case when coalesce(v_count, 0) = 0
      then jsonb_build_array(
        'Şu an opt-in havuzunda uygun aday bulunamadı. Havuza katıldın; yeni üyeler geldikçe eşleşmeler oluşacak.',
        'İsim ve iletişim asla otomatik paylaşılmaz; yalnızca karşılıklı onayla açılır.')
      else jsonb_build_array(
        coalesce(v_count, 0)::text || ' güvenli eşleşme bulundu. Kartlarda isim/iletişim gizli; tanışma isteği gönderip karşı taraf kabul edince açılır.') end,
    jsonb_build_array(
      jsonb_build_object('key','open_cadde','label','Cadde Cafe''de Grup Buluşması'),
      jsonb_build_object('key','complete_profile','label','Profilini Tamamla'),
      jsonb_build_object('key','view_directory','label','Directory''de Mentorları Filtrele')),
    '{}'::jsonb,
    'rule-v1'
  );
end;
$$;


--
-- Name: relocation_score_expat_lifestyle_persona_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.relocation_score_expat_lifestyle_persona_v1(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session public.relocation_tool_sessions%rowtype := public.rl_tool_owned_session(p_session_id);
  v_ans jsonb := public.rl_tool_answers_json(p_session_id);
  v_social numeric   := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'social_energy')::numeric, 3) - 1) / 4));
  v_plan numeric     := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'planning_style')::numeric, 3) - 1) / 4));
  v_lang numeric     := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'local_language')::numeric, 3) - 1) / 4));
  v_comm numeric     := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'community_need')::numeric, 3) - 1) / 4));
  v_comfort numeric  := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'comfort_zone')::numeric, 3) - 1) / 4));
  v_career numeric   := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'career_focus')::numeric, 3) - 1) / 4));
  v_family numeric   := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'family_rhythm')::numeric, 3) - 1) / 4));
  v_city numeric     := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'city_vs_nature')::numeric, 3) - 1) / 4));
  v_weekend text := v_ans ->> 'weekend_style';
  -- YENİ sinyaller
  v_travel numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'travel_frequency')::numeric, 3) - 1) / 4));
  v_remote_pref numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'remote_vs_office_pref')::numeric, 3) - 1) / 4));
  v_cuisine numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'cuisine_openness')::numeric, 3) - 1) / 4));
  v_outdoor numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'outdoor_activity_level')::numeric, 3) - 1) / 4));
  v_fin_risk numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'financial_risk_comfort')::numeric, 3) - 1) / 4));
  v_settle numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'long_term_settle_intent')::numeric, 3) - 1) / 4));
  v_hobby_social numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'hobby_social_mix')::numeric, 3) - 1) / 4));
  v_pace numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'pace_of_life_pref')::numeric, 3) - 1) / 4));
  v_culture_curiosity numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'cultural_curiosity')::numeric, 3) - 1) / 4));
  v_global numeric;
  v_quiet numeric;
  v_adventure numeric;
  v_family_p numeric;
  v_career_p numeric;
  v_community numeric;
  v_scores jsonb;
  v_top_key text;
  v_top_val numeric;
  v_second_key text;
  v_second_val numeric;
  v_is_hybrid boolean;
  v_persona_label text;
  v_explanation text;
begin
  -- Persona = Σ coef * normalize (coef'ler relocation-tools-ranking.ts PERSONA_SIGNALS aynası).
  v_global := v_social * 0.30 + v_career * 0.20 + v_city * 0.20 + v_pace * 0.15 + v_hobby_social * 0.10
              + case when v_weekend = 'network_event' then 0.10 else 0 end;
  v_quiet := (1 - v_social) * 0.25 + (1 - v_city) * 0.20 + (1 - v_plan) * 0.15 + (1 - v_comfort) * 0.10
              + (1 - v_pace) * 0.15 + (1 - v_hobby_social) * 0.10
              + case when v_weekend = 'quiet_cafe' then 0.10 else 0 end;
  v_adventure := v_plan * 0.25 + v_comfort * 0.25 + (1 - v_city) * 0.10 + v_lang * 0.10
              + v_travel * 0.10 + v_outdoor * 0.10 + v_cuisine * 0.05 + v_culture_curiosity * 0.05
              + case when v_weekend = 'hiking' then 0.10 else 0 end;
  v_family_p := v_family * 0.35 + (1 - v_comfort) * 0.15 + (1 - v_plan) * 0.15 + (1 - v_social) * 0.10
              + v_settle * 0.15 + (1 - v_fin_risk) * 0.10
              + case when v_weekend = 'family_market' then 0.10 else 0 end;
  v_career_p := v_career * 0.30 + v_city * 0.20 + v_social * 0.15 + v_fin_risk * 0.10 + v_remote_pref * 0.10
              + v_pace * 0.05
              + case when v_weekend = 'network_event' then 0.10 else 0 end;
  v_community := v_comm * 0.35 + v_lang * 0.20 + v_social * 0.15 + v_culture_curiosity * 0.15 + v_settle * 0.05
              + case when v_weekend = 'family_market' then 0.10 else 0 end;

  v_scores := jsonb_build_object(
    'global_networker', round(v_global, 4),
    'quiet_local', round(v_quiet, 4),
    'adventure_seeker', round(v_adventure, 4),
    'family_planner', round(v_family_p, 4),
    'career_builder', round(v_career_p, 4),
    'community_anchor', round(v_community, 4)
  );

  select key, value::numeric into v_top_key, v_top_val
  from jsonb_each_text(v_scores) order by value::numeric desc limit 1;
  select key, value::numeric into v_second_key, v_second_val
  from jsonb_each_text(v_scores) order by value::numeric desc offset 1 limit 1;

  v_is_hybrid := (v_top_val - v_second_val) <= 0.001;

  v_persona_label := case v_top_key
    when 'global_networker' then 'Global Networker'
    when 'quiet_local' then 'Sakin Yerleşik'
    when 'adventure_seeker' then 'Maceracı Kaşif'
    when 'family_planner' then 'Aile Planlayıcısı'
    when 'career_builder' then 'Kariyer İnşacısı'
    when 'community_anchor' then 'Topluluk Çapası'
    else v_top_key end;

  v_explanation := case v_top_key
    when 'global_networker' then 'Yeni şehirlerde hızlı bağlantı kurar, etkinlik ve profesyonel ağlardan enerji alırsın.'
    when 'quiet_local' then 'Sakin bir tempoda, yerel hayata yavaş ve derin uyum sağlamayı seversin.'
    when 'adventure_seeker' then 'Spontane, konfor alanı dışına çıkmaya hevesli ve keşfe açıksın.'
    when 'family_planner' then 'Aile, güvenlik ve planlı bir rutin senin için önceliklidir.'
    when 'career_builder' then 'Kariyer ve yoğun şehir hayatı taşınma kararının merkezinde.'
    when 'community_anchor' then 'Kendi kültürünle bağ kurmak ve topluluğa katkı senin için değerli.'
    else 'Yaşam tarzı personan hesaplandı.' end;

  return public.rl_tool_write_result(
    p_session_id,
    'persona',
    null,
    v_top_key,
    jsonb_build_object(
      'persona_key', v_top_key,
      'persona_label', v_persona_label,
      'is_hybrid', v_is_hybrid,
      'secondary_key', case when v_is_hybrid then v_second_key else null end
    ),
    v_scores,
    '[]'::jsonb,
    jsonb_build_array(
      'Persona''n: ' || v_persona_label ||
        case when v_is_hybrid then ' (hibrit)' else '' end || '.',
      v_explanation
    ),
    jsonb_build_array(
      jsonb_build_object('key','open_cadde','label','Cadde''ye Git'),
      jsonb_build_object('key','find_mentor','label','Benzer Personadaki Üyeleri Gör'),
      jsonb_build_object('key','complete_profile','label','Profil Badge''i Olarak Kaydet')
    ),
    '{}'::jsonb,
    'rule-v1'
  );
end;
$$;


--
-- Name: relocation_score_first_90_days_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.relocation_score_first_90_days_v1(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_session public.relocation_tool_sessions%rowtype := public.rl_tool_owned_session(p_session_id);
  v_ans jsonb := public.rl_tool_answers_json(p_session_id);
  -- Varış yakınlığı → deadline aciliyeti çarpanı (tarih yoksa nötr 0.6).
  v_arrival text := v_ans ->> 'arrival_date';
  v_days_to numeric;
  v_proximity numeric;
  v_phase_order jsonb := jsonb_build_object(
    'before_departure', 1, 'day_0_7', 2, 'day_8_30', 3, 'day_31_90', 4, 'ongoing', 5);
  v_tasks jsonb;
  v_top3 jsonb;
  v_task_count integer;
  v_source_link_count integer;
begin
  begin
    v_days_to := case when v_arrival ~ '^\d{4}-\d{2}-\d{2}$'
      then (v_arrival::date - current_date) else null end;
  exception when others then v_days_to := null; end;

  -- Yakınlık 0..1: <=7g → 1.0, >=180g → 0.3, arası lineer; tarih yok → 0.6.
  v_proximity := case
    when v_days_to is null then 0.6
    when v_days_to <= 7 then 1.0
    when v_days_to >= 180 then 0.3
    else round(1.0 - (v_days_to - 7) / 173.0 * 0.7, 3)
  end;

  -- Görev kataloğu: (task_key, phase, legal_dependency, base_urgency, gap_test, title, source_has_link)
  -- gap_test true ise görev üretilir. before_departure görevleri deadline'da +0.15 ek aciliyet alır.
  with catalog as (
    select * from (values
      ('health_insurance_setup', 'before_departure', 0.7, 0.9,
        (v_ans ->> 'health_insurance') in ('will_buy','none') or v_ans ->> 'health_insurance' is null,
        'Sağlık sigortasını netleştir', true),
      ('visa_finalize', 'before_departure', 1.0, 1.0,
        (v_ans ->> 'visa_status') in ('applied','researching','none'),
        'Vize/oturum sürecini tamamla', true),
      ('housing_secure', 'before_departure', 0.4, 0.85,
        (v_ans ->> 'housing_status') in ('searching','none') or v_ans ->> 'housing_status' is null,
        'İlk ay konaklamayı garantiye al', false),
      ('documents_copies', 'before_departure', 0.6, 0.7,
        (v_ans ->> 'documents_ready') in ('partial','no') or v_ans ->> 'documents_ready' is null,
        'Belgelerinin dijital + fiziksel kopyalarını hazırla', false),
      ('pets_transfer', 'before_departure', 0.5, 0.6,
        (v_ans ->> 'pets') = 'yes', 'Evcil hayvan taşıma/sağlık evraklarını tamamla', true),
      ('emergency_save', 'day_0_7', 0.3, 0.8,
        (v_ans ->> 'emergency_contacts') = 'no' or v_ans ->> 'emergency_contacts' is null,
        'Acil iletişim numaralarını kaydet', true),
      ('phone_line', 'day_0_7', 0.2, 0.7,
        (v_ans ->> 'phone_internet') in ('temporary','none') or v_ans ->> 'phone_internet' is null,
        'Yerel telefon/internet hattı edin', false),
      ('address_registration', 'day_0_7', 0.9, 0.85,
        (v_ans ->> 'address_registration_known') = 'no'
          or (v_ans ->> 'address_registration_known') is null,
        'Adres/belediye kaydı için randevu kontrolü yap', true),
      ('transport_setup', 'day_0_7', 0.2, 0.5,
        (v_ans ->> 'transport') = 'none' or v_ans ->> 'transport' is null,
        'İlk hafta ulaşım planını kur', false),
      ('banking_open', 'day_8_30', 0.5, 0.7,
        (v_ans ->> 'banking') in ('researching','none') or v_ans ->> 'banking' is null,
        'Yerel banka hesabı / ödeme çözümü aç', false),
      ('tax_social', 'day_8_30', 0.8, 0.6,
        (v_ans ->> 'tax_social_security') = 'no',
        'Vergi/sosyal güvenlik kayıt adımlarını öğren', true),
      ('school_enroll', 'day_8_30', 0.6, 0.75,
        (v_ans ->> 'children_school') = 'yes', 'Çocuk okul kaydını başlat', true),
      ('community_connect', 'day_8_30', 0.1, 0.4,
        (v_ans ->> 'community_intro') = 'yes', 'Topluluk/mentor desteğiyle bağlan', false),
      ('credential_apply', 'day_31_90', 0.7, 0.55,
        (v_ans ->> 'credential_recognition') in ('yes','not_sure'),
        'Mesleki denklik/lisans başvurusunu başlat', true),
      ('language_course', 'day_31_90', 0.2, 0.4,
        (v_ans ->> 'language_course') in ('yes','not_sure'),
        'Dil kursu/entegrasyon programına kaydol', false),
      ('permanent_housing', 'day_31_90', 0.3, 0.5,
        (v_ans ->> 'housing_status') in ('temporary','searching','none'),
        'Kalıcı konut araştırmasını ilerlet', false),
      ('driving_convert', 'day_31_90', 0.5, 0.4,
        (v_ans ->> 'driving_license') = 'yes', 'Ehliyet dönüşümü işlemlerini yap', true),
      ('integration_routine', 'ongoing', 0.2, 0.3,
        true, 'Yenileme/entegrasyon rutinini takvimine al', false)
    ) as t(task_key, phase, legal_dependency, base_urgency, gap_test, title, source_has_link)
  ),
  emitted as (
    select
      task_key, phase, title, source_has_link,
      -- deadline_urgency: faz tabanlı (erken faz daha acil) × varış yakınlığı, base_urgency ile harman.
      round(
        (case phase
           when 'before_departure' then 1.0
           when 'day_0_7' then 0.85
           when 'day_8_30' then 0.6
           when 'day_31_90' then 0.4
           else 0.25 end) * 0.5 + base_urgency * 0.3 + v_proximity * 0.2,
        4) as deadline_urgency,
      legal_dependency,
      1.0 as user_gap,
      case when source_has_link then 0.8 else 0.4 end as source_trust
    from catalog
    where gap_test
  ),
  scored as (
    select
      task_key, phase, title,
      round(deadline_urgency * 0.40 + legal_dependency * 0.25 + user_gap * 0.25 + source_trust * 0.10, 4) as priority_score
    from emitted
  )
  select
    coalesce(jsonb_agg(
      jsonb_build_object('key', task_key, 'title', title, 'phase', phase, 'priority', priority_score)
      order by (v_phase_order ->> phase)::int, priority_score desc
    ), '[]'::jsonb),
    coalesce((
      select jsonb_agg(jsonb_build_object('key', task_key, 'title', title, 'phase', phase, 'score', priority_score)
                       order by priority_score desc)
      from (select task_key, title, phase, priority_score from scored order by priority_score desc limit 3) t3
    ), '[]'::jsonb),
    count(*)
  into v_tasks, v_top3, v_task_count
  from scored;

  select count(*) into v_source_link_count
  from jsonb_array_elements(v_tasks) t
  where (t ->> 'key') in (
    select task_key from (values
      ('health_insurance_setup'),('visa_finalize'),('pets_transfer'),('emergency_save'),
      ('address_registration'),('tax_social'),('school_enroll'),('credential_apply'),('driving_convert')
    ) s(task_key)
  );

  return public.rl_tool_write_result(
    p_session_id,
    'checklist',
    null,
    null,
    jsonb_build_object('tasks', v_tasks, 'task_count', v_task_count, 'source_link_count', v_source_link_count),
    '{}'::jsonb,
    v_top3,
    jsonb_build_array(
      'İlk 90 gün planında ' || v_task_count::text || ' görev var.',
      v_source_link_count::text || ' görev resmi kaynak adımı içeriyor; en kritik 3''ten başla.'
    ),
    jsonb_build_array(
      jsonb_build_object('key','view_relocation_plan','label','Görevleri Taşınma Planında Gör'),
      jsonb_build_object('key','open_service_finder','label','Şehirdeki Servis Önerileri'),
      jsonb_build_object('key','find_mentor','label','Mentor/Topluluk Desteği')
    ),
    '{}'::jsonb,
    'rule-v1'
  );
end;
$_$;


--
-- Name: relocation_score_job_probability_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.relocation_score_job_probability_v1(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session public.relocation_tool_sessions%rowtype := public.rl_tool_owned_session(p_session_id);
  v_ans jsonb := public.rl_tool_answers_json(p_session_id);
  v_weights jsonb;
  v_bands jsonb := jsonb_build_array(
    jsonb_build_object('key','high','min',75),
    jsonb_build_object('key','medium_high','min',55),
    jsonb_build_object('key','challenging','min',40),
    jsonb_build_object('key','low','min',0));
  v_profession_key text := v_ans ->> 'profession_title';
  v_profession_id uuid;
  v_country text := upper(coalesce(v_ans ->> 'target_country', ''));
  v_signal public.relocation_job_market_signals%rowtype;
  v_demand numeric;
  v_lang_work numeric := public.rl_tool_clamp_neutral((coalesce((v_ans ->> 'language_level')::numeric, 2.5) / 5));
  v_lang_en numeric := public.rl_tool_clamp_neutral((coalesce((v_ans ->> 'english_level')::numeric, 2.5) / 5));
  v_language numeric;
  v_years numeric := coalesce((v_ans ->> 'years_experience')::numeric, 0);
  v_seniority text := v_ans ->> 'seniority';
  v_seniority_score numeric;
  v_portfolio text := v_ans ->> 'portfolio_cv';
  v_portfolio_score numeric;
  v_interviews text := v_ans ->> 'interviews';
  v_experience numeric;
  v_credential numeric;
  v_regulated text := v_ans ->> 'regulated_profession';
  v_cred_status text := v_ans ->> 'credential_status';
  v_work_auth text := v_ans ->> 'work_authorization';
  v_work_auth_score numeric;
  v_network text := v_ans ->> 'network';
  v_apps numeric := coalesce((v_ans ->> 'applications')::numeric, 0);
  v_network_activity numeric;
  v_breakdown jsonb;
  v_score100 numeric;
  v_bucket text;
  v_labels jsonb;
  v_weak jsonb;
  v_confidence numeric := 0.4;
  -- YENİ sinyaller
  v_linkedin_quality numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'linkedin_profile_quality')::numeric, 3) - 1) / 4));
  v_industry_certs text[] := coalesce(array(select jsonb_array_elements_text(coalesce(v_ans -> 'industry_specific_certifications', '[]'::jsonb))), '{}'::text[]);
  v_industry_cert_score numeric := case when cardinality(v_industry_certs) = 0 or v_industry_certs = array['none'] then 0.5
    else least(cardinality(v_industry_certs)::numeric / 2.0, 1.0) end;
  v_salary_research text := v_ans ->> 'salary_research_done';
  v_salary_research_score numeric := case v_salary_research when 'thorough' then 1.0 when 'basic' then 0.5 else 0.2 end;
  v_recruiter_contact text := v_ans ->> 'local_recruiter_contact';
  v_recruiter_score numeric := case v_recruiter_contact when 'yes' then 1.0 when 'in_progress' then 0.5 else 0.0 end;
begin
  select weights into v_weights from public.relocation_tools where key = 'job_finding_probability';
  select id into v_profession_id from public.relocation_professions where profession_key = v_profession_key and is_active;

  if v_profession_id is not null and v_country <> '' then
    select * into v_signal from public.relocation_job_market_signals
    where profession_id = v_profession_id and country_code = v_country and is_active;
  end if;
  if found then
    v_demand := public.rl_tool_clamp_neutral(
      coalesce(v_signal.vacancy_index, 0.5) * 0.4
      + coalesce(v_signal.shortage_index, 0.5) * 0.4
      + coalesce(v_signal.unemployment_inverse_index, 0.5) * 0.2);
    v_confidence := v_signal.confidence;
  else
    v_demand := 0.5;
  end if;

  v_language := public.rl_tool_clamp_neutral(v_lang_work * 0.65 + v_lang_en * 0.35);

  v_seniority_score := case v_seniority
    when 'junior' then 0.3 when 'mid' then 0.55 when 'senior' then 0.8
    when 'lead' then 0.9 when 'manager' then 0.95 else 0.5 end;
  v_portfolio_score := case v_portfolio when 'ready' then 1.0 when 'partial' then 0.5 else 0.3 end;
  v_experience := public.rl_tool_clamp_neutral(
    least(v_years / 10.0, 1.0) * 0.35 + v_seniority_score * 0.25 + v_portfolio_score * 0.15
    + (case v_interviews when 'multiple' then 1.0 when 'one' then 0.6 else 0.2 end) * 0.15
    + v_salary_research_score * 0.10);

  v_credential := (case
    when v_regulated = 'no' then 0.9
    when v_cred_status = 'recognized' then 0.95
    when v_cred_status = 'not_needed' then 0.9
    when v_cred_status = 'in_progress' then 0.55
    when v_regulated = 'yes' and v_cred_status in ('none', '') then 0.25
    else 0.5 end) * 0.85 + v_industry_cert_score * 0.15;

  v_work_auth_score := case v_work_auth
    when 'authorized' then 1.0 when 'eligible' then 0.75
    when 'needs_sponsor' then 0.4 else 0.4 end;

  v_network_activity := public.rl_tool_clamp_neutral(
    (case v_network when 'strong' then 1.0 when 'weak' then 0.5 else 0.2 end) * 0.35
    + least(v_apps / 20.0, 1.0) * 0.20
    + (case v_interviews when 'multiple' then 1.0 when 'one' then 0.6 else 0.2 end) * 0.15
    + v_linkedin_quality * 0.15
    + v_recruiter_score * 0.15);

  v_breakdown := jsonb_build_object(
    'demand_fit', round(v_demand, 4),
    'language_fit', round(v_language, 4),
    'experience_signal', round(v_experience, 4),
    'credential_fit', round(v_credential, 4),
    'work_authorization_fit', round(v_work_auth_score, 4),
    'network_activity_fit', round(v_network_activity, 4)
  );

  v_score100 := round(public.rl_tool_weighted_score(v_breakdown, v_weights) * 100, 2);
  v_bucket := public.rl_tool_resolve_bucket(v_score100, v_bands);

  v_labels := jsonb_build_object(
    'demand_fit', 'Talep Uyumu',
    'language_fit', 'Dil',
    'experience_signal', 'Deneyim Sinyali',
    'credential_fit', 'Denklik',
    'work_authorization_fit', 'Çalışma İzni',
    'network_activity_fit', 'Network & Aktivite');

  select coalesce(jsonb_agg(
    jsonb_build_object('key', dim, 'title', v_labels ->> dim, 'score', val,
      'detail', 'Hızlı kazanım: ' || (v_labels ->> dim) || ' alanını güçlendir.')
    order by val asc), '[]'::jsonb)
  into v_weak
  from (select key as dim, value::numeric as val,
               row_number() over (order by value::numeric asc, key) as rn
        from jsonb_each_text(v_breakdown)) r
  where rn <= 3;

  return public.rl_tool_write_result(
    p_session_id,
    'score',
    v_score100,
    v_bucket,
    jsonb_build_object('weakest3', v_weak, 'score', v_score100),
    v_breakdown,
    v_weak,
    jsonb_build_array(
      'İş bulma skorun: ' || v_score100::text || '/100 (karar destek skoru, garanti değildir).',
      'En zayıf alanlarınla başla; talep ve dil sinyalin skoru en çok etkiler.'),
    jsonb_build_array(
      jsonb_build_object('key','start_related_tool','label','Maaş Karşılaştırması','href','/tools/meslek-maas-karsilastirma'),
      jsonb_build_object('key','find_mentor','label','Diaspora Mentor Eşleşmesi','href','/tools/diaspora-ag-eslestirme'),
      jsonb_build_object('key','start_related_tool','label','Kariyer Yolu Roadmap','href','/tools/yurtdisi-kariyer-yolu')),
    jsonb_build_object('confidence', v_confidence),
    'rule-v1'
  );
end;
$$;


--
-- Name: relocation_score_profession_salary_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.relocation_score_profession_salary_v1(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session public.relocation_tool_sessions%rowtype := public.rl_tool_owned_session(p_session_id);
  v_ans jsonb := public.rl_tool_answers_json(p_session_id);
  v_weights jsonb;
  v_bands jsonb := jsonb_build_array(
    jsonb_build_object('key','high_value','min',75),
    jsonb_build_object('key','balanced','min',55),
    jsonb_build_object('key','expensive_but_high_salary','min',40),
    jsonb_build_object('key','low_salary_or_high_barrier','min',0));
  v_profession_key text := v_ans ->> 'profession_title';
  v_profession_id uuid;
  v_regulated text := v_ans ->> 'regulated_profession';
  v_targets text[] := coalesce(
    (select array_agg(upper(trim(t)))
     from regexp_split_to_table(coalesce(v_ans ->> 'target_countries', ''), ',') t
     where trim(t) <> ''), '{}'::text[]);
  v_global_max numeric;
  v_rows jsonb;
  v_top jsonb;
  v_top_score numeric;
  -- YENİ sinyaller: pazarlık özgüveni + mülakat hazırlığı → demand_fit'i hafifçe güçlendirir
  -- (kişinin talep tarafında ne kadar etkin olabileceğinin bir proxy'si);
  -- yan haklar önceliği + vize sponsor ihtiyacı → tax_social_fit'e katkı.
  v_negotiation numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'negotiation_experience')::numeric, 3) - 1) / 4));
  v_interview_ready numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'interview_readiness')::numeric, 3) - 1) / 4));
  v_visa_sponsor text := v_ans ->> 'visa_sponsor_need';
  v_benefits text[] := coalesce(array(select jsonb_array_elements_text(coalesce(v_ans -> 'benefits_priority', '[]'::jsonb))), '{}'::text[]);
  v_benefits_score numeric := case when cardinality(v_benefits) = 0 or v_benefits = array['none'] then 0.5
    else least(cardinality(v_benefits)::numeric / 3.0, 1.0) end;
begin
  select weights into v_weights from public.relocation_tools where key = 'profession_salary';

  select id into v_profession_id from public.relocation_professions where profession_key = v_profession_key and is_active;
  if v_profession_id is null then
    return public.rl_tool_write_result(
      p_session_id, 'comparison', null, null,
      jsonb_build_object('rows', '[]'::jsonb),
      '{}'::jsonb, '[]'::jsonb,
      jsonb_build_array('Seçilen meslek için maaş verisi bulunamadı.'),
      jsonb_build_array(jsonb_build_object('key','view_relocation_plan','label','Taşınma Planın')),
      '{}'::jsonb, 'rule-v1');
  end if;

  select max(salary_median) into v_global_max
  from public.relocation_salary_benchmarks
  where profession_id = v_profession_id and is_active;
  if coalesce(v_global_max, 0) = 0 then v_global_max := 1; end if;

  with rows0 as (
    select
      b.country_code,
      coalesce(cm.country_name_tr, b.country_code) as country_name,
      b.salary_min, b.salary_median, b.salary_max, b.currency,
      round(b.salary_median * b.net_ratio / 12.0, 0) as net_monthly_est,
      b.demand_index, b.confidence,
      cm.cost_index,
      jsonb_build_object(
        'salary_level', public.rl_tool_clamp_neutral(b.salary_median / v_global_max),
        'cost_adjusted_income', public.rl_tool_clamp_neutral(
          (b.salary_median * b.net_ratio / v_global_max) / nullif(0.4 + coalesce(cm.cost_index, 0.5), 0)),
        'demand_fit', public.rl_tool_clamp_neutral(
          b.demand_index * 0.8 + v_negotiation * 0.1 + v_interview_ready * 0.1),
        'tax_social_fit', public.rl_tool_clamp_neutral(
          b.net_ratio * 0.75 + v_benefits_score * 0.25),
        'credential_transferability', case
          when v_regulated = 'yes' then 0.3
          when v_regulated = 'not_sure' then 0.5
          else 0.85 end
          * (case when v_visa_sponsor = 'yes' then 0.9 else 1.0 end)
      ) as breakdown
    from public.relocation_salary_benchmarks b
    left join public.relocation_country_metrics cm on cm.country_code = b.country_code
    where b.profession_id = v_profession_id and b.is_active
      and (array_length(v_targets, 1) is null or b.country_code = any (v_targets))
  ),
  scored as (
    select *,
      round(public.rl_tool_weighted_score(breakdown, v_weights) * 100, 2) as power_index
    from rows0
  ),
  numbered as (
    select *, row_number() over (order by power_index desc, country_name) as rn from scored
  )
  select
    coalesce(jsonb_agg(
      jsonb_build_object(
        'key', country_code, 'title', country_name, 'score', power_index,
        'bucket', public.rl_tool_resolve_bucket(power_index, v_bands),
        'gross_min', salary_min, 'gross_median', salary_median, 'gross_max', salary_max,
        'net_monthly', net_monthly_est, 'currency', currency,
        'demand', demand_index, 'confidence', confidence,
        'sub_scores', breakdown,
        'detail', country_name || ' — brüt medyan ' || salary_median::text || ' ' || currency || '/yıl'
      ) order by power_index desc, country_name
    ) filter (where rn <= 8), '[]'::jsonb),
    (jsonb_agg(breakdown order by power_index desc, country_name) filter (where rn = 1)) -> 0,
    max(power_index) filter (where rn = 1)
  into v_rows, v_top, v_top_score
  from numbered;

  return public.rl_tool_write_result(
    p_session_id,
    'comparison',
    v_top_score,
    public.rl_tool_resolve_bucket(coalesce(v_top_score, 0), v_bands),
    jsonb_build_object('rows', v_rows),
    coalesce(v_top, '{}'::jsonb),
    v_rows,
    case when v_rows = '[]'::jsonb
      then jsonb_build_array('Seçtiğin ülkelerde bu meslek için maaş verisi bulunamadı.')
      else jsonb_build_array(
        'Meslek ve hedef ülkelere göre maaş gücü karşılaştırıldı.',
        'Brüt bandlar küratörlü veridir; net tahmin basitleştirilmiş ülke faktörüne dayanır, garanti değildir.') end,
    jsonb_build_array(
      jsonb_build_object('key','start_related_tool','label','İş Bulma Olasılığını Hesapla','href','/tools/is-bulma-olasiligi'),
      jsonb_build_object('key','find_mentor','label','Bu Meslekte Mentor Bul'),
      jsonb_build_object('key','start_related_tool','label','Kariyer Yolu Aracı','href','/tools/yurtdisi-kariyer-yolu')
    ),
    '{}'::jsonb,
    'rule-v1'
  );
end;
$$;


--
-- Name: relocation_score_readiness_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.relocation_score_readiness_v1(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session public.relocation_tool_sessions%rowtype := public.rl_tool_owned_session(p_session_id);
  v_ans jsonb := public.rl_tool_answers_json(p_session_id);
  v_weights jsonb;
  v_bands jsonb := jsonb_build_array(
    jsonb_build_object('key','ready','min',80),
    jsonb_build_object('key','proceed','min',60),
    jsonb_build_object('key','prepare','min',40),
    jsonb_build_object('key','high_risk','min',0)
  );
  s_savings numeric := public.rl_readiness_opt_score('relocation_readiness','savings_months', v_ans ->> 'savings_months');
  s_passport numeric := public.rl_readiness_opt_score('relocation_readiness','passport_validity', v_ans ->> 'passport_validity');
  s_visa numeric := public.rl_readiness_opt_score('relocation_readiness','visa_route', v_ans ->> 'visa_route');
  s_diploma numeric := public.rl_readiness_opt_score('relocation_readiness','diploma_docs', v_ans ->> 'diploma_docs');
  s_housing numeric := public.rl_readiness_opt_score('relocation_readiness','housing_first_month', v_ans ->> 'housing_first_month');
  s_job numeric := public.rl_readiness_opt_score('relocation_readiness','job_income_plan', v_ans ->> 'job_income_plan');
  s_health numeric := public.rl_readiness_opt_score('relocation_readiness','health_insurance', v_ans ->> 'health_insurance');
  s_support numeric := public.rl_readiness_opt_score('relocation_readiness','support_network', v_ans ->> 'support_network');
  s_family numeric := public.rl_readiness_opt_score('relocation_readiness','family_alignment', v_ans ->> 'family_alignment');
  s_emergency numeric := public.rl_readiness_opt_score('relocation_readiness','emergency_plan', v_ans ->> 'emergency_plan');
  -- YENİ single option skorları
  s_emergency_fund numeric := public.rl_readiness_opt_score('relocation_readiness','emergency_fund_access', v_ans ->> 'emergency_fund_access');
  s_bank numeric := public.rl_readiness_opt_score('relocation_readiness','local_bank_account', v_ans ->> 'local_bank_account');
  s_remote_transition numeric := public.rl_readiness_opt_score('relocation_readiness','remote_work_transition', v_ans ->> 'remote_work_transition');
  s_pet numeric := public.rl_readiness_opt_score('relocation_readiness','pet_relocation_plan', v_ans ->> 'pet_relocation_plan');
  s_debt numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'debt_pressure')::numeric, 3) - 1) / 4));
  s_lang numeric := public.rl_tool_clamp_neutral((coalesce((v_ans ->> 'language_level')::numeric, 2.5) / 5));
  s_adapt numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'adaptability')::numeric, 3) - 1) / 4));
  s_timeline numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'timeline_realism')::numeric, 3) - 1) / 4));
  s_mental numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'mental_health_readiness')::numeric, 3) - 1) / 4));
  v_breakdown jsonb;
  v_score01 numeric;
  v_score100 numeric;
  v_bucket text;
  v_labels jsonb;
  v_weak jsonb;
begin
  select weights into v_weights from public.relocation_tools where key = 'relocation_readiness';

  -- Boyut türetme (ortalama; relocation-tools-readiness.ts ile birebir + yeni sinyaller).
  v_breakdown := jsonb_build_object(
    'financial_readiness', round((s_savings * 0.5 + s_debt * 0.3 + s_emergency_fund * 0.2), 4),
    'legal_document_readiness', round((s_passport * 0.30 + s_visa * 0.30 + s_diploma * 0.25 + s_bank * 0.15), 4),
    'language_readiness', round(s_lang, 4),
    'housing_logistics', round((s_housing * 0.45 + s_timeline * 0.25 + s_family * 0.15 + s_pet * 0.15), 4),
    'job_income_readiness', round((s_job * 0.75 + s_remote_transition * 0.25), 4),
    'support_adaptability', round((s_support * 0.30 + s_emergency * 0.15 + s_health * 0.15 + s_adapt * 0.20 + s_mental * 0.20), 4)
  );

  v_score01 := public.rl_tool_weighted_score(v_breakdown, v_weights);
  v_score100 := round(v_score01 * 100, 2);
  v_bucket := public.rl_tool_resolve_bucket(v_score100, v_bands);

  v_labels := jsonb_build_object(
    'financial_readiness', 'Finansal Hazırlık',
    'legal_document_readiness', 'Evrak & Yasal',
    'language_readiness', 'Dil',
    'housing_logistics', 'Konaklama & Lojistik',
    'job_income_readiness', 'İş & Gelir',
    'support_adaptability', 'Destek & Uyum'
  );

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'key', dim, 'title', v_labels ->> dim, 'score', val,
      'detail', 'Bu alanı bu hafta güçlendir: ' || (v_labels ->> dim) || '.'
    ) order by val asc
  ) filter (where rn <= 3), '[]'::jsonb)
  into v_weak
  from (
    select key as dim, value::numeric as val,
           row_number() over (order by value::numeric asc, key) as rn
    from jsonb_each_text(v_breakdown)
  ) r;

  return public.rl_tool_write_result(
    p_session_id,
    'score',
    v_score100,
    v_bucket,
    jsonb_build_object('weakest3', v_weak, 'score', v_score100),
    v_breakdown,
    v_weak,
    jsonb_build_array(
      'Hazırlık skorun: ' || v_score100::text || '/100.',
      'En zayıf alanlarınla bu hafta başla; her negatif cevap bir aksiyon adımı.'
    ),
    jsonb_build_array(
      jsonb_build_object('key','start_related_tool','label','İlk 90 Gün Planlayıcı''ya Geç','href','/tools/ilk-90-gun-planlayici'),
      jsonb_build_object('key','start_related_tool','label','Ülke Seçimi Aracına Dön','href','/tools/ulke-secimi'),
      jsonb_build_object('key','find_mentor','label','Mentor/Topluluk Desteği Bul')
    ),
    '{}'::jsonb,
    'rule-v1'
  );
end;
$$;


--
-- Name: relocation_score_sigorta_secim_almanya_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.relocation_score_sigorta_secim_almanya_v1(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session public.relocation_tool_sessions%rowtype := public.rl_tool_owned_session(p_session_id);
  v_ans jsonb := public.rl_tool_answers_json(p_session_id);
  -- Sigorta tipleri: key → {title, base, mustAt, shouldAt} (ref101 INSURANCE_TYPES aynası).
  v_types jsonb := jsonb_build_array(
    jsonb_build_object('key','HEALTH','title','Sağlık Sigortası (Krankenversicherung)','base',10,'mustAt',12,'shouldAt',9),
    jsonb_build_object('key','LIABILITY','title','Özel Sorumluluk (Privathaftpflicht)','base',8,'mustAt',11,'shouldAt',8),
    jsonb_build_object('key','CAR','title','Araç Sigortası (Kfz-Haftpflicht + opsiyonel kasko)','base',0,'mustAt',5,'shouldAt',3),
    jsonb_build_object('key','HOUSEHOLD','title','Ev Eşyası (Hausrat)','base',2,'mustAt',8,'shouldAt',5),
    jsonb_build_object('key','LEGAL','title','Hukuk Koruma (Rechtsschutz)','base',1,'mustAt',9,'shouldAt',5),
    jsonb_build_object('key','BU','title','Çalışamazlık / Gelir Koruma (Berufsunfähigkeit)','base',1,'mustAt',10,'shouldAt',6),
    jsonb_build_object('key','LIFE','title','Risk Hayat (Risikolebensversicherung)','base',0,'mustAt',8,'shouldAt',4),
    jsonb_build_object('key','DENTAL','title','Diş Tamamlayıcı (Zahnzusatz)','base',0,'mustAt',7,'shouldAt',4),
    jsonb_build_object('key','ACCIDENT','title','Kaza Sigortası (Unfallversicherung)','base',0,'mustAt',7,'shouldAt',4),
    jsonb_build_object('key','TRAVEL','title','Seyahat Sağlık (Auslandsreise-KV)','base',0,'mustAt',7,'shouldAt',3),
    jsonb_build_object('key','BUILDING','title','Konut Bina (Wohngebäude) — ev sahibiysen','base',0,'mustAt',7,'shouldAt',3),
    jsonb_build_object('key','PET_LIAB','title','Evcil Hayvan Sorumluluk (Tierhalterhaftpflicht)','base',0,'mustAt',7,'shouldAt',2)
  );
  v_scores jsonb := '{}'::jsonb;
  v_q record;
  v_ranked jsonb;
  v_bands jsonb := jsonb_build_array(
    jsonb_build_object('key','excellent','min',80),
    jsonb_build_object('key','strong','min',60),
    jsonb_build_object('key','good','min',40),
    jsonb_build_object('key','moderate','min',0)
  );
  v_top_score numeric;
begin
  -- 1) Her sigorta tipinin base skoruyla başla.
  select coalesce(jsonb_object_agg(t ->> 'key', (t ->> 'base')::numeric), '{}'::jsonb)
  into v_scores
  from jsonb_array_elements(v_types) as t;

  -- 2) Cevaplardan tip katkılarını ekle (scoring->'add'->answer).
  for v_q in
    select (q.scoring -> 'add' -> (v_ans ->> q.question_key)) as add_obj
    from public.relocation_tool_questions q
    where q.tool_key = 'sigorta_secim_almanya' and q.is_active and v_ans ? q.question_key
  loop
    if v_q.add_obj is not null then
      select v_scores || (
        select jsonb_object_agg(k, coalesce((v_scores ->> k)::numeric, 0) + (val)::numeric)
        from jsonb_each_text(v_q.add_obj) as e(k, val)
      ) into v_scores;
    end if;
  end loop;

  -- 3) Tipleri skora göre sırala; öncelik bandını (must/should/optional) eşiklerle belirle.
  --    score100: ham skoru görece 0..100'e ölçekle (max ham skor = referans, en az 1).
  with scored as (
    select
      t ->> 'key' as key,
      t ->> 'title' as title,
      coalesce((v_scores ->> (t ->> 'key'))::numeric, 0) as raw,
      (t ->> 'mustAt')::numeric as must_at,
      (t ->> 'shouldAt')::numeric as should_at
    from jsonb_array_elements(v_types) as t
  ),
  banded as (
    select key, title, raw, must_at, should_at,
      case
        when raw >= must_at then 'must'
        when raw >= should_at then 'should'
        else 'optional'
      end as priority,
      greatest((select max(raw) from scored), 1) as max_raw
    from scored
  ),
  ranked as (
    select key, title, raw, priority,
      round(greatest(least(raw / max_raw, 1), 0) * 100, 0) as score100,
      case priority when 'must' then 1 when 'should' then 2 else 3 end as p_order,
      case priority when 'must' then 'Önce Al' when 'should' then 'Güçlü Öneri' else 'Opsiyonel' end as priority_label
    from banded
  )
  select
    coalesce(jsonb_agg(
      jsonb_build_object(
        'key', key,
        'title', title,
        'score', score100,
        'detail', priority_label,
        'priority', priority
      ) order by p_order asc, raw desc, title
    ), '[]'::jsonb),
    (select score100 from ranked order by p_order asc, raw desc, title limit 1)
  into v_ranked, v_top_score
  from ranked;

  return public.rl_tool_write_result(
    p_session_id,
    'ranked_list',
    v_top_score,
    public.rl_tool_resolve_bucket(coalesce(v_top_score, 0), v_bands),
    jsonb_build_object('ranked_insurances', v_ranked),
    '{}'::jsonb,
    v_ranked,
    jsonb_build_array(
      'Durumuna göre sigortaların öncelik sırasına dizildi: "Önce Al" kalemlerinden başla.',
      'Bu liste yönlendirme amaçlıdır; kapsam/koşulları sağlayıcının güncel şartlarından doğrula.'
    ),
    jsonb_build_array(
      jsonb_build_object('key','start_related_tool','label','Banka Seçimine Geç','href','/tools/banka-secim-almanya'),
      jsonb_build_object('key','find_mentor','label','Danışman/Topluluk Desteği Bul')
    ),
    '{}'::jsonb,
    'rule-v1'
  );
end;
$$;


--
-- Name: relocation_score_top_challenge_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.relocation_score_top_challenge_v1(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session public.relocation_tool_sessions%rowtype := public.rl_tool_owned_session(p_session_id);
  v_ans jsonb := public.rl_tool_answers_json(p_session_id);
  v_urgency text := v_ans ->> 'urgency';
  v_urgency_mult numeric;
  v_conf numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'confidence')::numeric, 3) - 1) / 4));
  v_risk numeric;
  v_docs text := v_ans ->> 'documents_state';
  v_income text := v_ans ->> 'income_state';
  v_support text := v_ans ->> 'support_state';
  -- YENİ kategori-derinlik sinyalleri
  v_housing_state text := v_ans ->> 'housing_state';
  v_language_state text := v_ans ->> 'language_state';
  v_finance_state text := v_ans ->> 'finance_state';
  -- YENİ genel bağlam sinyalleri: karar felci/eylem hazırlığı urgency çarpanını hafifçe ayarlar,
  -- bütçe tamponu finance kategorisi bağımlılığını güçlendirir.
  v_action_ready numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'action_readiness')::numeric, 3) - 1) / 4));
  v_decision_paralysis numeric := public.rl_tool_clamp_neutral(((coalesce((v_ans ->> 'decision_paralysis')::numeric, 3) - 1) / 4));
  v_budget_buffer text := v_ans ->> 'budget_buffer';
  v_scores jsonb := '{}'::jsonb;
  v_top_key text;
  v_top_val numeric;
  v_labels jsonb;
  v_recs jsonb;
  v_ctas jsonb;
begin
  v_urgency_mult := case v_urgency
    when '0-1m' then 1.0 when '1-3m' then 0.75 when '3-6m' then 0.5 when '6m+' then 0.25
    else 0.5 end;
  -- Karar felci arttıkça ve eylem hazırlığı azaldıkça risk hafifçe artar.
  v_risk := least((1 - v_conf) * 0.85 + v_decision_paralysis * 0.10 + (1 - v_action_ready) * 0.05, 1.0);

  with cat as (
    select * from (values
      ('visa_docs',  array['visa','paperwork']),
      ('job_income', array['job']),
      ('language',   array['language']),
      ('housing',    array['housing']),
      ('finance',    array['money']),
      ('community_support', array['loneliness']),
      ('credential_recognition', array['school']),
      ('healthcare_family', array['healthcare'])
    ) as t(cat_key, stress_keys)
  ),
  stress as (
    select array(select jsonb_array_elements_text(coalesce(v_ans -> 'stressors', '[]'::jsonb))) as keys
  ),
  blocked as (
    select array(select jsonb_array_elements_text(coalesce(v_ans -> 'blocked_progress', '[]'::jsonb))) as keys
  ),
  scored as (
    select
      c.cat_key,
      (case when exists (select 1 from unnest(c.stress_keys) sk where sk = any ((select keys from stress)))
            then 1.0 else 0.0 end) as user_stress,
      (case when exists (select 1 from unnest(c.stress_keys) sk where sk = any ((select keys from blocked)))
            then 1.0 else 0.0 end) as progress_blocker,
      -- dependency_factor: kategoriye özel derinlik sinyalleri (0..1); YENİ housing/language/finance
      -- state soruları + bütçe tamponu finance için ek ağırlık sağlar.
      (case c.cat_key
        when 'visa_docs' then case v_docs when 'confused' then 1.0 when 'partial' then 0.5 else 0.0 end
        when 'job_income' then case v_income when 'not_started' then 1.0 when 'searching' then 0.6 else 0.0 end
        when 'housing' then case v_housing_state when 'not_started' then 1.0 when 'searching' then 0.6 else 0.0 end
        when 'language' then case v_language_state when 'stuck' then 1.0 when 'learning' then 0.5 else 0.0 end
        when 'finance' then
          (case v_finance_state when 'critical' then 1.0 when 'tight' then 0.5 else 0.0 end) * 0.7
          + (case v_budget_buffer when 'no' then 1.0 when 'partial' then 0.5 else 0.0 end) * 0.3
        when 'community_support' then case v_support when 'none' then 1.0 when 'weak' then 0.5 else 0.0 end
        when 'healthcare_family' then
          case when jsonb_array_length(coalesce(v_ans -> 'health_family_complexity', '[]'::jsonb)) > 0
                    and not (coalesce(v_ans -> 'health_family_complexity', '[]'::jsonb) ? 'none')
               then 1.0 else 0.0 end
        else 0.0 end) as dependency_factor
    from cat c
  ),
  final as (
    select
      cat_key,
      round(
        user_stress * 0.35 + progress_blocker * 0.35
        + (v_urgency_mult * v_risk) * 0.20 + dependency_factor * 0.10,
        4
      ) as score
    from scored
  )
  select
    jsonb_object_agg(cat_key, score),
    (array_agg(cat_key order by score desc, cat_key))[1],
    (array_agg(score order by score desc, cat_key))[1]
  into v_scores, v_top_key, v_top_val
  from final;

  v_labels := jsonb_build_object(
    'visa_docs', 'Vize & Evrak',
    'job_income', 'İş & Gelir',
    'language', 'Dil',
    'housing', 'Konut',
    'finance', 'Finans',
    'community_support', 'Topluluk & Destek',
    'credential_recognition', 'Diploma Denkliği',
    'healthcare_family', 'Sağlık & Aile'
  );

  select coalesce(jsonb_agg(
    jsonb_build_object('key', cat_key, 'title', v_labels ->> cat_key, 'score', score)
    order by score desc, cat_key
  ) filter (where rn <= 3), '[]'::jsonb)
  into v_recs
  from (
    select key as cat_key, value::numeric as score,
           row_number() over (order by value::numeric desc, key) as rn
    from jsonb_each_text(v_scores)
  ) r;

  v_ctas := case v_top_key
    when 'job_income' then jsonb_build_array(
      jsonb_build_object('key','start_related_tool','label','İş Bulma Olasılığını Hesapla','href','/tools/is-bulma-olasiligi'),
      jsonb_build_object('key','start_related_tool','label','Maaş Karşılaştırmasını Aç','href','/tools/meslek-maas-karsilastirma'))
    when 'visa_docs' then jsonb_build_array(
      jsonb_build_object('key','start_related_tool','label','Hazırlık Skorunu Çalıştır','href','/tools/tasinma-hazirlik-skoru'),
      jsonb_build_object('key','start_related_tool','label','İlk 90 Gün Planı','href','/tools/ilk-90-gun-planlayici'))
    when 'language' then jsonb_build_array(
      jsonb_build_object('key','start_related_tool','label','Kariyer Yolu Aracı','href','/tools/yurtdisi-kariyer-yolu'))
    when 'housing' then jsonb_build_array(
      jsonb_build_object('key','start_related_tool','label','Şehir Eşleştirme','href','/tools/sehir-eslestirme'))
    when 'community_support' then jsonb_build_array(
      jsonb_build_object('key','find_mentor','label','Diaspora Eşleştirmeyi Dene','href','/tools/diaspora-ag-eslestirme'))
    else jsonb_build_array(
      jsonb_build_object('key','view_relocation_plan','label','Taşınma Planın'))
  end;
  v_ctas := v_ctas || jsonb_build_array(jsonb_build_object('key','find_mentor','label','Mentor Bul'));

  return public.rl_tool_write_result(
    p_session_id,
    'score',
    round(v_top_val * 100, 2),
    v_top_key,
    jsonb_build_object(
      'primary_challenge', v_top_key,
      'primary_label', v_labels ->> v_top_key,
      'top3', v_recs
    ),
    v_scores,
    v_recs,
    jsonb_build_array(
      'Öncelikli engelin: ' || (v_labels ->> v_top_key) || '.',
      'Bu alan netleşmeden diğer kararlar da riskli hale gelebilir; bu hafta buradan başla.'
    ),
    v_ctas,
    '{}'::jsonb,
    'rule-v1'
  );
end;
$$;


--
-- Name: relocation_tool_complete_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.relocation_tool_complete_session(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_session public.relocation_tool_sessions%rowtype := public.rl_tool_owned_session(p_session_id);
  v_tool public.relocation_tools%rowtype;
  v_score_fn text;
  v_exists boolean;
  v_result jsonb;
begin
  select * into v_tool from public.relocation_tools where key = v_session.tool_key;

  -- tool_key -> skor RPC adı (docs/10tool/00 sözleşmesi ile birebir).
  v_score_fn := case v_session.tool_key
    when 'relocation_readiness'      then 'relocation_score_readiness_v1'
    when 'top_relocation_challenge'  then 'relocation_score_top_challenge_v1'
    when 'career_path_abroad'        then 'relocation_score_career_path_v1'
    when 'first_90_days_planner'     then 'relocation_score_first_90_days_v1'
    when 'job_finding_probability'   then 'relocation_score_job_probability_v1'
    -- Sözleşmeye uyan araçlar (city_match, country_match, diaspora_matchmaker,
    -- expat_lifestyle_persona, profession_salary) + ileride eklenecek araçlar:
    else 'relocation_score_' || v_session.tool_key || '_v1'
  end;

  select exists (
    select 1 from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = v_score_fn
  ) into v_exists;

  if v_exists then
    -- Skor RPC'si sonucu rl_tool_write_result ile yazar ve döner.
    execute format('select public.%I($1)', v_score_fn) into v_result using p_session_id;
    insert into public.relocation_tool_events (user_id, session_id, tool_key, event_type)
    values (v_session.user_id, p_session_id, v_session.tool_key, 'complete');
    return v_result;
  end if;

  -- Skor RPC'si yoksa: boş/nötr sonuç yaz.
  v_result := public.rl_tool_write_result(
    p_session_id, coalesce(v_tool.result_kind, 'score'),
    null, null, '{}'::jsonb, '{}'::jsonb, '[]'::jsonb,
    jsonb_build_array('Bu araç için skor modeli henüz tanımlı değil.'),
    '[]'::jsonb, '{}'::jsonb, 'rule-v1'
  );
  insert into public.relocation_tool_events (user_id, session_id, tool_key, event_type)
  values (v_session.user_id, p_session_id, v_session.tool_key, 'complete');
  return v_result;
end;
$_$;


--
-- Name: relocation_tool_record_event(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.relocation_tool_record_event(p_session_id uuid, p_event_type text, p_context jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := public.rl_tool_require_user();
  v_tool_key text;
begin
  if p_session_id is not null then
    select tool_key into v_tool_key from public.relocation_tool_sessions
    where id = p_session_id and user_id = v_uid;
    if v_tool_key is null then
      raise exception 'rl_forbidden';
    end if;
  end if;

  insert into public.relocation_tool_events (user_id, session_id, tool_key, event_type, context)
  values (v_uid, p_session_id, coalesce(v_tool_key, (p_context ->> 'tool_key')),
          p_event_type, coalesce(p_context, '{}'::jsonb));
end;
$$;


--
-- Name: relocation_tool_save_answer(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.relocation_tool_save_answer(p_session_id uuid, p_question_key text, p_answer jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session public.relocation_tool_sessions%rowtype := public.rl_tool_owned_session(p_session_id);
begin
  if p_question_key is null or p_question_key = '' then
    raise exception 'rl_question_key_required';
  end if;

  insert into public.relocation_tool_answers (session_id, question_key, answer)
  values (p_session_id, p_question_key, coalesce(p_answer, 'null'::jsonb))
  on conflict (session_id, question_key)
  do update set answer = excluded.answer, answered_at = now();
end;
$$;


--
-- Name: relocation_tool_start_session(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.relocation_tool_start_session(p_tool_key text, p_mode text, p_source_move_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := public.rl_tool_require_user();
  v_tool public.relocation_tools%rowtype;
  v_session_id uuid;
begin
  select * into v_tool from public.relocation_tools where key = p_tool_key and is_active;
  if not found then
    raise exception 'rl_tool_not_found';
  end if;
  if p_mode not in ('quick','detailed') then
    raise exception 'rl_invalid_mode';
  end if;

  insert into public.relocation_tool_sessions (user_id, tool_key, mode, status, source_move_id)
  values (v_uid, p_tool_key, p_mode, 'in_progress', p_source_move_id)
  returning id into v_session_id;

  insert into public.relocation_tool_events (user_id, session_id, tool_key, event_type, context)
  values (v_uid, v_session_id, p_tool_key, 'start', jsonb_build_object('mode', p_mode));

  return jsonb_build_object('session_id', v_session_id, 'tool_key', p_tool_key, 'mode', p_mode);
end;
$$;


--
-- Name: relocation_update_move(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.relocation_update_move(p_move_id uuid, p_patch jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_move public.relocation_moves%rowtype := public.relocation_owned_move(p_move_id);
begin
  update public.relocation_moves set
    budget_monthly = coalesce(nullif(p_patch ->> 'budget_monthly', '')::numeric, budget_monthly),
    setup_budget_max = coalesce(nullif(p_patch ->> 'setup_budget_max', '')::numeric, setup_budget_max),
    move_window_start = coalesce(nullif(p_patch ->> 'move_window_start', '')::date, move_window_start),
    move_window_end = coalesce(nullif(p_patch ->> 'move_window_end', '')::date, move_window_end),
    target_country_codes = case
      when p_patch ? 'target_country_codes'
      then coalesce(array(select upper(jsonb_array_elements_text(p_patch -> 'target_country_codes'))), target_country_codes)
      else target_country_codes end,
    must_haves = case when p_patch ? 'must_haves'
      then coalesce(array(select jsonb_array_elements_text(p_patch -> 'must_haves')), must_haves) else must_haves end,
    nice_to_haves = case when p_patch ? 'nice_to_haves'
      then coalesce(array(select jsonb_array_elements_text(p_patch -> 'nice_to_haves')), nice_to_haves) else nice_to_haves end,
    household = coalesce(p_patch -> 'household', household),
    status = coalesce(nullif(p_patch ->> 'status', ''), status),
    updated_at = now()
  where id = p_move_id;
end;
$$;


--
-- Name: report_cadde_entity_v1(text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_cadde_entity_v1(p_entity_type text, p_entity_id uuid, p_reason text, p_details text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_reason text := trim(coalesce(p_reason, ''));
  v_exists boolean;
  v_today int;
begin
  if v_uid is null then
    raise exception 'cadde_auth_required';
  end if;

  if public.is_cadde_banned(v_uid) then
    raise exception 'cadde_banned';
  end if;

  if p_entity_type not in ('post', 'comment', 'cafe', 'carsi_item') then
    raise exception 'cadde_invalid_report_entity';
  end if;

  if length(v_reason) < 3 or length(v_reason) > 200 then
    raise exception 'cadde_invalid_report_reason';
  end if;

  v_exists := case p_entity_type
    when 'post' then exists (select 1 from public.cadde_posts where id = p_entity_id)
    when 'comment' then exists (select 1 from public.cadde_post_comments where id = p_entity_id)
    when 'cafe' then exists (select 1 from public.cadde_cafes where id = p_entity_id)
    when 'carsi_item' then exists (select 1 from public.carsi_items where id = p_entity_id)
  end;
  if not v_exists then
    raise exception 'cadde_entity_not_found';
  end if;

  select count(*) into v_today
  from public.cadde_reports
  where reporter_user_id = v_uid and created_at > now() - interval '24 hours';
  if v_today >= public.cadde_setting_int('cadde.report.daily_limit', 10) then
    raise exception 'cadde_rate_limit';
  end if;

  insert into public.cadde_reports (entity_type, entity_id, reporter_user_id, reason, details)
  values (p_entity_type, p_entity_id, v_uid, v_reason, nullif(trim(coalesce(p_details, '')), ''))
  on conflict (entity_type, entity_id, reporter_user_id) do nothing;

  -- Açık kuyruk kaydı varsa rapor sayısını artır; yoksa aç.
  update public.cadde_moderation_queue
  set report_count = report_count + 1
  where entity_type = p_entity_type and entity_id = p_entity_id and status = 'open';

  if not found then
    insert into public.cadde_moderation_queue (entity_type, entity_id, reason, status)
    values (p_entity_type, p_entity_id, v_reason, 'open');
  end if;
end;
$$;


--
-- Name: request_new_catalog_item(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_new_catalog_item(p_role_key text, p_title text, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request_id uuid;
  v_title text;
begin
  if auth.uid() is null then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if p_role_key is null or btrim(p_role_key) = '' then
    raise exception 'role key is required' using errcode = '22023';
  end if;

  if not exists (select 1 from public.roles r where r.key = p_role_key and r.is_active = true) then
    raise exception 'invalid role key' using errcode = '22023';
  end if;

  v_title := nullif(btrim(coalesce(p_title, '')), '');
  if v_title is null then
    raise exception 'title is required' using errcode = '22023';
  end if;

  if exists (
    select 1 from public.approval_requests
    where user_id = auth.uid()
      and request_type = 'new_profile'
      and status = 'pending'
  ) then
    raise exception 'a pending new profile request already exists' using errcode = '22023';
  end if;

  insert into public.approval_requests (
    request_type, user_id, target_role_key,
    target_entity_type, payload, status
  ) values (
    'new_profile', auth.uid(), p_role_key,
    'catalog_item', jsonb_build_object('role_key', p_role_key, 'title', v_title, 'note', p_note), 'pending'
  )
  returning id into v_request_id;

  return v_request_id;
end;
$$;


--
-- Name: FUNCTION request_new_catalog_item(p_role_key text, p_title text, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_new_catalog_item(p_role_key text, p_title text, p_note text) IS 'Secondary profile request 2026-07-23: user requests a second catalog_items profile for another role. Admin-approved via admin_review_approval_request.';


--
-- Name: resolve_approval_request_type(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_approval_request_type(p_feature_key text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case p_feature_key
    when 'directory.visible' then 'directory_visibility'
    when 'contact.show_whatsapp' then 'contact_visibility'
    when 'directory.featured' then 'featured_listing'
    when 'events.create' then 'event_create'
    when 'offers.create' then 'offer_create'
    when 'referral.create' then 'referral_create'
    when 'city.manage' then 'city_manage'
    else 'contact_visibility'
  end;
$$;


--
-- Name: review_catalog_claim_request(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_catalog_claim_request(target_claim_request_id uuid, decision text, review_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_claim public.catalog_item_claims%rowtype;
  v_before_item public.catalog_items%rowtype;
begin
  if v_actor_id is null or not public.is_moderator(v_actor_id) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if decision not in ('approved', 'rejected', 'cancelled') then
    raise exception 'invalid decision' using errcode = '22023';
  end if;

  select *
  into v_claim
  from public.catalog_item_claims
  where id = target_claim_request_id
  for update;

  if v_claim.id is null then
    raise exception 'claim request not found' using errcode = 'P0002';
  end if;

  if v_claim.status <> 'pending' then
    raise exception 'claim request already reviewed' using errcode = '22023';
  end if;

  select *
  into v_before_item
  from public.catalog_items
  where id = v_claim.item_id
  for update;

  update public.catalog_item_claims
  set
    status = decision,
    note = coalesce(review_note, note),
    reviewed_by_user_id = v_actor_id,
    reviewed_at = now(),
    updated_at = now()
  where id = v_claim.id;

  if decision = 'approved' then
    insert into public.catalog_item_managers (
      item_id,
      user_id,
      role,
      status
    )
    values (
      v_claim.item_id,
      v_claim.requested_by_user_id,
      'editor',
      'active'
    )
    on conflict (item_id, user_id, role) do update
    set
      status = 'active',
      updated_at = now();

    update public.catalog_items
    set
      verification_status = case
        when verification_status = 'unverified' then 'claimed'
        else verification_status
      end,
      updated_at = now()
    where id = v_claim.item_id;
  end if;

  insert into public.catalog_audit_logs (
    item_id,
    actor_user_id,
    action,
    details,
    before_data,
    after_data
  )
  values (
    v_claim.item_id,
    v_actor_id,
    'catalog_claim_request_reviewed',
    jsonb_build_object(
      'claim_request_id', v_claim.id,
      'decision', decision,
      'review_note', review_note,
      'granted_membership_role', case when decision = 'approved' then 'editor' else null end
    ),
    to_jsonb(v_before_item),
    (
      select to_jsonb(ci)
      from public.catalog_items ci
      where ci.id = v_claim.item_id
    )
  );

  return jsonb_build_object(
    'claim_request_id', v_claim.id,
    'item_id', v_claim.item_id,
    'decision', decision,
    'granted_membership_role', case when decision = 'approved' then 'editor' else null end,
    'reviewed_by_user_id', v_actor_id
  );
end;
$$;


--
-- Name: rl_readiness_opt_score(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rl_readiness_opt_score(p_tool_key text, p_question_key text, p_value text) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((
    select (opt ->> 'score')::numeric
    from public.relocation_tool_questions q,
         jsonb_array_elements(q.options) opt
    where q.tool_key = p_tool_key and q.question_key = p_question_key
      and opt ->> 'value' = p_value
    limit 1
  ), 0.5);
$$;


--
-- Name: rl_tool_answers_json(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rl_tool_answers_json(p_session_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_object_agg(question_key, answer), '{}'::jsonb)
  from public.relocation_tool_answers
  where session_id = p_session_id;
$$;


--
-- Name: rl_tool_clamp_neutral(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rl_tool_clamp_neutral(p_value numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case
    when p_value is null then 0.5
    when p_value < 0 then 0
    when p_value > 1 then 1
    else p_value
  end::numeric;
$$;


--
-- Name: relocation_tool_sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.relocation_tool_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid DEFAULT auth.uid() NOT NULL,
    tool_key text NOT NULL,
    mode text NOT NULL,
    status text DEFAULT 'in_progress'::text NOT NULL,
    source_move_id uuid,
    consent_profile_write boolean DEFAULT false NOT NULL,
    consent_partner_referral boolean DEFAULT false NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    expires_at timestamp with time zone DEFAULT (now() + '30 days'::interval) NOT NULL,
    CONSTRAINT relocation_tool_sessions_mode_check CHECK ((mode = ANY (ARRAY['quick'::text, 'detailed'::text]))),
    CONSTRAINT relocation_tool_sessions_status_check CHECK ((status = ANY (ARRAY['in_progress'::text, 'completed'::text, 'abandoned'::text])))
);


--
-- Name: rl_tool_owned_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rl_tool_owned_session(p_session_id uuid) RETURNS public.relocation_tool_sessions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := public.rl_tool_require_user();
  v_session public.relocation_tool_sessions%rowtype;
begin
  select * into v_session from public.relocation_tool_sessions where id = p_session_id;
  if not found then
    raise exception 'rl_session_not_found';
  end if;
  if v_session.user_id <> v_uid then
    raise exception 'rl_forbidden';
  end if;
  return v_session;
end;
$$;


--
-- Name: rl_tool_require_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rl_tool_require_user() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'rl_auth_required';
  end if;
  return v_uid;
end;
$$;


--
-- Name: rl_tool_resolve_bucket(numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rl_tool_resolve_bucket(p_score numeric, p_bands jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select b ->> 'key'
  from jsonb_array_elements(coalesce(p_bands, '[]'::jsonb)) as b
  where p_score >= (b ->> 'min')::numeric
  order by (b ->> 'min')::numeric desc
  limit 1;
$$;


--
-- Name: rl_tool_weighted_score(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rl_tool_weighted_score(p_breakdown jsonb, p_weights jsonb) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  with w as (
    select key as dim, value::numeric as weight
    from jsonb_each_text(coalesce(p_weights, '{}'::jsonb))
  )
  select case
    when coalesce(sum(w.weight), 0) = 0 then 0
    else round(
      sum(public.rl_tool_clamp_neutral((p_breakdown ->> w.dim)::numeric) * w.weight) / sum(w.weight),
      4
    )
  end
  from w;
$$;


--
-- Name: rl_tool_write_result(uuid, text, numeric, text, jsonb, jsonb, jsonb, jsonb, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rl_tool_write_result(p_session_id uuid, p_result_kind text, p_total_score numeric, p_score_bucket text, p_primary_result jsonb, p_sub_scores jsonb, p_recommendations jsonb, p_explanations jsonb, p_ctas jsonb, p_source_quality jsonb DEFAULT '{}'::jsonb, p_model_version text DEFAULT 'rule-v1'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session public.relocation_tool_sessions%rowtype;
  v_result_id uuid;
begin
  select * into v_session from public.relocation_tool_sessions where id = p_session_id;

  delete from public.relocation_tool_results where session_id = p_session_id;

  insert into public.relocation_tool_results (
    session_id, user_id, tool_key, result_kind, total_score, score_bucket,
    primary_result, sub_scores, recommendations, explanations, ctas, source_quality, model_version
  ) values (
    p_session_id, v_session.user_id, v_session.tool_key, p_result_kind, p_total_score, p_score_bucket,
    coalesce(p_primary_result, '{}'::jsonb), coalesce(p_sub_scores, '{}'::jsonb),
    coalesce(p_recommendations, '[]'::jsonb), coalesce(p_explanations, '[]'::jsonb),
    coalesce(p_ctas, '[]'::jsonb), coalesce(p_source_quality, '{}'::jsonb), p_model_version
  )
  returning id into v_result_id;

  update public.relocation_tool_sessions
    set status = 'completed', completed_at = now()
    where id = p_session_id;

  return jsonb_build_object(
    'result_id', v_result_id,
    'tool_key', v_session.tool_key,
    'result_kind', p_result_kind,
    'total_score', p_total_score,
    'score_bucket', p_score_bucket,
    'primary_result', coalesce(p_primary_result, '{}'::jsonb),
    'sub_scores', coalesce(p_sub_scores, '{}'::jsonb),
    'recommendations', coalesce(p_recommendations, '[]'::jsonb),
    'explanations', coalesce(p_explanations, '[]'::jsonb),
    'ctas', coalesce(p_ctas, '[]'::jsonb)
  );
end;
$$;


--
-- Name: search_cadde_mentions_v1(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_cadde_mentions_v1(p_query text, p_limit integer DEFAULT 8) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_q text := lower(unaccent(trim(coalesce(p_query, ''))));
  v_limit int := least(greatest(coalesce(p_limit, 8), 1), 20);
  v_result jsonb;
begin
  if v_uid is null or length(v_q) < 2 then
    return '[]'::jsonb;
  end if;

  with matches as (
    -- Üyeler: yalnız full_name'i public görünürlükte olanlar.
    select 'user' as type, upa.user_id as id, upa.value_text as label,
           'Üye'::text as subtitle, 1 as rank_group
    from public.user_profile_attributes upa
    join public.afs_attributes a on a.id = upa.attribute_id
    where a.key = 'full_name'
      and upa.visibility = 'public'
      and coalesce(upa.value_text, '') <> ''
      and lower(unaccent(upa.value_text)) like '%' || v_q || '%'

    union all

    select 'catalog_item', ci.id, ci.title, 'İşletme / Kuruluş', 2
    from public.catalog_items ci
    where ci.status = 'published'
      and lower(unaccent(ci.title)) like '%' || v_q || '%'

    union all

    select 'cafe', c.id, c.title, 'Cafe', 3
    from public.cadde_cafes c
    where c.status = 'published' and c.archived_at is null and c.is_active = true
      and lower(unaccent(c.title)) like '%' || v_q || '%'

    union all

    select 'carsi_item', i.id, i.title, 'Çarşı ilanı', 4
    from public.carsi_items i
    where i.status = 'published' and i.moderation_status = 'approved' and i.deleted_at is null
      and (i.expires_at is null or i.expires_at > now())
      and lower(unaccent(i.title)) like '%' || v_q || '%'
  ),
  ranked as (
    select *,
      -- Baştan eşleşme daha alakalı sayılır.
      case when lower(unaccent(label)) like v_q || '%' then 0 else 1 end as prefix_rank
    from matches
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'type', type, 'id', id, 'label', label, 'subtitle', subtitle
  ) order by prefix_rank, rank_group, label), '[]'::jsonb)
  into v_result
  from (select * from ranked order by prefix_rank, rank_group, label limit v_limit) capped;

  return v_result;
end;
$$;


--
-- Name: search_cadde_people_v1(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_cadde_people_v1(p_query text, p_limit integer DEFAULT 12) RETURNS TABLE(user_id uuid, full_name text, city text, country text, has_profile boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_query text := btrim(coalesce(p_query, ''));
  v_limit integer := least(greatest(coalesce(p_limit, 12), 1), 25);
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  -- 2 karakterden kısa sorgu: tüm üye listesini dökmeyi engeller (enumerasyon koruması).
  if char_length(v_query) < 2 then
    return;
  end if;

  return query
  with named_users as (
    -- Onaylı full_name'i olan tüm üyeler (arama evreni) — yönetici/moderatör hariç.
    select upa.user_id as uid, upa.value_text as name
    from public.user_profile_attributes upa
    join public.afs_attributes a on a.id = upa.attribute_id
    where a.key = 'full_name'
      and upa.approval_status = 'approved'
      and nullif(btrim(coalesce(upa.value_text, '')), '') is not null
      and upa.value_text ilike '%' || v_query || '%'
      and not exists (
        select 1
        from public.user_role_assignments ura_x
        join public.roles r_x on r_x.id = ura_x.role_id
        where ura_x.user_id = upa.user_id
          and (r_x.key ilike 'Admin_%' or r_x.key ilike 'Moderator_%')
      )
  )
  select
    nu.uid,
    nu.name,
    case
      when ipd.user_id is not null then ipd.active_city
      else pub_city.value_text  -- kapalı profil: şehir YALNIZ public görünürlükteyse
    end as city,
    case when ipd.user_id is not null then ipd.active_country else null end as country,
    (ipd.user_id is not null) as has_profile
  from named_users nu
  left join public.individual_profile_details ipd
    on ipd.user_id = nu.uid and ipd.visibility_status = 'open'
  left join lateral (
    select upa2.value_text
    from public.user_profile_attributes upa2
    join public.afs_attributes a2 on a2.id = upa2.attribute_id
    where upa2.user_id = nu.uid
      and a2.key = 'city'
      and upa2.approval_status = 'approved'
      and upa2.visibility = 'public'
    limit 1
  ) pub_city on ipd.user_id is null
  order by (ipd.user_id is not null) desc, nu.name
  limit v_limit;
end;
$$;


--
-- Name: FUNCTION search_cadde_people_v1(p_query text, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.search_cadde_people_v1(p_query text, p_limit integer) IS 'Cadde İnsanları Keşfet araması (m38). Açık profiller tam satır; ad-onaylı kapalı profiller yalnız isim(+public şehir). Admin/Moderator dışlanır.';


--
-- Name: search_catalog(text, text[], text[], text, text, text[], boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_catalog(search_query text, item_types text[] DEFAULT NULL::text[], category_slugs text[] DEFAULT NULL::text[], city_filter text DEFAULT NULL::text, country_filter text DEFAULT NULL::text, language_filters text[] DEFAULT NULL::text[], verified_only boolean DEFAULT false, limit_count integer DEFAULT 20, offset_count integer DEFAULT 0) RETURNS TABLE(item_id uuid, item_type text, slug text, title text, headline text, short_description text, city text, country_code text, verification_status text, category_slugs text[], language_codes text[], thumbnail_url text, score numeric, filter_data jsonb)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with normalized as (
    select
      nullif(btrim(search_query), '') as raw_query,
      public.catalog_search_normalize(search_query) as normalized_query,
      greatest(1, least(coalesce(limit_count, 20), 100)) as safe_limit,
      greatest(0, coalesce(offset_count, 0)) as safe_offset
  ),
  base as (
    select
      csd.item_id,
      ci.item_type,
      ci.slug,
      ci.title,
      ci.headline,
      ci.short_description,
      csd.city,
      csd.country_code,
      ci.verification_status,
      csd.category_slugs,
      csd.language_codes,
      coalesce(csd.filter_data ->> 'thumbnail_url', '') as thumbnail_url,
      coalesce(csd.filter_data, '{}'::jsonb) ||
        jsonb_strip_nulls(
          jsonb_build_object(
            'platform_role_key', coalesce(ci.platform_role_key, ci.attributes ->> 'platform_role_key'),
            'platform_role_label', coalesce(r.label, ci.attributes ->> 'platform_role_label'),
            'specialty_summary', ci.attributes ->> 'specialty_summary'
          )
        ) as filter_data,
      n.raw_query,
      n.normalized_query,
      case
        when n.raw_query is null then 0::numeric
        else (
          case
            when public.catalog_search_normalize(ci.title) = n.normalized_query then 100
            else 0
          end
          + (
            coalesce(
              ts_rank_cd(
                csd.search_vector,
                websearch_to_tsquery('simple', n.normalized_query)
              ),
              0
            ) * 10
          )
          + greatest(
            similarity(public.catalog_search_normalize(ci.title), n.normalized_query),
            similarity(public.catalog_search_normalize(csd.search_text), n.normalized_query)
          )
          + case
              when ci.verification_status in ('verified', 'official_source') then 0.25
              else 0
            end
        )::numeric
      end as score
    from public.catalog_search_documents csd
    join public.catalog_items ci on ci.id = csd.item_id
    cross join normalized n
    left join public.roles r on r.key = coalesce(ci.platform_role_key, ci.attributes ->> 'platform_role_key')
    left join public.person_profile_details ppd on ppd.item_id = ci.id
    where ci.status = 'published'
      and ci.visibility = 'public'
      and (
        ci.item_type <> 'person_profile'
        or coalesce(ppd.directory_opt_in, false) = true
      )
      and (
        item_types is null
        or cardinality(item_types) = 0
        or ci.item_type = any (item_types)
      )
      and (
        category_slugs is null
        or cardinality(category_slugs) = 0
        or csd.category_slugs && category_slugs
      )
      and (
        language_filters is null
        or cardinality(language_filters) = 0
        or csd.language_codes && language_filters
      )
      and (
        city_filter is null
        or lower(coalesce(csd.city, '')) = lower(city_filter)
      )
      and (
        country_filter is null
        or lower(coalesce(csd.country_code, '')) = lower(country_filter)
      )
      and (
        not verified_only
        or ci.verification_status in ('verified', 'official_source')
      )
      and (
        coalesce((csd.filter_data ->> 'expires_at')::timestamptz, 'infinity'::timestamptz) >= now()
      )
      and (
        n.raw_query is null
        or csd.search_vector @@ websearch_to_tsquery('simple', n.normalized_query)
        or similarity(public.catalog_search_normalize(ci.title), n.normalized_query) >= 0.20
        or similarity(public.catalog_search_normalize(csd.search_text), n.normalized_query) >= 0.12
      )
  )
  select
    b.item_id,
    b.item_type,
    b.slug,
    b.title,
    b.headline,
    b.short_description,
    b.city,
    b.country_code,
    b.verification_status,
    b.category_slugs,
    b.language_codes,
    nullif(b.thumbnail_url, '') as thumbnail_url,
    b.score,
    b.filter_data
  from base b
  order by
    case
      when b.raw_query is not null and public.catalog_search_normalize(b.title) = b.normalized_query then 1
      else 0
    end desc,
    case
      when b.verification_status in ('verified', 'official_source') then 1
      else 0
    end desc,
    b.score desc,
    b.title asc,
    b.item_id asc
  limit (select safe_limit from normalized)
  offset (select safe_offset from normalized);
$$;


--
-- Name: FUNCTION search_catalog(search_query text, item_types text[], category_slugs text[], city_filter text, country_filter text, language_filters text[], verified_only boolean, limit_count integer, offset_count integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.search_catalog(search_query text, item_types text[], category_slugs text[], city_filter text, country_filter text, language_filters text[], verified_only boolean, limit_count integer, offset_count integer) IS 'Deterministic unified catalog search RPC for public search UIs and AI assistants. Returns safe public fields plus catalog role metadata.';


--
-- Name: search_directory_catalog(text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_directory_catalog(p_search_text text DEFAULT NULL::text, p_role_key text DEFAULT NULL::text, p_country_code text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_featured_only boolean DEFAULT false) RETURNS TABLE(item_id uuid, item_type text, slug text, title text, role_key text, role_label text, description text, city text, country text, image_url text, special_label text, special_value text, is_featured boolean, is_verified boolean, is_claimable boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id     uuid    := auth.uid();
  v_search_text text    := nullif(btrim(coalesce(p_search_text, '')), '');
  v_role_key    text    := nullif(btrim(coalesce(p_role_key, '')), '');
  v_country_code text   := upper(nullif(btrim(coalesce(p_country_code, '')), ''));
  v_city        text    := nullif(btrim(coalesce(p_city, '')), '');
  v_words       text[]  := '{}';
begin
  if v_user_id is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  -- Split search text into individual words for AND-semantics multi-word search.
  if v_search_text is not null then
    select array_agg(w)
    into v_words
    from (
      select unnest(regexp_split_to_array(btrim(v_search_text), '\s+')) as w
    ) t
    where btrim(t.w) <> '';
  end if;

  return query
  -- Branch 1: catalog items
  with primary_locations as (
    select distinct on (cil.item_id)
      cil.item_id,
      cil.city,
      cil.country_code
    from public.catalog_item_locations cil
    order by cil.item_id, cil.is_primary desc, cil.created_at asc
  ),
  primary_media as (
    select distinct on (cim.item_id)
      cim.item_id,
      coalesce(cim.thumbnail_url, cim.url) as image_url
    from public.catalog_item_media cim
    where cim.is_public = true
    order by cim.item_id, cim.is_primary desc, cim.created_at asc
  ),
  claim_status as (
    select
      ccr.item_id,
      bool_or(ccr.status = 'pending') as has_pending_claim
    from public.catalog_item_claims ccr
    group by ccr.item_id
  )
  select
    ci.id as item_id,
    ci.item_type,
    ci.slug,
    ci.title,
    coalesce(ci.platform_role_key, r.key, ci.item_type) as role_key,
    coalesce(r.label, ci.platform_role_key, ci.item_type) as role_label,
    coalesce(ci.short_description, ci.headline, left(ci.long_description, 220)) as description,
    pl.city,
    pl.country_code as country,
    pm.image_url,
    case
      when coalesce(ci.attributes ->> 'specialty_summary', '') <> '' then 'Uzmanlık / Kategori'
      when coalesce(ci.headline, '') <> '' then 'Başlık'
      else null
    end as special_label,
    nullif(coalesce(ci.attributes ->> 'specialty_summary', ci.headline), '') as special_value,
    coalesce((ci.attributes ->> 'is_featured')::boolean, false) as is_featured,
    (ci.verification_status in ('verified', 'official_source', 'claimed')) as is_verified,
    (
      ci.verification_status <> 'claimed'
      and not coalesce(cs.has_pending_claim, false)
    ) as is_claimable
  from public.catalog_items ci
  left join public.roles r
    on r.key = ci.platform_role_key
  left join primary_locations pl
    on pl.item_id = ci.id
  left join primary_media pm
    on pm.item_id = ci.id
  left join claim_status cs
    on cs.item_id = ci.id
  where ci.status = 'published'
    and ci.visibility in ('public', 'unlisted')
    and coalesce(r.is_directory_visible, true)
    and (v_role_key is null or ci.platform_role_key = v_role_key)
    and (v_country_code is null or upper(coalesce(pl.country_code, '')) = v_country_code)
    and (v_city is null or lower(coalesce(pl.city, '')) = lower(v_city))
    and (
      not p_featured_only
      or coalesce((ci.attributes ->> 'is_featured')::boolean, false)
    )
    -- Multi-word AND search: every word must appear in at least one field.
    and (
      v_search_text is null
      or (
        select bool_and(
          ci.title ilike '%' || word || '%'
          or coalesce(r.label, '') ilike '%' || word || '%'
          or coalesce(ci.headline, '') ilike '%' || word || '%'
          or coalesce(ci.short_description, '') ilike '%' || word || '%'
          or coalesce(ci.long_description, '') ilike '%' || word || '%'
          or coalesce(pl.city, '') ilike '%' || word || '%'
          or coalesce(pl.country_code, '') ilike '%' || word || '%'
          or coalesce(ci.platform_role_key, '') ilike '%' || word || '%'
        )
        from unnest(v_words) as word
      )
    )

  union all

  -- Branch 2: individual users (AFS system via individual_profile_details).
  -- Display name now resolved from user_profile_attributes (key 'full_name'),
  -- replacing the dropped the legacy profiles table join.
  select
    ipd.user_id as item_id,
    'member' as item_type,
    ipd.user_id::text as slug,
    coalesce(member_name.full_name, 'CorteQS Üyesi') as title,
    'bireysel' as role_key,
    'Bireysel Kullanıcı' as role_label,
    ipd.tagline as description,
    ipd.active_city as city,
    gc.code as country,
    (ipd.front_card ->> 'profile_image_url') as image_url,
    null::text as special_label,
    null::text as special_value,
    false as is_featured,
    false as is_verified,
    false as is_claimable
  from public.individual_profile_details ipd
  left join lateral (
    select upa.value_text as full_name
    from public.user_profile_attributes upa
    join public.afs_attributes ac on ac.id = upa.attribute_id
    where upa.user_id = ipd.user_id
      and ac.key = 'full_name'
      and upa.approval_status = 'approved'
    limit 1
  ) member_name on true
  left join public.geo_countries gc
    on gc.is_active = true
    and (
      gc.name = ipd.active_country
      or gc.code = upper(ipd.active_country)
    )
  where ipd.visibility_status = 'open'
    -- B20: yönetici/moderatör hesapları halka açık dizinde listelenmez
    -- (is_admin/is_moderator ile aynı rol deseni).
    and not exists (
      select 1
      from public.user_role_assignments ura_x
      join public.roles r_x on r_x.id = ura_x.role_id
      where ura_x.user_id = ipd.user_id
        and (r_x.key ilike 'Admin_%' or r_x.key ilike 'Moderator_%')
    )
    and not p_featured_only
    and (v_role_key is null or v_role_key = 'bireysel')
    and (v_country_code is null or upper(coalesce(gc.code, '')) = v_country_code)
    and (v_city is null or lower(coalesce(ipd.active_city, '')) = lower(v_city))
    -- Multi-word AND search for individual profiles.
    and (
      v_search_text is null
      or (
        select bool_and(
          coalesce(member_name.full_name, '') ilike '%' || word || '%'
          or coalesce(ipd.tagline, '') ilike '%' || word || '%'
          or coalesce(ipd.active_city, '') ilike '%' || word || '%'
          or coalesce(ipd.active_country, '') ilike '%' || word || '%'
          or 'Bireysel Kullanıcı' ilike '%' || word || '%'
        )
        from unnest(v_words) as word
      )
    )

  order by
    is_featured desc,
    is_verified desc,
    title asc;
end;
$$;


--
-- Name: service_finder_require_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_finder_require_admin() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'sf_auth_required';
  end if;
  if not public.is_admin(v_uid) then
    raise exception 'sf_admin_required';
  end if;
  return v_uid;
end;
$$;


--
-- Name: service_finder_slugify(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_finder_slugify(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  select left(
    regexp_replace(
      regexp_replace(
        lower(translate(
          coalesce(p_value, ''),
          'ıİğĞüÜşŞöÖçÇäÄßéèêáàâúùûíìî',
          'iigguussooccaasseeeaaauuuiii'
        )),
        '[^a-z0-9]+', '-', 'g'
      ),
      '(^-+|-+$)', '', 'g'
    ),
    96
  );
$_$;


--
-- Name: service_finder_text_array(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_finder_text_array(p_value jsonb) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case
    when p_value is null or jsonb_typeof(p_value) <> 'array' then '{}'::text[]
    else coalesce(array(select jsonb_array_elements_text(p_value)), '{}'::text[])
  end;
$$;


