--
-- Name: set_catalog_search_embedding(uuid, public.vector); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_catalog_search_embedding(target_item_id uuid, next_embedding public.vector) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.role() <> 'service_role' then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  update public.catalog_search_documents
  set
    embedding = next_embedding,
    updated_at = now()
  where item_id = target_item_id;
end;
$$;


