--
-- Name: submissions_apply_referral_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submissions_apply_referral_code() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  validation_result RECORD;
  normalized_referral_code TEXT;
BEGIN
  IF NEW.id IS NULL THEN
    NEW.id := gen_random_uuid();
  END IF;

  IF NEW.referral_code IS NULL OR BTRIM(NEW.referral_code) = '' THEN
    NEW.referral_code := NULL;
    NEW.referral_code_id := NULL;
    RETURN NEW;
  END IF;

  normalized_referral_code := UPPER(BTRIM(NEW.referral_code));

  SELECT * INTO validation_result
  FROM public.validate_and_bind_referral_code(normalized_referral_code, COALESCE(NEW.created_at, now()))
  LIMIT 1;

  IF validation_result.status IS DISTINCT FROM 'valid' THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = COALESCE(validation_result.message, 'Referral code is invalid.'),
      DETAIL = COALESCE(validation_result.status, 'invalid_referral_code'),
      HINT = 'Use a valid and active referral code within its date range.';
  END IF;

  NEW.referral_code := validation_result.normalized_code;
  NEW.referral_code_id := validation_result.referral_code_id;

  RETURN NEW;
END;
$$;


--
-- Name: submissions_log_referral_usage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submissions_log_referral_usage() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.referral_code_id IS NULL THEN
    RETURN NEW;
  END IF;

  UPDATE public.referral_codes
  SET
    usage_count = COALESCE(usage_count, 0) + 1,
    is_used = true,
    used_at = GREATEST(COALESCE(used_at, TIMESTAMPTZ 'epoch'), COALESCE(NEW.created_at, now()))
  WHERE id = NEW.referral_code_id;

  INSERT INTO public.referral_code_usages (referral_code_id, submission_id, used_at, full_name, email)
  VALUES (
    NEW.referral_code_id,
    NEW.id,
    COALESCE(NEW.created_at, now()),
    NEW.fullname,
    NEW.email
  )
  ON CONFLICT (submission_id) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: catalog_item_claims; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.catalog_item_claims (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    item_id uuid NOT NULL,
    requested_by_user_id uuid NOT NULL,
    claim_type text DEFAULT 'ownership'::text NOT NULL,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    note text,
    status text DEFAULT 'pending'::text NOT NULL,
    reviewed_by_user_id uuid,
    reviewed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT catalog_claim_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'cancelled'::text]))),
    CONSTRAINT catalog_item_claims_status_chk CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'cancelled'::text])))
);


--
-- Name: TABLE catalog_item_claims; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.catalog_item_claims IS 'Rebuild 2026-06-09: item claim requests (was catalog_claim_requests).';


--
-- Name: submit_catalog_claim_request(uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_catalog_claim_request(target_item_id uuid, claim_type text DEFAULT 'ownership'::text, evidence jsonb DEFAULT '{}'::jsonb, note text DEFAULT NULL::text) RETURNS public.catalog_item_claims
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_claim public.catalog_item_claims%rowtype;
begin
  if v_user_id is null then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if target_item_id is null then
    raise exception 'item_id is required' using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.catalog_items ci
    where ci.id = target_item_id
  ) then
    raise exception 'catalog item not found' using errcode = 'P0002';
  end if;

  -- Only block if the user has an explicit owner membership row.
  -- Moderators can still submit claims on behalf of others (they don't "own" items just by being moderators).
  if exists (
    select 1
    from public.catalog_item_managers
    where item_id = target_item_id
      and user_id = v_user_id
      and role = 'owner'
      and status = 'active'
  ) then
    raise exception 'item already owned by current user' using errcode = '23505';
  end if;

  insert into public.catalog_item_claims (
    item_id,
    requested_by_user_id,
    claim_type,
    evidence,
    note,
    status
  )
  values (
    target_item_id,
    v_user_id,
    coalesce(nullif(btrim(claim_type), ''), 'ownership'),
    coalesce(evidence, '{}'::jsonb),
    note,
    'pending'
  )
  returning * into v_claim;

  insert into public.catalog_audit_logs (
    item_id,
    actor_user_id,
    action,
    details,
    after_data
  )
  values (
    target_item_id,
    v_user_id,
    'catalog_claim_request_submitted',
    jsonb_build_object('claim_request_id', v_claim.id),
    to_jsonb(v_claim)
  );

  return v_claim;
end;
$$;


--
-- Name: submit_feature_request(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_feature_request(feature_key text, payload jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request_id uuid;
  v_scope_role text;
  v_user_role_key text;
  v_request_type text;
begin
  if auth.uid() is null then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select fc.scope_role into v_scope_role
  from public.afs_features fc
  where fc.key = feature_key;

  if v_scope_role is null then
    raise exception 'invalid feature key' using errcode = '22023';
  end if;

  -- scope_role = '*' ise herkese açık, değilse kullanıcının rolüyle eşleşmeli
  if v_scope_role <> '*' then
    select r.key into v_user_role_key
    from public.user_role_assignments ura
    join public.roles r on r.id = ura.role_id
    where ura.user_id = auth.uid();

    if v_user_role_key is null or v_user_role_key <> v_scope_role then
      raise exception 'invalid feature key for current role' using errcode = '22023';
    end if;
  end if;

  v_request_type := public.resolve_approval_request_type(feature_key);

  insert into public.approval_requests (
    request_type, user_id, target_feature_key,
    target_entity_type, payload, status
  ) values (
    v_request_type, auth.uid(), feature_key,
    'feature', coalesce(payload, '{}'::jsonb), 'pending'
  )
  returning id into v_request_id;

  return v_request_id;
end;
$$;


--
-- Name: submit_role_change_request(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_role_change_request(target_role_key text, note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request_id uuid;
  v_current_role_key text;
begin
  if auth.uid() is null then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if target_role_key is null or btrim(target_role_key) = '' then
    raise exception 'target role key is required' using errcode = '22023';
  end if;

  if not exists (select 1 from public.roles r where r.key = target_role_key and r.is_active = true) then
    raise exception 'invalid role key' using errcode = '22023';
  end if;

  select r.key into v_current_role_key
  from public.user_role_assignments ura
  join public.roles r on r.id = ura.role_id
  where ura.user_id = auth.uid();

  if v_current_role_key = target_role_key then
    raise exception 'user already has this role' using errcode = '22023';
  end if;

  insert into public.approval_requests (
    request_type, user_id, target_role_key,
    target_entity_type, payload, status
  ) values (
    'role_change', auth.uid(), target_role_key,
    'profile', jsonb_build_object('note', note), 'pending'
  )
  returning id into v_request_id;

  return v_request_id;
end;
$$;


--
-- Name: sync_individual_public_profile_settings_from_attribute(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_individual_public_profile_settings_from_attribute() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_attribute_key text;
  v_user_id uuid;
  v_profile_settings jsonb;
  v_value_text text;
  v_visibility text;
  v_approval_status text;
begin
  if tg_op = 'DELETE' then
    v_user_id := old.user_id;
    v_visibility := 'private';
    v_approval_status := 'rejected';
    select key into v_attribute_key from public.afs_attributes where id = old.attribute_id limit 1;
    v_value_text := null;
  else
    v_user_id := new.user_id;
    v_visibility := new.visibility;
    v_approval_status := new.approval_status;
    select key into v_attribute_key from public.afs_attributes where id = new.attribute_id limit 1;
    v_value_text := nullif(btrim(coalesce(new.value_text, new.value_json #>> '{}', '')), '');
  end if;

  if v_attribute_key not in ('business_or_organization', 'interest_focus', 'referral_code', 'referral_source') then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  insert into public.individual_profile_details (user_id, profile_settings)
  values (v_user_id, '{}'::jsonb)
  on conflict (user_id) do nothing;

  select coalesce(profile_settings, '{}'::jsonb)
  into v_profile_settings
  from public.individual_profile_details
  where user_id = v_user_id
  for update;

  if v_attribute_key in ('business_or_organization', 'interest_focus')
     and v_visibility = 'public'
     and v_approval_status = 'approved'
     and v_value_text is not null then
    v_profile_settings := jsonb_set(
      coalesce(v_profile_settings, '{}'::jsonb),
      array[v_attribute_key],
      to_jsonb(v_value_text),
      true
    );
  else
    v_profile_settings := coalesce(v_profile_settings, '{}'::jsonb) - v_attribute_key;
  end if;

  v_profile_settings := v_profile_settings - 'referral_code' - 'referral_source';

  update public.individual_profile_details
  set
    profile_settings = v_profile_settings,
    updated_at = now()
  where user_id = v_user_id;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: sync_member_attribute_from_user_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_member_attribute_from_user_profile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item_id uuid;
begin
  if new.user_id is null then
    return new;
  end if;

  select ci.id
  into v_item_id
  from public.catalog_items ci
  where ci.linked_user_id = new.user_id
    and ci.item_type = 'member'
    and ci.deleted_at is null
  order by ci.created_at asc
  limit 1;

  if v_item_id is null then
    return new;
  end if;

  insert into public.catalog_item_attribute_values (
    item_id, attribute_id, value_text, value_json,
    visibility, approval_status, approved_by, approved_at, updated_at
  )
  values (
    v_item_id, new.attribute_id, new.value_text, new.value_json,
    new.visibility, new.approval_status, new.approved_by, new.approved_at, now()
  )
  on conflict (item_id, attribute_id) do update
  set
    value_text = excluded.value_text,
    value_json = excluded.value_json,
    visibility = excluded.visibility,
    approval_status = excluded.approval_status,
    approved_by = excluded.approved_by,
    approved_at = excluded.approved_at,
    updated_at = now();

  return new;
end;
$$;


--
-- Name: FUNCTION sync_member_attribute_from_user_profile(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_member_attribute_from_user_profile() IS 'Mirrors user_profile_attributes rows onto the user''s member catalog item so the public profile (catalog_item_attribute_values) reflects /profile edits.';


--
-- Name: sync_member_catalog_role_for_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_member_catalog_role_for_user(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role_key   text;
  v_email      text;
  v_title      text;
  v_slug       text;
  v_item_id    uuid;
begin
  if p_user_id is null then
    return;
  end if;

  -- Resolve the user's role from the role-assignment system (single source).
  select r.key
  into v_role_key
  from public.user_role_assignments ura
  join public.roles r on r.id = ura.role_id
  where ura.user_id = p_user_id
  limit 1;

  -- Every authenticated user defaults to the standard diaspora member role.
  v_role_key := coalesce(v_role_key, 'User_DiasporaMember');

  -- Guard: platform_role_key has a FK to roles(key); skip role if it vanished.
  if not exists (select 1 from public.roles where key = v_role_key) then
    v_role_key := null;
  end if;

  -- Existing bridge?
  select ci.id
  into v_item_id
  from public.catalog_items ci
  where ci.linked_user_id = p_user_id
    and ci.item_type = 'member'
  order by ci.created_at asc
  limit 1;

  if v_item_id is not null then
    update public.catalog_items ci
    set
      platform_role_key = v_role_key,
      attributes = coalesce(ci.attributes, '{}'::jsonb)
                   || jsonb_build_object('platform_role_key', v_role_key),
      updated_at = now()
    where ci.id = v_item_id
      and (
        ci.platform_role_key is distinct from v_role_key
        or coalesce(ci.attributes ->> 'platform_role_key', '') is distinct from coalesce(v_role_key, '')
      );

    insert into public.catalog_item_managers (item_id, user_id, role, status)
    values (v_item_id, p_user_id, 'owner', 'active')
    on conflict (item_id, user_id, role) do update
    set status = 'active', updated_at = now();

    -- Keep the primary flat-role link in sync as well.
    if v_role_key is not null then
      insert into public.catalog_item_roles (catalog_item_id, role_id, is_primary)
      select v_item_id, r.id, not exists (
        select 1 from public.catalog_item_roles cir
        where cir.catalog_item_id = v_item_id and cir.is_primary
      )
      from public.roles r
      where r.key = v_role_key
      on conflict (catalog_item_id, role_id) do nothing;
    end if;

    return;
  end if;

  -- No bridge yet -> create one. Never leak wa.local phone local-parts as title.
  select au.email into v_email from auth.users au where au.id = p_user_id;
  if v_email like '%@wa.local' then
    v_title := 'CorteQS Üyesi';
  else
    v_title := coalesce(
      nullif(btrim(split_part(coalesce(v_email, ''), '@', 1)), ''),
      'CorteQS Üyesi'
    );
  end if;

  v_slug := 'member-' || substr(replace(p_user_id::text, '-', ''), 1, 16);
  if exists (
    select 1 from public.catalog_items ci
    where ci.slug = v_slug and ci.linked_user_id is distinct from p_user_id
  ) then
    v_slug := v_slug || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 4);
  end if;

  insert into public.catalog_items (
    item_type,
    slug,
    title,
    status,
    visibility,
    verification_status,
    linked_user_id,
    created_by,
    platform_role_key,
    attributes,
    published_at
  )
  values (
    'member',
    v_slug,
    v_title,
    'published',
    'public',
    'claimed',
    p_user_id,
    p_user_id,
    v_role_key,
    jsonb_build_object('bridge_source', 'auth_member_sync', 'platform_role_key', v_role_key),
    now()
  )
  on conflict (slug) do nothing
  returning id into v_item_id;

  if v_item_id is null then
    select ci.id into v_item_id
    from public.catalog_items ci
    where ci.linked_user_id = p_user_id and ci.item_type = 'member'
    order by ci.created_at asc
    limit 1;
  end if;

  if v_item_id is not null then
    insert into public.catalog_item_managers (item_id, user_id, role, status)
    values (v_item_id, p_user_id, 'owner', 'active')
    on conflict (item_id, user_id, role) do update
    set status = 'active', updated_at = now();

    if v_role_key is not null then
      insert into public.catalog_item_roles (catalog_item_id, role_id, is_primary)
      select v_item_id, r.id, true
      from public.roles r
      where r.key = v_role_key
      on conflict (catalog_item_id, role_id) do nothing;
    end if;
  end if;
end;
$$;


--
-- Name: FUNCTION sync_member_catalog_role_for_user(p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_member_catalog_role_for_user(p_user_id uuid) IS 'Idempotent member bridge: default flat role User_DiasporaMember, wa.local-safe title, keeps platform_role_key + catalog_item_roles + owner manager row in sync.';


--
-- Name: sync_member_catalog_role_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_member_catalog_role_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid;
begin
  v_user_id := coalesce(new.user_id, old.user_id);
  perform public.sync_member_catalog_role_for_user(v_user_id);
  return coalesce(new, old);
end;
$$;


--
-- Name: sync_member_title_from_full_name(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_member_title_from_full_name() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_attribute_key text;
  v_title text;
begin
  if new.user_id is null then
    return new;
  end if;

  select a.key
  into v_attribute_key
  from public.afs_attributes a
  where a.id = new.attribute_id;

  if v_attribute_key is distinct from 'full_name' then
    return new;
  end if;

  -- Onaylanmamış değişiklikler title'a yansımaz (onay akışıyla tutarlı).
  if coalesce(new.approval_status, 'approved') <> 'approved' then
    return new;
  end if;

  v_title := nullif(btrim(coalesce(new.value_text, '')), '');
  if v_title is null then
    return new;
  end if;

  update public.catalog_items ci
  set title = v_title, updated_at = now()
  where ci.linked_user_id = new.user_id
    and ci.item_type = 'member'
    and ci.deleted_at is null
    and ci.title is distinct from v_title;

  return new;
end;
$$;


