--
-- Name: update_cafe_member_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_cafe_member_count() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public.cafes SET member_count = member_count + 1 WHERE id = NEW.cafe_id;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE public.cafes SET member_count = GREATEST(0, member_count - 1) WHERE id = OLD.cafe_id;
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: update_carsi_item_v1(uuid, text, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_carsi_item_v1(p_item_id uuid, p_title text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_price_amount numeric DEFAULT NULL::numeric, p_price_currency text DEFAULT NULL::text, p_status text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_uid uuid := auth.uid();
  v_item public.carsi_items%rowtype;
  v_title text := nullif(trim(coalesce(p_title, '')), '');
  v_description text := nullif(trim(coalesce(p_description, '')), '');
  v_currency text := upper(nullif(trim(coalesce(p_price_currency, '')), ''));
  v_is_privileged boolean;
begin
  if v_uid is null then
    raise exception 'cadde_auth_required';
  end if;

  select * into v_item from public.carsi_items where id = p_item_id and deleted_at is null;
  if v_item.id is null then
    raise exception 'cadde_carsi_item_not_found';
  end if;

  v_is_privileged := public.is_admin(v_uid) or public.is_moderator(v_uid);
  if v_item.owner_user_id is distinct from v_uid and not v_is_privileged then
    raise exception 'cadde_carsi_owner_required';
  end if;

  if v_item.owner_user_id = v_uid and not v_is_privileged
     and not public.has_cadde_feature(v_uid, 'cadde.carsi.manage_own') then
    raise exception 'cadde_carsi_permission_denied';
  end if;

  if v_title is not null and (length(v_title) < 3 or length(v_title) > 100) then
    raise exception 'cadde_invalid_carsi_title';
  end if;

  if v_description is not null and length(v_description) > 2000 then
    raise exception 'cadde_invalid_carsi_description';
  end if;

  if p_price_amount is not null and p_price_amount < 0 then
    raise exception 'cadde_invalid_carsi_price';
  end if;

  if v_currency is not null and v_currency !~ '^[A-Z]{3}$' then
    raise exception 'cadde_invalid_carsi_currency';
  end if;

  -- Sahip yalnız yayına alma/pasife alma yapar; expired/draft geçişleri de serbest.
  if p_status is not null and p_status not in ('draft', 'published', 'paused', 'expired') then
    raise exception 'cadde_invalid_carsi_status';
  end if;

  update public.carsi_items
  set title = coalesce(v_title, title),
      description = coalesce(v_description, description),
      price_amount = coalesce(p_price_amount, price_amount),
      price_currency = coalesce(v_currency, price_currency),
      status = coalesce(p_status, status),
      updated_at = now()
  where id = p_item_id;
end;
$_$;


--
-- Name: update_catalog_item_attribute(uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_catalog_item_attribute(p_item_id uuid, p_attribute_key text, p_value jsonb, p_visibility text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item       public.catalog_items%rowtype;
  v_attribute  public.afs_attributes%rowtype;
  v_rule       public.role_attributes%rowtype;
  v_role_id    uuid;
  v_visibility text;
  v_value_text text;
  v_request_id uuid;
begin
  if auth.uid() is null then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select *
  into v_item
  from public.catalog_items
  where id = p_item_id
  limit 1;

  if v_item.id is null then
    raise exception 'item not found' using errcode = 'P0002';
  end if;

  if not (
    v_item.linked_user_id = auth.uid()
    or public.catalog_user_can_edit_item(auth.uid(), p_item_id)
    or public.is_admin(auth.uid())
  ) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select *
  into v_attribute
  from public.afs_attributes
  where key = p_attribute_key
    and is_active = true
  limit 1;

  if v_attribute.id is null then
    raise exception 'invalid attribute key' using errcode = '22023';
  end if;

  -- Primary flat role; fallback to platform_role_key.
  select cir.role_id
  into v_role_id
  from public.catalog_item_roles cir
  join public.roles r on r.id = cir.role_id and r.is_active = true and r.deleted_at is null
  where cir.catalog_item_id = v_item.id
    and cir.is_primary
  limit 1;

  if v_role_id is null and v_item.platform_role_key is not null then
    select r.id
    into v_role_id
    from public.roles r
    where r.key = v_item.platform_role_key
      and r.is_active = true
      and r.deleted_at is null
    limit 1;
  end if;

  if v_role_id is null then
    raise exception 'item has no active role' using errcode = '42501';
  end if;

  select *
  into v_rule
  from public.role_attributes
  where role_id = v_role_id
    and attribute_id = v_attribute.id
    and is_enabled = true
  limit 1;

  if v_rule.id is null then
    raise exception 'attribute is not enabled for current role' using errcode = '42501';
  end if;

  if not public.is_admin(auth.uid()) and not coalesce(v_rule.user_can_edit, false) then
    raise exception 'attribute not editable' using errcode = '42501';
  end if;

  v_visibility := coalesce(
    nullif(btrim(coalesce(p_visibility, '')), ''),
    case when coalesce(v_rule.is_public_default, false) then 'public' else 'private' end
  );

  if v_visibility not in ('public', 'private', 'admin_only') then
    raise exception 'invalid visibility' using errcode = '22023';
  end if;

  if not public.is_admin(auth.uid())
     and not coalesce(v_rule.user_can_hide, true)
     and v_visibility <> 'public' then
    raise exception 'attribute visibility cannot be changed' using errcode = '42501';
  end if;

  if v_attribute.data_type in ('text', 'textarea', 'select', 'url', 'phone') then
    v_value_text := nullif(btrim(coalesce(p_value #>> '{}', '')), '');
  end if;

  if coalesce(v_rule.requires_admin_approval_on_change, false) and not public.is_admin(auth.uid()) then
    insert into public.approval_requests (
      request_type, user_id, target_entity_type, target_entity_id, payload, status
    )
    values (
      'attribute_change', auth.uid(), 'catalog_item', p_item_id,
      jsonb_build_object(
        'item_id', p_item_id,
        'attribute_key', p_attribute_key,
        'attribute_value', p_value,
        'visibility', v_visibility
      ),
      'pending'
    )
    returning id into v_request_id;

    return jsonb_build_object(
      'status', 'pending',
      'request_id', v_request_id,
      'attribute_key', p_attribute_key
    );
  end if;

  if p_attribute_key = 'full_name' then
    update public.catalog_items
    set title = coalesce(v_value_text, title), updated_at = now()
    where id = p_item_id;
  end if;

  insert into public.catalog_item_attribute_values (
    item_id, attribute_id, value_text, value_json,
    visibility, approval_status, approved_by, approved_at, updated_at
  )
  values (
    p_item_id,
    v_attribute.id,
    case when v_attribute.data_type in ('text', 'textarea', 'select', 'url', 'phone') then v_value_text else null end,
    case when v_attribute.data_type in ('multi_select', 'boolean', 'json') then p_value else null end,
    v_visibility,
    'approved',
    auth.uid(),
    now(),
    now()
  )
  on conflict (item_id, attribute_id) do update
  set
    value_text = excluded.value_text,
    value_json = excluded.value_json,
    visibility = excluded.visibility,
    approval_status = 'approved',
    approved_by = excluded.approved_by,
    approved_at = excluded.approved_at,
    updated_at = now();

  -- Member items: mirror to the user-scoped store so /profile stays in sync.
  if v_item.item_type = 'member' and v_item.linked_user_id is not null then
    insert into public.user_profile_attributes (
      user_id, attribute_id, value_text, value_json,
      visibility, approval_status, approved_by, approved_at, updated_at
    )
    values (
      v_item.linked_user_id,
      v_attribute.id,
      case when v_attribute.data_type in ('text', 'textarea', 'select', 'url', 'phone') then v_value_text else null end,
      case when v_attribute.data_type in ('multi_select', 'boolean', 'json') then p_value else null end,
      v_visibility,
      'approved',
      auth.uid(),
      now(),
      now()
    )
    on conflict (user_id, attribute_id) do update
    set
      value_text = excluded.value_text,
      value_json = excluded.value_json,
      visibility = excluded.visibility,
      approval_status = 'approved',
      approved_by = excluded.approved_by,
      approved_at = excluded.approved_at,
      updated_at = now();
  end if;

  return jsonb_build_object(
    'status', 'approved',
    'attribute_key', p_attribute_key,
    'visibility', v_visibility
  );
end;
$$;


--
-- Name: FUNCTION update_catalog_item_attribute(p_item_id uuid, p_attribute_key text, p_value jsonb, p_visibility text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_catalog_item_attribute(p_item_id uuid, p_attribute_key text, p_value jsonb, p_visibility text) IS 'Owner/editor/admin attribute write for a catalog item, gated by the flat-role AFS rules (role_attributes). Member items mirror writes to user_profile_attributes.';


--
-- Name: catalog_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.catalog_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    item_type text NOT NULL,
    slug text NOT NULL,
    title text NOT NULL,
    headline text,
    short_description text,
    long_description text,
    status text DEFAULT 'draft'::text NOT NULL,
    visibility text DEFAULT 'public'::text NOT NULL,
    verification_status text DEFAULT 'unverified'::text NOT NULL,
    created_by uuid,
    published_at timestamp with time zone,
    attributes jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    platform_role_key text,
    linked_user_id uuid,
    is_placeholder boolean DEFAULT false NOT NULL,
    is_verified boolean DEFAULT false NOT NULL,
    country_code text,
    city text,
    deleted_at timestamp with time zone,
    CONSTRAINT catalog_items_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending_review'::text, 'published'::text, 'archived'::text, 'rejected'::text]))),
    CONSTRAINT catalog_items_verification_status_check CHECK ((verification_status = ANY (ARRAY['unverified'::text, 'pending'::text, 'verified'::text, 'official_source'::text, 'claimed'::text]))),
    CONSTRAINT catalog_items_visibility_check CHECK ((visibility = ANY (ARRAY['public'::text, 'private'::text, 'unlisted'::text])))
);


--
-- Name: TABLE catalog_items; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.catalog_items IS 'Universal searchable catalog record. Type-specific fields live in extension tables keyed by catalog_items.id.';


--
-- Name: COLUMN catalog_items.linked_user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.catalog_items.linked_user_id IS 'AFS bridge: authenticated user that owns or represents this catalog record.';


--
-- Name: COLUMN catalog_items.is_placeholder; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.catalog_items.is_placeholder IS 'Rebuild 2026-06-09: true = seed placeholder (one per flat role), deletable in one query.';


--
-- Name: COLUMN catalog_items.is_verified; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.catalog_items.is_verified IS 'Rebuild 2026-06-09: boolean derived from verification_status; canonical verification flag.';


--
-- Name: update_catalog_item_editor_content(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_catalog_item_editor_content(target_item_id uuid, next_headline text DEFAULT NULL::text, next_short_description text DEFAULT NULL::text, next_long_description text DEFAULT NULL::text, attributes_patch jsonb DEFAULT '{}'::jsonb) RETURNS public.catalog_items
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_item public.catalog_items%rowtype;
begin
  if v_actor_id is null then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if not public.catalog_user_can_edit_item(v_actor_id, target_item_id) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  update public.catalog_items
  set
    headline = coalesce(next_headline, headline),
    short_description = coalesce(next_short_description, short_description),
    long_description = coalesce(next_long_description, long_description),
    attributes = coalesce(attributes, '{}'::jsonb) || coalesce(attributes_patch, '{}'::jsonb),
    updated_at = now()
  where id = target_item_id
  returning * into v_item;

  if v_item.id is null then
    raise exception 'catalog item not found' using errcode = 'P0002';
  end if;

  return v_item;
end;
$$;


--
-- Name: update_current_user_editable_whatsapp_landing(uuid, text, text, text, text, text, text, text, text, text, text, text, integer, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_current_user_editable_whatsapp_landing(p_landing_id uuid, p_group_name text, p_category text, p_country text, p_city text, p_hero_image text, p_call_to_action_text text, p_conditions text, p_whatsapp_link text, p_admin_name text, p_admin_contact text, p_description text, p_member_count integer, p_member_count_updated_at timestamp with time zone, p_language text, p_origin text) RETURNS public.whatsapp_landings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_before public.whatsapp_landings%rowtype;
  v_after public.whatsapp_landings%rowtype;
begin
  if auth.uid() is null then
    raise exception 'unauthorized'
      using errcode = '42501';
  end if;

  select *
  into v_before
  from public.whatsapp_landings
  where id = p_landing_id
  limit 1;

  if v_before.id is null then
    raise exception 'landing not found'
      using errcode = 'P0002';
  end if;

  if not public.current_user_can_edit_whatsapp_landing(v_before.id) then
    raise exception 'forbidden'
      using errcode = '42501';
  end if;

  update public.whatsapp_landings
  set
    group_name = btrim(p_group_name),
    category = btrim(p_category),
    country = btrim(p_country),
    city = btrim(p_city),
    hero_image = nullif(btrim(coalesce(p_hero_image, '')), ''),
    call_to_action_text = nullif(btrim(coalesce(p_call_to_action_text, '')), ''),
    conditions = nullif(btrim(coalesce(p_conditions, '')), ''),
    whatsapp_link = btrim(p_whatsapp_link),
    admin_name = nullif(btrim(coalesce(p_admin_name, '')), ''),
    admin_contact = nullif(btrim(coalesce(p_admin_contact, '')), ''),
    description = nullif(btrim(coalesce(p_description, '')), ''),
    member_count = p_member_count,
    member_count_updated_at = p_member_count_updated_at,
    language = nullif(btrim(coalesce(p_language, '')), ''),
    origin = nullif(btrim(coalesce(p_origin, '')), ''),
    status = 'pending',
    rejection_reason = null,
    updated_at = now()
  where id = v_before.id
  returning * into v_after;

  perform public.write_admin_audit_log(
    'whatsapp_landing.editor_submitted',
    auth.uid(),
    'whatsapp_landing',
    v_after.id,
    to_jsonb(v_before),
    to_jsonb(v_after)
  );

  return v_after;
end;
$$;


--
-- Name: update_feed_like_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_feed_like_count() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public.feed_posts SET like_count = like_count + 1 WHERE id = NEW.post_id;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE public.feed_posts SET like_count = GREATEST(0, like_count - 1) WHERE id = OLD.post_id;
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: update_profile_attribute(text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_profile_attribute(attribute_key text, attribute_value jsonb, visibility text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_role_key text;
  v_role_id uuid;
  v_attribute public.afs_attributes%rowtype;
  v_rule public.role_attributes%rowtype;
  v_visibility text;
  v_value_text text;
  v_request_id uuid;
  -- Referral (B09) yerelleri:
  v_existing_usage public.referral_code_usages%rowtype;
  v_existing_code text;
  v_referral record;
  v_new_usage_code_id uuid;
  v_usage_row_id uuid;
  v_full_name text;
  v_email text;
begin
  if v_user_id is null then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select r.key, r.id into v_role_key, v_role_id
  from public.user_role_assignments ura
  join public.roles r on r.id = ura.role_id
  where ura.user_id = v_user_id
  limit 1;

  if v_role_key is null then
    raise exception 'user role not found' using errcode = 'P0002';
  end if;

  select * into v_attribute from public.afs_attributes where key = attribute_key and is_active = true limit 1;
  if v_attribute.id is null then
    raise exception 'invalid attribute key' using errcode = '22023';
  end if;

  select rar.* into v_rule
  from public.role_attributes rar
  where rar.role_id = v_role_id
    and rar.attribute_id = v_attribute.id
    and rar.is_enabled = true
  limit 1;

  if v_rule.id is null then
    raise exception 'attribute is not enabled for current role' using errcode = '42501';
  end if;

  if not v_rule.user_can_edit then
    raise exception 'attribute is not editable' using errcode = '42501';
  end if;

  v_visibility := coalesce(visibility, case when v_rule.is_public_default then 'public' else 'private' end);
  if v_visibility not in ('public', 'private', 'admin_only') then
    raise exception 'invalid visibility' using errcode = '22023';
  end if;

  -- B09: referral alanları HER ZAMAN private — 20260604190000'daki istisnanın geri
  -- getirilmesi. user_can_hide kontrolü bu iki key için atlanır (42501 blocker'ının çözümü).
  if v_attribute.key in ('referral_code', 'referral_source') then
    v_visibility := 'private';
  elsif not v_rule.user_can_hide and v_visibility <> 'public' then
    raise exception 'attribute visibility cannot be changed' using errcode = '42501';
  end if;

  if v_attribute.data_type in ('text','textarea','select','url','phone') then
    v_value_text := nullif(btrim(coalesce(attribute_value #>> '{}', '')), '');
  end if;

  -- B09: referral_source allowlist doğrulaması (canlıda vardı, kullanılmıyordu — yeniden bağlandı).
  if v_attribute.key = 'referral_source' then
    v_value_text := public.validate_profile_onboarding_referral_source(v_value_text);
  end if;

  -- B09: referral_code doğrulama + kilit.
  if v_attribute.key = 'referral_code' then
    v_value_text := nullif(upper(btrim(coalesce(v_value_text, ''))), '');

    select * into v_existing_usage
    from public.referral_code_usages
    where user_id = v_user_id
    limit 1;

    if v_existing_usage.id is not null then
      select upper(rc.code) into v_existing_code
      from public.referral_codes rc
      where rc.id = v_existing_usage.referral_code_id;

      if v_value_text is null or v_value_text <> v_existing_code then
        -- Kilit: doğrulanmış kod değiştirilemez ve boşaltılamaz.
        raise exception 'referral code locked' using errcode = 'P0001', detail = 'locked';
      end if;
      -- Aynı kod: no-op (çift sayım yok) — normalize edilmiş değeri yazmaya devam et.
      v_value_text := v_existing_code;
    elsif v_value_text is not null then
      select * into v_referral
      from public.validate_and_bind_referral_code(v_value_text, now())
      limit 1;

      if v_referral.status is distinct from 'valid' then
        raise exception 'referral code rejected' using errcode = 'P0001', detail = coalesce(v_referral.status, 'not_found');
      end if;

      v_value_text := v_referral.normalized_code;
      v_new_usage_code_id := v_referral.referral_code_id;
    end if;
  end if;

  if v_rule.requires_admin_approval_on_change then
    insert into public.approval_requests (
      request_type, user_id, target_entity_type, payload, status
    ) values (
      'attribute_change', v_user_id, 'attribute',
      jsonb_build_object('attribute_key', attribute_key, 'attribute_value', attribute_value, 'visibility', v_visibility),
      'pending'
    ) returning id into v_request_id;

    return jsonb_build_object('status', 'pending', 'request_id', v_request_id, 'attribute_key', attribute_key);
  end if;

  insert into public.user_profile_attributes (
    user_id, attribute_id, value_text, value_json,
    visibility, approval_status, approved_by, approved_at, updated_at
  ) values (
    v_user_id, v_attribute.id,
    case when v_attribute.data_type in ('text','textarea','select','url','phone') then v_value_text else null end,
    case when v_attribute.data_type in ('multi_select','boolean','json') then attribute_value else null end,
    v_visibility, 'approved', v_user_id, now(), now()
  )
  on conflict (user_id, attribute_id) do update
  set value_text = excluded.value_text,
      value_json = excluded.value_json,
      visibility = excluded.visibility,
      approval_status = 'approved',
      approved_by = excluded.approved_by,
      approved_at = excluded.approved_at,
      updated_at = now();

  -- B09: doğrulama geçtiyse ve bu kullanıcı için İLK kullanımsa kaydı düş + sayaç artır.
  -- Attribute upsert'inden SONRA: değer kaydedilmeden kullanım yazılmaz.
  if v_new_usage_code_id is not null then
    select upa.value_text into v_full_name
    from public.user_profile_attributes upa
    join public.afs_attributes a on a.id = upa.attribute_id
    where upa.user_id = v_user_id and a.key = 'full_name'
    limit 1;

    select u.email::text into v_email from auth.users u where u.id = v_user_id;

    insert into public.referral_code_usages (referral_code_id, user_id, source, used_at, full_name, email)
    values (v_new_usage_code_id, v_user_id, 'profile', now(), v_full_name, v_email)
    on conflict do nothing
    returning id into v_usage_row_id;

    -- Satır GERÇEKTEN eklendiyse sayaç artar (submissions_log_referral_usage semantiği;
    -- yarış koşulunda ON CONFLICT atlarsa çift sayım olmaz).
    if v_usage_row_id is not null then
      update public.referral_codes
      set usage_count = coalesce(usage_count, 0) + 1,
          is_used = true,
          used_at = greatest(coalesce(used_at, timestamptz 'epoch'), now())
      where id = v_new_usage_code_id;
    end if;
  end if;

  return jsonb_build_object('status', 'approved', 'attribute_key', attribute_key, 'visibility', v_visibility);
end;
$$;


--
-- Name: update_profile_avatar(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_profile_avatar(next_avatar_url text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_attribute_id uuid;
  v_normalized_url text := nullif(btrim(next_avatar_url), '');
begin
  if v_user_id is null then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select id
  into v_attribute_id
  from public.afs_attributes
  where key = 'profile_photo_url'
    and is_active = true
  limit 1;

  if v_attribute_id is null then
    raise exception 'profile_photo_url attribute missing' using errcode = 'P0002';
  end if;

  if v_normalized_url is null then
    delete from public.user_profile_attributes
    where user_id = v_user_id
      and attribute_id = v_attribute_id;
  else
    insert into public.user_profile_attributes (
      user_id,
      attribute_id,
      value_text,
      value_json,
      visibility,
      approval_status,
      approved_by,
      approved_at,
      updated_at
    ) values (
      v_user_id,
      v_attribute_id,
      v_normalized_url,
      null,
      'public',
      'approved',
      v_user_id,
      now(),
      now()
    )
    on conflict (user_id, attribute_id) do update
    set
      value_text = excluded.value_text,
      value_json = null,
      visibility = 'public',
      approval_status = 'approved',
      approved_by = excluded.approved_by,
      approved_at = excluded.approved_at,
      updated_at = now();
  end if;

  return jsonb_build_object(
    'status', 'approved',
    'avatar_url', v_normalized_url
  );
end;
$$;


--
-- Name: update_updated_at_column(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: update_user_taxonomy_selection(text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_taxonomy_selection(group_key text, option_keys text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role_key text;
  v_group public.taxonomy_groups%rowtype;
  v_rule public.role_taxonomy_rules%rowtype;
  v_role public.roles%rowtype;
  v_selected_count integer;
begin
  if auth.uid() is null then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select r.key
  into v_role_key
  from public.user_role_assignments ura
  join public.roles r on r.id = ura.role_id
  where ura.user_id = auth.uid()
  limit 1;

  select * into v_group from public.taxonomy_groups where key = group_key and is_active = true limit 1;
  select * into v_role from public.roles where key = v_role_key limit 1;

  if v_role_key is null or v_group.id is null or v_role.id is null then
    raise exception 'invalid taxonomy update context' using errcode = '22023';
  end if;

  select * into v_rule
  from public.role_taxonomy_rules
  where role_id = v_role.id and group_id = v_group.id and is_enabled = true
  limit 1;

  if v_rule.id is null then
    raise exception 'taxonomy group is not enabled for current role' using errcode = '42501';
  end if;

  select count(*)
  into v_selected_count
  from public.taxonomy_options
  where group_id = v_group.id
    and is_active = true
    and key = any(coalesce(option_keys, array[]::text[]));

  if v_selected_count <> coalesce(array_length(option_keys, 1), 0) then
    raise exception 'one or more taxonomy options are invalid' using errcode = '22023';
  end if;

  if v_rule.selection_mode = 'single' and coalesce(array_length(option_keys, 1), 0) > 1 then
    raise exception 'single selection group cannot accept multiple options' using errcode = '22023';
  end if;

  if v_rule.is_required and coalesce(array_length(option_keys, 1), 0) = 0 then
    raise exception 'at least one taxonomy option is required' using errcode = '22023';
  end if;

  delete from public.user_taxonomy_selections
  where user_id = auth.uid()
    and group_id = v_group.id;

  insert into public.user_taxonomy_selections (user_id, group_id, option_id)
  select auth.uid(), v_group.id, t.id
  from public.taxonomy_options t
  where t.group_id = v_group.id
    and t.key = any(coalesce(option_keys, array[]::text[]));

  return jsonb_build_object(
    'group_key', group_key,
    'selection_count', coalesce(array_length(option_keys, 1), 0),
    'status', 'approved'
  );
end;
$$;


--
-- Name: validate_and_bind_referral_code(text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_and_bind_referral_code(input_code text, reference_time timestamp with time zone DEFAULT now()) RETURNS TABLE(status text, referral_code_id uuid, message text, normalized_code text, source_code text, group_code text, type_code text, valid_from date, valid_until date)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  candidate_code TEXT := UPPER(BTRIM(COALESCE(input_code, '')));
  reference_date DATE := COALESCE(reference_time, now())::date;
  code_row RECORD;
BEGIN
  IF candidate_code = '' THEN
    RETURN QUERY
    SELECT
      'missing'::TEXT,
      NULL::UUID,
      'Referral code is empty.'::TEXT,
      NULL::TEXT,
      NULL::TEXT,
      NULL::TEXT,
      NULL::TEXT,
      NULL::DATE,
      NULL::DATE;
    RETURN;
  END IF;

  SELECT
    referral_codes.id,
    referral_codes.code,
    referral_codes.is_active,
    referral_codes.source_code,
    referral_codes.group_code,
    referral_codes.type_code,
    referral_codes.valid_from,
    referral_codes.valid_until,
    referral_sources.is_active AS source_is_active,
    referral_groups.is_active AS group_is_active,
    referral_types.is_active AS type_is_active
  INTO code_row
  FROM public.referral_codes AS referral_codes
  JOIN public.referral_sources AS referral_sources ON referral_sources.id = referral_codes.source_id
  JOIN public.referral_groups AS referral_groups ON referral_groups.id = referral_codes.group_id
  JOIN public.referral_types AS referral_types ON referral_types.id = referral_codes.type_id
  WHERE UPPER(referral_codes.code) = candidate_code
  ORDER BY referral_codes.created_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN QUERY
    SELECT
      'not_found'::TEXT,
      NULL::UUID,
      'Referral code not found.'::TEXT,
      candidate_code,
      NULL::TEXT,
      NULL::TEXT,
      NULL::TEXT,
      NULL::DATE,
      NULL::DATE;
    RETURN;
  END IF;

  IF NOT code_row.is_active OR NOT code_row.source_is_active OR NOT code_row.group_is_active OR NOT code_row.type_is_active THEN
    RETURN QUERY
    SELECT
      'inactive'::TEXT,
      code_row.id,
      'Referral code is inactive.'::TEXT,
      code_row.code,
      code_row.source_code,
      code_row.group_code,
      code_row.type_code,
      code_row.valid_from,
      code_row.valid_until;
    RETURN;
  END IF;

  IF reference_date < code_row.valid_from THEN
    RETURN QUERY
    SELECT
      'out_of_window'::TEXT,
      code_row.id,
      'Referral code is not active yet.'::TEXT,
      code_row.code,
      code_row.source_code,
      code_row.group_code,
      code_row.type_code,
      code_row.valid_from,
      code_row.valid_until;
    RETURN;
  END IF;

  IF reference_date > code_row.valid_until THEN
    RETURN QUERY
    SELECT
      'expired'::TEXT,
      code_row.id,
      'Referral code is expired.'::TEXT,
      code_row.code,
      code_row.source_code,
      code_row.group_code,
      code_row.type_code,
      code_row.valid_from,
      code_row.valid_until;
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    'valid'::TEXT,
    code_row.id,
    'Referral code is valid.'::TEXT,
    code_row.code,
    code_row.source_code,
    code_row.group_code,
    code_row.type_code,
    code_row.valid_from,
    code_row.valid_until;
END;
$$;


--
-- Name: validate_profile_onboarding_referral_source(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_profile_onboarding_referral_source(input_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
  v_value text := nullif(btrim(coalesce(input_value, '')), '');
begin
  if v_value is null then
    return null;
  end if;

  if v_value not in (
    'whatsapp',
    'instagram',
    'linkedin',
    'x-twitter',
    'facebook',
    'tiktok',
    'youtube',
    'arkadas-tavsiye',
    'etkinlik',
    'google',
    'basin-haber',
    'diger'
  ) then
    raise exception 'invalid referral source' using errcode = '22023';
  end if;

  return v_value;
end;
$$;


--
-- Name: worker_append_service_finder_event(uuid, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_append_service_finder_event(p_job_id uuid, p_event_type text, p_message text, p_event_level text DEFAULT 'info'::text, p_candidate_id uuid DEFAULT NULL::uuid, p_event_payload jsonb DEFAULT '{}'::jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id bigint;
begin
  insert into public.service_finder_job_events
    (job_id, candidate_id, event_type, event_level, message, event_payload)
  values
    (p_job_id, p_candidate_id, p_event_type, coalesce(p_event_level, 'info'),
     p_message, coalesce(p_event_payload, '{}'::jsonb))
  returning id into v_id;
  return v_id;
end;
$$;


--
-- Name: relocation_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.relocation_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    title text NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    priority integer DEFAULT 100 NOT NULL,
    created_by_user_id uuid NOT NULL,
    target_kind text NOT NULL,
    service_category text,
    country_code text NOT NULL,
    city_code text,
    source_id uuid,
    soft_cap_usd numeric(12,4) DEFAULT 1.0000 NOT NULL,
    hard_cap_usd numeric(12,4) DEFAULT 2.0000 NOT NULL,
    cost_total_usd numeric(12,4) DEFAULT 0.0000 NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    locked_by text,
    locked_at timestamp with time zone,
    lease_expires_at timestamp with time zone,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    last_error_code text,
    last_error_message text,
    progress jsonb DEFAULT '{}'::jsonb NOT NULL,
    result_summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    CONSTRAINT relocation_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'review'::text, 'completed'::text, 'failed'::text, 'cancelled'::text, 'budget_stopped'::text]))),
    CONSTRAINT relocation_jobs_target_kind_check CHECK ((target_kind = ANY (ARRAY['service'::text, 'bureaucratic_step'::text, 'emergency_contact'::text])))
);


--
-- Name: worker_claim_relocation_jobs(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_claim_relocation_jobs(p_worker_id text, p_limit integer) RETURNS SETOF public.relocation_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return query
  with claimable as (
    select id from public.relocation_jobs
    where status in ('queued', 'failed')
      and next_attempt_at <= now()
    order by priority asc, next_attempt_at asc
    limit p_limit
    for update skip locked
  )
  update public.relocation_jobs j
  set status = 'running',
      locked_by = p_worker_id,
      locked_at = now(),
      lease_expires_at = now() + interval '5 minutes',
      started_at = coalesce(j.started_at, now()),
      attempts = j.attempts + 1
  from claimable c
  where j.id = c.id
  returning j.*;
end;
$$;


