    seed_urls text[] DEFAULT '{}'::text[] NOT NULL,
    CONSTRAINT service_finder_jobs_catalog_publish_mode_check CHECK ((catalog_publish_mode = ANY (ARRAY['manual_review'::text, 'approve_then_publish'::text, 'direct_publish_disabled'::text]))),
    CONSTRAINT service_finder_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'review'::text, 'completed'::text, 'failed'::text, 'cancelled'::text, 'budget_stopped'::text])))
);


--
-- Name: worker_claim_service_finder_jobs(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_claim_service_finder_jobs(p_worker_id text, p_limit integer DEFAULT 1) RETURNS SETOF public.service_finder_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if nullif(trim(coalesce(p_worker_id, '')), '') is null then
    raise exception 'sf_worker_id_required';
  end if;

  return query
  with claimable as (
    select id
    from public.service_finder_jobs
    where (status = 'queued' and run_after <= now())
       or (status = 'running' and lease_expires_at is not null and lease_expires_at < now())
    order by priority desc, created_at asc
    limit greatest(1, least(coalesce(p_limit, 1), 10))
    for update skip locked
  )
  update public.service_finder_jobs j
  set status = 'running',
      locked_by = p_worker_id,
      lease_expires_at = now() + interval '5 minutes',
      started_at = coalesce(j.started_at, now()),
      attempts = j.attempts + 1,
      updated_at = now()
  from claimable
  where j.id = claimable.id
  returning j.*;
end;
$$;


--
-- Name: worker_complete_relocation_job(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_complete_relocation_job(p_job_id uuid, p_worker_id text, p_status text, p_result_summary jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ok boolean;
begin
  if p_status not in ('review', 'completed', 'budget_stopped') then
    raise exception 'rl_invalid_completion_status';
  end if;
  update public.relocation_jobs
  set status = p_status,
      result_summary = coalesce(p_result_summary, result_summary),
      finished_at = now(),
      locked_by = null,
      lease_expires_at = null
  where id = p_job_id and locked_by = p_worker_id
  returning true into v_ok;
  return coalesce(v_ok, false);
end;
$$;


--
-- Name: worker_complete_service_finder_job(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_complete_service_finder_job(p_job_id uuid, p_worker_id text, p_status text DEFAULT 'review'::text, p_result_summary jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_updated int;
begin
  if p_status not in ('review', 'completed', 'budget_stopped') then
    raise exception 'sf_invalid_final_status';
  end if;

  update public.service_finder_jobs
  set status = p_status,
      result_summary = coalesce(p_result_summary, '{}'::jsonb),
      finished_at = now(),
      locked_by = null,
      lease_expires_at = null,
      updated_at = now()
  where id = p_job_id
    and locked_by = p_worker_id
    and status = 'running';
  get diagnostics v_updated = row_count;
  return v_updated = 1;
end;
$$;


--
-- Name: worker_fail_relocation_job(uuid, text, text, text, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_fail_relocation_job(p_job_id uuid, p_worker_id text, p_error_code text, p_error_message text, p_retryable boolean, p_retry_delay_seconds integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.relocation_jobs
  set status = case when p_retryable then 'failed' else 'failed' end,
      last_error_code = p_error_code,
      last_error_message = p_error_message,
      next_attempt_at = now() + make_interval(secs => greatest(coalesce(p_retry_delay_seconds, 60), 1)),
      locked_by = null,
      lease_expires_at = null
  where id = p_job_id and locked_by = p_worker_id;
end;
$$;


--
-- Name: worker_fail_service_finder_job(uuid, text, text, text, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_fail_service_finder_job(p_job_id uuid, p_worker_id text, p_error_code text, p_error_message text, p_retryable boolean DEFAULT false, p_retry_delay_seconds integer DEFAULT 60) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_attempts int;
  v_updated int;
begin
  select attempts into v_attempts
  from public.service_finder_jobs
  where id = p_job_id and locked_by = p_worker_id and status = 'running'
  for update;
  if not found then
    return false;
  end if;

  if p_retryable and v_attempts < 5 then
    update public.service_finder_jobs
    set status = 'queued',
        run_after = now() + make_interval(secs => greatest(coalesce(p_retry_delay_seconds, 60), 5)),
        locked_by = null,
        lease_expires_at = null,
        last_error_code = p_error_code,
        last_error_message = left(coalesce(p_error_message, ''), 2000),
        updated_at = now()
    where id = p_job_id;
  else
    update public.service_finder_jobs
    set status = 'failed',
        finished_at = now(),
        locked_by = null,
        lease_expires_at = null,
        last_error_code = p_error_code,
        last_error_message = left(coalesce(p_error_message, ''), 2000),
        updated_at = now()
    where id = p_job_id;
  end if;
  get diagnostics v_updated = row_count;

  insert into public.service_finder_job_events (job_id, event_type, event_level, message, event_payload)
  values (p_job_id, 'job_failed', 'error',
          coalesce(p_error_message, p_error_code, 'unknown'),
          jsonb_build_object('error_code', p_error_code, 'retryable', p_retryable, 'attempts', v_attempts));

  return v_updated = 1;
end;
$$;


--
-- Name: worker_heartbeat_relocation_job(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_heartbeat_relocation_job(p_job_id uuid, p_worker_id text, p_progress jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ok boolean;
begin
  update public.relocation_jobs
  set lease_expires_at = now() + interval '5 minutes',
      progress = coalesce(p_progress, progress)
  where id = p_job_id and locked_by = p_worker_id and status = 'running'
  returning true into v_ok;
  return coalesce(v_ok, false);
end;
$$;


--
-- Name: worker_heartbeat_service_finder_job(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_heartbeat_service_finder_job(p_job_id uuid, p_worker_id text, p_progress jsonb DEFAULT NULL::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
