end;
$$;


--
-- Name: worker_record_relocation_cost(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_record_relocation_cost(p_payload jsonb) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_job_id uuid := (p_payload ->> 'job_id')::uuid;
  v_amount numeric := coalesce((p_payload ->> 'amount_usd')::numeric, 0);
  v_total numeric;
begin
  insert into public.relocation_cost_ledger
    (job_id, provider_key, event_type, billing_unit, quantity, unit_cost_usd, amount_usd, request_meta)
  values (
    v_job_id,
    p_payload ->> 'provider_key',
    p_payload ->> 'event_type',
    coalesce(p_payload ->> 'billing_unit', 'request'),
    coalesce((p_payload ->> 'quantity')::numeric, 0),
    coalesce((p_payload ->> 'unit_cost_usd')::numeric, 0),
    v_amount,
    coalesce(p_payload -> 'request_meta', '{}'::jsonb)
  );
  update public.relocation_jobs
  set cost_total_usd = cost_total_usd + v_amount
  where id = v_job_id
  returning cost_total_usd into v_total;
  return coalesce(v_total, 0);
end;
$$;


--
-- Name: worker_record_service_finder_cost(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_record_service_finder_cost(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_job_id uuid := (p_payload ->> 'job_id')::uuid;
  v_event_type text := p_payload ->> 'event_type';
  v_amount numeric(12,4) := coalesce((p_payload ->> 'amount_usd')::numeric, 0);
  v_candidate_id uuid := (p_payload ->> 'candidate_id')::uuid;
  v_total numeric(12,4);
  v_soft numeric(12,4);
  v_hard numeric(12,4);
begin
  if v_job_id is null or v_event_type is null then
    raise exception 'sf_cost_payload_invalid';
  end if;

  insert into public.service_finder_cost_ledger
    (job_id, query_id, source_id, candidate_id, provider_config_id, provider_key,
     event_type, billing_unit, quantity, unit_cost_usd, amount_usd, currency,
     model_name, request_meta)
  values
    (v_job_id,
     (p_payload ->> 'query_id')::uuid,
     (p_payload ->> 'source_id')::uuid,
     v_candidate_id,
     (p_payload ->> 'provider_config_id')::uuid,
     coalesce(p_payload ->> 'provider_key', 'unknown'),
     v_event_type,
     coalesce(p_payload ->> 'billing_unit', 'unit'),
     coalesce((p_payload ->> 'quantity')::numeric, 1),
     coalesce((p_payload ->> 'unit_cost_usd')::numeric, 0),
     v_amount,
     coalesce(p_payload ->> 'currency', 'USD'),
     nullif(p_payload ->> 'model_name', ''),
     coalesce(p_payload -> 'request_meta', '{}'::jsonb));

  update public.service_finder_jobs
  set cost_total_usd = cost_total_usd + v_amount,
      search_requests = search_requests + (case when v_event_type = 'search' then 1 else 0 end),
      extract_requests = extract_requests + (case when v_event_type = 'extract' then 1 else 0 end),
      classify_requests = classify_requests + (case when v_event_type = 'classify' then 1 else 0 end),
      updated_at = now()
  where id = v_job_id
  returning cost_total_usd, soft_cap_usd, hard_cap_usd into v_total, v_soft, v_hard;

  if v_total is null then
    raise exception 'sf_job_not_found';
  end if;

  if v_candidate_id is not null then
    update public.service_finder_candidates
    set cost_total_usd = cost_total_usd + v_amount, updated_at = now()
    where id = v_candidate_id;
  end if;

  return jsonb_build_object(
    'cost_total_usd', v_total,
    'soft_cap_usd', v_soft,
    'hard_cap_usd', v_hard,
    'soft_cap_exceeded', v_total >= v_soft,
    'hard_cap_exceeded', v_total >= v_hard
  );
end;
$$;


--
-- Name: worker_upsert_relocation_candidate(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_upsert_relocation_candidate(p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
begin
  insert into public.relocation_candidates
    (job_id, target_kind, normalized_payload, duplicate_key, source_url, evidence, confidence_score)
  values (
    (p_payload ->> 'job_id')::uuid,
    p_payload ->> 'target_kind',
    p_payload -> 'normalized_payload',
    p_payload ->> 'duplicate_key',
    p_payload ->> 'source_url',
    coalesce(p_payload -> 'evidence', '[]'::jsonb),
    coalesce((p_payload ->> 'confidence_score')::numeric, 0.5)
  )
  on conflict (job_id, duplicate_key) do nothing
  returning id into v_id;
  return v_id;
end;
$$;


--
-- Name: write_admin_audit_log(text, uuid, text, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.write_admin_audit_log(p_action text, p_target_user_id uuid DEFAULT NULL::uuid, p_target_entity_type text DEFAULT NULL::text, p_target_entity_id uuid DEFAULT NULL::uuid, p_before_value jsonb DEFAULT NULL::jsonb, p_after_value jsonb DEFAULT NULL::jsonb) RETURNS void
