begin
  insert into public.admin_audit_logs (
    actor_user_id,
    action,
    target_user_id,
    target_entity_type,
    target_entity_id,
    before_value,
    after_value
  )
  values (
    auth.uid(),
    p_action,
    p_target_user_id,
    p_target_entity_type,
    p_target_entity_id,
    p_before_value,
    p_after_value
  );
end;
$$;


